INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91421, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他冒险下水，但没拯救了那个孩子。", "corrected_sentence": "他冒险下水，但没拯救那个孩子。", "error_description": "错误形式：“没拯救了”（“拯救”后多出一个“了”）；正确形式：“没拯救”。表示过去没有发生的动作用“没”，“没”否定时动词后不能再加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91421, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经拯救了过一个掉下悬崖的登山者。", "corrected_sentence": "他曾经拯救过一个掉下悬崖的登山者。", "error_description": "错误形式：“拯救了过”；正确形式：“拯救过”。表示曾经做过某事用“过”，“了”和“过”不能同时用在同一个动词后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
