INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91422, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "救助，使脱离危险。", "primary_collocate": null, "pronunciation": "zhěng jiù", "ipa": "ʈʂɤŋ˨˩˦ tɕjou˥˩", "syllable_count": 2, "sentences": [{"text": "医生做了十个小时手术，拯救了病人。", "target_word": "拯救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消防员冲进大火，拯救了三个孩子。", "target_word": "拯救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影讲的是英雄拯救世界的故事。", "target_word": "拯救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要马上行动，拯救这些濒危动物。", "target_word": "拯救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱拯救了快要关门的小公司。", "target_word": "拯救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水来了，战士们拯救了全村的人。", "target_word": "拯救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得只有爱才能拯救这个世界。", "target_word": "拯救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人能拯救一个不想改变的人。", "target_word": "拯救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直想拯救那些没有家的小狗。", "target_word": "拯救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次手术拯救了她的生命，她很感谢医生。", "target_word": "拯救", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拯救了", "label": "体标（了）"}, {"form": "拯救过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "动词；救助某人或某事物，使其脱离危险", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db945215-8bb7-469b-a806-7db5687ef759') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91422, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是地方或展览，不能说“参观病人”。"}, {"text": "拯救", "is_correct": true, "explanation": "“拯救”表示使病人脱离生命危险，与手术的目的相合，符合句意。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所或物品，不能用于“病人”。"}, {"text": "偷", "is_correct": false, "explanation": "语义：“偷”与手术救治病人的目的相反，句子说不通。"}], "explanations": {"参观": "搭配：“参观”的对象是地方或展览，不能说“参观病人”。", "拯救": "“拯救”表示使病人脱离生命危险，与手术的目的相合，符合句意。", "打扫": "搭配：“打扫”的对象是场所或物品，不能用于“病人”。", "偷": "语义：“偷”与手术救治病人的目的相反，句子说不通。"}, "sentence_index": 0, "correct_answer": "拯救"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每月拯救一百块钱。", "explanation": "这里应该用〈节省〉。“拯救”表示使人或事物脱离危险，不能用于金钱的节约。"}, {"text": "我们要及时拯救这个错误。", "explanation": "这里应该用〈补救〉。“拯救”针对脱离危险的人或事物，错误要用“补救”。"}, {"text": "我每天拯救一小时，用来读书。", "explanation": "这里应该用〈挤出〉。时间是挤出来的，没有脱离危险的意思，不能用“拯救”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91422, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毁坏", "is_correct": false, "explanation": "语义：“毁坏”与前面的“爱”相悖，句意不通。"}, {"text": "拯救", "is_correct": true, "explanation": "“拯救”表示使世界脱离危险，与“只有爱才能”的意思相合，符合句意。"}, {"text": "清点", "is_correct": false, "explanation": "搭配：“清点”的对象是物品或数目，不能用于“世界”。"}, {"text": "冷落", "is_correct": false, "explanation": "语义：“冷落”与“爱”的态度相反，句子不合逻辑。"}], "explanations": {"毁坏": "语义：“毁坏”与前面的“爱”相悖，句意不通。", "拯救": "“拯救”表示使世界脱离危险，与“只有爱才能”的意思相合，符合句意。", "清点": "搭配：“清点”的对象是物品或数目，不能用于“世界”。", "冷落": "语义：“冷落”与“爱”的态度相反，句子不合逻辑。"}, "sentence_index": 6, "correct_answer": "拯救"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上拯救一杯咖啡喝。", "explanation": "这里应该用〈泡〉。泡咖啡没有脱离危险的意思，不能用“拯救”。"}, {"text": "工人拯救了坏掉的水管。", "explanation": "这里应该用〈修理〉。坏掉的水管只需修理，没有脱离危险的意思，不能用“拯救”。"}, {"text": "他每天晚上都拯救一次手机。", "explanation": "这里应该用〈给……充电〉，说“给手机充电”。手机没电不是危险，不能用“拯救”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91422, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海军及时赶到，了拯救了一位落水的渔民。", "corrected_sentence": "海军及时赶到，拯救了一位落水的渔民。", "error_description": "错误形式：“了拯救”（“拯救”前多出一个“了”）；正确形式：“拯救了”。“了”是动态助词，要放在动词后面表示完成，不能放在动词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91422, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "消防员把那个被困的孩子拯救。", "corrected_sentence": "消防员把那个被困的孩子拯救了。", "error_description": "错误形式：“把……拯救”；正确形式：“把……拯救了”。“把”字句的动词后面要有“了”等成分，只用动词句子不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
