INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91423, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "正要是说刚好准备做一件事。", "primary_collocate": null, "pronunciation": "zhèng yào", "ipa": "ʈʂəŋ˥˩ iɑu˥˩", "syllable_count": 2, "sentences": [{"text": "小王正要下楼，遇到了老同学。", "target_word": "正要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我正要买票，发现钱包不见了。", "target_word": "正要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子正要哭，妈妈笑着抱住了他。", "target_word": "正要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正要回家，老板又叫住了他。", "target_word": "正要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我正要问你这件事，你就告诉我了。", "target_word": "正要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家正要出发，天忽然黑了。", "target_word": "正要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我正要洗澡，朋友打来了电话。", "target_word": "正要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她正要开门，门自己开了。", "target_word": "正要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机正要起飞，下起了大雨。", "target_word": "正要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我正要睡觉，邻居敲门了。", "target_word": "正要", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "刚好准备做一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ebe5ac-3a97-4d64-8d3b-45e11368ef3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91423, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正要", "is_correct": true, "explanation": "“正要”表示恰好准备做某事，与“遇到了老同学”的衔接相符。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来没有，与“遇到了老同学”的情境冲突。"}, {"text": "果然", "is_correct": false, "explanation": "语义：“果然”表示与预料相符，与“正要下楼”的即将发生不符。"}, {"text": "千万", "is_correct": false, "explanation": "语法：“千万”用于祈使、叮嘱（如“千万别忘了”），不能用在叙述句“小王千万下楼”中。"}], "explanations": {"正要": "“正要”表示恰好准备做某事，与“遇到了老同学”的衔接相符。", "从不": "语义：“从不”表示从来没有，与“遇到了老同学”的情境冲突。", "果然": "语义：“果然”表示与预料相符，与“正要下楼”的即将发生不符。", "千万": "语法：“千万”用于祈使、叮嘱（如“千万别忘了”），不能用在叙述句“小王千万下楼”中。"}, "sentence_index": 0, "correct_answer": "正要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他正要回过家，老板又叫住了他。", "explanation": "“正要”指即将开始，与表示曾经发生过的“过”相冲突，不能说“正要回过家”。"}, {"text": "他正要回了家，老板又叫住了他。", "explanation": "“正要”指即将开始，与表示完成的“了”相冲突，不能说“正要回了家”。"}, {"text": "他正要才回到家，老板又叫住了他。", "explanation": "“才”表示刚刚发生且偏晚，与“正要”指即将开始语义冲突，不能说“正要才回到家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7346b50-fae3-4dab-8aac-85e10340955a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91423, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正要", "is_correct": true, "explanation": "“正要”表示恰好准备做某事，与“朋友打来了电话”的衔接相符。"}, {"text": "毕竟", "is_correct": false, "explanation": "语义：“毕竟”表示总括或让步，句中没有它所需要的前提。"}, {"text": "遂", "is_correct": false, "explanation": "语域：“遂”是文言用法，与口语化的叙述不协调。"}, {"text": "反而", "is_correct": false, "explanation": "语义：“反而”表示与预期相反，与“正要洗澡，朋友打来电话”的衔接不符。"}], "explanations": {"正要": "“正要”表示恰好准备做某事，与“朋友打来了电话”的衔接相符。", "毕竟": "语义：“毕竟”表示总括或让步，句中没有它所需要的前提。", "遂": "语域：“遂”是文言用法，与口语化的叙述不协调。", "反而": "语义：“反而”表示与预期相反，与“正要洗澡，朋友打来电话”的衔接不符。"}, "sentence_index": 6, "correct_answer": "正要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我正要睡过觉，邻居敲门了。", "explanation": "“正要”指即将开始，与表示曾经发生过的“过”相冲突，不能说“正要睡过觉”。"}, {"text": "我正要早就睡觉，邻居敲门了。", "explanation": "“早就”表示很久以前已经发生，与“正要”指即将开始语义冲突。"}, {"text": "我正要已经睡觉，邻居敲门了。", "explanation": "“已经”表示动作已经完成，与“正要”指即将开始语义冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7346b50-fae3-4dab-8aac-85e10340955a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91423, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我正要了下班，老板又叫住了我。", "corrected_sentence": "我正要下班，老板又叫住了我。", "error_description": "错误：“正要”后面不能直接加“了”。“正要”本身表示即将做某事，不带时态标记，应说“我正要下班”，不能说“我正要了下班”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7346b50-fae3-4dab-8aac-85e10340955a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91423, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我正要了关门，电话响了。", "corrected_sentence": "我正要关门，电话响了。", "error_description": "错误：“正要”后面不能直接加“了”。“正要”本身表示即将做某事，不带时态标记，应说“我正要关门”，不能说“我正要了关门”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7346b50-fae3-4dab-8aac-85e10340955a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91426, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "旧时代", "is_correct": true, "explanation": "反义：“旧时代”指过去的历史时期，与“新时代”构成反义关系。"}, {"text": "夜晚", "is_correct": false, "explanation": "无反义关系：“夜晚”指一天中的时段，与历史时期无关。"}, {"text": "河流", "is_correct": false, "explanation": "无反义关系：“河流”指自然界的水体，与历史时期无关。"}, {"text": "窗户", "is_correct": false, "explanation": "无反义关系：“窗户”指建筑上的开口，与历史时期无关。"}], "correct_answer": "旧时代", "explanations": {"旧时代": "反义：“旧时代”指过去的历史时期，与“新时代”构成反义关系。", "夜晚": "无反义关系：“夜晚”指一天中的时段，与历史时期无关。", "河流": "无反义关系：“河流”指自然界的水体，与历史时期无关。", "窗户": "无反义关系：“窗户”指建筑上的开口，与历史时期无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91426, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "旧时代", "is_correct": true, "explanation": "反义：“旧时代”指过去的历史时期，与“新时代”构成反义关系。"}, {"text": "清晨", "is_correct": false, "explanation": "无反义关系：“清晨”指一天的开始时段，与历史时期无关。"}, {"text": "石头", "is_correct": false, "explanation": "无反义关系：“石头”指自然界的固体，与历史时期无关。"}, {"text": "湖泊", "is_correct": false, "explanation": "无反义关系：“湖泊”指地表的水域，与历史时期无关。"}], "correct_answer": "旧时代", "explanations": {"旧时代": "反义：“旧时代”指过去的历史时期，与“新时代”构成反义关系。", "清晨": "无反义关系：“清晨”指一天的开始时段，与历史时期无关。", "石头": "无反义关系：“石头”指自然界的固体，与历史时期无关。", "湖泊": "无反义关系：“湖泊”指地表的水域，与历史时期无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91426, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "具有新特征、新面貌的历史时期。", "primary_collocate": null, "pronunciation": "xīn shí dài", "ipa": "ɕin˥ ʂʅ˧˥ tai˥˩", "syllable_count": 3, "sentences": [{"text": "我们生活在一个新时代。", "target_word": "新时代", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新时代需要新的想法。", "target_word": "新时代", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "网络把我们带进了新时代。", "target_word": "新时代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家进入了新时代。", "target_word": "新时代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新时代的青年很有活力。", "target_word": "新时代", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "科技的发展开启了一个新时代。", "target_word": "新时代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在新时代，人人都能上网学习。", "target_word": "新时代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新时代给农村带来了很大变化。", "target_word": "新时代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，我们要为新时代努力学习。", "target_word": "新时代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新时代的城市越来越干净。", "target_word": "新时代", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "书面", "sense_fingerprint": "新时代·具有新特征新面貌的历史时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600a7bce-3638-4377-bbfd-4ecbfb4cb6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91426, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "新时代", "is_correct": true, "explanation": "正确：“生活在一个新时代”指所处的历史时期，与句子语境相符。"}, {"text": "新手机", "is_correct": false, "explanation": "语义：人不能“生活在”一部手机里，句子说不通。"}, {"text": "新朋友", "is_correct": false, "explanation": "语义：“生活在”后面要接时间或地点，不能接一个人。"}, {"text": "新玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，且无法表示人所处的历史时期，与书面语境不合。"}], "explanations": {"新时代": "正确：“生活在一个新时代”指所处的历史时期，与句子语境相符。", "新手机": "语义：人不能“生活在”一部手机里，句子说不通。", "新朋友": "语义：“生活在”后面要接时间或地点，不能接一个人。", "新玩意儿": "语域：“玩意儿”是口语说法，且无法表示人所处的历史时期，与书面语境不合。"}, "sentence_index": 0, "correct_answer": "新时代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在新时代的早上七点出发。", "explanation": "这里把“新时代”当成具体的时间点，应该用〈时候〉。“新时代”指一段历史时期，不能和“早上七点”这样的具体时刻搭配。"}, {"text": "我们在新时代的办公室里开会。", "explanation": "这里把“新时代”当成场所，但它指抽象的历史时期，不能像〈房间〉那样用作地点。"}, {"text": "妈妈在新时代里放了两个苹果。", "explanation": "这里把“新时代”当成可以装东西的容器，应该用〈篮子〉。“新时代”指具有新特征的历史时期，是抽象概念，不能装东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91426, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "新时代", "is_correct": true, "explanation": "正确：“在新时代，人人都能上网学习”指当下的历史时期，符合语境。"}, {"text": "新蛋糕", "is_correct": false, "explanation": "搭配：“在……，”后面要接时间或场合，“新蛋糕”不能充当这样的背景，句子说不通。"}, {"text": "新课本", "is_correct": false, "explanation": "搭配：“新课本”不能作“在……”的背景，人不能“在课本里”上网学习。"}, {"text": "新家伙", "is_correct": false, "explanation": "配价：“在”引出的处所或时间不能是“家伙”这类指人的名词。"}], "explanations": {"新时代": "正确：“在新时代，人人都能上网学习”指当下的历史时期，符合语境。", "新蛋糕": "搭配：“在……，”后面要接时间或场合，“新蛋糕”不能充当这样的背景，句子说不通。", "新课本": "搭配：“新课本”不能作“在……”的背景，人不能“在课本里”上网学习。", "新家伙": "配价：“在”引出的处所或时间不能是“家伙”这类指人的名词。"}, "sentence_index": 6, "correct_answer": "新时代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城市一天之内就进入了两个新时代。", "explanation": "这里把“新时代”当成可以按次数计数的短时段，一天之内数出两个。“新时代”指历史上的一段时期，不能在一天之内重复出现多个，与历史时期的义项不符。"}, {"text": "这个城市的新时代昨天下午打了两次电话。", "explanation": "这里让“新时代”做了打电话的主语。“新时代”是历史时期，不是能说话、打电话的人，应该用〈市政府〉。"}, {"text": "这个城市的老人把新时代收进了衣柜。", "explanation": "这里把“新时代”当成可以收进衣柜的实物，应该用〈衣服〉。“新时代”指历史时期，是抽象概念，不是实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91426, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们正生活在一张新时代的开端。", "corrected_sentence": "我们正生活在一个新时代的开端。", "error_description": "“时代”前应用量词“个”。“张”用于纸张、桌面等平面的东西，学习者常把量词选错，应说“一个新时代”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91426, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在新时代地背景下，人们的学习方式变了。", "corrected_sentence": "在新时代的背景下，人们的学习方式变了。", "error_description": "“新时代”修饰“背景”，应用“的”，不能用“地”。“地”用于动词、形容词前面，不用于名词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
