INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91427, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "步枪是士兵用的长枪。", "primary_collocate": null, "pronunciation": "bù qiāng", "ipa": "pu˥˩ tɕʰiaŋ˥", "syllable_count": 2, "sentences": [{"text": "他爸爸当过兵，用过步枪。", "target_word": "步枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支步枪是新的。", "target_word": "步枪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个兵肩上扛着一支步枪。", "target_word": "步枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们站成一排，手里都拿着步枪。", "target_word": "步枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起手枪，步枪更长。", "target_word": "步枪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他第一次在训练中打步枪。", "target_word": "步枪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战士在山上用步枪打靶。", "target_word": "步枪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把步枪是爷爷留下的。", "target_word": "步枪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "步枪的枪身长，士兵可以站着打。", "target_word": "步枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在电影里看到士兵拿着步枪冲过去。", "target_word": "步枪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "支", "label": "量词"}, {"form": "自动步枪", "label": "复合"}], "register": "中性", "sense_fingerprint": "士兵使用的长枪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f1d42d-5220-4b0c-9fb7-df56a4a71c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91427, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "步枪", "is_correct": true, "explanation": "步枪是士兵用的长枪，与“当过兵”相符，“用过”搭配正确。"}, {"text": "云彩", "is_correct": false, "explanation": "语义：“用过”的对象不能是云彩，句意不通。"}, {"text": "河流", "is_correct": false, "explanation": "配价：“用”要求可以使用的具体工具，河流不能被“用”。"}, {"text": "幼儿园", "is_correct": false, "explanation": "语义：幼儿园是场所，不能被“用过”，句意不通。"}], "explanations": {"步枪": "步枪是士兵用的长枪，与“当过兵”相符，“用过”搭配正确。", "云彩": "语义：“用过”的对象不能是云彩，句意不通。", "河流": "配价：“用”要求可以使用的具体工具，河流不能被“用”。", "幼儿园": "语义：幼儿园是场所，不能被“用过”，句意不通。"}, "sentence_index": 0, "correct_answer": "步枪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "士兵们站成一排，手里都拿着一张步枪。", "explanation": "这里应该用〈支〉。步枪是长枪，量词用“支”；“张”用于平而薄的东西。"}, {"text": "士兵们用步枪切菜。", "explanation": "这里应该用〈菜刀〉。步枪是枪械，不能用来切菜。"}, {"text": "他把步枪种在了花园里。", "explanation": "这里应该用〈花〉。步枪是枪械，不能种在地里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91427, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "步枪", "is_correct": true, "explanation": "步枪可以用来射击，是打靶的器械，符合句意。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包不能用来打靶，句意不通。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵不是射击的工具，句意不通。"}, {"text": "书包", "is_correct": false, "explanation": "配价：“打靶”需要能发射的器械，书包不能作为打靶的工具。"}], "explanations": {"步枪": "步枪可以用来射击，是打靶的器械，符合句意。", "面包": "语义：面包不能用来打靶，句意不通。", "花朵": "语义：花朵不是射击的工具，句意不通。", "书包": "配价：“打靶”需要能发射的器械，书包不能作为打靶的工具。"}, "sentence_index": 6, "correct_answer": "步枪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在电影里看到士兵抱着一辆步枪冲过去。", "explanation": "这里应该用〈支〉。步枪量词是“支”，“辆”用于车辆。"}, {"text": "他在电影里看到士兵用步枪切面包。", "explanation": "这里应该用〈刀〉。切面包要用刀，步枪是射击的武器，不能用来切。"}, {"text": "工兵用步枪炸开了城门。", "explanation": "这里应该用〈炸药〉。炸开城门要用炸药，步枪只能射击。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91427, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷当年在部队里扛过一张步枪。", "corrected_sentence": "爷爷当年在部队里扛过一支步枪。", "error_description": "错误：量词“张”。步枪是长枪，应用“支”；“张”用于平而薄的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91427, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老兵把步枪擦很亮。", "corrected_sentence": "老兵把步枪擦得很亮。", "error_description": "错误：漏掉补语标记“得”。正确：“擦得很亮”，动词后带表示结果或程度的补语时要用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
