INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91428, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "单兵使用的、枪身较长的枪械。", "primary_collocate": null, "pronunciation": "bù qiāng", "ipa": "pu˥˩ tɕʰiaŋ˥", "syllable_count": 2, "sentences": [{"text": "士兵手里拿着一支步枪。", "target_word": "步枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支步枪很长，也很重。", "target_word": "步枪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在博物馆看到一支旧步枪。", "target_word": "步枪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "步枪比手枪长，士兵常用它。", "target_word": "步枪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "士兵每天都要擦步枪。", "target_word": "步枪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战士背着步枪走过桥。", "target_word": "步枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把步枪放在桌子上了。", "target_word": "步枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支步枪能打得很远。", "target_word": "步枪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个士兵都有一支步枪。", "target_word": "步枪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老兵向我们介绍了这种步枪。", "target_word": "步枪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "支", "label": "量词"}, {"form": "自动步枪", "label": "复合"}], "register": "中性", "sense_fingerprint": "单兵使用的长枪身枪械", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f1d42d-5220-4b0c-9fb7-df56a4a71c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91428, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "步枪", "is_correct": true, "explanation": "步枪是单兵用的长枪，可以用手拿，“一支”搭配正确，符合句意。"}, {"text": "军队", "is_correct": false, "explanation": "语义：“拿着”的对象不能是军队，句意不通。"}, {"text": "乐队", "is_correct": false, "explanation": "搭配：“拿着”不能搭配“乐队”，句子的动作与对象不协调。"}, {"text": "歌", "is_correct": false, "explanation": "语义：“一支歌”可以说，但歌不能拿在手里，句意不通。"}], "explanations": {"步枪": "步枪是单兵用的长枪，可以用手拿，“一支”搭配正确，符合句意。", "军队": "语义：“拿着”的对象不能是军队，句意不通。", "乐队": "搭配：“拿着”不能搭配“乐队”，句子的动作与对象不协调。", "歌": "语义：“一支歌”可以说，但歌不能拿在手里，句意不通。"}, "sentence_index": 0, "correct_answer": "步枪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "士兵的肩上扛着一张步枪。", "explanation": "这里应该用〈支〉。步枪是长枪，量词用“支”；“张”用于平而薄的东西。"}, {"text": "士兵用步枪切菜。", "explanation": "这里应该用〈菜刀〉。步枪是枪械，不能用来切菜。"}, {"text": "士兵用步枪喝水。", "explanation": "这里应该用〈杯子〉。步枪是枪械，不能用来喝水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91428, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "步枪", "is_correct": true, "explanation": "步枪是可以移动的武器，能放在桌子上，符合句意。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海不能被搬来放在桌子上，句意不通。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不能被搬来放在桌子上，句意不通。"}, {"text": "空气", "is_correct": false, "explanation": "配价：“放”的对象要是可以移动的具体物件，“空气”不能被放置。"}], "explanations": {"步枪": "步枪是可以移动的武器，能放在桌子上，符合句意。", "大海": "语义：大海不能被搬来放在桌子上，句意不通。", "月亮": "语义：月亮不能被搬来放在桌子上，句意不通。", "空气": "配价：“放”的对象要是可以移动的具体物件，“空气”不能被放置。"}, "sentence_index": 6, "correct_answer": "步枪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他送给我一辆步枪。", "explanation": "这里应该用〈支〉。步枪量词是“支”，“辆”用于车辆。"}, {"text": "敌人用步枪轰炸了城门。", "explanation": "这里应该用〈火炮〉。轰炸要用火炮，步枪只能射击，不能用于轰炸。"}, {"text": "步枪开过了桥。", "explanation": "这里应该用〈坦克〉。开过桥的是坦克这类车辆，步枪是单兵武器，不能开过桥。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91428, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张老式步枪保存得很好。", "corrected_sentence": "这支老式步枪保存得很好。", "error_description": "错误：量词“张”。步枪是长枪，应用“支”；“张”用于平而薄的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
