INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91429, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "支是数细长东西的字，一支笔，一支花。", "primary_collocate": null, "pronunciation": "zhī", "ipa": "ʈʂɻ̩˥", "syllable_count": 1, "sentences": [{"text": "我有一支红笔。", "target_word": "支", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桌子上有两支铅笔。", "target_word": "支", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请给我一支笔，我写个名字。", "target_word": "支", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他送给妈妈一支红玫瑰。", "target_word": "支", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的书包里有三支圆珠笔和一把尺子。", "target_word": "支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上点着一支红蜡烛。", "target_word": "支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支钢笔是我爸爸送给我的。", "target_word": "支", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她包里有两支口红。", "target_word": "支", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师用一支粉笔写了三个字。", "target_word": "支", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想买一支黑色的笔，考试的时候用。", "target_word": "支", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "支：量词，数笔、花、蜡烛等细长的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c40d4862-37ee-47f3-905b-3a171e8ebee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91429, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "支", "is_correct": true, "explanation": "支：量词，用于细长的东西，如“一支笔”。这是正确答案。"}, {"text": "纸", "is_correct": false, "explanation": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是纸。"}, {"text": "吃", "is_correct": false, "explanation": "ch 与 zh 声母不同，意思是吃。"}, {"text": "诗", "is_correct": false, "explanation": "sh 与 zh 声母不同，意思是诗。"}, {"text": "直", "is_correct": false, "explanation": "zhí（第二声）与 zhī（第一声）声调不同，意思是直。"}, {"text": "智", "is_correct": false, "explanation": "zhì（第四声）与 zhī（第一声）声调不同，意思是智慧。"}, {"text": "资", "is_correct": false, "explanation": "z 与 zh 声母不同，意思是资料。"}], "explanations": {"支": "支：量词，用于细长的东西，如“一支笔”。这是正确答案。", "纸": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是纸。", "吃": "ch 与 zh 声母不同，意思是吃。", "诗": "sh 与 zh 声母不同，意思是诗。", "直": "zhí（第二声）与 zhī（第一声）声调不同，意思是直。", "智": "zhì（第四声）与 zhī（第一声）声调不同，意思是智慧。", "资": "z 与 zh 声母不同，意思是资料。"}, "sentence_index": null, "correct_answer": "支"}, "level_3": {"options": [{"text": "支", "is_correct": true, "explanation": "支：量词，用于细长的东西，笔可以用“支”。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于纸、桌子等平面的东西，笔不能说“一张红笔”。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”用于动物或成对物中的一个，笔不用“只”。"}, {"text": "本", "is_correct": false, "explanation": "语义：“本”用于书、本子等，红笔不属于这一类。"}], "explanations": {"支": "支：量词，用于细长的东西，笔可以用“支”。", "张": "搭配：“张”用于纸、桌子等平面的东西，笔不能说“一张红笔”。", "只": "搭配：“只”用于动物或成对物中的一个，笔不用“只”。", "本": "语义：“本”用于书、本子等，红笔不属于这一类。"}, "sentence_index": 0, "correct_answer": "支"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一支书。", "explanation": "这里应该用〈本〉。书用量词“本”计量，“支”只用于细长的东西。"}, {"text": "院子里跑来一支小狗。", "explanation": "这里应该用〈只〉。狗是动物，用量词“只”计量，不用“支”。"}, {"text": "我们班转来一支新同学。", "explanation": "这里应该用〈个〉。同学指人，用“个”计量，不用“支”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91429, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "支", "is_correct": true, "explanation": "支：量词，用于细长的东西，如“一支笔”。这是正确答案。"}, {"text": "指", "is_correct": false, "explanation": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是手指。"}, {"text": "失", "is_correct": false, "explanation": "sh 与 zh 声母不同，意思是失去。"}, {"text": "值", "is_correct": false, "explanation": "zhí（第二声）与 zhī（第一声）声调不同，意思是价值。"}, {"text": "制", "is_correct": false, "explanation": "zhì（第四声）与 zhī（第一声）声调不同，意思是制作。"}, {"text": "姿", "is_correct": false, "explanation": "z 与 zh 声母不同，意思是姿势。"}], "explanations": {"支": "支：量词，用于细长的东西，如“一支笔”。这是正确答案。", "指": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是手指。", "失": "sh 与 zh 声母不同，意思是失去。", "值": "zhí（第二声）与 zhī（第一声）声调不同，意思是价值。", "制": "zhì（第四声）与 zhī（第一声）声调不同，意思是制作。", "姿": "z 与 zh 声母不同，意思是姿势。"}, "sentence_index": null, "correct_answer": "支"}, "level_3": {"options": [{"text": "支", "is_correct": true, "explanation": "支：量词，用于细长的东西，钢笔用“支”。"}, {"text": "台", "is_correct": false, "explanation": "搭配：“台”用于机器、仪器，钢笔不能说“这台钢笔”。"}, {"text": "部", "is_correct": false, "explanation": "搭配：“部”用于电影、手机等，钢笔不用“部”。"}, {"text": "双", "is_correct": false, "explanation": "语义：“双”指成对的东西，一支钢笔不成对。"}], "explanations": {"支": "支：量词，用于细长的东西，钢笔用“支”。", "台": "搭配：“台”用于机器、仪器，钢笔不能说“这台钢笔”。", "部": "搭配：“部”用于电影、手机等，钢笔不用“部”。", "双": "语义：“双”指成对的东西，一支钢笔不成对。"}, "sentence_index": 6, "correct_answer": "支"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他家买了一支大房子。", "explanation": "这里应该用〈座〉。房子是大型建筑，用量词“座”计量，不用“支”。"}, {"text": "教室里有一支新椅子。", "explanation": "这里应该用〈把〉。椅子常用量词“把”计量，不用“支”。"}, {"text": "这支河很长。", "explanation": "这里应该用〈条〉。河是长条形的，用量词“条”计量，不用“支”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91429, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天买了支一钢笔。", "corrected_sentence": "我昨天买了一支钢笔。", "error_description": "量词语序错：“一支”不能说成“支一”。正确：“一支钢笔”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
