INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91430, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词，用于杆状物、队伍、歌曲等。", "primary_collocate": null, "pronunciation": "zhī", "ipa": "ʈʂɻ̩˥", "syllable_count": 1, "sentences": [{"text": "这支部队明天要去山里。", "target_word": "支", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校有一支很好的足球队。", "target_word": "支", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他给大家弹了一支很好听的曲子。", "target_word": "支", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这支军队走了三天才到海边。", "target_word": "支", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一支长长的车队开进了学校。", "target_word": "支", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们是一支年轻的篮球队，每天练习。", "target_word": "支", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这支乐队在北京很有名。", "target_word": "支", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从包里拿出一支箭。", "target_word": "支", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "晚上他手里拿着一支火把。", "target_word": "支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里走来一支跑步的队伍。", "target_word": "支", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "支：量词，用于杆状物、队伍、乐曲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c40d4862-37ee-47f3-905b-3a171e8ebee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91430, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "支", "is_correct": true, "explanation": "支：量词，用于队伍、乐曲、杆状物等，这里正确。"}, {"text": "指", "is_correct": false, "explanation": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是手指。"}, {"text": "吃", "is_correct": false, "explanation": "ch 与 zh 声母不同，意思是吃。"}, {"text": "诗", "is_correct": false, "explanation": "sh 与 zh 声母不同，意思是诗。"}, {"text": "直", "is_correct": false, "explanation": "zhí（第二声）与 zhī（第一声）声调不同，意思是直。"}, {"text": "智", "is_correct": false, "explanation": "zhì（第四声）与 zhī（第一声）声调不同，意思是智慧。"}, {"text": "资", "is_correct": false, "explanation": "z 与 zh 声母不同，意思是资料。"}], "explanations": {"支": "支：量词，用于队伍、乐曲、杆状物等，这里正确。", "指": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是手指。", "吃": "ch 与 zh 声母不同，意思是吃。", "诗": "sh 与 zh 声母不同，意思是诗。", "直": "zhí（第二声）与 zhī（第一声）声调不同，意思是直。", "智": "zhì（第四声）与 zhī（第一声）声调不同，意思是智慧。", "资": "z 与 zh 声母不同，意思是资料。"}, "sentence_index": null, "correct_answer": "支"}, "level_3": {"options": [{"text": "支", "is_correct": true, "explanation": "支：量词，用于队伍，“这支部队”正确。"}, {"text": "位", "is_correct": false, "explanation": "搭配：“位”用于单个的人（敬称），部队是集体，不能说“这位部队”。"}, {"text": "名", "is_correct": false, "explanation": "搭配：“名”用于单个的人，部队是集体，不能说“这名部队”。"}, {"text": "张", "is_correct": false, "explanation": "语义：“张”用于平面的东西，部队不是这类事物。"}], "explanations": {"支": "支：量词，用于队伍，“这支部队”正确。", "位": "搭配：“位”用于单个的人（敬称），部队是集体，不能说“这位部队”。", "名": "搭配：“名”用于单个的人，部队是集体，不能说“这名部队”。", "张": "语义：“张”用于平面的东西，部队不是这类事物。"}, "sentence_index": 0, "correct_answer": "支"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家养了一支小猫。", "explanation": "这里应该用〈只〉。猫是动物，用量词“只”计量，不用“支”。"}, {"text": "教室里摆着一支桌子。", "explanation": "这里应该用〈张〉。桌子是平面家具，用量词“张”计量，不用“支”。"}, {"text": "他骑着一支马跑远了。", "explanation": "这里应该用〈匹〉。马用量词“匹”计量，不用“支”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') 