INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91430, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "支", "is_correct": true, "explanation": "支：量词，用于队伍、乐曲、杆状物等，这里正确。"}, {"text": "纸", "is_correct": false, "explanation": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是纸。"}, {"text": "失", "is_correct": false, "explanation": "sh 与 zh 声母不同，意思是失去。"}, {"text": "值", "is_correct": false, "explanation": "zhí（第二声）与 zhī（第一声）声调不同，意思是价值。"}, {"text": "制", "is_correct": false, "explanation": "zhì（第四声）与 zhī（第一声）声调不同，意思是制作。"}, {"text": "姿", "is_correct": false, "explanation": "z 与 zh 声母不同，意思是姿势。"}], "explanations": {"支": "支：量词，用于队伍、乐曲、杆状物等，这里正确。", "纸": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是纸。", "失": "sh 与 zh 声母不同，意思是失去。", "值": "zhí（第二声）与 zhī（第一声）声调不同，意思是价值。", "制": "zhì（第四声）与 zhī（第一声）声调不同，意思是制作。", "姿": "z 与 zh 声母不同，意思是姿势。"}, "sentence_index": null, "correct_answer": "支"}, "level_3": {"options": [{"text": "支", "is_correct": true, "explanation": "支：量词，用于乐队等团体，“这支乐队”正确。"}, {"text": "首", "is_correct": false, "explanation": "搭配：“首”用于歌曲、诗词，乐队不说“这首乐队”。"}, {"text": "座", "is_correct": false, "explanation": "语义：“座”指大型固定的建筑或山，乐队不属于这一类。"}, {"text": "部", "is_correct": false, "explanation": "搭配：“部”用于电影、书、手机等，乐队不用“部”。"}], "explanations": {"支": "支：量词，用于乐队等团体，“这支乐队”正确。", "首": "搭配：“首”用于歌曲、诗词，乐队不说“这首乐队”。", "座": "语义：“座”指大型固定的建筑或山，乐队不属于这一类。", "部": "搭配：“部”用于电影、书、手机等，乐队不用“部”。"}, "sentence_index": 6, "correct_answer": "支"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公园里走来一支大象。", "explanation": "这里应该用〈头〉。大象是大型动物，用量词“头”计量，不用“支”。"}, {"text": "他推开一支门走了进去。", "explanation": "这里应该用〈扇〉。门用量词“扇”计量，不用“支”。"}, {"text": "院子里停着一支自行车。", "explanation": "这里应该用〈辆〉。自行车用量词“辆”计量，不用“支”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91430, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他肩上扛着支一长枪。", "corrected_sentence": "他肩上扛着一支长枪。", "error_description": "量词语序错：“一支”不能说成“支一”。正确：“一支长枪”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91430, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他手里握着一支的火把。", "corrected_sentence": "他手里握着一支火把。", "error_description": "错误：“一支的火把”，数量词“一支”后不能直接加“的”，应说“一支火把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
