INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91431, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把旧的拿走，放上新的。", "primary_collocate": null, "pronunciation": "gēng huàn", "ipa": "kɤŋ˥ xwan˥˩", "syllable_count": 2, "sentences": [{"text": "这个灯坏了，需要更换。", "target_word": "更换", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想更换手机的电池。", "target_word": "更换", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "师傅正在更换汽车的轮胎。", "target_word": "更换", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水龙头漏水，要更换新的。", "target_word": "更换", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请更换这个旧灯泡。", "target_word": "更换", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "空调的过滤网要定期更换。", "target_word": "更换", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他更换了手机的屏幕。", "target_word": "更换", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人明天来更换门锁。", "target_word": "更换", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "窗户的玻璃碎了，得更换。", "target_word": "更换", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条旧电线太危险，必须更换。", "target_word": "更换", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "更换了", "label": "完成体"}, {"form": "更换过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "更换·把旧的物件拿走，装上新的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600a7bce-3638-4377-bbfd-4ecbfb4cb6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91431, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "更换", "is_correct": true, "explanation": "正确：“需要更换”表示把坏了的灯换成新的，符合句意。"}, {"text": "点亮", "is_correct": false, "explanation": "语义：点亮是使灯发光，与“这个灯坏了”相矛盾。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：欣赏指赏识美好的事物，与坏灯的处理方式不符。"}, {"text": "保存", "is_correct": false, "explanation": "搭配：“保存”多用于文件、数据、食物，不说“需要保存”一盏坏灯。"}], "explanations": {"更换": "正确：“需要更换”表示把坏了的灯换成新的，符合句意。", "点亮": "语义：点亮是使灯发光，与“这个灯坏了”相矛盾。", "欣赏": "语义：欣赏指赏识美好的事物，与坏灯的处理方式不符。", "保存": "搭配：“保存”多用于文件、数据、食物，不说“需要保存”一盏坏灯。"}, "sentence_index": 0, "correct_answer": "更换"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次经历更换了他的想法。", "explanation": "这里应该用〈改变〉。更换指把旧的拿走、放上新的，多用于具体物件；想法的变化要用改变。"}, {"text": "这个孩子这一年个子更换了很多。", "explanation": "这里应该用〈增长〉。更换是把旧的换成新的，个子长高要用增长。"}, {"text": "他们更换了公司的规模。", "explanation": "这里应该用〈扩大〉。更换是换掉旧物，规模变大要用扩大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91431, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "更换", "is_correct": true, "explanation": "正确：“更换了手机的屏幕”表示换掉坏的或旧的屏幕，符合句意。"}, {"text": "浇灌", "is_correct": false, "explanation": "语义：浇灌用于植物或田地，不能浇灌手机屏幕。"}, {"text": "歌颂", "is_correct": false, "explanation": "搭配：“歌颂”的对象是人物或事迹，不说歌颂屏幕。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮用于食物，手机屏幕不能被煮。"}], "explanations": {"更换": "正确：“更换了手机的屏幕”表示换掉坏的或旧的屏幕，符合句意。", "浇灌": "语义：浇灌用于植物或田地，不能浇灌手机屏幕。", "歌颂": "搭配：“歌颂”的对象是人物或事迹，不说歌颂屏幕。", "煮": "语义：煮用于食物，手机屏幕不能被煮。"}, "sentence_index": 6, "correct_answer": "更换"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "运动更换了他的体力。", "explanation": "这里应该用〈增强〉。更换指把旧的换成新的，体力的增加要用增强。"}, {"text": "这个方法更换了成本。", "explanation": "这里应该用〈降低〉。成本减少要用降低，更换是换掉旧东西，不能用于成本。"}, {"text": "老师要更换教室的安静。", "explanation": "这里应该用〈保持〉。安静是一种状态，要保持，不能更换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91431, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "师傅把灯更换。", "corrected_sentence": "师傅把灯更换了。", "error_description": "“把”字句中动词“更换”后要带“了”等成分。说“师傅把灯更换”不完整，应说“师傅把灯更换了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91431, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电工下个星期来更换了电线。", "corrected_sentence": "电工下个星期来更换电线。", "error_description": "“下个星期”表示动作还没发生，“更换”后不能加表示完成的“了”。应说“电工下个星期来更换电线”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
