INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91432, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把原来的换成另外的。", "primary_collocate": null, "pronunciation": "gēng huàn", "ipa": "kɤŋ˥ xwan˥˩", "syllable_count": 2, "sentences": [{"text": "她想更换自己的名字。", "target_word": "更换", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师让我们更换座位。", "target_word": "更换", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司更换了新的负责人。", "target_word": "更换", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他为了工作，更换了联系方式。", "target_word": "更换", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你更换一个更简单的办法。", "target_word": "更换", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "导演决定更换主角。", "target_word": "更换", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "网站要求每个月更换一次密码。", "target_word": "更换", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛前，教练更换了两名队员。", "target_word": "更换", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要更换旅馆的房间。", "target_word": "更换", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行建议客户定期更换银行卡密码。", "target_word": "更换", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "更换了", "label": "完成体"}, {"form": "更换过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "更换·把原来的人、事、安排换成另外的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600a7bce-3638-4377-bbfd-4ecbfb4cb6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91432, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "更换", "is_correct": true, "explanation": "正确：“想更换自己的名字”表示换掉原来的名字，符合句意。"}, {"text": "偷窃", "is_correct": false, "explanation": "语义：偷窃是拿走别人的东西，不能偷窃自己的名字。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：吃掉用于食物，名字不能被吃掉。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”要配歌曲、歌词，不说唱自己的名字。"}], "explanations": {"更换": "正确：“想更换自己的名字”表示换掉原来的名字，符合句意。", "偷窃": "语义：偷窃是拿走别人的东西，不能偷窃自己的名字。", "吃掉": "语义：吃掉用于食物，名字不能被吃掉。", "唱": "搭配：“唱”要配歌曲、歌词，不说唱自己的名字。"}, "sentence_index": 0, "correct_answer": "更换"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他为了工作，更换了英语水平。", "explanation": "这里应该用〈提高〉。提高用于水平、质量，更换是把旧的换成新的，不能用于水平。"}, {"text": "这两年他的收入更换了很多。", "explanation": "这里应该用〈增长〉。收入增加要用增长，更换不能表示数量变多。"}, {"text": "这个办法更换了他的压力。", "explanation": "这里应该用〈减轻〉。压力减少要用减轻，更换不能用于压力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91432, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "更换", "is_correct": true, "explanation": "正确：“每个月更换一次密码”表示定期换掉旧密码，符合句意。"}, {"text": "朗诵", "is_correct": false, "explanation": "搭配：“朗诵”的对象是文章或诗歌，不说朗诵密码。"}, {"text": "颁布", "is_correct": false, "explanation": "语义：颁布指正式发布法令或规章，与网站的定期要求无关。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：欣赏是赏识美好的事物，与“要求每个月做一次”的意思不符。"}], "explanations": {"更换": "正确：“每个月更换一次密码”表示定期换掉旧密码，符合句意。", "朗诵": "搭配：“朗诵”的对象是文章或诗歌，不说朗诵密码。", "颁布": "语义：颁布指正式发布法令或规章，与网站的定期要求无关。", "欣赏": "语义：欣赏是赏识美好的事物，与“要求每个月做一次”的意思不符。"}, "sentence_index": 6, "correct_answer": "更换"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校更换了学生的兴趣。", "explanation": "这里应该用〈培养〉。培养是逐步发展兴趣，更换是把旧的换成新的，兴趣不能被更换。"}, {"text": "新方法更换了工期。", "explanation": "这里应该用〈缩短〉。工期减少要用缩短，更换不能用于时间长短。"}, {"text": "这本书更换了我的知识。", "explanation": "这里应该用〈更新〉。更换是把原来的换成另外的，多用于具体物件或人员；用新知识替换过时知识要用更新。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91432, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他我更换了一台新电脑。", "corrected_sentence": "他给我更换了一台新电脑。", "error_description": "漏掉了引进受益人的“给”。“给我”要放在动词前，表示为我做这件事。说“他我更换”不对，应说“他给我更换了一台新电脑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91432, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校把校车更换。", "corrected_sentence": "学校把校车更换了。", "error_description": "“把”字句中动词“更换”后要带“了”等成分。说“学校把校车更换”不完整，应说“学校把校车更换了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91433, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
