INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91433, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "毫无疑问是说一点也不用怀疑，一定是这样。", "primary_collocate": null, "pronunciation": "háo wú yí wèn", "ipa": "xaʊ˧˥ u˧˥ i˧˥ wən˥˩", "syllable_count": 4, "sentences": [{"text": "毫无疑问，这家饭馆的菜是全城最好吃的。", "target_word": "毫无疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑得那么快，毫无疑问会拿第一名。", "target_word": "毫无疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看了他的成绩，毫无疑问，他是今年最努力的学生。", "target_word": "毫无疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事毫无疑问是他做的，因为只有他有钥匙。", "target_word": "毫无疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天这么黑，路又滑，毫无疑问今晚不能开车了。", "target_word": "毫无疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说得这么好，毫无疑问学过很多年中文。", "target_word": "毫无疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毫无疑问，明天的比赛我们会赢。", "target_word": "毫无疑问", "complexity_tier": "T3", "furigana": "háo wú yí wèn", "sentence_source": "generated"}, {"text": "他每天都练习，毫无疑问，他的中文会越来越好。", "target_word": "毫无疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的雨这么大，毫无疑问，会议要换时间了。", "target_word": "毫无疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了她的歌，毫无疑问，我们都喜欢她。", "target_word": "毫无疑问", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "毫無疑問", "label": "繁体"}], "register": "中性", "sense_fingerprint": "毫无疑问｜副词｜句首或谓语前，表示说话人认为一定如此", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a33d6d74-ea1a-4c9f-88d6-078bbe064f42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91433, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毫无疑问", "is_correct": true, "explanation": "正确：句首副词，表示说话人确信无疑，与“全城最好吃”的判断相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示少有、不常发生，与“全城最好吃”的断言矛盾。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”表示事情意外发生，不用来对事物作断定。"}, {"text": "很少", "is_correct": false, "explanation": "搭配：“很少”修饰动作或频率，不能用来开头作判断。"}], "explanations": {"毫无疑问": "正确：句首副词，表示说话人确信无疑，与“全城最好吃”的判断相符。", "偶尔": "语义：“偶尔”表示少有、不常发生，与“全城最好吃”的断言矛盾。", "突然": "语义：“突然”表示事情意外发生，不用来对事物作断定。", "很少": "搭配：“很少”修饰动作或频率，不能用来开头作判断。"}, "sentence_index": 0, "correct_answer": "毫无疑问"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他有没有来，我们还不确定，毫无疑问他忘了。", "explanation": "这里应该用〈或许〉。毫无疑问表示完全肯定，与“还不确定”矛盾；只是推测时应用〈或许〉。"}, {"text": "毫无疑问他昨天去了北京，但我还没有证实。", "explanation": "这里应该用〈据说〉。毫无疑问表示说话人亲自确信，与“还没有证实”矛盾；转述他人的话应用〈据说〉。"}, {"text": "那条裙子毫无疑问是她买的，但还不能确定。", "explanation": "这里应该用〈可能〉。毫无疑问表示完全确定，与“还不能确定”矛盾；只是推测应用〈可能〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91433, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毫无疑问", "is_correct": true, "explanation": "正确：句首副词，表示对“比赛会赢”的确信，符合句意。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：“偏偏”表示与预期相反，与“会赢”的确信语气不符。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”指一向如此，不能用来对明天的比赛作断定，句子不通。"}, {"text": "差不多", "is_correct": false, "explanation": "搭配：“差不多”修饰程度，不能对“比赛会赢”这样的事件作判断。"}], "explanations": {"毫无疑问": "正确：句首副词，表示对“比赛会赢”的确信，符合句意。", "偏偏": "语义：“偏偏”表示与预期相反，与“会赢”的确信语气不符。", "从来": "语义：“从来”指一向如此，不能用来对明天的比赛作断定，句子不通。", "差不多": "搭配：“差不多”修饰程度，不能对“比赛会赢”这样的事件作判断。"}, "sentence_index": 6, "correct_answer": "毫无疑问"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文章的作者毫无疑问是老师，但我还没有查证。", "explanation": "这里应该用〈也许〉。毫无疑问表示完全确定，与“还没有查证”矛盾；只是推测应用〈也许〉。"}, {"text": "我们还不知道他有没有到家，毫无疑问他已经到家了。", "explanation": "这里应该用〈大概〉。毫无疑问表示完全确定，与“还不知道”矛盾；只是估计应用〈大概〉。"}, {"text": "没想到，他毫无疑问考了第一名。", "explanation": "这里应该用〈竟然〉。毫无疑问表示事先确定，与“没想到”的意外语气矛盾；表示出乎意料应用〈竟然〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91433, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个计划毫无疑问的会成功，大家都很有信心。", "corrected_sentence": "这个计划毫无疑问会成功，大家都很有信心。", "error_description": "词性错误：作副词时，“毫无疑问”后面不能加“的”，“的”会把它变成定语。“毫无疑问的会成功”应改为“毫无疑问会成功”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91433, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他坚持锻炼，很毫无疑问身体会越来越好。", "corrected_sentence": "他坚持锻炼，毫无疑问身体会越来越好。", "error_description": "程度词误用：“毫无疑问”本身表示完全确定，不能再用“很”修饰，“很毫无疑问”应改为“毫无疑问”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
