INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91434, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有任何怀疑，完全肯定。", "primary_collocate": null, "pronunciation": "háo wú yí wèn", "ipa": "xaʊ˧˥ u˧˥ i˧˥ wən˥˩", "syllable_count": 4, "sentences": [{"text": "他是第一名，这是毫无疑问的。", "target_word": "毫无疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事毫无疑问，你不用再问了。", "target_word": "毫无疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的能力是毫无疑问的，大家都很放心。", "target_word": "毫无疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对我们的好意是毫无疑问的，所以我才相信他。", "target_word": "毫无疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球是圆的，这是毫无疑问的事实。", "target_word": "毫无疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个答案毫无疑问，老师也说对了。", "target_word": "毫无疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个毫无疑问的好办法。", "target_word": "毫无疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会来，这一点毫无疑问。", "target_word": "毫无疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的诚实是毫无疑问的，没有人怀疑。", "target_word": "毫无疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的是真话，这一点毫无疑问。", "target_word": "毫无疑问", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "毫無疑問", "label": "繁体"}], "register": "中性", "sense_fingerprint": "毫无疑问｜形容词｜作谓语或定语，指事情确定、不容怀疑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a33d6d74-ea1a-4c9f-88d6-078bbe064f42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91434, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毫无疑问", "is_correct": true, "explanation": "正确：“这是……的”作谓语，表示事情确定无疑，与“第一名”的结果相符。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”形容空气或物体的状态，与“第一名”的结果无关，句子不通。"}, {"text": "遥远", "is_correct": false, "explanation": "语义：“遥远”指距离，与“第一名”的结果不相关，句子不通。"}, {"text": "美味", "is_correct": false, "explanation": "搭配：“美味”只用于食物，不能用来形容“第一名”这类结果。"}], "explanations": {"毫无疑问": "正确：“这是……的”作谓语，表示事情确定无疑，与“第一名”的结果相符。", "潮湿": "语义：“潮湿”形容空气或物体的状态，与“第一名”的结果无关，句子不通。", "遥远": "语义：“遥远”指距离，与“第一名”的结果不相关，句子不通。", "美味": "搭配：“美味”只用于食物，不能用来形容“第一名”这类结果。"}, "sentence_index": 0, "correct_answer": "毫无疑问"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事有几种毫无疑问的原因，我们还不清楚。", "explanation": "这里应该用〈可能的〉。毫无疑问的表示完全确定，与“我们还不清楚”矛盾；说有多种可能时应用〈可能的〉。"}, {"text": "关于这件事，证据还不够，结论是毫无疑问的。", "explanation": "这里应该用〈有待证实〉。毫无疑问的表示完全确定，与“证据还不够”矛盾；结论尚未证实应用〈有待证实〉。"}, {"text": "我对他的话是毫无疑问的，还在考虑。", "explanation": "这里应该用〈半信半疑〉。毫无疑问的表示没有任何怀疑，与“还在考虑”的犹豫矛盾；心存疑虑应用〈半信半疑〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91434, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毫无疑问", "is_correct": true, "explanation": "正确：“毫无疑问的”作定语修饰“好办法”，表示确定无疑的好办法，句子成立。"}, {"text": "冰冷", "is_correct": false, "explanation": "语义：“冰冷”描述温度或态度，不能用来修饰“办法”。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的体形，不能用来形容“办法”。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”指年龄或新旧状态，用来修饰“办法”语义不通。"}], "explanations": {"毫无疑问": "正确：“毫无疑问的”作定语修饰“好办法”，表示确定无疑的好办法，句子成立。", "冰冷": "语义：“冰冷”描述温度或态度，不能用来修饰“办法”。", "高大": "体貌：“高大”形容人或物的体形，不能用来形容“办法”。", "年轻": "语义：“年轻”指年龄或新旧状态，用来修饰“办法”语义不通。"}, "sentence_index": 6, "correct_answer": "毫无疑问"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的计算是毫无疑问的，需要重新算一遍。", "explanation": "这里应该用〈错误〉。毫无疑问表示确定无误，与“需要重新算”矛盾；计算有差错应用〈错误〉。"}, {"text": "这个消息的来源是毫无疑问的，别轻易相信。", "explanation": "这里应该用〈不可靠〉。毫无疑问表示确定可信，与“别轻易相信”矛盾；来源值得怀疑应用〈不可靠〉。"}, {"text": "这件事我们还没查清，只是一种毫无疑问的猜测。", "explanation": "这里应该用〈未经证实的〉。毫无疑问的表示完全确定，与“猜测”自相矛盾；尚未证实应用〈未经证实的〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91434, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一个毫无疑问成功。", "corrected_sentence": "这是一个毫无疑问的成功。", "error_description": "语法错误：“毫无疑问”作定语修饰名词时，后面必须加“的”，应说“毫无疑问的成功”，不能说“毫无疑问成功”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91434, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的诚意很毫无疑问的，大家都很感动。", "corrected_sentence": "他的诚意是毫无疑问的，大家都很感动。", "error_description": "程度词误用：“毫无疑问”表示完全确定，不能用“很”修饰，“很毫无疑问的”应改为“是毫无疑问的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
