INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91435, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "新型是新出来的一种，和以前的不一样。", "primary_collocate": null, "pronunciation": "xīn xíng", "ipa": "ɕin⁵⁵ ɕiŋ³⁵", "syllable_count": 2, "sentences": [{"text": "这是一种新型手机。", "target_word": "新型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开一辆新型汽车。", "target_word": "新型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院买了新型机器。", "target_word": "新型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂做出了新型电视。", "target_word": "新型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种新型电脑很轻。", "target_word": "新型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里有新型教室。", "target_word": "新型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新型自行车比以前轻多了。", "target_word": "新型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民开始用新型机器种地。", "target_word": "新型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖新型冰箱。", "target_word": "新型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司做新型玩具。", "target_word": "新型", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "放在名词前，说东西是新出来的一种，和以前的不同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ee8993d-4865-4819-b75e-8462bbfe4aca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91435, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "新型", "is_correct": true, "explanation": "正确答案：新型（xīn xíng），指新出现的、与以前不同的一种类型。"}, {"text": "新星", "is_correct": false, "explanation": "「xīng（第一声）与 xíng（第二声）声调不同」，新星意思是新出现的明星或天体。"}, {"text": "心情", "is_correct": false, "explanation": "「qíng 与 xíng 声母不同（q 与 x）」，心情意思是心里的感受。"}, {"text": "心性", "is_correct": false, "explanation": "「xìng（第四声）与 xíng（第二声）声调不同」，心性意思是性情。"}], "explanations": {"新型": "正确答案：新型（xīn xíng），指新出现的、与以前不同的一种类型。", "新星": "「xīng（第一声）与 xíng（第二声）声调不同」，新星意思是新出现的明星或天体。", "心情": "「qíng 与 xíng 声母不同（q 与 x）」，心情意思是心里的感受。", "心性": "「xìng（第四声）与 xíng（第二声）声调不同」，心性意思是性情。"}, "sentence_index": null, "correct_answer": "新型"}, "level_3": {"options": [{"text": "新型", "is_correct": true, "explanation": "正确：「新型」说明手机是新出现的一类，符合「一种」的语境。"}, {"text": "美味", "is_correct": false, "explanation": "语义：「美味」形容食物好吃，不能用来修饰手机。"}, {"text": "甜", "is_correct": false, "explanation": "语义：「甜」形容味道，与手机无关。"}, {"text": "饿", "is_correct": false, "explanation": "搭配：「饿」只能形容人或动物的状态，不能修饰物品。"}], "explanations": {"新型": "正确：「新型」说明手机是新出现的一类，符合「一种」的语境。", "美味": "语义：「美味」形容食物好吃，不能用来修饰手机。", "甜": "语义：「甜」形容味道，与手机无关。", "饿": "搭配：「饿」只能形容人或动物的状态，不能修饰物品。"}, "sentence_index": 0, "correct_answer": "新型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们结婚才一个月，是新型夫妻。", "explanation": "这里应该用〈新婚〉。新型指与原有种类不同，刚结婚的夫妻要说〈新婚〉。"}, {"text": "我们班来了一个新型同学，是上个月刚转来的。", "explanation": "这里应该用〈新〉。刚转来的同学是新来的，不是类型不同，用新型不合适，要说〈新同学〉。"}, {"text": "这块鱼是新型的，刚从河里捞上来。", "explanation": "这里应该用〈新鲜〉。新型指类型不同，刚捞上来的鱼要说〈新鲜〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41029984-13d8-4521-9fd7-656bf2eabd77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91435, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "新型", "is_correct": true, "explanation": "正确答案：新型（xīn xíng），指新出现的、与以前不同的一种类型。"}, {"text": "新兴", "is_correct": false, "explanation": "「xīng（第一声）与 xíng（第二声）声调不同」，新兴意思是正在兴起的。"}, {"text": "心境", "is_correct": false, "explanation": "「jìng 与 xíng 声母不同（j 与 x）」，心境意思是内心的状态。"}, {"text": "心性", "is_correct": false, "explanation": "「xìng（第四声）与 xíng（第二声）声调不同」，心性意思是性情。"}], "explanations": {"新型": "正确答案：新型（xīn xíng），指新出现的、与以前不同的一种类型。", "新兴": "「xīng（第一声）与 xíng（第二声）声调不同」，新兴意思是正在兴起的。", "心境": "「jìng 与 xíng 声母不同（j 与 x）」，心境意思是内心的状态。", "心性": "「xìng（第四声）与 xíng（第二声）声调不同」，心性意思是性情。"}, "sentence_index": null, "correct_answer": "新型"}, "level_3": {"options": [{"text": "新型", "is_correct": true, "explanation": "正确：「新型」说明自行车是新出现的类型，与「比以前轻多了」的对比相符。"}, {"text": "重", "is_correct": false, "explanation": "语义：「重」与后面的「轻」意思相反，句子自相矛盾。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：「胖」形容人或动物的体型，不能用于自行车。"}, {"text": "苦", "is_correct": false, "explanation": "语义：「苦」形容味道，与自行车无关。"}], "explanations": {"新型": "正确：「新型」说明自行车是新出现的类型，与「比以前轻多了」的对比相符。", "重": "语义：「重」与后面的「轻」意思相反，句子自相矛盾。", "胖": "体貌：「胖」形容人或动物的体型，不能用于自行车。", "苦": "语义：「苦」形容味道，与自行车无关。"}, "sentence_index": 6, "correct_answer": "新型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位姑娘是新型的，才二十岁。", "explanation": "这里应该用〈年轻〉。新型指类型不同，不能用来说人的年龄，形容年纪小要用〈年轻〉。"}, {"text": "他的脾气是新型的，常常发火。", "explanation": "这里应该用〈暴躁〉。新型只表示类型不同，不能用来形容脾气，形容脾气急躁要用〈暴躁〉。"}, {"text": "他的心情是新型的，一会儿笑一会儿哭。", "explanation": "这里应该用〈反复无常〉。新型指类型不同，不能形容心情变化，心情变化不定要用〈反复无常〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41029984-13d8-4521-9fd7-656bf2eabd77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91435, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们买了一台新型得手机。", "corrected_sentence": "我们买了一台新型手机。", "error_description": "错误形式是“新型得手机”，正确形式是“新型手机”。“新型”是区别词，后面不能加结构助词“得”，应去掉“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41029984-13d8-4521-9fd7-656bf2eabd77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91435, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种很新型电池好用。", "corrected_sentence": "这种新型电池好用。", "error_description": "错误形式是“很新型电池”，正确形式是“新型电池”。“新型”是区别词，前面不能加程度副词“很”修饰，应去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41029984-13d8-4521-9fd7-656bf2eabd77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91437, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91437, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91437, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "能想出法子，把难事做成。", "primary_collocate": null, "pronunciation": "yǒu bàn fǎ", "ipa": "jou˨˩˦ pan˥˩ fa˨˩˦", "syllable_count": 3, "sentences": [{"text": "王经理真有办法，一天就把货找到了。", "target_word": "有办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很有办法，再难的事也能做成。", "target_word": "有办法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都说小李有办法，让生意好起来了。", "target_word": "有办法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈最有办法，什么难题都难不倒她。", "target_word": "有办法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板很有办法，买到了最难买的票。", "target_word": "有办法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你真有办法，这么快就修好了电脑。", "target_word": "有办法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一点儿也不笨，做起事来很有办法。", "target_word": "有办法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我朋友很有办法，总能找到便宜的机票。", "target_word": "有办法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁最有办法，谁就能把这件事办成。", "target_word": "有办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都夸他有办法，把旧房子变成了新家。", "target_word": "有办法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没办法", "label": "否定"}, {"form": "没有办法", "label": "否定"}], "register": "口语", "sense_fingerprint": "有办法|属性|形容人能干、会想法子办成难事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad9311d-2259-4b31-9471-d7d48a98239a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91437, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有办法", "is_correct": true, "explanation": "正确。「有办法」指能想出法子把事办成，与后句「一天就把货找到了」相符。"}, {"text": "没办法", "is_correct": false, "explanation": "语义：「没办法」表示想不出法子，与后句「一天就把货找到了」矛盾。"}, {"text": "懒", "is_correct": false, "explanation": "语义：「懒」与后句「一天就把货找到了」的高效不符，前后矛盾。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：「胖」描写外形，不能说明办事能力，与后句无关。"}], "explanations": {"有办法": "正确。「有办法」指能想出法子把事办成，与后句「一天就把货找到了」相符。", "没办法": "语义：「没办法」表示想不出法子，与后句「一天就把货找到了」矛盾。", "懒": "语义：「懒」与后句「一天就把货找到了」的高效不符，前后矛盾。", "胖": "体貌：「胖」描写外形，不能说明办事能力，与后句无关。"}, "sentence_index": 0, "correct_answer": "有办法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子很有办法，四条腿又结实又稳。", "explanation": "这里应该用〈结实〉。「有办法」说的是人的能力，不用来形容物品的质地。"}, {"text": "这首歌很有办法，大家都喜欢听。", "explanation": "这里应该用〈有名〉。「有办法」说的是人的能力，不用来形容歌曲出名。"}, {"text": "这个周末的天气很有办法，又冷又下雨。", "explanation": "这里应该用〈糟糕〉。「有办法」说的是人能想出法子，不用来形容天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91437, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有办法", "is_correct": true, "explanation": "正确。「有办法」说人做事有方法，与前句「一点儿也不笨」及后半句「做起事来」相符。"}, {"text": "有空", "is_correct": false, "explanation": "语义：「有空」指有闲暇，与「做起事来」的方式无关，句子不通。"}, {"text": "有钱", "is_correct": false, "explanation": "语义：金钱与「做起事来」的方式无关，句子意思不通。"}, {"text": "有病", "is_correct": false, "explanation": "体貌：「有病」指身体不适，不能描述做事的方式，与「不笨」矛盾。"}], "explanations": {"有办法": "正确。「有办法」说人做事有方法，与前句「一点儿也不笨」及后半句「做起事来」相符。", "有空": "语义：「有空」指有闲暇，与「做起事来」的方式无关，句子不通。", "有钱": "语义：金钱与「做起事来」的方式无关，句子意思不通。", "有病": "体貌：「有病」指身体不适，不能描述做事的方式，与「不笨」矛盾。"}, "sentence_index": 6, "correct_answer": "有办法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张纸很有办法，又白又厚。", "explanation": "这里应该用〈厚实〉。「有办法」说的是人能想出法子，不用来形容纸张。"}, {"text": "他前几天有办法，一直在家休息。", "explanation": "这里应该用〈有病〉。「有办法」指能解决问题，不能用来说身体不适。"}, {"text": "我今天有办法，不能去了。", "explanation": "这里应该用〈有事〉。「有办法」不表示有事情要做，这句话前后不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91437, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小张没办法，三天就把这台机器修好了。", "corrected_sentence": "小张有办法，三天就把这台机器修好了。", "error_description": "否定词用错：表示能想出办法、把事做成要用「有办法」；「没办法」表示想不出办法，与后面「三天就修好了」矛盾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91437, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有办法很，把这件事办得很顺利。", "corrected_sentence": "他很有办法，把这件事办得很顺利。", "error_description": "语序错误：程度副词「很」要放在「有办法」前面，说「很有办法」，不能说「有办法很」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
