INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91438, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "有解决问题的方法或能力。", "primary_collocate": null, "pronunciation": "yǒu bàn fǎ", "ipa": "jou˨˩˦ pan˥˩ fa˨˩˦", "syllable_count": 3, "sentences": [{"text": "这个问题你有办法解决吗？", "target_word": "有办法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我有办法让孩子安静下来。", "target_word": "有办法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电脑坏了，你有办法修好吗？", "target_word": "有办法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只要有办法，我就一定帮你。", "target_word": "有办法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说他有办法让我们按时到。", "target_word": "有办法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁有办法打开这扇门？", "target_word": "有办法", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师有办法让学生爱上读书。", "target_word": "有办法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车没油了，你们有办法回家吗？", "target_word": "有办法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们都想不出来，你有办法吗？", "target_word": "有办法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他有办法把大箱子搬上三楼。", "target_word": "有办法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没办法", "label": "否定"}, {"form": "没有办法", "label": "否定"}], "register": "口语", "sense_fingerprint": "有办法|属性|具备解决具体问题的方法或能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad9311d-2259-4b31-9471-d7d48a98239a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91438, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有办法", "is_correct": true, "explanation": "正确。「有办法」指有解决问题的方法或能力，与「解决吗」相符。"}, {"text": "有病", "is_correct": false, "explanation": "配价：「有病」是不带动词宾语的结构，不能接「解决」这样的动作。"}, {"text": "有气", "is_correct": false, "explanation": "语义：「有气」指生气，与问题能否解决无关。"}, {"text": "有理", "is_correct": false, "explanation": "语义：「有理」说的是道理正当，不能表示有解决问题的能力。"}], "explanations": {"有办法": "正确。「有办法」指有解决问题的方法或能力，与「解决吗」相符。", "有病": "配价：「有病」是不带动词宾语的结构，不能接「解决」这样的动作。", "有气": "语义：「有气」指生气，与问题能否解决无关。", "有理": "语义：「有理」说的是道理正当，不能表示有解决问题的能力。"}, "sentence_index": 0, "correct_answer": "有办法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电影很有办法，大家都爱看。", "explanation": "这里应该用〈有趣〉。「有办法」说人能想出法子，不用来评价事物有没有意思。"}, {"text": "这个房间很有办法，又大又亮。", "explanation": "这里应该用〈宽敞〉。「有办法」说的是人能想出法子，不用来形容房间的大小。"}, {"text": "这座小桥很有办法，又窄又旧。", "explanation": "这里应该用〈破旧〉。「有办法」说的是人能想出法子，不用来形容桥。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91438, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有办法", "is_correct": true, "explanation": "正确。「有办法」表示能想出法子，与后句「让学生爱上读书」的教学成效相符。"}, {"text": "结婚", "is_correct": false, "explanation": "配价：「结婚」是不带兼语的离合词，不能接「让学生爱上读书」。"}, {"text": "没钱", "is_correct": false, "explanation": "语义：金钱与「让学生爱上读书」的教学方法无关，句子不通。"}, {"text": "生病", "is_correct": false, "explanation": "语义：「生病」与「让学生爱上读书」的成效矛盾，句子前后不搭。"}], "explanations": {"有办法": "正确。「有办法」表示能想出法子，与后句「让学生爱上读书」的教学成效相符。", "结婚": "配价：「结婚」是不带兼语的离合词，不能接「让学生爱上读书」。", "没钱": "语义：金钱与「让学生爱上读书」的教学方法无关，句子不通。", "生病": "语义：「生病」与「让学生爱上读书」的成效矛盾，句子前后不搭。"}, "sentence_index": 6, "correct_answer": "有办法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服很有办法，又大又长。", "explanation": "这里应该用〈宽大〉。「有办法」说的是人能想出法子，不用来形容衣服。"}, {"text": "他前几天有办法，一直在家休息。", "explanation": "这里应该用〈有病〉。「有办法」指能解决问题，不能用来说身体不适。"}, {"text": "我今天有办法，不能去了。", "explanation": "这里应该用〈有事〉。「有办法」不表示有事情要做，这句话前后不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91438, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有办法着让孩子很快安静下来。", "corrected_sentence": "我有办法让孩子很快安静下来。", "error_description": "体标用错：「有办法」后不能加「着」，应去掉「着」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91438, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你们有办法过回家吗？", "corrected_sentence": "你们有办法回家吗？", "error_description": "体标用错：「有办法」后接动词时不能加「过」，应去掉「过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
