INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91441, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "月钱是每个月可以拿到的钱。", "primary_collocate": null, "pronunciation": "yuè qián", "ipa": "ɥe˥˩ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他在店里做事，月钱不太高。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板每个月发月钱。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我这个月的月钱还没拿到。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作一年了，她的月钱多了一点。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把月钱都寄给了家里。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月钱到手以后，我先去买菜。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作的月钱怎么样？", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的月钱不够交房租。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个月的月钱有五千块。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王拿到月钱，请朋友吃饭。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "月钱：每个月可以拿到的钱，指工作或做事按月得到的收入", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05e66eed-24af-4555-9219-89fc197dcac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91441, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "月钱", "is_correct": true, "explanation": "月钱指每个月拿到的收入，此处指他在店里做事拿到的工钱，与“不太高”搭配，正确。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮可以高，但句中说的是在店里做事的收入，与月亮无关，句子不通。"}, {"text": "月份", "is_correct": false, "explanation": "搭配：“高”说的是数量或水平，不能用来形容月份。"}, {"text": "月色", "is_correct": false, "explanation": "语义：月色是月光，与做事得到的收入无关，不能说“不太高”。"}], "explanations": {"月钱": "月钱指每个月拿到的收入，此处指他在店里做事拿到的工钱，与“不太高”搭配，正确。", "月亮": "语义：月亮可以高，但句中说的是在店里做事的收入，与月亮无关，句子不通。", "月份": "搭配：“高”说的是数量或水平，不能用来形容月份。", "月色": "语义：月色是月光，与做事得到的收入无关，不能说“不太高”。"}, "sentence_index": 0, "correct_answer": "月钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司每年年终都给我发一笔月钱。", "explanation": "这里应该用〈奖金〉。月钱指每个月按时拿到的收入，年终一次性发放的钱不能叫月钱。"}, {"text": "我们公司按季度发月钱。", "explanation": "这里应该用〈工资〉。月钱指每个月按时拿到的收入，按季度发放的钱不能叫月钱。"}, {"text": "我在银行存钱，每年拿到一笔月钱。", "explanation": "这里应该用〈利息〉。月钱指工作按月得到的收入，存款每年得到的钱不能叫月钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f04b711-8b52-447c-8ee9-e5931ba22acb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91441, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月钱", "is_correct": true, "explanation": "月钱指按月得到的收入，此处问这份工作的收入情况，正确。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：工作没有颜色，颜色不能用来询问工作的收入情况。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高指人的身材，不能用来询问工作的情况。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重指人的体形，不能用来询问工作的情况。"}], "explanations": {"月钱": "月钱指按月得到的收入，此处问这份工作的收入情况，正确。", "颜色": "语义：工作没有颜色，颜色不能用来询问工作的收入情况。", "身高": "体貌：身高指人的身材，不能用来询问工作的情况。", "体重": "体貌：体重指人的体形，不能用来询问工作的情况。"}, "sentence_index": 6, "correct_answer": "月钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的月钱是按天算的，每天下班后结一次。", "explanation": "这里应该用〈工资〉。月钱指按月得到的收入，按天结算的工钱不能叫月钱。"}, {"text": "我租房时交了一笔月钱给房东。", "explanation": "这里应该用〈押金〉。月钱指工作得到的收入，交给房东的押金不能叫月钱。"}, {"text": "这次比赛他得了第一名，拿到一笔月钱。", "explanation": "这里应该用〈奖金〉。月钱指按月得到的工作收入，比赛获奖得到的钱不能叫月钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f04b711-8b52-447c-8ee9-e5931ba22acb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91441, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这个月拿到了一只月钱。", "corrected_sentence": "他这个月拿到了一笔月钱。", "error_description": "量词错误：“月钱”前应用“笔”或“份”，“只”用于动物或成对物品中的一个，不能修饰“月钱”。正确说法是“一笔月钱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f04b711-8b52-447c-8ee9-e5931ba22acb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91441, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他月钱每个月都会按时发放。", "corrected_sentence": "他的月钱每个月都会按时发放。", "error_description": "领属标记错误：“他月钱”漏了“的”，应说“他的月钱”，代词加名词作定语时通常要用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f04b711-8b52-447c-8ee9-e5931ba22acb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
