INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91442, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "按月给的零用钱或钱财。", "primary_collocate": null, "pronunciation": "yuè qián", "ipa": "ɥe˥˩ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "妈妈每月给我两百块月钱。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷给孙子的月钱不多。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明用月钱买了一个玩具。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的月钱一个星期就花完了。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，月钱要自己学会存。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟想要多一点月钱。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把月钱放进小盒子里。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上大学以后，爸爸每月寄月钱给我。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月爸爸没给我月钱。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都等着发月钱。", "target_word": "月钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "月钱：家里长辈按月给孩子的零用钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05e66eed-24af-4555-9219-89fc197dcac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91442, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "月钱", "is_correct": true, "explanation": "月钱指长辈按月给孩子的零用钱，此处是妈妈每月给我的零用钱，正确。"}, {"text": "罚款", "is_correct": false, "explanation": "语义：罚款是违规后交给对方的钱，妈妈不会因此给我钱，句子不通。"}, {"text": "力气", "is_correct": false, "explanation": "语义：力气不能用“块”来计算，也不能由妈妈每月给我，句子不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是钱，不能说“两百块天气”。"}], "explanations": {"月钱": "月钱指长辈按月给孩子的零用钱，此处是妈妈每月给我的零用钱，正确。", "罚款": "语义：罚款是违规后交给对方的钱，妈妈不会因此给我钱，句子不通。", "力气": "语义：力气不能用“块”来计算，也不能由妈妈每月给我，句子不通。", "天气": "语义：天气不是钱，不能说“两百块天气”。"}, "sentence_index": 0, "correct_answer": "月钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "过年时爷爷给我一笔月钱。", "explanation": "这里应该用〈压岁钱〉。月钱是按月给的零用钱，过年时的红包不能叫月钱。"}, {"text": "他打碎了玻璃，赔了一笔月钱。", "explanation": "这里应该用〈赔偿金〉。月钱是按月给的零用钱，因损坏东西而付的赔偿不能叫月钱。"}, {"text": "我在超市打工，老板每月给我发月钱。", "explanation": "这里应该用〈工资〉。本义项的月钱是长辈按月给孩子的零用钱，打工得到的报酬应说工资。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f04b711-8b52-447c-8ee9-e5931ba22acb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91442, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月钱", "is_correct": true, "explanation": "月钱是长辈给孩子的零用钱，可以装进小盒子里，正确。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子太大，放不进小盒子里，句子不通。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海无法装进小盒子里，与“放进小盒子里”不合。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高指人的身材，不是能放进盒子的东西。"}], "explanations": {"月钱": "月钱是长辈给孩子的零用钱，可以装进小盒子里，正确。", "房子": "语义：房子太大，放不进小盒子里，句子不通。", "大海": "语义：大海无法装进小盒子里，与“放进小盒子里”不合。", "身高": "体貌：身高指人的身材，不是能放进盒子的东西。"}, "sentence_index": 6, "correct_answer": "月钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校每学期给他发一笔月钱。", "explanation": "这里应该用〈奖学金〉。月钱是按月给的零用钱，学校每学期发的奖学金不能叫月钱。"}, {"text": "他闯红灯，被交警罚了一笔月钱。", "explanation": "这里应该用〈罚款〉。月钱是按月给的零用钱，交通违章的罚款不能叫月钱。"}, {"text": "他借了朋友的钱，每月还一笔月钱。", "explanation": "这里应该用〈欠款〉。月钱是长辈按月给的零用钱，还给朋友的借款不能叫月钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f04b711-8b52-447c-8ee9-e5931ba22acb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91442, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈每个月给我一台月钱。", "corrected_sentence": "妈妈每个月给我一笔月钱。", "error_description": "量词错误：“月钱”前应用“笔”，“台”用于机器、电器等，不能修饰“月钱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f04b711-8b52-447c-8ee9-e5931ba22acb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91442, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我月钱都放在小盒子里。", "corrected_sentence": "我的月钱都放在小盒子里。", "error_description": "领属标记错误：“我月钱”漏了“的”，应说“我的月钱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f04b711-8b52-447c-8ee9-e5931ba22acb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
