INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91443, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "觉得别人比你好，愿意听他的。", "primary_collocate": null, "pronunciation": "fú", "ipa": "fu˧˥", "syllable_count": 1, "sentences": [{"text": "他打球那么好，我真服他。", "target_word": "服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "论做饭，我只服我妈妈。", "target_word": "服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的本事大，谁都服他。", "target_word": "服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个队长很有本事，队员们都服他。", "target_word": "服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我谁也不服，就服你。", "target_word": "服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比画画，我服小李，他画得真好。", "target_word": "服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不服别人，只听自己的。", "target_word": "服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老教授的学问深，年轻人都服他。", "target_word": "服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你跑得比我快，我服你。", "target_word": "服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他赢了三次，现在大家都服他了。", "target_word": "服", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "服了", "label": "体标"}], "register": "口语", "sense_fingerprint": "佩服某个人，觉得他比自己强，愿意听他的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600a7bce-3638-4377-bbfd-4ecbfb4cb6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91443, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "服", "is_correct": true, "explanation": "正确：听到的是“服”（fú，第二声），表示佩服别人的本事。"}, {"text": "付", "is_correct": false, "explanation": "fù（第四声）与 fú（第二声）声调不同，意思是付钱。"}, {"text": "府", "is_correct": false, "explanation": "fǔ（第三声）与 fú（第二声）声调不同，意思是官府或住所。"}, {"text": "湖", "is_correct": false, "explanation": "声母 h 与 f 不同（hú，第二声），意思是湖泊。"}], "explanations": {"服": "正确：听到的是“服”（fú，第二声），表示佩服别人的本事。", "付": "fù（第四声）与 fú（第二声）声调不同，意思是付钱。", "府": "fǔ（第三声）与 fú（第二声）声调不同，意思是官府或住所。", "湖": "声母 h 与 f 不同（hú，第二声），意思是湖泊。"}, "sentence_index": null, "correct_answer": "服"}, "level_3": {"options": [{"text": "服", "is_correct": true, "explanation": "正确：“我真服他”表示佩服他的本事，符合句意。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示反感，与“打球那么好”的赞赏相反。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”是指出缺点，与赞赏的语气不合。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”是讥笑别人，与“打球那么好”的赞赏语气相反。"}], "explanations": {"服": "正确：“我真服他”表示佩服他的本事，符合句意。", "讨厌": "语义：“讨厌”表示反感，与“打球那么好”的赞赏相反。", "批评": "语义：“批评”是指出缺点，与赞赏的语气不合。", "嘲笑": "语义：“嘲笑”是讥笑别人，与“打球那么好”的赞赏语气相反。"}, "sentence_index": 0, "correct_answer": "服"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他服了一下午的课。", "explanation": "这里应该用〈上〉。服表示佩服别人的本事或听从，不能用来表示上课、参加学习。"}, {"text": "大家都服他的失误。", "explanation": "这里应该用〈原谅〉。服表示佩服别人的本事，不能用来对待别人的失误；包容别人的失误要用原谅。"}, {"text": "他服工作太累。", "explanation": "这里应该用〈吃不消〉。服表示佩服或听从，不能用来表示承受工作的辛苦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91443, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "服", "is_correct": true, "explanation": "正确：听到的是“服”（fú，第二声），表示佩服别人的本事。"}, {"text": "夫", "is_correct": false, "explanation": "fū（第一声）与 fú（第二声）声调不同，意思是丈夫。"}, {"text": "府", "is_correct": false, "explanation": "fǔ（第三声）与 fú（第二声）声调不同，意思是官府或住所。"}, {"text": "胡", "is_correct": false, "explanation": "声母 h 与 f 不同（hú，第二声），意思是胡子，也是姓。"}], "explanations": {"服": "正确：听到的是“服”（fú，第二声），表示佩服别人的本事。", "夫": "fū（第一声）与 fú（第二声）声调不同，意思是丈夫。", "府": "fǔ（第三声）与 fú（第二声）声调不同，意思是官府或住所。", "胡": "声母 h 与 f 不同（hú，第二声），意思是胡子，也是姓。"}, "sentence_index": null, "correct_answer": "服"}, "level_3": {"options": [{"text": "服", "is_correct": true, "explanation": "正确：“不服别人”表示不佩服别人、不愿听别人的，与“只听自己的”前后呼应。"}, {"text": "借", "is_correct": false, "explanation": "语义：“借”的对象是东西，不能借别人，句意不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的宾语多是衣物或身体部位，不说洗别人。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指吃东西，“吃别人”与“只听自己的”的意思无关。"}], "explanations": {"服": "正确：“不服别人”表示不佩服别人、不愿听别人的，与“只听自己的”前后呼应。", "借": "语义：“借”的对象是东西，不能借别人，句意不通。", "洗": "搭配：“洗”的宾语多是衣物或身体部位，不说洗别人。", "吃": "语义：“吃”指吃东西，“吃别人”与“只听自己的”的意思无关。"}, "sentence_index": 6, "correct_answer": "服"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师服了这本书。", "explanation": "这里应该用〈欣赏〉。服表示佩服别人的本事，不能用于欣赏书籍这样的作品。"}, {"text": "这只小狗服了这顿饭。", "explanation": "这里应该用〈吃〉。服表示佩服别人的本事，不能用于吃饭这类动作。"}, {"text": "他很服童年。", "explanation": "这里应该用〈怀念〉。服表示佩服，不表示思念过去的时光。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91443, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的棋艺很高，我真他服。", "corrected_sentence": "他的棋艺很高，我真服他。", "error_description": "“服”是及物动词，宾语“他”应放在动词后面。应说“我真服他”，“我真他服”语序颠倒。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91443, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次比赛后，大家都他服了。", "corrected_sentence": "这次比赛后，大家都服他了。", "error_description": "宾语“他”要放在动词“服”后面，不能放在“服”前面。应说“大家都服他了”，“大家都他服了”语序错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
