INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91444, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "信服；服从。", "primary_collocate": null, "pronunciation": "fú", "ipa": "fu˧˥", "syllable_count": 1, "sentences": [{"text": "他说得有道理，大家都服。", "target_word": "服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个结果不公平，我不服。", "target_word": "服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裁判的决定，他一点也不服。", "target_word": "服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说得这么清楚，我服了。", "target_word": "服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他输了比赛，可是心里不服。", "target_word": "服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对这个判决，她不服，决定再申请一次。", "target_word": "服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板的安排太不合理，大家都不服。", "target_word": "服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲的办法很有效，同事们都服。", "target_word": "服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁对谁错，看了证据，他才服。", "target_word": "服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不服，因为他觉得老师没有看清楚。", "target_word": "服", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "服了", "label": "体标"}], "register": "口语", "sense_fingerprint": "对道理、结果或决定心里接受，不再反对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600a7bce-3638-4377-bbfd-4ecbfb4cb6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91444, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "服", "is_correct": true, "explanation": "正确：听到的是“服”（fú，第二声），表示心里信服、不再反对。"}, {"text": "父", "is_correct": false, "explanation": "fù（第四声）与 fú（第二声）声调不同，意思是父亲。"}, {"text": "府", "is_correct": false, "explanation": "fǔ（第三声）与 fú（第二声）声调不同，意思是官府或住所。"}, {"text": "夫", "is_correct": false, "explanation": "fū（第一声）与 fú（第二声）声调不同，意思是丈夫。"}, {"text": "湖", "is_correct": false, "explanation": "声母 h 与 f 不同（hú，第二声），意思是湖泊。"}], "explanations": {"服": "正确：听到的是“服”（fú，第二声），表示心里信服、不再反对。", "父": "fù（第四声）与 fú（第二声）声调不同，意思是父亲。", "府": "fǔ（第三声）与 fú（第二声）声调不同，意思是官府或住所。", "夫": "fū（第一声）与 fú（第二声）声调不同，意思是丈夫。", "湖": "声母 h 与 f 不同（hú，第二声），意思是湖泊。"}, "sentence_index": null, "correct_answer": "服"}, "level_3": {"options": [{"text": "服", "is_correct": true, "explanation": "正确：“大家都服”表示对有道理的说法心里接受，符合句意。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“说得有道理”之后说“反对”，与句意相反。"}, {"text": "怀疑", "is_correct": false, "explanation": "语义：“怀疑”表示不信，与“说得有道理”的评价相反。"}, {"text": "批评", "is_correct": false, "explanation": "配价：“批评”后面要有批评的对象，单说“大家都批评”不完整。"}], "explanations": {"服": "正确：“大家都服”表示对有道理的说法心里接受，符合句意。", "反对": "语义：“说得有道理”之后说“反对”，与句意相反。", "怀疑": "语义：“怀疑”表示不信，与“说得有道理”的评价相反。", "批评": "配价：“批评”后面要有批评的对象，单说“大家都批评”不完整。"}, "sentence_index": 0, "correct_answer": "服"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天服生病的父亲。", "explanation": "这里应该用〈服侍〉。服表示心里信服或服从，照顾、侍奉病人要用服侍，不能只用“服”。"}, {"text": "老师服了我的请求。", "explanation": "这里应该用〈答应〉。服表示心里信服或服从，不能用来表示同意别人的请求。"}, {"text": "他服了自己的错误。", "explanation": "这里应该用〈承认〉。服表示心里信服、不再反对，承认错误要用承认，不能用服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91444, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "服", "is_correct": true, "explanation": "正确：听到的是“服”（fú，第二声），表示心里信服、不再反对。"}, {"text": "富", "is_correct": false, "explanation": "fù（第四声）与 fú（第二声）声调不同，意思是富有。"}, {"text": "府", "is_correct": false, "explanation": "fǔ（第三声）与 fú（第二声）声调不同，意思是官府或住所。"}, {"text": "壶", "is_correct": false, "explanation": "声母 h 与 f 不同（hú，第二声），意思是水壶。"}], "explanations": {"服": "正确：听到的是“服”（fú，第二声），表示心里信服、不再反对。", "富": "fù（第四声）与 fú（第二声）声调不同，意思是富有。", "府": "fǔ（第三声）与 fú（第二声）声调不同，意思是官府或住所。", "壶": "声母 h 与 f 不同（hú，第二声），意思是水壶。"}, "sentence_index": null, "correct_answer": "服"}, "level_3": {"options": [{"text": "服", "is_correct": true, "explanation": "正确：“大家都不服”表示对不合理的安排心里不接受，符合句意。"}, {"text": "脸红", "is_correct": false, "explanation": "语义：脸红表示害羞，不能用来表达对安排的态度。"}, {"text": "歌唱", "is_correct": false, "explanation": "语义：“歌唱”是唱歌，与句中的态度无关。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“不”后接“游泳”不能表示对安排的态度，“游泳”与“安排不合理”的评价搭配不上。"}], "explanations": {"服": "正确：“大家都不服”表示对不合理的安排心里不接受，符合句意。", "脸红": "语义：脸红表示害羞，不能用来表达对安排的态度。", "歌唱": "语义：“歌唱”是唱歌，与句中的态度无关。", "游泳": "搭配：“不”后接“游泳”不能表示对安排的态度，“游泳”与“安排不合理”的评价搭配不上。"}, "sentence_index": 6, "correct_answer": "服"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于服了烟。", "explanation": "这里应该用〈戒〉。服表示心里信服或服从，戒烟要用戒，“服烟”不通。"}, {"text": "我们服他的帮助。", "explanation": "这里应该用〈感谢〉。服表示心里信服，不用于感谢别人的帮助。"}, {"text": "他服了朋友的过错。", "explanation": "这里应该用〈原谅〉。服是心里接受、不再反对，不能用于宽恕别人的过错。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
