INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91445, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "流入", "is_correct": true, "explanation": "流入指从外面流进里面，与“流出”意思相反，是反义词。"}, {"text": "收集", "is_correct": false, "explanation": "收集指把分散的东西聚到一起，与“流出”没有反义关系。"}, {"text": "滴落", "is_correct": false, "explanation": "滴落指液体一滴一滴往下落，动作相近，但不是反义词。"}, {"text": "煮沸", "is_correct": false, "explanation": "煮沸指加热使液体冒泡，与“流出”没有反义关系。"}], "correct_answer": "流入", "explanations": {"流入": "流入指从外面流进里面，与“流出”意思相反，是反义词。", "收集": "收集指把分散的东西聚到一起，与“流出”没有反义关系。", "滴落": "滴落指液体一滴一滴往下落，动作相近，但不是反义词。", "煮沸": "煮沸指加热使液体冒泡，与“流出”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
