INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91445, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "流出是水从里面往外面走。", "primary_collocate": null, "pronunciation": "liú chū", "ipa": "ljou˧˥ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "水龙头坏了，水一直流出来。", "target_word": "流出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子破了，水从里面流出了。", "target_word": "流出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桶底有个洞，水慢慢流出。", "target_word": "流出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "泉水从山里流出，清清的。", "target_word": "流出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水管裂了，水流出了很多。", "target_word": "流出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水从湖里流出，流向大海。", "target_word": "流出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，雨水从房顶的洞里流出来。", "target_word": "流出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开门，水马上流出来了。", "target_word": "流出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瓶子倒了，水从瓶口流出。", "target_word": "流出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房的水流出门外了。", "target_word": "流出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "流出来", "label": "复合"}, {"form": "流出去", "label": "复合"}, {"form": "流出了", "label": "体标"}], "register": "中性", "sense_fingerprint": "水从里面流到外面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e23a7c-9131-4a56-a854-f3c79c067e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91445, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "流出", "is_correct": true, "explanation": "流出指水等液体从里面流到外面，与听到的读音一致，即正确答案。"}, {"text": "溜出", "is_correct": false, "explanation": "liū（第一声）与 liú（第二声）声调不同，溜出指悄悄地跑出去。"}, {"text": "露出", "is_correct": false, "explanation": "lòu（第四声）与 liú 的韵母和声调都不同，露出指显露在外面。"}, {"text": "流苏", "is_correct": false, "explanation": "sū 与 chū 声母不同，流苏指衣物或装饰上垂下的穗子。"}], "explanations": {"流出": "流出指水等液体从里面流到外面，与听到的读音一致，即正确答案。", "溜出": "liū（第一声）与 liú（第二声）声调不同，溜出指悄悄地跑出去。", "露出": "lòu（第四声）与 liú 的韵母和声调都不同，露出指显露在外面。", "流苏": "sū 与 chū 声母不同，流苏指衣物或装饰上垂下的穗子。"}, "sentence_index": null, "correct_answer": "流出"}, "level_3": {"options": [{"text": "流出", "is_correct": true, "explanation": "流出：水从里面流到外面，与句意“一直流出来”相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的动作要由人或动物发出，水不会唱，句子不通。"}, {"text": "笑", "is_correct": false, "explanation": "语义：“笑”的主体要是人，水不会笑，句子不通。"}, {"text": "喊", "is_correct": false, "explanation": "语义：“喊”需要有发声的主体，水不能喊，句子不通。"}], "explanations": {"流出": "流出：水从里面流到外面，与句意“一直流出来”相符。", "唱": "语义：“唱”的动作要由人或动物发出，水不会唱，句子不通。", "笑": "语义：“笑”的主体要是人，水不会笑，句子不通。", "喊": "语义：“喊”需要有发声的主体，水不能喊，句子不通。"}, "sentence_index": 0, "correct_answer": "流出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小河最后流出大海。", "explanation": "这里应该用〈流入〉。流出指从里面到外面，小河是流进大海，不能说流出大海。"}, {"text": "鱼从河里流出来了。", "explanation": "这里应该用〈游出〉。“流出”只用于液体或气体，鱼是动物，应说游出来。"}, {"text": "他的脚从鞋子里流出来了。", "explanation": "这里应该用〈伸出〉。“流出”只用于液体或气体，脚是身体部位，应说伸出来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91445, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流出", "is_correct": true, "explanation": "流出：液体从里面流到外面，与“雨水从洞里流出来”的句意相符。"}, {"text": "爬", "is_correct": false, "explanation": "搭配：“爬”多用于人或动物，雨水不能爬。"}, {"text": "跳", "is_correct": false, "explanation": "搭配：“跳”的主体一般是人或动物，雨水不会跳，句子不通。"}, {"text": "说", "is_correct": false, "explanation": "语义：“说”需要有人发言，雨水不会说话，句子不通。"}], "explanations": {"流出": "流出：液体从里面流到外面，与“雨水从洞里流出来”的句意相符。", "爬": "搭配：“爬”多用于人或动物，雨水不能爬。", "跳": "搭配：“跳”的主体一般是人或动物，雨水不会跳，句子不通。", "说": "语义：“说”需要有人发言，雨水不会说话，句子不通。"}, "sentence_index": 6, "correct_answer": "流出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "石子从缝隙里流出来了。", "explanation": "这里应该用〈滚出〉。“流出”只用于液体或气体，石子是固体，应说滚出来。"}, {"text": "书从箱子里流出来了。", "explanation": "这里应该用〈掉出〉。“流出”只用于液体或气体，书是固体，不能说流出。"}, {"text": "苹果从树上流出来了。", "explanation": "这里应该用〈掉下〉。“流出”指液体从里面流到外面，苹果从树上掉落不能说流出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91445, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "水管破了，水被流出来了。", "corrected_sentence": "水管破了，水流出来了。", "error_description": "错误：不及物动词“流出”不能用“被”字句。正确：应说“水流出来了”，不加“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91445, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋顶漏水，缝隙里的水流出去来了，很脏。", "corrected_sentence": "屋顶漏水，缝隙里的水流出来了，很脏。", "error_description": "错误：趋向补语“去”与“来”不能并用。正确：应说“流出来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
