INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91446, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "液体从内向外流动。", "primary_collocate": null, "pronunciation": "liú chū", "ipa": "ljou˧˥ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "他的手受伤了，血流出来了。", "target_word": "流出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车下面有油流出，要修一下。", "target_word": "流出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开瓶盖，果汁慢慢流出。", "target_word": "流出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑得眼泪都流出来了。", "target_word": "流出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "伤口里流出了红红的血。", "target_word": "流出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器坏了，油从里面流出。", "target_word": "流出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶从杯子里流出，桌上都是。", "target_word": "流出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕切开，热热的巧克力流出来。", "target_word": "流出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "锅裂了，汤从缝里流出。", "target_word": "流出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心，别让药水从瓶子里流出来。", "target_word": "流出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "流出来", "label": "复合"}, {"form": "流出去", "label": "复合"}, {"form": "流出了", "label": "体标"}], "register": "中性", "sense_fingerprint": "血、油、泪等液体从内部流到外部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e23a7c-9131-4a56-a854-f3c79c067e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91446, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "流出", "is_correct": true, "explanation": "流出指液体从里面流到外面，与听到的读音一致，即正确答案。"}, {"text": "溜出", "is_correct": false, "explanation": "liū（第一声）与 liú（第二声）声调不同，溜出指悄悄地跑出去。"}, {"text": "露出", "is_correct": false, "explanation": "lòu（第四声）与 liú 的韵母和声调都不同，露出指显露在外面。"}, {"text": "流苏", "is_correct": false, "explanation": "sū 与 chū 声母不同，流苏指衣物或装饰上垂下的穗子。"}], "explanations": {"流出": "流出指液体从里面流到外面，与听到的读音一致，即正确答案。", "溜出": "liū（第一声）与 liú（第二声）声调不同，溜出指悄悄地跑出去。", "露出": "lòu（第四声）与 liú 的韵母和声调都不同，露出指显露在外面。", "流苏": "sū 与 chū 声母不同，流苏指衣物或装饰上垂下的穗子。"}, "sentence_index": null, "correct_answer": "流出"}, "level_3": {"options": [{"text": "流出", "is_correct": true, "explanation": "流出：液体从里面流到外面，与句意“血流出来了”相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的动作要由人发出，血不会唱，句子不通。"}, {"text": "说", "is_correct": false, "explanation": "语义：“说”需要有发言的主体，血不会说话，句子不通。"}, {"text": "跳", "is_correct": false, "explanation": "搭配：“跳”多用于人或动物，血不能跳出来，搭配不当。"}], "explanations": {"流出": "流出：液体从里面流到外面，与句意“血流出来了”相符。", "唱": "语义：“唱”的动作要由人发出，血不会唱，句子不通。", "说": "语义：“说”需要有发言的主体，血不会说话，句子不通。", "跳": "搭配：“跳”多用于人或动物，血不能跳出来，搭配不当。"}, "sentence_index": 0, "correct_answer": "流出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "钥匙从口袋里流出来了。", "explanation": "这里应该用〈掉出〉。“流出”只用于液体或气体，钥匙是固体，不能说流出。"}, {"text": "小狗从院子里流出来了。", "explanation": "这里应该用〈跑出〉。“流出”只用于液体或气体，小狗是动物，应说跑出来。"}, {"text": "猫从箱子里流出来了。", "explanation": "这里应该用〈钻出〉。“流出”只用于液体或气体，猫是动物，应说钻出来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91446, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流出", "is_correct": true, "explanation": "流出：液体从里面流到外面，与“牛奶从杯子里流出，桌上都是”相符。"}, {"text": "爬", "is_correct": false, "explanation": "搭配：“爬”多用于人或动物，牛奶不能爬出杯子。"}, {"text": "摇", "is_correct": false, "explanation": "搭配：“摇”指晃动，不能说牛奶被摇出杯子，搭配不当。"}, {"text": "喊", "is_correct": false, "explanation": "语义：“喊”需要有发声的主体，牛奶不能喊，句子不通。"}], "explanations": {"流出": "流出：液体从里面流到外面，与“牛奶从杯子里流出，桌上都是”相符。", "爬": "搭配：“爬”多用于人或动物，牛奶不能爬出杯子。", "摇": "搭配：“摇”指晃动，不能说牛奶被摇出杯子，搭配不当。", "喊": "语义：“喊”需要有发声的主体，牛奶不能喊，句子不通。"}, "sentence_index": 6, "correct_answer": "流出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "钉子从箱子里流出来了。", "explanation": "这里应该用〈蹦出〉。“流出”只用于液体或气体，钉子是固体，应说蹦出来。"}, {"text": "硬币从口袋里流出来了。", "explanation": "这里应该用〈掉下〉。硬币是固体，“流出”只用于液体或气体，不能说流出。"}, {"text": "青蛙从池塘里流出来了。", "explanation": "这里应该用〈跳出〉。“流出”只用于液体或气体，青蛙是动物，应说跳出来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91446, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "机器漏油，油被流出来了。", "corrected_sentence": "机器漏油，油流出来了。", "error_description": "错误：不及物动词“流出”不能用“被”字句。正确：应说“油流出来了”，不加“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91446, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "伤口里的血流出去来了，很多。", "corrected_sentence": "伤口里的血流出来了，很多。", "error_description": "错误：趋向补语“去”与“来”不能并用。正确：应说“流出来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
