INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91447, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "波是水面上一起一伏的纹，像海浪一样。", "primary_collocate": null, "pronunciation": "bō", "ipa": "pwo˥", "syllable_count": 1, "sentences": [{"text": "风一吹，湖面上的波就大了。", "target_word": "波", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小石头落进水里，水面上有一圈圈的波。", "target_word": "波", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河面很平，一点波也没有。", "target_word": "波", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "船开过去以后，水里的波慢慢变小了。", "target_word": "波", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们看着水里的波一圈一圈散开。", "target_word": "波", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海上的波一个接一个地涌过来。", "target_word": "波", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天湖里没有风，水面上几乎没有波。", "target_word": "波", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他扔了一块石头，水中的波一直传到岸边。", "target_word": "波", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水面上的波很小，像鱼鳞一样。", "target_word": "波", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨点落下来，池塘里起了小小的波。", "target_word": "波", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "波浪", "label": "复合"}, {"form": "波纹", "label": "复合"}], "register": "中性", "sense_fingerprint": "波：水面上一起一伏的纹", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78a3ef50-e145-4c82-a7e3-e5ad63c2ba2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91447, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "波", "is_correct": true, "explanation": "正确。波（bō）指水面上一起一伏的纹。"}, {"text": "伯", "is_correct": false, "explanation": "伯（bó）与波（bō）声调不同，意思是伯伯、父亲的哥哥。"}, {"text": "脖", "is_correct": false, "explanation": "脖（bó）与波（bō）声调不同，意思是脖子。"}, {"text": "坡", "is_correct": false, "explanation": "坡（pō）与波（bō）的声母送气不同（p 与 b），意思是山坡。"}, {"text": "博", "is_correct": false, "explanation": "博（bó）与波（bō）声调不同，意思是博大、博士。"}], "explanations": {"波": "正确。波（bō）指水面上一起一伏的纹。", "伯": "伯（bó）与波（bō）声调不同，意思是伯伯、父亲的哥哥。", "脖": "脖（bó）与波（bō）声调不同，意思是脖子。", "坡": "坡（pō）与波（bō）的声母送气不同（p 与 b），意思是山坡。", "博": "博（bó）与波（bō）声调不同，意思是博大、博士。"}, "sentence_index": null, "correct_answer": "波"}, "level_3": {"options": [{"text": "波", "is_correct": true, "explanation": "正确。“风一吹，湖面上的波就大了”指风吹后水面的起伏变大，符合句意。"}, {"text": "字", "is_correct": false, "explanation": "语义：湖面上不会出现“字”，句子指水面的起伏，不通。"}, {"text": "梦", "is_correct": false, "explanation": "语义：“梦”不能出现在湖面上，也不能“就大了”，句子不通。"}, {"text": "桥", "is_correct": false, "explanation": "搭配：“桥”不会因风吹而“大了”，“湖面上的桥”也不是常用说法。"}], "explanations": {"波": "正确。“风一吹，湖面上的波就大了”指风吹后水面的起伏变大，符合句意。", "字": "语义：湖面上不会出现“字”，句子指水面的起伏，不通。", "梦": "语义：“梦”不能出现在湖面上，也不能“就大了”，句子不通。", "桥": "搭配：“桥”不会因风吹而“大了”，“湖面上的桥”也不是常用说法。"}, "sentence_index": 0, "correct_answer": "波"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的手指上有一圈圈的波。", "explanation": "这里应该用〈纹〉。指纹、木纹这类纹路用“纹”，水面起伏才用“波”。"}, {"text": "刀划过桌面，留下了一道深深的波。", "explanation": "这里应该用〈痕〉。划痕、印痕用“痕”，“波”只指水面的起伏。"}, {"text": "湖面上起了一棵波，慢慢散开了。", "explanation": "这里应该用〈圈〉。“棵”用于树木、植物，不能修饰水面的波，应说“一圈波”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91447, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "波", "is_correct": true, "explanation": "正确。波（bō）指水面上一起一伏的纹。"}, {"text": "泼", "is_correct": false, "explanation": "泼（pō）与波（bō）的声母送气不同（p 与 b），意思是泼洒。"}, {"text": "颇", "is_correct": false, "explanation": "颇（pō）与波（bō）的声母送气不同（p 与 b），意思是相当、很。"}, {"text": "伯", "is_correct": false, "explanation": "伯（bó）与波（bō）声调不同，意思是伯伯、父亲的哥哥。"}], "explanations": {"波": "正确。波（bō）指水面上一起一伏的纹。", "泼": "泼（pō）与波（bō）的声母送气不同（p 与 b），意思是泼洒。", "颇": "颇（pō）与波（bō）的声母送气不同（p 与 b），意思是相当、很。", "伯": "伯（bó）与波（bō）声调不同，意思是伯伯、父亲的哥哥。"}, "sentence_index": null, "correct_answer": "波"}, "level_3": {"options": [{"text": "波", "is_correct": true, "explanation": "正确。“没有风，水面上几乎没有波”表示水面平静，符合句意。"}, {"text": "雨", "is_correct": false, "explanation": "语义：“没有风”与“没有雨”没有因果关系，句意不通。"}, {"text": "火", "is_correct": false, "explanation": "语义：水面上不会有“火”，与语境冲突。"}, {"text": "歌", "is_correct": false, "explanation": "语义：“歌”不会出现在水面上，与“没有风”无关。"}], "explanations": {"波": "正确。“没有风，水面上几乎没有波”表示水面平静，符合句意。", "雨": "语义：“没有风”与“没有雨”没有因果关系，句意不通。", "火": "语义：水面上不会有“火”，与语境冲突。", "歌": "语义：“歌”不会出现在水面上，与“没有风”无关。"}, "sentence_index": 6, "correct_answer": "波"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "池塘里起了一尾波，很快就散开了。", "explanation": "这里应该用〈圈〉。“尾”用于鱼，不能修饰水面的波，应说“一圈圈的波”。"}, {"text": "雨停以后，湖面起了一滴波。", "explanation": "这里应该用〈道〉。“滴”只用于少量液体，不能修饰水面的波，应说“一道波”。"}, {"text": "小船划过湖面，身后拖出了一头波。", "explanation": "这里应该用〈道〉。“头”用于牛、羊等牲畜，不能修饰水面的波，应说“一道波”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91447, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一阵风吹过，湖面上起了一颗波。", "corrected_sentence": "一阵风吹过，湖面上起了一圈圈的波。", "error_description": "“波”的量词应为“圈”，“颗”用于圆粒状的东西，不能修饰水面的波，应改为“一圈圈的波”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91447, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一阵风吹过，湖面上泛起了细细波。", "corrected_sentence": "一阵风吹过，湖面上泛起了细细的波。", "error_description": "“细细”修饰“波”时要加“的”，应写成“细细的波”；“细细波”不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
