INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91450, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过节食、运动等减轻体重。", "primary_collocate": null, "pronunciation": "jiǎn féi", "ipa": "tɕjɛn˨˩˦ fei˧˥", "syllable_count": 2, "sentences": [{"text": "她每天跑步，是为了减肥。", "target_word": "减肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不吃晚饭，想靠节食减肥。", "target_word": "减肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说我要多运动，才能减肥。", "target_word": "减肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我正在减肥，不能吃蛋糕。", "target_word": "减肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坚持运动，半年就减肥成功了。", "target_word": "减肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她办了健身卡，准备减肥。", "target_word": "减肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "减肥时要少吃油多的东西。", "target_word": "减肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我试过节食减肥，但很难坚持。", "target_word": "减肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天走一万步也能帮你减肥。", "target_word": "减肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了减肥，他不再喝甜饮料了。", "target_word": "减肥", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "减过肥", "label": "体标"}, {"form": "减了肥", "label": "体标"}, {"form": "减肥药", "label": "复合"}], "register": "口语", "sense_fingerprint": "靠节食、运动等方法减轻体重", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e23a7c-9131-4a56-a854-f3c79c067e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91450, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "减肥", "is_correct": true, "explanation": "减肥：通过运动减轻体重，与句中的「为了」和「跑步」构成合理的目的关系，句意通顺。"}, {"text": "增重", "is_correct": false, "explanation": "语义：「增重」指体重增加，与跑步的目的（减轻体重）正好相反。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：跑步不是为了洗澡，「为了洗澡」与句意不符。"}, {"text": "上课", "is_correct": false, "explanation": "搭配：「是为了上课」不能说明跑步的目的，二者没有合理的目的关系。"}], "explanations": {"减肥": "减肥：通过运动减轻体重，与句中的「为了」和「跑步」构成合理的目的关系，句意通顺。", "增重": "语义：「增重」指体重增加，与跑步的目的（减轻体重）正好相反。", "洗澡": "语义：跑步不是为了洗澡，「为了洗澡」与句意不符。", "上课": "搭配：「是为了上课」不能说明跑步的目的，二者没有合理的目的关系。"}, "sentence_index": 0, "correct_answer": "减肥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司这个月的成本减肥了不少。", "explanation": "这里应该用〈降低〉。减肥只用于人的体重，成本、价格等数量的变化要用降低。"}, {"text": "这次手术后，他的心理压力减肥了很多。", "explanation": "这里应该用〈减轻〉。减肥只指身体变瘦，压力、负担要用减轻。"}, {"text": "今年的交通事故减肥了很多。", "explanation": "这里应该用〈减少〉。减肥只指身体变瘦，事故数量的变化要用减少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91450, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "减肥", "is_correct": true, "explanation": "减肥：指减轻体重，与「少吃油多的东西」的饮食要求相符，句意合理。"}, {"text": "增肥", "is_correct": false, "explanation": "语义：「增肥」是增加体重，与「少吃油多的东西」的目的相反。"}, {"text": "写作业", "is_correct": false, "explanation": "语义：「写作业时要少吃油多的东西」与句子表达的意思无关，不构成合理的饮食要求。"}, {"text": "减价", "is_correct": false, "explanation": "搭配：「减价」用于商品降价，不能用于人的饮食要求。"}], "explanations": {"减肥": "减肥：指减轻体重，与「少吃油多的东西」的饮食要求相符，句意合理。", "增肥": "语义：「增肥」是增加体重，与「少吃油多的东西」的目的相反。", "写作业": "语义：「写作业时要少吃油多的东西」与句子表达的意思无关，不构成合理的饮食要求。", "减价": "搭配：「减价」用于商品降价，不能用于人的饮食要求。"}, "sentence_index": 6, "correct_answer": "减肥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今年的房价减肥了不少。", "explanation": "这里应该用〈下降〉。减肥只指人的身体变瘦，房价的下跌要用下降。"}, {"text": "这次的手续费减肥了一部分。", "explanation": "这里应该用〈减免〉。减肥只用于身体，费用的免除或减少要用减免。"}, {"text": "公司的预算减肥了一百万。", "explanation": "这里应该用〈削减〉。减肥指身体减重，预算的减少要用削减。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91450, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年成功减肥，体重减肥掉了十公斤。", "corrected_sentence": "他去年成功减肥，体重减掉了十公斤。", "error_description": "错误：「减肥掉了」，正确：「减掉了」。主语已是「体重」，后面又有数量「十公斤」，应该用「减掉＋数量」，不能再带宾语「肥」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91450, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他减肥得很快，一个月就瘦了五公斤。", "corrected_sentence": "他减肥减得很快，一个月就瘦了五公斤。", "error_description": "错误：「减肥得很快」，正确：「减肥减得很快」。带补语「得」的离合词，要先重复动词「减」，说「减肥减得」，不能直接在「减肥」后面加「得」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
