INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91451, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "球队是一起踢球或打球的一群人。", "primary_collocate": null, "pronunciation": "qiú duì", "ipa": "tɕʰi̯ou̯˧˥ tu̯eɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "我们几个朋友组了一个球队。", "target_word": "球队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末，球队的人一起去踢球。", "target_word": "球队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个球队里有老人，也有小孩。", "target_word": "球队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们球队每个星期六下午都踢球。", "target_word": "球队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队的孩子们在草地上跑来跑去。", "target_word": "球队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚搬来，想找一个球队一起打球。", "target_word": "球队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家在公园里分成两个球队。", "target_word": "球队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队里的人都叫他小王。", "target_word": "球队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，球队的人都回家了。", "target_word": "球队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的球队没有教练，大家轮流带队。", "target_word": "球队", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "支", "label": "量词"}, {"form": "足球队", "label": "复合"}], "register": "中性", "sense_fingerprint": "朋友或邻居自己组成、一起踢球打球玩的一群人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '058bf7b9-c599-498a-840c-e5af9b2c9c86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91451, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "球队", "is_correct": true, "explanation": "“球队”指一起踢球或打球的一群人，朋友可以组成它，句意完整。"}, {"text": "合同", "is_correct": false, "explanation": "搭配：“组”搭配的是人群或团体，不能说“组了一个合同”。"}, {"text": "饭店", "is_correct": false, "explanation": "语义：饭店是提供服务的场所，不能由几个朋友组成。"}, {"text": "球场", "is_correct": false, "explanation": "语义：球场是场地，不能由几个朋友组成。"}], "explanations": {"球队": "“球队”指一起踢球或打球的一群人，朋友可以组成它，句意完整。", "合同": "搭配：“组”搭配的是人群或团体，不能说“组了一个合同”。", "饭店": "语义：饭店是提供服务的场所，不能由几个朋友组成。", "球场": "语义：球场是场地，不能由几个朋友组成。"}, "sentence_index": 0, "correct_answer": "球队"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们球队每天下午都练琴。", "explanation": "这里应该用〈乐队〉。球队指一起踢球或打球的一群人，练琴的要用乐队。"}, {"text": "球队在实验室里做实验。", "explanation": "这里应该用〈研究小组〉。球队指一起踢球或打球的一群人，在实验室里做实验要用研究小组。"}, {"text": "球队正在排演一出话剧。", "explanation": "这里应该用〈剧团〉。球队指踢球或打球的一群人，排演话剧要用剧团。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91451, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "球队", "is_correct": true, "explanation": "“球队”是一群人组成的团体，可以被“分成两个”，句意完整。"}, {"text": "操场", "is_correct": false, "explanation": "语义：操场是场地，不能被分成两个团队。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是可以分组的人群或团体。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“分成两个”用于可分的人群或团体，书包不能这样分。"}], "explanations": {"球队": "“球队”是一群人组成的团体，可以被“分成两个”，句意完整。", "操场": "语义：操场是场地，不能被分成两个团队。", "颜色": "语义：颜色不是可以分组的人群或团体。", "书包": "搭配：“分成两个”用于可分的人群或团体，书包不能这样分。"}, "sentence_index": 6, "correct_answer": "球队"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们几个同学组了一个球队，每周一起读书。", "explanation": "这里应该用〈读书会〉。球队指一起踢球或打球的一群人，一起读书要用读书会。"}, {"text": "我们几个邻居组了一个球队，每天一起唱歌。", "explanation": "这里应该用〈合唱团〉。球队指一起踢球或打球的一群人，一起唱歌要用合唱团。"}, {"text": "下班以后，同事们组了一个球队，一起研究新技术。", "explanation": "这里应该用〈研究小组〉。球队指一起踢球或打球的一群人，研究技术要用研究小组。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91451, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们那名球队去年和邻居踢过一场球。", "corrected_sentence": "我们那个球队去年和邻居踢过一场球。", "error_description": "量词错误：球队是一群人，用“个”，“名”只用于单个人，应说“那个球队”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91451, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们小区有一张球队，周末大家一起踢球。", "corrected_sentence": "我们小区有一个球队，周末大家一起踢球。", "error_description": "量词错误：“张”用于纸、桌子等平面的东西。球队是一群人，要用“个”，应说“一个球队”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
