INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91452, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "参加球类比赛的运动队。", "primary_collocate": null, "pronunciation": "qiú duì", "ipa": "tɕʰi̯ou̯˧˥ tu̯eɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "这支球队今天赢了比赛。", "target_word": "球队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校的球队明天和别的学校比赛。", "target_word": "球队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那支球队有十一个球员，教练很年轻。", "target_word": "球队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队在球场上练习了两个小时。", "target_word": "球队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这支球队里跑得最快的球员。", "target_word": "球队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的球队去年拿了冠军。", "target_word": "球队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队输了比赛，球迷们都很难过。", "target_word": "球队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队要去北京参加比赛，明天坐飞机。", "target_word": "球队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想加入这支球队，每天去练球。", "target_word": "球队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板花钱买了一支球队。", "target_word": "球队", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "支", "label": "量词"}, {"form": "篮球队", "label": "复合"}, {"form": "足球队", "label": "复合"}], "register": "中性", "sense_fingerprint": "参加比赛的运动队，有教练和球员，代表学校或城市", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '058bf7b9-c599-498a-840c-e5af9b2c9c86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91452, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "球队", "is_correct": true, "explanation": "“球队”指参加比赛的运动队，可以被“这支”修饰，并且能作为赢球的主体，句意完整。"}, {"text": "球迷", "is_correct": false, "explanation": "语义：球迷是观看比赛的人，不会赢比赛。"}, {"text": "教练", "is_correct": false, "explanation": "搭配：“支”用于成队的人或物，不能用来数一名教练。"}, {"text": "球场", "is_correct": false, "explanation": "语义：球场是比赛的场地，不能作为赢球的主体。"}], "explanations": {"球队": "“球队”指参加比赛的运动队，可以被“这支”修饰，并且能作为赢球的主体，句意完整。", "球迷": "语义：球迷是观看比赛的人，不会赢比赛。", "教练": "搭配：“支”用于成队的人或物，不能用来数一名教练。", "球场": "语义：球场是比赛的场地，不能作为赢球的主体。"}, "sentence_index": 0, "correct_answer": "球队"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的球队要去远方执行任务。", "explanation": "这里应该用〈队伍〉。球队只指参加球类比赛的运动队，去远方执行任务等非体育活动要用队伍。"}, {"text": "他是我们队里的球队，每天练球。", "explanation": "这里应该用〈球员〉。球队指整支队伍，不能用来指队里的某一个人。"}, {"text": "球队在灾区给病人看病。", "explanation": "这里应该用〈医疗队〉。球队指参加球类比赛的运动队，在灾区给病人看病要用医疗队。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91452, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "球队", "is_correct": true, "explanation": "“球队”是参赛的一方，可以作“输了比赛”的主语，与“球迷们都很难过”前后呼应。"}, {"text": "裁判", "is_correct": false, "explanation": "语义：裁判只负责执法，不参加比赛，不会输掉比赛。"}, {"text": "球馆", "is_correct": false, "explanation": "语义：球馆是比赛的场地，不能作为输掉比赛的一方。"}, {"text": "观众", "is_correct": false, "explanation": "配价：“输”要求参赛的一方作主语，观众不是参赛方。"}], "explanations": {"球队": "“球队”是参赛的一方，可以作“输了比赛”的主语，与“球迷们都很难过”前后呼应。", "裁判": "语义：裁判只负责执法，不参加比赛，不会输掉比赛。", "球馆": "语义：球馆是比赛的场地，不能作为输掉比赛的一方。", "观众": "配价：“输”要求参赛的一方作主语，观众不是参赛方。"}, "sentence_index": 6, "correct_answer": "球队"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所学校的球队每周给学生上数学课。", "explanation": "这里应该用〈教研组〉。球队指参加比赛的运动队，给学生上课要用教研组。"}, {"text": "我们学校的球队每天在社区里发放食品。", "explanation": "这里应该用〈志愿者团队〉。球队指参加比赛的运动队，在社区发放食品要用志愿者团队。"}, {"text": "那支球队专门负责给病人做手术。", "explanation": "这里应该用〈医疗队〉。球队指参加比赛的运动队，给病人做手术要用医疗队。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91452, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这名球队今天赢了那场比赛。", "corrected_sentence": "这支球队今天赢了那场比赛。", "error_description": "量词错误：球队用“支”，“名”用于单个人，不能用来数球队，应说“这支球队”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91452, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们城市去年新成立了一只球队。", "corrected_sentence": "我们城市去年新成立了一支球队。", "error_description": "量词错误：“只”用于动物等，球队要用“支”，应说“一支球队”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91453, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "粗糙", "is_correct": true, "explanation": "粗糙：表面不平、不光溜，与“滑”构成反义。"}, {"text": "宽敞", "is_correct": false, "explanation": "宽敞：说空间大，与“滑”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "安静：说不吵闹，与“滑”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮：说光线强，与“滑”没有反义关系。"}], "correct_answer": "粗糙", "explanations": {"粗糙": "粗糙：表面不平、不光溜，与“滑”构成反义。", "宽敞": "宽敞：说空间大，与“滑”没有反义关系。", "安静": "安静：说不吵闹，与“滑”没有反义关系。", "明亮": "明亮：说光线强，与“滑”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91453, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "粗糙", "is_correct": true, "explanation": "粗糙：表面不平滑，与“滑”构成反义。"}, {"text": "宽敞", "is_correct": false, "explanation": "宽敞：说空间大，与“滑”没有反义关系。"}, {"text": "勇敢", "is_correct": false, "explanation": "勇敢：说胆量大，与“滑”没有反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮：说外貌好看，与“滑”没有反义关系。"}], "correct_answer": "粗糙", "explanations": {"粗糙": "粗糙：表面不平滑，与“滑”构成反义。", "宽敞": "宽敞：说空间大，与“滑”没有反义关系。", "勇敢": "勇敢：说胆量大，与“滑”没有反义关系。", "漂亮": "漂亮：说外貌好看，与“滑”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91453, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "滑是表面很平，东西容易溜走。", "primary_collocate": null, "pronunciation": "huá", "ipa": "xua˧˥", "syllable_count": 1, "sentences": [{"text": "下雨以后，路很滑。", "target_word": "滑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地板刚拖过，有点滑，小心点儿。", "target_word": "滑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天路上结了冰，特别滑。", "target_word": "滑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋的底太滑，走路不安全。", "target_word": "滑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨天山路很滑，你慢点走。", "target_word": "滑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浴室的地砖湿了，很滑，要小心。", "target_word": "滑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台阶上有水，非常滑。", "target_word": "滑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼梯太滑了，奶奶不敢下去。", "target_word": "滑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪后的桥面又湿又滑，开车要慢。", "target_word": "滑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子上有油，太滑，我拿不住。", "target_word": "滑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "表面平整湿润，人或物容易滑倒、滑走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f1d42d-5220-4b0c-9fb7-df56a4a71c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91453, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "滑", "is_correct": true, "explanation": "滑：huá，指表面平整光溜、东西容易溜走，是本条的目标词。"}, {"text": "花", "is_correct": false, "explanation": "声调不同：huá（第二声）与 huā（第一声）只差声调，意思是花。"}, {"text": "话", "is_correct": false, "explanation": "声调不同：huá（第二声）与 huà（第四声）只差声调，意思是话语。"}, {"text": "画", "is_correct": false, "explanation": "声调不同：huá（第二声）与 huà（第四声）只差声调，意思是绘画。"}, {"text": "怀", "is_correct": false, "explanation": "韵母不同：huá 的 ua 与 huái 的 uai 不同，意思是怀抱。"}], "explanations": {"滑": "滑：huá，指表面平整光溜、东西容易溜走，是本条的目标词。", "花": "声调不同：huá（第二声）与 huā（第一声）只差声调，意思是花。", "话": "声调不同：huá（第二声）与 huà（第四声）只差声调，意思是话语。", "画": "声调不同：huá（第二声）与 huà（第四声）只差声调，意思是绘画。", "怀": "韵母不同：huá 的 ua 与 huái 的 uai 不同，意思是怀抱。"}, "sentence_index": null, "correct_answer": "滑"}, "level_3": {"options": [{"text": "滑", "is_correct": true, "explanation": "滑：指路面光溜、容易滑倒，符合下雨后的语境。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：下雨以后路面应是湿的，说“干燥”与雨后的语境矛盾。"}, {"text": "滚烫", "is_correct": false, "explanation": "搭配：“滚烫”形容液体或器物的温度，不用来形容路面。"}, {"text": "嫩绿", "is_correct": false, "explanation": "搭配：“嫩绿”形容植物或颜色，不用来形容路面。"}], "explanations": {"滑": "滑：指路面光溜、容易滑倒，符合下雨后的语境。", "干燥": "语义：下雨以后路面应是湿的，说“干燥”与雨后的语境矛盾。", "滚烫": "搭配：“滚烫”形容液体或器物的温度，不用来形容路面。", "嫩绿": "搭配：“嫩绿”形容植物或颜色，不用来形容路面。"}, "sentence_index": 0, "correct_answer": "滑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块木头很滑，摸上去扎手。", "explanation": "这里应该用〈粗糙〉。滑表示表面光溜、容易溜走，描写摸上去扎手的木头要用粗糙。"}, {"text": "清晨的空气很滑，吸进肺里很舒服。", "explanation": "这里应该用〈湿润〉。滑描写表面光溜、容易溜走，形容空气应用湿润。"}, {"text": "这块饼烤得很滑，咬一口很脆。", "explanation": "这里应该用〈焦〉。滑形容表面光溜，烤饼的表面状态要用焦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91453, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "滑", "is_correct": true, "explanation": "滑：huá，指表面平整光溜、东西容易溜走，是本条的目标词。"}, {"text": "化", "is_correct": false, "explanation": "声调不同：huá（第二声）与 huà（第四声）只差声调，意思是变化。"}, {"text": "壶", "is_correct": false, "explanation": "韵母不同：huá 的 ua 与 hú 的 u 不同，声调相同，意思是水壶。"}, {"text": "花", "is_correct": false, "explanation": "声调不同：huá（第二声）与 huā（第一声）只差声调，意思是花。"}, {"text": "话", "is_correct": false, "explanation": "声调不同：huá（第二声）与 huà（第四声）只差声调，意思是话语。"}], "explanations": {"滑": "滑：huá，指表面平整光溜、东西容易溜走，是本条的目标词。", "化": "声调不同：huá（第二声）与 huà（第四声）只差声调，意思是变化。", "壶": "韵母不同：huá 的 ua 与 hú 的 u 不同，声调相同，意思是水壶。", "花": "声调不同：huá（第二声）与 huā（第一声）只差声调，意思是花。", "话": "声调不同：huá（第二声）与 huà（第四声）只差声调，意思是话语。"}, "sentence_index": null, "correct_answer": "滑"}, "level_3": {"options": [{"text": "滑", "is_correct": true, "explanation": "滑：台阶有水时表面光溜、容易溜走，符合“非常”的语境。"}, {"text": "干爽", "is_correct": false, "explanation": "语义：台阶上有水，说“干爽”与语境矛盾。"}, {"text": "漆黑", "is_correct": false, "explanation": "搭配：“漆黑”形容颜色或夜色，不用来形容台阶的状态。"}, {"text": "雪白", "is_correct": false, "explanation": "搭配：“雪白”形容颜色，不用来形容台阶湿或滑的状态。"}], "explanations": {"滑": "滑：台阶有水时表面光溜、容易溜走，符合“非常”的语境。", "干爽": "语义：台阶上有水，说“干爽”与语境矛盾。", "漆黑": "搭配：“漆黑”形容颜色或夜色，不用来形容台阶的状态。", "雪白": "搭配：“雪白”形容颜色，不用来形容台阶湿或滑的状态。"}, "sentence_index": 6, "correct_answer": "滑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块石头很滑，摸上去坑坑洼洼的。", "explanation": "这里应该用〈粗糙〉。滑指表面光溜、容易溜走，摸上去坑坑洼洼的石头要用粗糙。"}, {"text": "这丛草很滑，碰到就疼。", "explanation": "这里应该用〈扎人〉。滑表示表面光溜、不扎人，描写碰到就刺痛的草要用扎人。"}, {"text": "这块地很滑，适合种庄稼。", "explanation": "这里应该用〈平〉。滑形容表面容易溜走，说土地的平整要用平。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91453, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨后的台阶滑很，爷爷走路要扶着栏杆。", "corrected_sentence": "雨后的台阶很滑，爷爷走路要扶着栏杆。", "error_description": "错误在于“很”的位置：应放在“滑”前面，说“很滑”，不能说“滑很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91453, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "楼梯滑一点儿，奶奶不敢下去。", "corrected_sentence": "楼梯有点滑，奶奶不敢下去。", "error_description": "错误在于程度表达：说不如意的状态时，“有点儿”要放在形容词前面，应说“有点滑”。“滑一点儿”是用来比较的说法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91455, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高兴", "is_correct": true, "explanation": "高兴指心里愉快，与“生气”意思相反，是反义词。"}, {"text": "安静", "is_correct": false, "explanation": "安静形容没有声音或状态平和，与“生气”不构成反义关系。"}, {"text": "整理", "is_correct": false, "explanation": "整理指把东西收拾得有条理，与“生气”不构成反义关系。"}, {"text": "迟到", "is_correct": false, "explanation": "迟到指超过规定时间才到，与“生气”不构成反义关系。"}], "correct_answer": "高兴", "explanations": {"高兴": "高兴指心里愉快，与“生气”意思相反，是反义词。", "安静": "安静形容没有声音或状态平和，与“生气”不构成反义关系。", "整理": "整理指把东西收拾得有条理，与“生气”不构成反义关系。", "迟到": "迟到指超过规定时间才到，与“生气”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f04b711-8b52-447c-8ee9-e5931ba22acb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
