INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91455, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "生气是你很不高兴，心里发火。", "primary_collocate": null, "pronunciation": "shēng qì", "ipa": "ʂɤŋ˥ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "你别生气，我不是故意的。", "target_word": "生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈看到房间很乱，很生气。", "target_word": "生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天一直不说话，好像在生气。", "target_word": "生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我生气了，不想和他说话。", "target_word": "生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别跟小孩子生气。", "target_word": "生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个消息，她非常生气。", "target_word": "生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥生气的时候，脸红红的。", "target_word": "生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么这么生气？", "target_word": "生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸今天不生气了。", "target_word": "生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很生气，所以关上门走了。", "target_word": "生气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生气了", "label": "体标（了）"}], "register": "口语", "sense_fingerprint": "生气：心里很不高兴、发火的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05e66eed-24af-4555-9219-89fc197dcac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91455, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生气", "is_correct": true, "explanation": "生气指心里很不高兴、发火，是本题的正确答案。"}, {"text": "升起", "is_correct": false, "explanation": "shēng qǐ（第三声）与 shēng qì（第四声）声调不同，意思是向上升。"}, {"text": "升旗", "is_correct": false, "explanation": "shēng qí（第二声）与 shēng qì（第四声）声调不同，意思是把旗子升上去。"}, {"text": "生漆", "is_correct": false, "explanation": "shēng qī（第一声）与 shēng qì（第四声）声调不同，意思是一种天然涂料。"}], "explanations": {"生气": "生气指心里很不高兴、发火，是本题的正确答案。", "升起": "shēng qǐ（第三声）与 shēng qì（第四声）声调不同，意思是向上升。", "升旗": "shēng qí（第二声）与 shēng qì（第四声）声调不同，意思是把旗子升上去。", "生漆": "shēng qī（第一声）与 shēng qì（第四声）声调不同，意思是一种天然涂料。"}, "sentence_index": null, "correct_answer": "生气"}, "level_3": {"options": [{"text": "生气", "is_correct": true, "explanation": "生气指因不满而不高兴，此处是对方因误会而不高兴，正确。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“我不是故意的”是道歉，与“你别散步”没有关联，句子不通。"}, {"text": "讨论", "is_correct": false, "explanation": "配价：“讨论”需要说明讨论什么，“你别讨论”后接道歉，语义接不上。"}, {"text": "下棋", "is_correct": false, "explanation": "语义：下棋是娱乐活动，与“我不是故意的”的道歉不搭。"}], "explanations": {"生气": "生气指因不满而不高兴，此处是对方因误会而不高兴，正确。", "散步": "语义：“我不是故意的”是道歉，与“你别散步”没有关联，句子不通。", "讨论": "配价：“讨论”需要说明讨论什么，“你别讨论”后接道歉，语义接不上。", "下棋": "语义：下棋是娱乐活动，与“我不是故意的”的道歉不搭。"}, "sentence_index": 0, "correct_answer": "生气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "半夜独自走夜路，她很生气。", "explanation": "这里应该用〈害怕〉。生气表示因不满而发怒，夜路上的恐惧应说害怕。"}, {"text": "收到生日礼物的时候，他很生气。", "explanation": "这里应该用〈高兴〉。生气表示因不满而发怒，收到礼物应该高兴，不能说生气。"}, {"text": "考试拿到了满分，他心里很生气。", "explanation": "这里应该用〈自豪〉。生气表示因不满而发怒，考了满分应该自豪，不能说生气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f04b711-8b52-447c-8ee9-e5931ba22acb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91455, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "生气", "is_correct": true, "explanation": "生气指心里很不高兴、发火，是本题的正确答案。"}, {"text": "生意", "is_correct": false, "explanation": "yì（第四声）与 qì（第四声）声母不同，意思是买卖。"}, {"text": "生日", "is_correct": false, "explanation": "rì（第四声）与 qì（第四声）声母不同，意思是出生的那一天。"}, {"text": "升旗", "is_correct": false, "explanation": "shēng qí（第二声）与 shēng qì（第四声）声调不同，意思是把旗子升上去。"}], "explanations": {"生气": "生气指心里很不高兴、发火，是本题的正确答案。", "生意": "yì（第四声）与 qì（第四声）声母不同，意思是买卖。", "生日": "rì（第四声）与 qì（第四声）声母不同，意思是出生的那一天。", "升旗": "shēng qí（第二声）与 shēng qì（第四声）声调不同，意思是把旗子升上去。"}, "sentence_index": null, "correct_answer": "生气"}, "level_3": {"options": [{"text": "生气", "is_correct": true, "explanation": "生气指因不满而发怒的状态，此处描写哥哥发怒时的样子，正确。"}, {"text": "打开", "is_correct": false, "explanation": "配价：“打开”后面要有宾语，“哥哥打开的时候”不完整，句子不通。"}, {"text": "保管", "is_correct": false, "explanation": "配价：“保管”需要保管的东西，此处缺少宾语。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”的主语是天气，不能用“哥哥……的时候”来说人。"}], "explanations": {"生气": "生气指因不满而发怒的状态，此处描写哥哥发怒时的样子，正确。", "打开": "配价：“打开”后面要有宾语，“哥哥打开的时候”不完整，句子不通。", "保管": "配价：“保管”需要保管的东西，此处缺少宾语。", "下雨": "语义：“下雨”的主语是天气，不能用“哥哥……的时候”来说人。"}, "sentence_index": 6, "correct_answer": "生气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们在公园里玩得很生气，笑个不停。", "explanation": "这里应该用〈开心〉。生气表示因不满而发怒，玩得愉快时不能说生气。"}, {"text": "开学第一天，他很生气，不停地跟同学聊天。", "explanation": "这里应该用〈兴奋〉。生气表示因不满而发怒，开学第一天见到同学的心情应说兴奋。"}, {"text": "孩子的第一次笑声，让她很生气。", "explanation": "这里应该用〈感动〉。生气表示因不满而发怒，听到孩子笑声的温暖心情应说感动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f04b711-8b52-447c-8ee9-e5931ba22acb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91455, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他又生气了我的气。", "corrected_sentence": "他又生了我的气。", "error_description": "离合词错误：“生气”是离合词，不能直接带宾语，应说“生了……的气”，此处应改为“他又生了我的气”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f04b711-8b52-447c-8ee9-e5931ba22acb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91455, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她生气了地关上了门。", "corrected_sentence": "她生气地关上了门。", "error_description": "体标位置错误：“生气了”后不能直接接状语“地”修饰动词，“了”表示完成，应去掉，说“她生气地关上了门”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f04b711-8b52-447c-8ee9-e5931ba22acb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
