INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91458, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "按预定方案进行的军事或应急演练。", "primary_collocate": null, "pronunciation": "yǎn xí", "ipa": "jɛn˨˩ ɕi˧˥", "syllable_count": 2, "sentences": [{"text": "军队在海边举行了大型演习。", "target_word": "演习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校今天上午进行消防演习。", "target_word": "演习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震演习时，同学们都躲到桌子下面。", "target_word": "演习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国海军将在下个月举行联合演习。", "target_word": "演习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次演习的目的是提高应急能力。", "target_word": "演习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府组织居民进行防洪演习。", "target_word": "演习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演习开始以后，消防车很快赶到了。", "target_word": "演习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部队正在山区进行实弹演习。", "target_word": "演习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了应对火灾，公司每年都有一次演习。", "target_word": "演习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演习结束后，指挥官总结了经验。", "target_word": "演习", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "军事演习", "label": "复合"}, {"form": "消防演习", "label": "复合"}, {"form": "一场演习", "label": "量词"}, {"form": "一次演习", "label": "量词"}], "register": "中性", "sense_fingerprint": "军队或单位按预定方案进行的军事、消防等应急演练", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f1d42d-5220-4b0c-9fb7-df56a4a71c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91458, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "演习", "is_correct": true, "explanation": "正确。演习指军队或单位按预定方案进行的军事或应急演练。"}, {"text": "演戏", "is_correct": false, "explanation": "演戏（xì）与演习（xí）第二个音节声调不同，意思是表演戏剧。"}, {"text": "研习", "is_correct": false, "explanation": "研习（yán）与演习（yǎn）第一个音节声调不同，意思是钻研学习。"}, {"text": "宴席", "is_correct": false, "explanation": "宴席（yàn）与演习（yǎn）第一个音节声调不同，意思是宴会上的酒席。"}, {"text": "沿袭", "is_correct": false, "explanation": "沿袭（yán）与演习（yǎn）第一个音节声调不同，意思是沿用旧的做法。"}], "explanations": {"演习": "正确。演习指军队或单位按预定方案进行的军事或应急演练。", "演戏": "演戏（xì）与演习（xí）第二个音节声调不同，意思是表演戏剧。", "研习": "研习（yán）与演习（yǎn）第一个音节声调不同，意思是钻研学习。", "宴席": "宴席（yàn）与演习（yǎn）第一个音节声调不同，意思是宴会上的酒席。", "沿袭": "沿袭（yán）与演习（yǎn）第一个音节声调不同，意思是沿用旧的做法。"}, "sentence_index": null, "correct_answer": "演习"}, "level_3": {"options": [{"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是疾病，不能“举行”，句子读不通。"}, {"text": "演习", "is_correct": true, "explanation": "正确。演习指按预定方案进行的军事演练，“军队在海边举行了大型演习”合乎语境。"}, {"text": "午睡", "is_correct": false, "explanation": "语义：“午睡”是个人休息，不能“举行”，与军队的大型活动不符。"}, {"text": "生日派对", "is_correct": false, "explanation": "语义：军队在海边举办生日派对，与军事活动的语境不符。"}], "explanations": {"感冒": "语义：“感冒”是疾病，不能“举行”，句子读不通。", "演习": "正确。演习指按预定方案进行的军事演练，“军队在海边举行了大型演习”合乎语境。", "午睡": "语义：“午睡”是个人休息，不能“举行”，与军队的大型活动不符。", "生日派对": "语义：军队在海边举办生日派对，与军事活动的语境不符。"}, "sentence_index": 0, "correct_answer": "演习"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在医院演习了半年。", "explanation": "这里应该用〈实习〉。演习指按预定方案进行的军事或应急演练，在医院学习业务要用实习。"}, {"text": "我每天晚上都演习英语单词。", "explanation": "这里应该用〈复习〉。演习指按预定方案进行的演练，温习已学的单词要用复习。"}, {"text": "他把房间演习了一遍。", "explanation": "这里应该用〈打扫〉。演习指按预定方案的演练或为正式做事先练一遍，打扫房间是日常家务，要用打扫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91458, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "课程", "is_correct": false, "explanation": "语义：“课程”与消防车赶到的紧急情况无关，句子语义不通。"}, {"text": "讲座", "is_correct": false, "explanation": "语义：讲座开始以后不会有消防车赶来，与句中的紧急情况矛盾。"}, {"text": "演习", "is_correct": true, "explanation": "正确。演习开始以后，消防车赶来参与应急处置，句子合乎语境。"}, {"text": "晨读", "is_correct": false, "explanation": "语义：晨读是日常学习活动，与消防车赶到的应急情境不符。"}], "explanations": {"课程": "语义：“课程”与消防车赶到的紧急情况无关，句子语义不通。", "讲座": "语义：讲座开始以后不会有消防车赶来，与句中的紧急情况矛盾。", "演习": "正确。演习开始以后，消防车赶来参与应急处置，句子合乎语境。", "晨读": "语义：晨读是日常学习活动，与消防车赶到的应急情境不符。"}, "sentence_index": 6, "correct_answer": "演习"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这篇文章演习成了英文。", "explanation": "这里应该用〈翻译〉。演习指军事或应急的按方案演练，把文字转成另一种语言要用翻译。"}, {"text": "我今天穿了一件新演习。", "explanation": "这里应该用〈衣服〉。演习指军事或应急的按方案演练，不是可以穿的东西。"}, {"text": "妈妈每天晚上演习碗。", "explanation": "这里应该用〈洗〉。演习指军事或应急的按方案演练，洗碗是日常家务，不能用演习。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91458, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校上午进行了一张消防演习。", "corrected_sentence": "学校上午进行了一次消防演习。", "error_description": "错误在于量词：“演习”用“次”或“场”，不能用“张”，应说“一次消防演习”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91458, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "去年冬天，工厂组织了一张防火演习。", "corrected_sentence": "去年冬天，工厂组织了一次防火演习。", "error_description": "错误在于量词：“演习”用“次”或“场”，不能用“张”，应说“一次防火演习”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
