INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91460, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "双方订立条约或合同并签字。", "primary_collocate": null, "pronunciation": "qiān dìng", "ipa": "tɕʰi̯ɛn˥ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "两家公司今天签订了合同。", "target_word": "签订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司和工人签订了三年的合同。", "target_word": "签订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国领导人在北京签订了条约。", "target_word": "签订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房东和我签订了租房合同。", "target_word": "签订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方签订合同以后，就不能改了。", "target_word": "签订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明天去银行签订买房合同。", "target_word": "签订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队和他签订了新合同。", "target_word": "签订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "签订合同以前，请你先看清楚。", "target_word": "签订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们终于签订了那份合同。", "target_word": "签订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校和公司签订了合作的协议。", "target_word": "签订", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "签订了", "label": "体标"}, {"form": "签订过", "label": "体标"}, {"form": "签订好", "label": "结果补语"}], "register": "正式", "sense_fingerprint": "双方正式订立合同、条约或协议并签字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '058bf7b9-c599-498a-840c-e5af9b2c9c86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91460, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "签订", "is_correct": true, "explanation": "“签订”表示双方订立合同，与“两家公司”和“合同”搭配，句意完整。"}, {"text": "吃", "is_correct": false, "explanation": "语义：合同是文件，不能吃。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能搭配“合同”，合同不能被唱。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语要是饮品，不能搭配“合同”。"}], "explanations": {"签订": "“签订”表示双方订立合同，与“两家公司”和“合同”搭配，句意完整。", "吃": "语义：合同是文件，不能吃。", "唱": "搭配：“唱”不能搭配“合同”，合同不能被唱。", "喝": "搭配：“喝”的宾语要是饮品，不能搭配“合同”。"}, "sentence_index": 0, "correct_answer": "签订"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "总统签订了这项法律。", "explanation": "这里应该用〈签署〉。签订指双方订立合同或条约，总统单方面签署法律要用签署。"}, {"text": "我在快递单上签订了包裹。", "explanation": "这里应该用〈签收〉。签订指双方订约，收到包裹在快递单上签名要用签收。"}, {"text": "我在网上签订了一本书。", "explanation": "这里应该用〈订购〉。签订用于合同、协议等书面约定，买书要用订购。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91460, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "签订", "is_correct": true, "explanation": "“签订”表示双方订立合同，与“球队和他”和“新合同”搭配，句意完整。"}, {"text": "踢", "is_correct": false, "explanation": "语义：合同不能用脚去踢，“踢了新合同”说不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能搭配“合同”，合同不能被洗。"}, {"text": "养", "is_correct": false, "explanation": "配价：“养”要求有生命的宾语，“合同”不能作“养”的对象。"}], "explanations": {"签订": "“签订”表示双方订立合同，与“球队和他”和“新合同”搭配，句意完整。", "踢": "语义：合同不能用脚去踢，“踢了新合同”说不通。", "洗": "搭配：“洗”不能搭配“合同”，合同不能被洗。", "养": "配价：“养”要求有生命的宾语，“合同”不能作“养”的对象。"}, "sentence_index": 6, "correct_answer": "签订"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两家公司签订了友谊。", "explanation": "这里应该用〈建立〉。友谊是建立的，签订只用于合同、协议等书面约定。"}, {"text": "我们俩签订了一次约会。", "explanation": "这里应该用〈约定〉。约会可以约定，不能签订；签订用于合同或协议。"}, {"text": "他和朋友签订了一次聚会。", "explanation": "这里应该用〈举办〉。聚会是举办的，不能签订。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91460, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两家公司去年签订着供货合同。", "corrected_sentence": "这两家公司去年签订过供货合同。", "error_description": "体标错误：表示经历过的动作要用“过”，“着”表示动作持续，不能用于“去年”已经完成的签订，应说“签订过供货合同”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91460, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两家公司昨天没签订了协议。", "corrected_sentence": "两家公司昨天没签订协议。", "error_description": "“没”与“了”不能同时用于同一动作：否定未发生的动作时“了”要去掉，应说“没签订协议”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
