INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91462, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由受激辐射产生的、方向性强、亮度高的光。", "primary_collocate": null, "pronunciation": "jī guāng", "ipa": "tɕi˥ kwɑŋ˥", "syllable_count": 2, "sentences": [{"text": "医生用激光给病人做手术。", "target_word": "激光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞台上有红色的激光。", "target_word": "激光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "激光很亮，不要直接看。", "target_word": "激光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "激光可以切开很硬的铁。", "target_word": "激光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一束绿色的激光照到墙上。", "target_word": "激光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种激光的方向性很强。", "target_word": "激光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用激光测量房间的长度。", "target_word": "激光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "激光已经用在很多医院里。", "target_word": "激光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，激光从山顶射向天空。", "target_word": "激光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把激光对准了远处的目标。", "target_word": "激光", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "束", "label": "量词"}, {"form": "激光器", "label": "复合词"}, {"form": "激光笔", "label": "复合词"}], "register": "中性", "sense_fingerprint": "受激辐射产生的方向性强、亮度高的光", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ebe5ac-3a97-4d64-8d3b-45e11368ef3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91462, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "激光", "is_correct": true, "explanation": "激光（jī guāng）：由受激辐射产生、方向性强、亮度高的光，是正确答案。"}, {"text": "机关", "is_correct": false, "explanation": "机关（jī guān）：第二个音节 guān 比 guāng 少了鼻音韵尾 -ng（an 与 ang 不同），声调相同，意思是机械的构造或机构。"}, {"text": "吃光", "is_correct": false, "explanation": "吃光（chī guāng）：声母 ch 与 j 不同，声调相同（第一声），意思是把东西全部吃完。"}, {"text": "极光", "is_correct": false, "explanation": "极光（jí guāng）：第一个音节声调不同（第二声），意思是极地上空出现的彩色光带。"}], "explanations": {"激光": "激光（jī guāng）：由受激辐射产生、方向性强、亮度高的光，是正确答案。", "机关": "机关（jī guān）：第二个音节 guān 比 guāng 少了鼻音韵尾 -ng（an 与 ang 不同），声调相同，意思是机械的构造或机构。", "吃光": "吃光（chī guāng）：声母 ch 与 j 不同，声调相同（第一声），意思是把东西全部吃完。", "极光": "极光（jí guāng）：第一个音节声调不同（第二声），意思是极地上空出现的彩色光带。"}, "sentence_index": null, "correct_answer": "激光"}, "level_3": {"options": [{"text": "激光", "is_correct": true, "explanation": "正确。激光可用于手术器械，“用激光给病人做手术”符合句意。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐不能切割组织，“医生用音乐给病人做手术”不合常理。"}, {"text": "牙刷", "is_correct": false, "explanation": "语义：牙刷是用来刷牙的，不能用来做手术，“用牙刷做手术”说不通。"}, {"text": "微笑", "is_correct": false, "explanation": "搭配：“做手术”要用器械或设备，不说“用微笑做手术”，搭配不当。"}], "explanations": {"激光": "正确。激光可用于手术器械，“用激光给病人做手术”符合句意。", "音乐": "语义：音乐不能切割组织，“医生用音乐给病人做手术”不合常理。", "牙刷": "语义：牙刷是用来刷牙的，不能用来做手术，“用牙刷做手术”说不通。", "微笑": "搭配：“做手术”要用器械或设备，不说“用微笑做手术”，搭配不当。"}, "sentence_index": 0, "correct_answer": "激光"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这束激光很暖，照在身上很舒服。", "explanation": "这里应该用〈阳光〉。激光能量集中，照在身上会伤皮肤，不会“很暖很舒服”，这是阳光的特点。"}, {"text": "篝火旁的激光很暖，大家围坐着烤火。", "explanation": "这里应该用〈火光〉。火光会发热，人可以靠近取暖；激光不用来取暖，这样说是错的。"}, {"text": "激光很柔和，洒在湖面上。", "explanation": "这里应该用〈月光〉。月光是散开地洒下来的；激光方向性强，只能说“射”，不能说“洒”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7346b50-fae3-4dab-8aac-85e10340955a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91462, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "激光", "is_correct": true, "explanation": "激光（jī guāng）：由受激辐射产生、方向性强、亮度高的光，是正确答案。"}, {"text": "精光", "is_correct": false, "explanation": "精光（jīng guāng）：第一个音节多了韵尾 -ng，声调相同，意思是一点不剩（口语）。"}, {"text": "金光", "is_correct": false, "explanation": "金光（jīn guāng）：第一个音节多了韵尾 -n，声调相同，意思是金色的光。"}, {"text": "近光", "is_correct": false, "explanation": "近光（jìn guāng）：第一个音节声调不同（第四声），并多了韵尾 -n，意思是汽车的近光灯光。"}], "explanations": {"激光": "激光（jī guāng）：由受激辐射产生、方向性强、亮度高的光，是正确答案。", "精光": "精光（jīng guāng）：第一个音节多了韵尾 -ng，声调相同，意思是一点不剩（口语）。", "金光": "金光（jīn guāng）：第一个音节多了韵尾 -n，声调相同，意思是金色的光。", "近光": "近光（jìn guāng）：第一个音节声调不同（第四声），并多了韵尾 -n，意思是汽车的近光灯光。"}, "sentence_index": null, "correct_answer": "激光"}, "level_3": {"options": [{"text": "激光", "is_correct": true, "explanation": "正确。激光方向性强，可以用来测量距离，“用激光测量房间的长度”符合句意。"}, {"text": "电话", "is_correct": false, "explanation": "语义：电话是用来通话的，不能拿来测量长度，“用电话测量房间的长度”说不通。"}, {"text": "饺子", "is_correct": false, "explanation": "搭配：测量长度要用尺、卷尺或测距仪，不说“用饺子测量”，搭配不当。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不能用来测量长度，“用钢琴测量房间的长度”不合常理。"}], "explanations": {"激光": "正确。激光方向性强，可以用来测量距离，“用激光测量房间的长度”符合句意。", "电话": "语义：电话是用来通话的，不能拿来测量长度，“用电话测量房间的长度”说不通。", "饺子": "搭配：测量长度要用尺、卷尺或测距仪，不说“用饺子测量”，搭配不当。", "钢琴": "语义：钢琴是乐器，不能用来测量长度，“用钢琴测量房间的长度”不合常理。"}, "sentence_index": 6, "correct_answer": "激光"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "晚饭时，桌上点起了激光，大家安静地吃饭。", "explanation": "这里应该用〈烛光〉。“点起”多用于蜡烛、灯火，激光是受激辐射产生的光，不能这样点。"}, {"text": "屋檐下的激光滴滴答答，打湿了台阶。", "explanation": "这里应该用〈雨水〉。雨水会滴落、打湿台阶；激光是光，不会滴落，也不会打湿东西。"}, {"text": "他用毛笔蘸着激光写字。", "explanation": "这里应该用〈墨汁〉。毛笔要蘸墨汁才能写字；激光是光，不是液体，不能蘸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7346b50-fae3-4dab-8aac-85e10340955a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91462, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "舞台上射出了一张红色的激光。", "corrected_sentence": "舞台上射出了一束红色的激光。", "error_description": "量词错误：激光要用“束”计量，“张”用于纸、桌子等平面的东西，不能说“一张激光”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7346b50-fae3-4dab-8aac-85e10340955a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91462, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋顶上射出一只激光。", "corrected_sentence": "屋顶上射出一束激光。", "error_description": "量词错误：激光应用“束”计量，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7346b50-fae3-4dab-8aac-85e10340955a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91465, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有生命", "is_correct": true, "explanation": "有生命与无生命互为反义，指具有生命、能生长和活动的。"}, {"text": "坚硬", "is_correct": false, "explanation": "坚硬形容质地硬，与“无生命”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线或颜色，与“无生命”没有反义关系。"}, {"text": "缓慢", "is_correct": false, "explanation": "缓慢形容速度慢，与“无生命”没有反义关系。"}], "correct_answer": "有生命", "explanations": {"有生命": "有生命与无生命互为反义，指具有生命、能生长和活动的。", "坚硬": "坚硬形容质地硬，与“无生命”没有反义关系。", "明亮": "明亮形容光线或颜色，与“无生命”没有反义关系。", "缓慢": "缓慢形容速度慢，与“无生命”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91465, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有生命", "is_correct": true, "explanation": "有生命与无生命互为反义，指具有生命、能生长和活动的。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软形容质地软，与“无生命”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚形容清晰、明白，与“无生命”没有反义关系。"}, {"text": "迟钝", "is_correct": false, "explanation": "迟钝形容反应慢，与“无生命”没有反义关系。"}], "correct_answer": "有生命", "explanations": {"有生命": "有生命与无生命互为反义，指具有生命、能生长和活动的。", "柔软": "柔软形容质地软，与“无生命”没有反义关系。", "清楚": "清楚形容清晰、明白，与“无生命”没有反义关系。", "迟钝": "迟钝形容反应慢，与“无生命”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91465, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不是活的，不会长大、不会动的。", "primary_collocate": null, "pronunciation": "wú shēng mìng", "ipa": "u˧˥ ʂɤŋ˥ miŋ˥˩", "syllable_count": 3, "sentences": [{"text": "石头是无生命的东西。", "target_word": "无生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子和椅子都是无生命的。", "target_word": "无生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小树会长大，石头却是无生命的。", "target_word": "无生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无生命的东西不会自己动。", "target_word": "无生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玩具车是无生命的，不是活的。", "target_word": "无生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水杯是无生命的，所以不会长大。", "target_word": "无生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们找出教室里无生命的东西。", "target_word": "无生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风筝飞得很高，但它是无生命的。", "target_word": "无生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子不会长大，是无生命的。", "target_word": "无生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗是活的，书包是无生命的。", "target_word": "无生命", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "无生命体", "label": "复合"}], "register": "中性", "sense_fingerprint": "不会长大、不会动、不是活的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62e3c067-3c4e-4854-b164-7c1afd2d112c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91465, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无生命", "is_correct": true, "explanation": "石头不会长大、不会动，正是没有生命的东西，与“无生命”的意思一致。"}, {"text": "有生命", "is_correct": false, "explanation": "语义：石头没有生命，“有生命”与句中的“石头”矛盾。"}, {"text": "饥饿", "is_correct": false, "explanation": "语义：饥饿指需要进食的生物，不能用来形容石头。"}, {"text": "胆小", "is_correct": false, "explanation": "搭配：“胆小”形容人或动物的性格，不说“胆小的东西”。"}], "explanations": {"无生命": "石头不会长大、不会动，正是没有生命的东西，与“无生命”的意思一致。", "有生命": "语义：石头没有生命，“有生命”与句中的“石头”矛盾。", "饥饿": "语义：饥饿指需要进食的生物，不能用来形容石头。", "胆小": "搭配：“胆小”形容人或动物的性格，不说“胆小的东西”。"}, "sentence_index": 0, "correct_answer": "无生命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "入夜以后，这座山谷变得很无生命。", "explanation": "这里应该用〈死寂〉。无生命只说事物不具备生命，不能用来形容山谷的寂静和冷清。"}, {"text": "爷爷去年无生命了。", "explanation": "这里应该用〈去世〉。无生命说的是事物不具备生命，不用来说人的死亡。"}, {"text": "他听完这个消息，脸上毫无表情，显得很无生命。", "explanation": "这里应该用〈无生气〉。无生命指没有生命的事物，形容人的神态要用无生气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91465, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无生命", "is_correct": true, "explanation": "教室里的东西如桌椅、书本等都是没有生命的，符合“无生命”的意思。"}, {"text": "害羞", "is_correct": false, "explanation": "语义：害羞是有情感的人才会有的状态，不能用来形容教室里的东西。"}, {"text": "快乐", "is_correct": false, "explanation": "语义：快乐是有感受的生物的情绪，东西不会快乐。"}, {"text": "瘦弱", "is_correct": false, "explanation": "体貌：瘦弱描述人或动物的身体状态，不用来形容物品。"}], "explanations": {"无生命": "教室里的东西如桌椅、书本等都是没有生命的，符合“无生命”的意思。", "害羞": "语义：害羞是有情感的人才会有的状态，不能用来形容教室里的东西。", "快乐": "语义：快乐是有感受的生物的情绪，东西不会快乐。", "瘦弱": "体貌：瘦弱描述人或动物的身体状态，不用来形容物品。"}, "sentence_index": 6, "correct_answer": "无生命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文章写得很无生命，读起来没意思。", "explanation": "这里应该用〈枯燥〉。无生命只说事物没有生命，不能用来形容文章的乏味。"}, {"text": "节日过后，这条街显得很无生命。", "explanation": "这里应该用〈冷清〉。无生命不能形容街道上人少、不热闹的样子。"}, {"text": "这幅画的色彩很无生命。", "explanation": "这里应该用〈暗淡〉。暗淡形容色彩不鲜亮，无生命只指事物不具备生命。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91465, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块石头是无生命了的。", "corrected_sentence": "这块石头是无生命的。", "error_description": "错误：“无生命”后多加了“了”，表示由有生命变为无生命的变化，与石头本来就不具备生命的状态不符。正确说法是“这块石头是无生命的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91465, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "椅子是无生命，不会自己动。", "corrected_sentence": "椅子是无生命的，不会自己动。", "error_description": "错误：“是……的”结构中漏掉了“的”，“是无生命”后应接“的”。正确说法是“椅子是无生命的，不会自己动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91466, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有生命", "is_correct": true, "explanation": "有生命与无生命互为反义，指具有生命、能生长和活动的。"}, {"text": "坚硬", "is_correct": false, "explanation": "坚硬形容质地硬，与“无生命”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线或颜色，与“无生命”没有反义关系。"}, {"text": "缓慢", "is_correct": false, "explanation": "缓慢形容速度慢，与“无生命”没有反义关系。"}], "correct_answer": "有生命", "explanations": {"有生命": "有生命与无生命互为反义，指具有生命、能生长和活动的。", "坚硬": "坚硬形容质地硬，与“无生命”没有反义关系。", "明亮": "明亮形容光线或颜色，与“无生命”没有反义关系。", "缓慢": "缓慢形容速度慢，与“无生命”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91466, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有生命", "is_correct": true, "explanation": "有生命与无生命互为反义，指具有生命、能生长和活动的。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软形容质地软，与“无生命”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚形容清晰、明白，与“无生命”没有反义关系。"}, {"text": "迟钝", "is_correct": false, "explanation": "迟钝形容反应慢，与“无生命”没有反义关系。"}], "correct_answer": "有生命", "explanations": {"有生命": "有生命与无生命互为反义，指具有生命、能生长和活动的。", "柔软": "柔软形容质地软，与“无生命”没有反义关系。", "清楚": "清楚形容清晰、明白，与“无生命”没有反义关系。", "迟钝": "迟钝形容反应慢，与“无生命”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91466, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有生命的，不具备生命特征的。", "primary_collocate": null, "pronunciation": "wú shēng mìng", "ipa": "u˧˥ ʂɤŋ˥ miŋ˥˩", "syllable_count": 3, "sentences": [{"text": "岩石和沙子是无生命的物质。", "target_word": "无生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家想知道生命是怎么从无生命的物质来的。", "target_word": "无生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病毒不是细胞，有人说它是无生命的。", "target_word": "无生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月球表面是无生命的世界。", "target_word": "无生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生物学家把自然界分成有生命和无生命两类。", "target_word": "无生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这颗星球上没有水，是一片无生命的荒地。", "target_word": "无生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无生命的物体不能呼吸，也不能繁殖。", "target_word": "无生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里的玻璃和金属都是无生命的材料。", "target_word": "无生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火星表面看起来是无生命的。", "target_word": "无生命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气、阳光、土壤属于环境中无生命的部分。", "target_word": "无生命", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "无生命体", "label": "复合"}], "register": "书面", "sense_fingerprint": "不具备生命特征的（科学语境）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62e3c067-3c4e-4854-b164-7c1afd2d112c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91466, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无生命", "is_correct": true, "explanation": "岩石和沙子没有生命特征，是无生命的物质，与“无生命”的意思一致。"}, {"text": "有生命", "is_correct": false, "explanation": "语义：岩石和沙子没有生命，“有生命”与句中的主语矛盾。"}, {"text": "胆小", "is_correct": false, "explanation": "搭配：“胆小”形容人或动物的性格，不用来形容物质。"}, {"text": "快乐", "is_correct": false, "explanation": "语义：快乐是有感受的生物的情绪，岩石和沙子没有情绪。"}], "explanations": {"无生命": "岩石和沙子没有生命特征，是无生命的物质，与“无生命”的意思一致。", "有生命": "语义：岩石和沙子没有生命，“有生命”与句中的主语矛盾。", "胆小": "搭配：“胆小”形容人或动物的性格，不用来形容物质。", "快乐": "语义：快乐是有感受的生物的情绪，岩石和沙子没有情绪。"}, "sentence_index": 0, "correct_answer": "无生命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座小镇在战后显得十分无生命。", "explanation": "这里应该用〈荒凉〉。无生命指事物没有生命，不用来形容景象的凄凉。"}, {"text": "他的表情很无生命。", "explanation": "这里应该用〈呆板〉。呆板形容神情不灵活，无生命只说事物没有生命。"}, {"text": "他的作文写得很无生命。", "explanation": "这里应该用〈死板〉。死板形容文章或说话不灵活，无生命不能形容文字的生动程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91466, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无生命", "is_correct": true, "explanation": "无生命的物体不能呼吸、不能繁殖，与句子的意思一致。"}, {"text": "害羞", "is_correct": false, "explanation": "语义：害羞是有情感的人才会有的状态，物体不会害羞。"}, {"text": "饥饿", "is_correct": false, "explanation": "语义：饥饿指需要进食的生物，不能用来形容物体。"}, {"text": "瘦弱", "is_correct": false, "explanation": "体貌：瘦弱描述人或动物的身体状态，不用来形容物体。"}], "explanations": {"无生命": "无生命的物体不能呼吸、不能繁殖，与句子的意思一致。", "害羞": "语义：害羞是有情感的人才会有的状态，物体不会害羞。", "饥饿": "语义：饥饿指需要进食的生物，不能用来形容物体。", "瘦弱": "体貌：瘦弱描述人或动物的身体状态，不用来形容物体。"}, "sentence_index": 6, "correct_answer": "无生命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "节日过后，广场上显得很无生命。", "explanation": "这里应该用〈冷清〉。无生命指事物不具备生命特征，不能形容场所人少、不热闹。"}, {"text": "这个班的气氛很无生命。", "explanation": "这里应该用〈沉闷〉。无生命只指不具备生命特征，不能形容气氛不活跃。"}, {"text": "这段讲解很无生命。", "explanation": "这里应该用〈枯燥〉。枯燥形容讲解乏味，无生命只指不具备生命特征。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91466, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "火星表面是无生命地的。", "corrected_sentence": "火星表面是无生命的。", "error_description": "错误：“是……的”结构中修饰语应用“的”，不能用“地”（“地”用于状语）。正确说法是“火星表面是无生命的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91466, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "石块是无生命了的，不能呼吸。", "corrected_sentence": "石块是无生命的，不能呼吸。", "error_description": "错误：“无生命”后多加了“了”，形成“是无生命了的”。“是……的”结构中的形容词后不能再加“了”，正确说法是“石块是无生命的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
