INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91468, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生物体结构和功能的基本单位。", "primary_collocate": null, "pronunciation": "xì bāo", "ipa": "ɕi˥˩ paʊ˥", "syllable_count": 2, "sentences": [{"text": "细胞是生物体的基本单位。", "target_word": "细胞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物和植物的身体都是由细胞构成的。", "target_word": "细胞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个细胞都有自己的功能。", "target_word": "细胞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "细菌只有一个细胞，却是活的生物。", "target_word": "细胞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生物课上，老师讲了细胞的结构。", "target_word": "细胞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "细胞分裂以后，生物体就长大了。", "target_word": "细胞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，细胞是生命的基本单位。", "target_word": "细胞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "细胞有一层膜，保护着里面。", "target_word": "细胞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大量细胞受损，身体就可能生病。", "target_word": "细胞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家研究过细胞的结构。", "target_word": "细胞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "細胞", "label": "繁体"}], "register": "中性", "sense_fingerprint": "生物体结构和功能的基本单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '014adc03-4858-4184-a9b1-120df8f0a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91468, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小东西", "is_correct": false, "explanation": "语域：“小东西”是口语，泛指小物件，不能用于“基本单位”这一科学说法。"}, {"text": "细胞", "is_correct": true, "explanation": "细胞是构成生物体结构和功能的基本单位，与句意一致。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字是用来称呼的，不是生物体的基本单位。"}, {"text": "食物", "is_correct": false, "explanation": "语义：食物是生物体摄取的东西，不是构成生物体的基本单位。"}], "explanations": {"小东西": "语域：“小东西”是口语，泛指小物件，不能用于“基本单位”这一科学说法。", "细胞": "细胞是构成生物体结构和功能的基本单位，与句意一致。", "名字": "语义：名字是用来称呼的，不是生物体的基本单位。", "食物": "语义：食物是生物体摄取的东西，不是构成生物体的基本单位。"}, "sentence_index": 0, "correct_answer": "细胞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在显微镜下看到一条细胞。", "explanation": "这里应该用〈个〉。〈条〉用于细长的东西，细胞不能用〈条〉。"}, {"text": "心脏是人体的重要细胞，负责输送血液。", "explanation": "这里应该用〈器官〉。心脏是由多种组织构成的器官，不是一个细胞。"}, {"text": "氧是一种化学细胞。", "explanation": "这里应该用〈元素〉。氧是化学元素，不是生物体的结构单位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91468, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "微笑", "is_correct": false, "explanation": "语义：微笑是表情，不是生命的基本单位。"}, {"text": "细胞", "is_correct": true, "explanation": "细胞是生命的基本结构单位，与“书上说”的语境相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是大气的状况，不是生命的基本单位。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，泛指东西，不用于这种科学表述。"}], "explanations": {"微笑": "语义：微笑是表情，不是生命的基本单位。", "细胞": "细胞是生命的基本结构单位，与“书上说”的语境相符。", "天气": "语义：天气是大气的状况，不是生命的基本单位。", "玩意儿": "语域：“玩意儿”是口语，泛指东西，不用于这种科学表述。"}, "sentence_index": 6, "correct_answer": "细胞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "皮肤是人体最大的细胞。", "explanation": "这里应该用〈器官〉。皮肤是人体最大的器官，由多种组织构成，本身不是一个细胞。"}, {"text": "铁是由铁细胞组成的。", "explanation": "这里应该用〈原子〉。铁由铁原子组成，不由细胞组成。"}, {"text": "酒精是由很多细胞组成的。", "explanation": "这里应该用〈分子〉。酒精由分子组成，不由细胞组成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91468, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "显微镜下有一细胞在动。", "corrected_sentence": "显微镜下有一个细胞在动。", "error_description": "缺少量词。“细胞”前要加量词“个”，应说“一个细胞”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91468, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "科学家在培养皿里观察到了很多细胞们。", "corrected_sentence": "科学家在培养皿里观察到了很多细胞。", "error_description": "“们”只用于指人的词后面，“细胞”后不能加；“很多”已表示数量，不需要再加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91469, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "勤奋", "is_correct": false, "explanation": "“勤奋”指努力肯干，与“无能”没有反义关系。"}, {"text": "能干", "is_correct": true, "explanation": "“能干”指有能力、做事出色，与“无能”是反义词。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”指不吵闹，与“无能”没有反义关系。"}, {"text": "美丽", "is_correct": false, "explanation": "“美丽”指外表好看，与“无能”没有反义关系。"}], "correct_answer": "能干", "explanations": {"勤奋": "“勤奋”指努力肯干，与“无能”没有反义关系。", "能干": "“能干”指有能力、做事出色，与“无能”是反义词。", "安静": "“安静”指不吵闹，与“无能”没有反义关系。", "美丽": "“美丽”指外表好看，与“无能”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91469, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "热情", "is_correct": false, "explanation": "“热情”指待人友好、积极，与“无能”没有反义关系。"}, {"text": "幽默", "is_correct": false, "explanation": "“幽默”指说话风趣，与“无能”没有反义关系。"}, {"text": "勇敢", "is_correct": false, "explanation": "“勇敢”指不怕困难和危险，与“无能”没有反义关系。"}, {"text": "能干", "is_correct": true, "explanation": "“能干”指有能力、做事出色，与“无能”是反义词。"}], "correct_answer": "能干", "explanations": {"热情": "“热情”指待人友好、积极，与“无能”没有反义关系。", "幽默": "“幽默”指说话风趣，与“无能”没有反义关系。", "勇敢": "“勇敢”指不怕困难和危险，与“无能”没有反义关系。", "能干": "“能干”指有能力、做事出色，与“无能”是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91469, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "无能是什么事都做不好。", "primary_collocate": null, "pronunciation": "wú néng", "ipa": "u˧˥ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他什么事都做不好，大家都说他很无能。", "target_word": "无能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个经理太无能了，公司一年比一年差。", "target_word": "无能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我觉得自己很无能，连饭都做不好。", "target_word": "无能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是个无能的人，做什么都失败。", "target_word": "无能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别人说他无能，他听了很难过。", "target_word": "无能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他当了很多年经理，还是那么无能。", "target_word": "无能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "无能的老板让所有员工都很失望。", "target_word": "无能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不想承认自己无能，所以总怪别人。", "target_word": "无能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的领导很无能，人民生活很苦。", "target_word": "无能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得自己无能，什么事都不敢试。", "target_word": "无能", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容人什么事都做不好，很没用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ce21c1-82f6-40df-91c8-18dde08ef184') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91469, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "能干", "is_correct": false, "explanation": "语义：能干是有能力，与“什么事都做不好”矛盾。"}, {"text": "无能", "is_correct": true, "explanation": "无能：形容什么事都做不好，与前半句的描述一致。"}, {"text": "完美", "is_correct": false, "explanation": "语义：完美是很好的意思，与“什么事都做不好”矛盾。"}, {"text": "卓越", "is_correct": false, "explanation": "语域：卓越是书面赞扬，口语中不说“很卓越”，且与前句矛盾。"}], "explanations": {"能干": "语义：能干是有能力，与“什么事都做不好”矛盾。", "无能": "无能：形容什么事都做不好，与前半句的描述一致。", "完美": "语义：完美是很好的意思，与“什么事都做不好”矛盾。", "卓越": "语域：卓越是书面赞扬，口语中不说“很卓越”，且与前句矛盾。"}, "sentence_index": 0, "correct_answer": "无能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他身体很无能，走不动路。", "explanation": "这里应该用〈无力〉。无能说做事的能力差，形容身体没有力气要用“无力”。"}, {"text": "他无能地摇了摇头。", "explanation": "这里应该用〈无奈〉。无奈形容没有办法的样子，无能指能力差，不能用来修饰摇头。"}, {"text": "我们收到了无能的信。", "explanation": "这里应该用〈无数〉。无能形容人的能力，不能修饰“信”；说数量很多要用“无数”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91469, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面或气氛，不用来修饰“老板”。"}, {"text": "无能", "is_correct": true, "explanation": "无能：形容能力差，与“让所有员工都很失望”相符。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”形容环境或物体，不能修饰“老板”，与句子不搭。"}, {"text": "圆形", "is_correct": false, "explanation": "搭配：“圆形”形容物体形状，不能修饰“老板”。"}], "explanations": {"热闹": "搭配：“热闹”形容场面或气氛，不用来修饰“老板”。", "无能": "无能：形容能力差，与“让所有员工都很失望”相符。", "潮湿": "搭配：“潮湿”形容环境或物体，不能修饰“老板”，与句子不搭。", "圆形": "搭配：“圆形”形容物体形状，不能修饰“老板”。"}, "sentence_index": 6, "correct_answer": "无能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对客人很无能，大家都不喜欢他。", "explanation": "这里应该用〈无理〉。无能说能力差；对人态度粗鲁要用“无理”。"}, {"text": "这种无能的压力很大。", "explanation": "这里应该用〈无形〉。无能用来形容人的能力，不能修饰“压力”；说看不见的压力要用“无形”。"}, {"text": "她对孩子有无能的爱。", "explanation": "这里应该用〈无限〉。无能说能力差，形容爱的程度要用“无限”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91469, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是个很无能人，什么事都做不好。", "corrected_sentence": "他是个很无能的人，什么事都做不好。", "error_description": "错误：“很无能人”；正确：“很无能的人”。“无能”修饰“人”时后面要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91469, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个老板太无能的了，员工都很失望。", "corrected_sentence": "这个老板太无能了，员工都很失望。", "error_description": "错误：“太无能的了”；正确：“太无能了”。“太……了”中间直接放形容词，不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91470, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "精致", "is_correct": false, "explanation": "“精致”指做工细巧，与“无能”没有反义关系。"}, {"text": "能干", "is_correct": true, "explanation": "“能干”指有能力、做事出色，与“无能”是反义词。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”指明白、不模糊，与“无能”没有反义关系。"}, {"text": "慷慨", "is_correct": false, "explanation": "“慷慨”指大方给予，与“无能”没有反义关系。"}], "correct_answer": "能干", "explanations": {"精致": "“精致”指做工细巧，与“无能”没有反义关系。", "能干": "“能干”指有能力、做事出色，与“无能”是反义词。", "清楚": "“清楚”指明白、不模糊，与“无能”没有反义关系。", "慷慨": "“慷慨”指大方给予，与“无能”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91470, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "诚实", "is_correct": false, "explanation": "“诚实”指不说谎、不欺骗，与“无能”没有反义关系。"}, {"text": "严肃", "is_correct": false, "explanation": "“严肃”指态度认真或庄重，与“无能”没有反义关系。"}, {"text": "勤劳", "is_correct": false, "explanation": "“勤劳”指肯干、不懒，与“无能”没有反义关系。"}, {"text": "能干", "is_correct": true, "explanation": "“能干”指有能力、做事出色，与“无能”是反义词。"}], "correct_answer": "能干", "explanations": {"诚实": "“诚实”指不说谎、不欺骗，与“无能”没有反义关系。", "严肃": "“严肃”指态度认真或庄重，与“无能”没有反义关系。", "勤劳": "“勤劳”指肯干、不懒，与“无能”没有反义关系。", "能干": "“能干”指有能力、做事出色，与“无能”是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91470, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有能力，不能胜任。", "primary_collocate": null, "pronunciation": "wú néng", "ipa": "u˧˥ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他太无能，不能胜任这个职位。", "target_word": "无能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板说我无能，不能做经理。", "target_word": "无能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这样的无能领导，怎么管好公司？", "target_word": "无能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他无能，所以老板把他换掉了。", "target_word": "无能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她觉得自己无能，不能带好这个班。", "target_word": "无能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生无能，病人只能去别的医院。", "target_word": "无能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府无能，所以问题多年没有解决。", "target_word": "无能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他承认自己无能，不能胜任经理工作。", "target_word": "无能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为队长无能，我们队一直输球。", "target_word": "无能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "无能的人当不好老师，更当不好校长。", "target_word": "无能", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容人缺乏能力，不能胜任工作或职位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ce21c1-82f6-40df-91c8-18dde08ef184') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91470, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "称职", "is_correct": false, "explanation": "语义：称职指能胜任，与“不能胜任这个职位”矛盾。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面，不用来形容人的能力。"}, {"text": "无能", "is_correct": true, "explanation": "无能：没有能力，不能胜任，与后半句一致。"}, {"text": "卓越", "is_correct": false, "explanation": "语域：卓越是书面赞扬，口语不说“太卓越”，且与“不能胜任”矛盾。"}], "explanations": {"称职": "语义：称职指能胜任，与“不能胜任这个职位”矛盾。", "热闹": "搭配：“热闹”形容场面，不用来形容人的能力。", "无能": "无能：没有能力，不能胜任，与后半句一致。", "卓越": "语域：卓越是书面赞扬，口语不说“太卓越”，且与“不能胜任”矛盾。"}, "sentence_index": 0, "correct_answer": "无能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对老师很无能。", "explanation": "这里应该用〈无礼〉。无能说能力不足；对人态度不尊重要用“无礼”。"}, {"text": "他无能地走了出去。", "explanation": "这里应该用〈无声〉。无能说能力差，形容走路安静要用“无声”。"}, {"text": "这幅画是无能之宝。", "explanation": "这里应该用〈无价〉。无能形容人的能力，不能形容宝物；形容非常珍贵要用“无价”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91470, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "能干", "is_correct": false, "explanation": "语义：能干指有能力，与“问题多年没有解决”矛盾。"}, {"text": "高效", "is_correct": false, "explanation": "语义：高效指效率高，政府高效不会让问题多年没解决，与后句矛盾。"}, {"text": "无能", "is_correct": true, "explanation": "无能：没有能力，问题多年没有解决与之相符。"}, {"text": "圆满", "is_correct": false, "explanation": "搭配：“圆满”多用于事情或结果，不说“政府圆满”。"}], "explanations": {"能干": "语义：能干指有能力，与“问题多年没有解决”矛盾。", "高效": "语义：高效指效率高，政府高效不会让问题多年没解决，与后句矛盾。", "无能": "无能：没有能力，问题多年没有解决与之相符。", "圆满": "搭配：“圆满”多用于事情或结果，不说“政府圆满”。"}, "sentence_index": 6, "correct_answer": "无能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事跟我无能。", "explanation": "这里应该用〈无关〉。无能指能力差；说与自己没有关系要用“无关”。"}, {"text": "我们无能地支持你。", "explanation": "这里应该用〈无条件〉。无能说能力差；表示不附带条件的支持要用“无条件”。"}, {"text": "这张桌子很无能，一放东西就晃。", "explanation": "这里应该用〈不稳〉。无能指人的能力差，桌子晃动要说“不稳”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91470, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他做事很无能地，总是出错。", "corrected_sentence": "他做事很无能，总是出错。", "error_description": "错误：“很无能地”；正确：“很无能”。形容词作谓语时，后面不加“地”，应说“他做事很无能，总是出错”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91470, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个队长太无能的了，我们一直输球。", "corrected_sentence": "这个队长太无能了，我们一直输球。", "error_description": "错误：“太无能的了”；正确：“太无能了”。“太……了”中间直接放形容词，不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
