INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91472, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个国家或地区经济规模扩大、水平提高的过程。", "primary_collocate": null, "pronunciation": "jīng jì fā zhǎn", "ipa": "tɕiŋ˥ tɕi˥˩ fa˥ ʈʂan˨˩˦", "syllable_count": 4, "sentences": [{"text": "这个国家的经济发展速度很快。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济发展离不开科学技术。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近年来，该地区的经济发展水平不断提高。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府很重视经济发展和环境保护。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济发展给城市带来了新的机会。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国的经济发展并不一样。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济发展需要稳定的社会环境。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区的经济发展有了很大变化。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教育对经济发展有重要作用。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要保护环境，也要促进经济发展。", "target_word": "经济发展", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "经济发展：国家或地区经济规模扩大、水平提高的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05e66eed-24af-4555-9219-89fc197dcac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91472, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人口", "is_correct": false, "explanation": "搭配：人口本身没有“速度”，应说“增长速度”。"}, {"text": "经济发展", "is_correct": true, "explanation": "正确：“经济发展速度”指经济规模扩大、水平提高的快慢，与“很快”搭配。"}, {"text": "历史", "is_correct": false, "explanation": "语义：历史是过去的事，没有快慢，“历史速度”说不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气没有速度，“天气速度很快”不成立。"}], "explanations": {"人口": "搭配：人口本身没有“速度”，应说“增长速度”。", "经济发展": "正确：“经济发展速度”指经济规模扩大、水平提高的快慢，与“很快”搭配。", "历史": "语义：历史是过去的事，没有快慢，“历史速度”说不通。", "天气": "语义：天气没有速度，“天气速度很快”不成立。"}, "sentence_index": 0, "correct_answer": "经济发展"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个城市的经济发展很漂亮。", "explanation": "语义：这里误把“经济发展”当成〈外貌〉来用。“经济发展”指国家或地区经济规模扩大、水平提高的过程，不能用来形容外貌。"}, {"text": "我的小狗今年经济发展得很好。", "explanation": "语义：这里误把“经济发展”当成〈成长〉来用。“经济发展”只用于国家或地区，小狗长大应说“长得很好”。"}, {"text": "这张桌子的经济发展很好。", "explanation": "语义：这里误把“经济发展”当成〈质量〉来用。“经济发展”指国家或地区经济的壮大，不能描述桌子，桌子的好坏应说“质量”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f04b711-8b52-447c-8ee9-e5931ba22acb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91472, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花朵", "is_correct": false, "explanation": "语义：花朵不需要社会环境，这句话不成立。"}, {"text": "经济发展", "is_correct": true, "explanation": "正确：经济发展需要稳定的社会环境，符合常理。"}, {"text": "睡眠", "is_correct": false, "explanation": "语义：睡眠是个人的生理活动，不需要社会环境。"}, {"text": "语速", "is_correct": false, "explanation": "搭配：“需要稳定的社会环境”的主语应是事业或发展，“语速”与之不搭。"}], "explanations": {"花朵": "语义：花朵不需要社会环境，这句话不成立。", "经济发展": "正确：经济发展需要稳定的社会环境，符合常理。", "睡眠": "语义：睡眠是个人的生理活动，不需要社会环境。", "语速": "搭配：“需要稳定的社会环境”的主语应是事业或发展，“语速”与之不搭。"}, "sentence_index": 6, "correct_answer": "经济发展"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "要保护环境，也要促进这座桥的经济发展。", "explanation": "语义：这里误把“经济发展”当成〈建设〉来用。“经济发展”只用于国家或地区的经济，不能用于一座桥，桥的修建应说“建设”。"}, {"text": "要保护环境，也要促进猫的经济发展。", "explanation": "语义：这里误把“经济发展”当成〈成长〉来用。猫的成长应说“促进猫的成长”，“经济发展”只用于国家或地区。"}, {"text": "要保护环境，也要促进这台电脑的经济发展。", "explanation": "语义：这里误把“经济发展”当成〈性能〉来用。“经济发展”只用于国家或地区，电脑的能力应说“性能”，如“提高电脑的性能”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f04b711-8b52-447c-8ee9-e5931ba22acb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91472, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个省的一只经济发展水平提高了。", "corrected_sentence": "这个省的经济发展水平提高了。", "error_description": "错误：在“经济发展水平”前加了量词“只”。“只”用于动物，应直接说“这个省的经济发展水平提高了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f04b711-8b52-447c-8ee9-e5931ba22acb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91472, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个县的经济发展了很快。", "corrected_sentence": "这个县的经济发展得很快。", "error_description": "错误：补语标记应用“得”，不能用“了”。“经济发展了很快”不成立，应说“经济发展得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f04b711-8b52-447c-8ee9-e5931ba22acb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91473, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷漠", "is_correct": true, "explanation": "冷漠：对人或事没有热情、不愿帮助，与“热心”构成反义。"}, {"text": "聪明", "is_correct": false, "explanation": "聪明：说头脑灵活，与“热心”没有反义关系。"}, {"text": "勇敢", "is_correct": false, "explanation": "勇敢：说胆量大，与“热心”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "安静：说不吵闹，与“热心”没有反义关系。"}], "correct_answer": "冷漠", "explanations": {"冷漠": "冷漠：对人或事没有热情、不愿帮助，与“热心”构成反义。", "聪明": "聪明：说头脑灵活，与“热心”没有反义关系。", "勇敢": "勇敢：说胆量大，与“热心”没有反义关系。", "安静": "安静：说不吵闹，与“热心”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91473, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷淡", "is_correct": true, "explanation": "冷淡：对人或事不热情、不关心，与“热心”构成反义。"}, {"text": "勤奋", "is_correct": false, "explanation": "勤奋：说努力、不懈怠，与“热心”没有反义关系。"}, {"text": "诚实", "is_correct": false, "explanation": "诚实：说为人不说假话，与“热心”没有反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮：说外貌好看，与“热心”没有反义关系。"}], "correct_answer": "冷淡", "explanations": {"冷淡": "冷淡：对人或事不热情、不关心，与“热心”构成反义。", "勤奋": "勤奋：说努力、不懈怠，与“热心”没有反义关系。", "诚实": "诚实：说为人不说假话，与“热心”没有反义关系。", "漂亮": "漂亮：说外貌好看，与“热心”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91473, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "热心是很愿意帮助别人。", "primary_collocate": null, "pronunciation": "rè xīn", "ipa": "ɻɤ˥˩ ɕin˥", "syllable_count": 2, "sentences": [{"text": "我的邻居很热心。", "target_word": "热心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他是个热心的人，总是帮助别人。", "target_word": "热心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老奶奶迷路了，一位热心的姑娘帮她找到了家。", "target_word": "热心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他热心地帮我搬了家。", "target_word": "热心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们都很热心，经常帮我练习汉语。", "target_word": "热心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢你这么热心，帮我找到了钥匙。", "target_word": "热心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公交车上，一位热心的叔叔给我让了座。", "target_word": "热心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很热心，别人有困难就去帮忙。", "target_word": "热心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的老板很热心，还送我回酒店。", "target_word": "热心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一点也不热心，从来不帮别人。", "target_word": "热心", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "热心肠", "label": "复合"}, {"form": "热心人", "label": "复合"}], "register": "中性", "sense_fingerprint": "乐于帮助别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f1d42d-5220-4b0c-9fb7-df56a4a71c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91473, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "热心", "is_correct": true, "explanation": "热心：指乐于帮助别人，与“我的邻居很”搭配，符合邻居的形象。"}, {"text": "干燥", "is_correct": false, "explanation": "搭配：“干燥”多用于空气、土地、皮肤，不用来形容人的性情。"}, {"text": "漆黑", "is_correct": false, "explanation": "搭配：“漆黑”形容颜色或夜色，不能用来形容邻居。"}, {"text": "坚硬", "is_correct": false, "explanation": "语义：“坚硬”指物体的硬度，与人乐于帮忙的性格无关。"}], "explanations": {"热心": "热心：指乐于帮助别人，与“我的邻居很”搭配，符合邻居的形象。", "干燥": "搭配：“干燥”多用于空气、土地、皮肤，不用来形容人的性情。", "漆黑": "搭配：“漆黑”形容颜色或夜色，不能用来形容邻居。", "坚硬": "语义：“坚硬”指物体的硬度，与人乐于帮忙的性格无关。"}, "sentence_index": 0, "correct_answer": "热心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "观众热心地鼓掌，欢呼声不断。", "explanation": "这里应该用〈热烈〉。热心强调乐于帮忙，形容鼓掌的激昂场面要用热烈。"}, {"text": "她热心生活，每天都过得很开心。", "explanation": "这里应该用〈热爱〉。热心强调乐于帮助别人，不能直接带表示喜爱的宾语，表达对生活的喜爱要用热爱。"}, {"text": "这位演员最近很热心，到处都是他的消息。", "explanation": "这里应该用〈热门〉。热心形容人乐于帮助别人，形容演员受欢迎、人人关注要用热门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91473, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "热心", "is_correct": true, "explanation": "热心：修饰“叔叔”，说明他乐于帮助人，与让座的情节一致。"}, {"text": "稚嫩", "is_correct": false, "explanation": "体貌：“稚嫩”形容幼小孩童的外貌，不能用来形容成年的叔叔。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”指空气或物体含水多，不能用来形容人。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：“干燥”指空气或物体缺少水分，不能用来形容人。"}], "explanations": {"热心": "热心：修饰“叔叔”，说明他乐于帮助人，与让座的情节一致。", "稚嫩": "体貌：“稚嫩”形容幼小孩童的外貌，不能用来形容成年的叔叔。", "潮湿": "语义：“潮湿”指空气或物体含水多，不能用来形容人。", "干燥": "语义：“干燥”指空气或物体缺少水分，不能用来形容人。"}, "sentence_index": 6, "correct_answer": "热心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他热心地等了三个小时。", "explanation": "这里应该用〈耐心〉。热心强调乐于帮助别人，等待时的忍耐和专注要用耐心。"}, {"text": "他热心地盼望着父母的来信。", "explanation": "这里应该用〈热切〉。热切表示迫切的期待，热心强调乐于帮助，不能用来表达盼望的心情。"}, {"text": "他热心地摔门而去，谁也不理。", "explanation": "这里应该用〈愤怒〉。热心强调乐于帮助别人，不能形容摔门发脾气时的情绪，表达愤怒要用愤怒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91473, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位阿姨很很热心，常常主动帮忙。", "corrected_sentence": "那位阿姨很热心，常常主动帮忙。", "error_description": "错误：程度副词“很”重复。正确：“很热心”只用一个“很”，形容词前只用一个程度副词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91473, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一位热心地邻居主动帮我修好了自行车。", "corrected_sentence": "一位热心的邻居主动帮我修好了自行车。", "error_description": "错误在于结构助词用错：“热心”修饰名词“邻居”时应用“的”，“地”只用于修饰动词，不能放在名词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
