INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91474, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "对人对事积极、热情。", "primary_collocate": null, "pronunciation": "rè xīn", "ipa": "ɻɤ˥˩ ɕin˥", "syllable_count": 2, "sentences": [{"text": "她对工作很热心。", "target_word": "热心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他热心公益，常去做志愿者。", "target_word": "热心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师对学生的事特别热心。", "target_word": "热心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对学汉语很热心，每天都练习。", "target_word": "热心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸热心地参加社区活动。", "target_word": "热心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对这件事不太热心，所以没来。", "target_word": "热心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都很热心，想把晚会办好。", "target_word": "热心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对朋友的事一向很热心。", "target_word": "热心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他热心教我们打球。", "target_word": "热心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "张先生对学校的活动非常热心。", "target_word": "热心", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "热心肠", "label": "复合"}, {"form": "热心人", "label": "复合"}], "register": "中性", "sense_fingerprint": "对人对事积极热情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f1d42d-5220-4b0c-9fb7-df56a4a71c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91474, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "热心", "is_correct": true, "explanation": "热心：指对工作积极、热情，与“她对工作很”搭配自然。"}, {"text": "漫长", "is_correct": false, "explanation": "搭配：“漫长”修饰时间或路程，不用来形容人对工作的态度。"}, {"text": "嘹亮", "is_correct": false, "explanation": "语义：“嘹亮”形容声音响亮，与人对工作的态度无关。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：“陈旧”指东西过时，用来形容人对工作的态度语义不通。"}], "explanations": {"热心": "热心：指对工作积极、热情，与“她对工作很”搭配自然。", "漫长": "搭配：“漫长”修饰时间或路程，不用来形容人对工作的态度。", "嘹亮": "语义：“嘹亮”形容声音响亮，与人对工作的态度无关。", "陈旧": "语义：“陈旧”指东西过时，用来形容人对工作的态度语义不通。"}, "sentence_index": 0, "correct_answer": "热心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她热心地撕碎了那封信。", "explanation": "这里应该用〈愤怒〉。热心指对人对事积极、热情，不能用来形容撕信时的怒气。"}, {"text": "他热心地躺在沙发上睡了一整天。", "explanation": "这里应该用〈懒散〉。热心指对人对事积极、热情，与整天躺着睡觉的状态矛盾；描写懒散要用懒散。"}, {"text": "这把椅子很热心，坐上去一点儿也不晃。", "explanation": "这里应该用〈稳当〉。热心形容人对人对事积极热情，不能用来形容椅子；描写椅子牢固平稳要用稳当。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91474, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "热心", "is_correct": true, "explanation": "热心：指大家乐于出力，与“想把晚会办好”的意图一致。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”指空气或物体含水多，不能用来形容人。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：“干燥”指空气或物体缺少水分，不能用来形容人。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音或食物爽脆，不能用来形容人。"}], "explanations": {"热心": "热心：指大家乐于出力，与“想把晚会办好”的意图一致。", "潮湿": "语义：“潮湿”指空气或物体含水多，不能用来形容人。", "干燥": "语义：“干燥”指空气或物体缺少水分，不能用来形容人。", "清脆": "语义：“清脆”形容声音或食物爽脆，不能用来形容人。"}, "sentence_index": 6, "correct_answer": "热心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对前来求助的人很热心，连话都不愿说。", "explanation": "这里应该用〈冷漠〉。热心表示积极热情，与“连话都不愿说”的态度矛盾；描写冷淡疏远的态度要用冷漠。"}, {"text": "他对这件事很热心，从来不关心。", "explanation": "这里应该用〈冷淡〉。热心表示积极热情，与“从来不关心”矛盾；描写不热情的态度要用冷淡。"}, {"text": "他热心地摇了摇头，什么也没说。", "explanation": "这里应该用〈失望〉。热心表示积极热情，不能形容摇头时的失望情绪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91474, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她新工作很热心，每天都主动学习。", "corrected_sentence": "她对新工作很热心，每天都主动学习。", "error_description": "错误在于漏掉“对”：表示对某事热心，要用“对+事情”引出对象，应为“她对新工作很热心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91474, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "王阿姨把邻居很热心，常常帮大家买菜。", "corrected_sentence": "王阿姨对邻居很热心，常常帮大家买菜。", "error_description": "错误在于介词：表示对某人热心，要用“对”引出对象，不能用“把”，应说“对邻居很热心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
