INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91475, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91475, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "自治是自己管自己的事，不要别人来管。", "primary_collocate": null, "pronunciation": "zì zhì", "ipa": "ts˥˩ ʈʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "这个地区实行自治。", "target_word": "自治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们希望自治，不愿让老师事事干预。", "target_word": "自治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇多年前就开始自治了。", "target_word": "自治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们希望自己管事，实现自治。", "target_word": "自治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家给了岛上的人自治的权利。", "target_word": "自治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让同学们自治，班里的事自己决定。", "target_word": "自治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的居民已经自治了十年。", "target_word": "自治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个社区实行自治，需要大家一起努力。", "target_word": "自治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学应当实行自治，外界不得随意干预。", "target_word": "自治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个民族可以自己做决定，也就是自治。", "target_word": "自治", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自治了", "label": "体标"}, {"form": "自治过", "label": "体标"}, {"form": "自治区", "label": "复合"}], "register": "正式", "sense_fingerprint": "一个地区、团体自己管理自己的事，不受别人管", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f7f4cc0-d72a-4bc5-95a4-88c0d7487b96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91475, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "自治", "is_correct": true, "explanation": "自治是自己管自己的事，不受别人管。"}, {"text": "资质", "is_correct": false, "explanation": "zī（第一声）与 zì（第四声）声调不同，意思是资质、素质。"}, {"text": "自知", "is_correct": false, "explanation": "zhī（第一声）与 zhì（第四声）声调不同，意思是自己知道。"}, {"text": "字纸", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是写过字的纸，多指废纸。"}], "explanations": {"自治": "自治是自己管自己的事，不受别人管。", "资质": "zī（第一声）与 zì（第四声）声调不同，意思是资质、素质。", "自知": "zhī（第一声）与 zhì（第四声）声调不同，意思是自己知道。", "字纸": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是写过字的纸，多指废纸。"}, "sentence_index": null, "correct_answer": "自治"}, "level_3": {"options": [{"text": "自治", "is_correct": true, "explanation": "正确。“这个地区实行”后接“自治”，指地区自己管理自己的事务，符合句意。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：“实行”要带名词或动词性宾语，“睡觉”是不及物动词，不能作其宾语。"}, {"text": "飞翔", "is_correct": false, "explanation": "语义：“飞翔”是鸟类或飞行器的动作，不能被“实行”，与“地区”的语境矛盾。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”是休闲活动，不是可以“实行”的制度或政策。"}], "explanations": {"自治": "正确。“这个地区实行”后接“自治”，指地区自己管理自己的事务，符合句意。", "睡觉": "配价：“实行”要带名词或动词性宾语，“睡觉”是不及物动词，不能作其宾语。", "飞翔": "语义：“飞翔”是鸟类或飞行器的动作，不能被“实行”，与“地区”的语境矛盾。", "散步": "语义：“散步”是休闲活动，不是可以“实行”的制度或政策。"}, "sentence_index": 0, "correct_answer": "自治"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家终于自治了。", "explanation": "这里应该用〈独立〉。国家取得完全主权用“独立”；“自治”指在国家内部自己管理事务，不指脱离国家。"}, {"text": "他每天自治地锻炼身体。", "explanation": "这里应该用〈自律〉。“自治”用于地区或团体自己管理事务，个人约束自己要用“自律”。"}, {"text": "这位大学生自治选择了专业。", "explanation": "这里应该用〈自主〉。个人自己做决定用“自主”，“自治”指地区或团体自行管理事务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91475, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自治", "is_correct": true, "explanation": "正确。“已经……了十年”后接“自治”，指居民所在地区自行管理事务，符合句意。"}, {"text": "生锈", "is_correct": false, "explanation": "语义：“生锈”指金属被氧化，居民不会生锈，与句意矛盾。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：“结冰”指液体变成固体，不用来形容居民。"}, {"text": "开花", "is_correct": false, "explanation": "搭配：“开花”一般用于植物，不搭配“居民”。"}], "explanations": {"自治": "正确。“已经……了十年”后接“自治”，指居民所在地区自行管理事务，符合句意。", "生锈": "语义：“生锈”指金属被氧化，居民不会生锈，与句意矛盾。", "结冰": "语义：“结冰”指液体变成固体，不用来形容居民。", "开花": "搭配：“开花”一般用于植物，不搭配“居民”。"}, "sentence_index": 6, "correct_answer": "自治"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶已经能自治生活了。", "explanation": "这里应该用〈自理〉。个人照顾自己的生活用“自理”，“自治”用于地区或团体。"}, {"text": "他自治留下来帮忙。", "explanation": "这里应该用〈自愿〉。个人主动做某事用“自愿”，“自治”指地区或团体管理自身事务。"}, {"text": "他很早就自治了。", "explanation": "这里应该用〈自立〉。个人独立生活、不靠他人用“自立”，“自治”不用于个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91475, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个地区还不有自治。", "corrected_sentence": "这个地区还没有自治。", "error_description": "否定词错误：错误形式“不有自治”，正确形式“没有自治”。表示尚未具备的有无，要用“没有”，不用“不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91475, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里已经实行了十个年自治。", "corrected_sentence": "这里已经实行了十年自治。", "error_description": "错误在“个”。“年”可以直接跟数词，不加量词“个”，应说“十年自治”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
