INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91476, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "自己管理自己的事务。", "primary_collocate": null, "pronunciation": "zì zhì", "ipa": "tsɨ˥˩ ʈʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "这个城市有权自治。", "target_word": "自治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方实行自治，当地人自己管理当地的事务。", "target_word": "自治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个岛一直在自治，不受别人干预。", "target_word": "自治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校让学生自治，由他们管理宿舍。", "target_word": "自治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子实行自治，村务由村民自己决定。", "target_word": "自治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去这里不能自治，现在可以了。", "target_word": "自治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的村子已经自治了很多年。", "target_word": "自治", "complexity_tier": "T3", "furigana": "tāmen de cūnzi yǐjīng zìzhì le hěn duō nián", "sentence_source": "generated"}, {"text": "小区居民自己选人管理，这就是自治。", "target_word": "自治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区希望自治，不愿受外部干预。", "target_word": "自治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学实行自治，校内事务由学校自己管理。", "target_word": "自治", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自治了", "label": "体标"}, {"form": "自治过", "label": "体标"}, {"form": "自治县", "label": "复合"}], "register": "正式", "sense_fingerprint": "政治或社会上，地方、团体自行管理本身的事务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f7f4cc0-d72a-4bc5-95a4-88c0d7487b96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91476, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "自治", "is_correct": true, "explanation": "自治是地方或团体自行管理本身的事务。"}, {"text": "资质", "is_correct": false, "explanation": "zī（第一声）与 zì（第四声）声调不同，意思是资质、素质。"}, {"text": "自知", "is_correct": false, "explanation": "zhī（第一声）与 zhì（第四声）声调不同，意思是自己知道。"}, {"text": "字纸", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是写过字的纸，多指废纸。"}], "explanations": {"自治": "自治是地方或团体自行管理本身的事务。", "资质": "zī（第一声）与 zì（第四声）声调不同，意思是资质、素质。", "自知": "zhī（第一声）与 zhì（第四声）声调不同，意思是自己知道。", "字纸": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是写过字的纸，多指废纸。"}, "sentence_index": null, "correct_answer": "自治"}, "level_3": {"options": [{"text": "自治", "is_correct": true, "explanation": "正确。“这个城市有权”后接“自治”，指城市有权自行管理事务，符合句意。"}, {"text": "飞翔", "is_correct": false, "explanation": "语义：城市不会飞翔，“飞翔”只用于有翅膀的生物或飞行器。"}, {"text": "生锈", "is_correct": false, "explanation": "语义：“生锈”指金属被氧化，与“城市”不搭。"}, {"text": "发芽", "is_correct": false, "explanation": "搭配：“发芽”多用于植物或种子，不能与“城市”搭配。"}], "explanations": {"自治": "正确。“这个城市有权”后接“自治”，指城市有权自行管理事务，符合句意。", "飞翔": "语义：城市不会飞翔，“飞翔”只用于有翅膀的生物或飞行器。", "生锈": "语义：“生锈”指金属被氧化，与“城市”不搭。", "发芽": "搭配：“发芽”多用于植物或种子，不能与“城市”搭配。"}, "sentence_index": 0, "correct_answer": "自治"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天自治地学习。", "explanation": "这里应该用〈自觉〉。个人主动做事用“自觉”，“自治”指地区或团体自己管理事务。"}, {"text": "他已经能自治生活了。", "explanation": "这里应该用〈自理〉。个人照顾自己的生活用“自理”，“自治”用于地区或团体。"}, {"text": "学校由校长自治。", "explanation": "这里应该用〈管理〉。“由……管理”表示外部人员负责；“自治”是自己管理自己的事，不能由外人负责。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91476, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自治", "is_correct": true, "explanation": "正确。“他们的村子已经……了很多年”后接“自治”，指村子自行管理事务，符合句意。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：“结冰”指液体变成固体，村子不会结冰。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”是人或动物的动作，村子不会睡觉。"}, {"text": "开花", "is_correct": false, "explanation": "搭配：“开花”多用于植物，不搭配“村子”。"}], "explanations": {"自治": "正确。“他们的村子已经……了很多年”后接“自治”，指村子自行管理事务，符合句意。", "结冰": "语义：“结冰”指液体变成固体，村子不会结冰。", "睡觉": "语义：“睡觉”是人或动物的动作，村子不会睡觉。", "开花": "搭配：“开花”多用于植物，不搭配“村子”。"}, "sentence_index": 6, "correct_answer": "自治"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他自治决定去北京工作。", "explanation": "这里应该用〈自主〉。个人自己做决定用“自主”，“自治”指地区或团体自行管理事务。"}, {"text": "他十八岁就自治了。", "explanation": "这里应该用〈自立〉。个人独立、不靠父母用“自立”，“自治”不用于个人。"}, {"text": "他自治留下来帮忙。", "explanation": "这里应该用〈自愿〉。个人主动做某事用“自愿”，“自治”指地区或团体管理自身事务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91476, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个岛曾经自治过过。", "corrected_sentence": "这个岛曾经自治过。", "error_description": "重复错误：错误形式“自治过过”，多写了一个“过”。表示经历的“过”只用一次，应说“曾经自治过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91476, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个镇正在自治过。", "corrected_sentence": "这个镇正在自治。", "error_description": "体标错误：“正在”表示动作进行中，不能与表示经历的“过”同用。应去掉“过”，说“这个镇正在自治”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
