INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91477, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "父子是爸爸和儿子。", "primary_collocate": null, "pronunciation": "fù zǐ", "ipa": "fu˥˩ tsɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "那对父子在公园里踢足球。", "target_word": "父子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这对父子长得很像。", "target_word": "父子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "父子一起去钓鱼了，玩得很开心。", "target_word": "父子", "complexity_tier": "T3", "furigana": "fù zǐ yì qǐ qù diào yú le, wán de hěn kāi xīn", "sentence_source": "generated"}, {"text": "我看见一对父子在河边走路。", "target_word": "父子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们是父子，爸爸很高，儿子也很高。", "target_word": "父子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "星期天，父子一起做饭，很开心。", "target_word": "父子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店是父子开的，生意很好。", "target_word": "父子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "父子今天早上去看电影了。", "target_word": "父子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那对父子手里拿着一个大西瓜。", "target_word": "父子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家隔壁住着一对父子，很友好。", "target_word": "父子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对", "label": "量词"}, {"form": "父子俩", "label": "复合"}], "register": "口语", "sense_fingerprint": "指爸爸和儿子两个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ce21c1-82f6-40df-91c8-18dde08ef184') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91477, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "父子", "is_correct": true, "explanation": "父子：爸爸和儿子，可以放在“那对”后面，指两人，与“在公园里踢足球”相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有生命，不会踢足球，与句子的施事冲突。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不会踢足球，“踢足球”要求有人作施事。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“对”用于成双的人或物，不能用于房子，应说“座”或“栋”。"}], "explanations": {"父子": "父子：爸爸和儿子，可以放在“那对”后面，指两人，与“在公园里踢足球”相符。", "石头": "语义：石头没有生命，不会踢足球，与句子的施事冲突。", "汽车": "语义：汽车不会踢足球，“踢足球”要求有人作施事。", "房子": "搭配：“对”用于成双的人或物，不能用于房子，应说“座”或“栋”。"}, "sentence_index": 0, "correct_answer": "父子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我看见一只父子在河边走路。", "explanation": "这里应该用〈对〉。父子指两个人，量词用“对”；“只”多用于动物或单个物件。"}, {"text": "我看见一对父子在河边走路，她们是两个小女孩。", "explanation": "父子指父亲和儿子，两人都是男性，不能指两个小女孩；这里应该用〈姐妹〉。"}, {"text": "他们俩是父子，是同一天出生的。", "explanation": "这里应该用〈兄弟〉。父子是父亲和儿子，不可能同一天出生；同一天出生的两人应说〈兄弟〉（如双胞胎）。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91477, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "父子", "is_correct": true, "explanation": "父子：爸爸和儿子，是“开的”施事，与“生意很好”相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会开店，句子的主语必须是能做事的人。"}, {"text": "宠物", "is_correct": false, "explanation": "配价：“开店”的施事必须是人，宠物不能作“开的”主体。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不可能开店。"}], "explanations": {"父子": "父子：爸爸和儿子，是“开的”施事，与“生意很好”相符。", "石头": "语义：石头不会开店，句子的主语必须是能做事的人。", "宠物": "配价：“开店”的施事必须是人，宠物不能作“开的”主体。", "窗户": "语义：窗户是建筑部件，不可能开店。"}, "sentence_index": 6, "correct_answer": "父子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这对父子结婚十年了。", "explanation": "这里应该用〈夫妻〉。父子指父亲和儿子，不能是结婚的一对；结婚的两人应说〈夫妻〉。"}, {"text": "我家隔壁住着一对父子，她们是姐妹。", "explanation": "父子指父亲和儿子，两人都是男性，不能用来指“她们”这两位女性；指两位女性时应换成〈母女〉之类的女性亲属词。"}, {"text": "我家隔壁住着一对父子，他一个人住在那里。", "explanation": "父子需要两个人，“一个人住”与“一对”相矛盾；这里应该用〈父亲〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91477, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只父子每天早上一起去跑步。", "corrected_sentence": "那对父子每天早上一起去跑步。", "error_description": "量词错误：“只”用于动物或单个东西，父子指两个人，应把“只”改为“对”，即“那对父子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91477, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个父子每天早上一起吃饭。", "corrected_sentence": "这对父子每天早上一起吃饭。", "error_description": "量词错误：“个”用于单个的人，父子是两人一组，应把“个”改为“对”，即“这对父子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
