INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91478, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "父亲和儿子的合称。", "primary_collocate": null, "pronunciation": "fù zǐ", "ipa": "fu˥˩ tsɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这对父子都是有名的医生。", "target_word": "父子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "父子两代人都在这所大学工作。", "target_word": "父子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们父子感情很好，常常一起聊天。", "target_word": "父子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "父子之间应该多说话，多听对方的想法。", "target_word": "父子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影讲的是一对父子的故事。", "target_word": "父子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们父子三年没见面，今天终于见到了。", "target_word": "父子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在比赛中，父子同时拿到了冠军。", "target_word": "父子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司是父子共同办的。", "target_word": "父子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那对父子为了钱吵了一架。", "target_word": "父子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "父子相处需要耐心，也需要尊重。", "target_word": "父子", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "对", "label": "量词"}, {"form": "父子俩", "label": "复合"}], "register": "口语", "sense_fingerprint": "父亲与儿子两人的合称，也指两人之间的关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ce21c1-82f6-40df-91c8-18dde08ef184') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91478, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "父子", "is_correct": true, "explanation": "父子：父亲与儿子的合称，与“这对”搭配，指两人都是医生。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不是医生，无法与“有名的医生”相符。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“对”一般不用于房子，且房子不能是医生。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有职业，不能是医生。"}], "explanations": {"父子": "父子：父亲与儿子的合称，与“这对”搭配，指两人都是医生。", "椅子": "语义：椅子不是医生，无法与“有名的医生”相符。", "房子": "搭配：“对”一般不用于房子，且房子不能是医生。", "石头": "语义：石头没有职业，不能是医生。"}, "sentence_index": 0, "correct_answer": "父子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这对父子是十年前结的婚。", "explanation": "这里应该用〈夫妻〉。父子是父亲和儿子，不能是结婚的一对；结婚的两人应说〈夫妻〉。"}, {"text": "他们父子俩都是女孩，性格很像。", "explanation": "父子俩指父亲和儿子，不能指两个女孩；这里应该用〈姐妹〉。"}, {"text": "这只父子都是有名的医生。", "explanation": "这里应该用〈对〉。“只”多用于动物或单个物件，父子是两人，应该用“对”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91478, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "父子", "is_correct": true, "explanation": "父子：父亲与儿子，是比赛中拿到冠军的人，与“拿到了冠军”相符。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：篮球是器材，不会在比赛中拿到冠军。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户与比赛毫无关系，不能拿到冠军。"}, {"text": "汽车", "is_correct": false, "explanation": "配价：“拿到冠军”的主体需要是人或队伍，汽车不能作主语。"}], "explanations": {"父子": "父子：父亲与儿子，是比赛中拿到冠军的人，与“拿到了冠军”相符。", "篮球": "语义：篮球是器材，不会在比赛中拿到冠军。", "窗户": "语义：窗户与比赛毫无关系，不能拿到冠军。", "汽车": "配价：“拿到冠军”的主体需要是人或队伍，汽车不能作主语。"}, "sentence_index": 6, "correct_answer": "父子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父子一个人在家，很无聊。", "explanation": "父子指两人，不能只指一个人；这里应该用〈父亲〉。"}, {"text": "这对父子是两只精美的瓷杯，很漂亮。", "explanation": "父子指父亲和儿子，是人，不能指物品；这里指的是瓷杯，应改用〈杯子〉这类物品名词。"}, {"text": "母亲和女儿相处需要耐心，这就是父子相处。", "explanation": "父子指父亲和儿子，不能指母亲和女儿；这里应该用〈母女〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91478, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只父子常常一起去钓鱼。", "corrected_sentence": "这对父子常常一起去钓鱼。", "error_description": "量词错误：“只”用于动物或单个东西，父子指两个人，应把“只”改为“对”，即“这对父子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91478, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个父子在比赛中拿到了冠军。", "corrected_sentence": "这对父子在比赛中拿到了冠军。", "error_description": "量词错误：“个”用于单个的人，父子是两人一组，应把“个”改为“对”，即“这对父子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
