INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91479, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "色彩是红、黄、蓝、绿这些颜色。", "primary_collocate": null, "pronunciation": "sè cǎi", "ipa": "sɤ˥˩ tsʰaɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这幅画的色彩很漂亮。", "target_word": "色彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天的花园里有各种色彩。", "target_word": "色彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢用明亮的色彩画画。", "target_word": "色彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "彩虹有七种色彩。", "target_word": "色彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的房间里色彩很丰富。", "target_word": "色彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天的山上，红黄的色彩真美。", "target_word": "色彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服的色彩太深了。", "target_word": "色彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片里的色彩看起来很自然。", "target_word": "色彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢这家店里鲜艳的色彩。", "target_word": "色彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子里的色彩是白色和蓝色。", "target_word": "色彩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "物体呈现的红、黄、蓝、绿等颜色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '014adc03-4858-4184-a9b1-120df8f0a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91479, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "色彩", "is_correct": true, "explanation": "色彩指颜色，“这幅画的色彩”与“很漂亮”搭配，句子通顺。"}, {"text": "歌声", "is_correct": false, "explanation": "语义：画不发出声音，不能说“这幅画的歌声”。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”不能用“漂亮”来形容。"}, {"text": "温度", "is_correct": false, "explanation": "语义：画作没有温度，“这幅画的温度”说不通。"}], "explanations": {"色彩": "色彩指颜色，“这幅画的色彩”与“很漂亮”搭配，句子通顺。", "歌声": "语义：画不发出声音，不能说“这幅画的歌声”。", "味道": "搭配：“味道”不能用“漂亮”来形容。", "温度": "语义：画作没有温度，“这幅画的温度”说不通。"}, "sentence_index": 0, "correct_answer": "色彩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把色彩倒进了水桶里，准备刷墙。", "explanation": "这里应该用〈颜料〉。色彩指颜色本身，是看到的效果，不能像颜料一样倒进水桶。"}, {"text": "这首歌的色彩很好听。", "explanation": "这里应该用〈旋律〉。“好听”形容声音、旋律，色彩是看到的颜色，不能说好听。"}, {"text": "这道菜的色彩很咸。", "explanation": "这里应该用〈味道〉。色彩指颜色，不能用“咸”来形容；“咸”形容的是味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91479, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "色彩", "is_correct": true, "explanation": "“这件衣服的色彩太深了”指颜色的深浅，应用“色彩”。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：“深”说的是颜色，不用来形容尺寸。"}, {"text": "声音", "is_correct": false, "explanation": "语义：衣服没有声音，这句话不成立。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“深”不修饰重量，应说“重”。"}], "explanations": {"色彩": "“这件衣服的色彩太深了”指颜色的深浅，应用“色彩”。", "尺寸": "搭配：“深”说的是颜色，不用来形容尺寸。", "声音": "语义：衣服没有声音，这句话不成立。", "重量": "搭配：“深”不修饰重量，应说“重”。"}, "sentence_index": 6, "correct_answer": "色彩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在纸上画了很粗的色彩。", "explanation": "这里应该用〈线条〉。“粗”形容线条，色彩不能用“粗”来形容。"}, {"text": "这块布的色彩很硬。", "explanation": "这里应该用〈质地〉。“硬”形容质地，色彩不能说硬。"}, {"text": "我把色彩贴在墙上。", "explanation": "这里应该用〈照片〉。色彩是颜色，不是可以贴在墙上的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91479, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块布有很多只色彩。", "corrected_sentence": "这块布有很多种色彩。", "error_description": "量词错误：“很多只色彩”应为“很多种色彩”。色彩用“种”计量，“只”用于动物或单件物品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91479, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "墙上有一颗淡淡的色彩。", "corrected_sentence": "墙上有一种淡淡的色彩。", "error_description": "量词错误：“一颗”应为“一种”。“颗”用于颗粒状的东西，色彩用“种”计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
