INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91480, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物所带的特点或倾向，如民族色彩、政治色彩。", "primary_collocate": null, "pronunciation": "sè cǎi", "ipa": "sɤ˥˩ tsʰaɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这首歌有很浓的民族色彩。", "target_word": "色彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话带着政治色彩。", "target_word": "色彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市有很浓的历史色彩。", "target_word": "色彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事带有神秘的色彩。", "target_word": "色彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆有浓浓的地方色彩。", "target_word": "色彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的文章有一点个人色彩。", "target_word": "色彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书有很强的宗教色彩。", "target_word": "色彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日有很浓的传统色彩。", "target_word": "色彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影带着一种悲伤的色彩。", "target_word": "色彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的画有很浓的东方色彩。", "target_word": "色彩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "事物所带的特点或倾向（民族色彩、政治色彩）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '014adc03-4858-4184-a9b1-120df8f0a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91480, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "色彩", "is_correct": true, "explanation": "“民族色彩”指事物所带的民族特点，“很浓”修饰色彩，搭配自然。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“很浓”不修饰温度，这里的“浓”说的是色彩或情调。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“很浓”不用于重量，句子不通顺。"}, {"text": "尺寸", "is_correct": false, "explanation": "语义：歌曲没有尺寸，“民族尺寸”说不通。"}], "explanations": {"色彩": "“民族色彩”指事物所带的民族特点，“很浓”修饰色彩，搭配自然。", "温度": "搭配：“很浓”不修饰温度，这里的“浓”说的是色彩或情调。", "重量": "搭配：“很浓”不用于重量，句子不通顺。", "尺寸": "语义：歌曲没有尺寸，“民族尺寸”说不通。"}, "sentence_index": 0, "correct_answer": "色彩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的色彩是三十块钱。", "explanation": "这里应该用〈价钱〉。色彩指颜色或事物的特点，不能指价钱。"}, {"text": "这座城市有很高的历史色彩。", "explanation": "这里应该用〈价值〉。“高”通常修饰价值、地位，不用来形容色彩。"}, {"text": "这家饭馆的地方色彩很甜。", "explanation": "这里应该用〈味道〉。色彩不能用“甜”来形容，“甜”形容的是味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91480, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "色彩", "is_correct": true, "explanation": "“宗教色彩”指事物带有的宗教特点，“很强”修饰色彩，搭配自然。"}, {"text": "速度", "is_correct": false, "explanation": "语义：书没有速度，“宗教速度”说不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“很强”不修饰价格，这里不能说“很强的价格”。"}, {"text": "长度", "is_correct": false, "explanation": "语义：书的长度与宗教特点无关，句子不成立。"}], "explanations": {"色彩": "“宗教色彩”指事物带有的宗教特点，“很强”修饰色彩，搭配自然。", "速度": "语义：书没有速度，“宗教速度”说不通。", "价格": "搭配：“很强”不修饰价格，这里不能说“很强的价格”。", "长度": "语义：书的长度与宗教特点无关，句子不成立。"}, "sentence_index": 6, "correct_answer": "色彩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家饭馆的地方色彩很好吃。", "explanation": "这里应该用〈菜〉。色彩指事物带有的特点，不能用“好吃”形容；好吃的是菜。"}, {"text": "这本书的宗教色彩一共有三百页。", "explanation": "这里应该用〈页数〉。色彩指书带有的特点，不能用页来计算；说多少页，应用“页数”。"}, {"text": "这部电影的悲伤色彩是两个小时。", "explanation": "这里应该用〈片长〉。色彩指电影带有的情调，不指时间长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91480, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这首歌有一只悲伤的色彩。", "corrected_sentence": "这首歌有一种悲伤的色彩。", "error_description": "量词错误：“一只悲伤的色彩”应为“一种悲伤的色彩”。色彩用“种”计量，“只”不能用于抽象的特点。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91480, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座古镇有一颗淡淡的传统色彩。", "corrected_sentence": "这座古镇有一种淡淡的传统色彩。", "error_description": "量词错误：“一颗淡淡的传统色彩”应为“一种淡淡的传统色彩”。“颗”用于颗粒状的东西，色彩用“种”计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
