INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91482, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "书籍出版的次序，如第一版、第二版。", "primary_collocate": null, "pronunciation": "bǎn cì", "ipa": "pan˨˩˦ tsʰɨ˥˩", "syllable_count": 2, "sentences": [{"text": "这本书的版次比以前高了。", "target_word": "版次", "complexity_tier": "T3", "furigana": "zhè běn shū de bǎn cì bǐ yǐ qián gāo le。", "sentence_source": "generated"}, {"text": "买书的时候，我先看一下版次。", "target_word": "版次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本词典的版次太旧了，新词都没有。", "target_word": "版次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你在书的第一页找一找版次。", "target_word": "版次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的版次写在封底上。", "target_word": "版次", "complexity_tier": "T3", "furigana": "zhè běn shū de bǎn cì xiě zài fēng dǐ shàng。", "sentence_source": "generated"}, {"text": "老师让我们先查一下版次。", "target_word": "版次", "complexity_tier": "T3", "furigana": "lǎo shī ràng wǒ men xiān chá yí xià bǎn cì。", "sentence_source": "generated"}, {"text": "我的书和你的书的版次不一样。", "target_word": "版次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "版次越高，书里的错误就越少。", "target_word": "版次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个版次的封面是红色的。", "target_word": "版次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书的最后一页写着版次和价格。", "target_word": "版次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "版次｜名词｜图书第几版的编号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a33d6d74-ea1a-4c9f-88d6-078bbe064f42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91482, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "版次", "is_correct": true, "explanation": "正确：版次可以说“高”，表示版本较新，符合“比以前高了”。"}, {"text": "作者", "is_correct": false, "explanation": "语义：作者是人，“这本书的作者比以前高了”不通，与书的版本新旧无关。"}, {"text": "书名", "is_correct": false, "explanation": "语义：书名是文字，不能说“高”。"}, {"text": "字数", "is_correct": false, "explanation": "搭配：字数说多少，不说高低。"}], "explanations": {"版次": "正确：版次可以说“高”，表示版本较新，符合“比以前高了”。", "作者": "语义：作者是人，“这本书的作者比以前高了”不通，与书的版本新旧无关。", "书名": "语义：书名是文字，不能说“高”。", "字数": "搭配：字数说多少，不说高低。"}, "sentence_index": 0, "correct_answer": "版次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台手机的版次已经更新到最新了。", "explanation": "这里应该用〈版本〉。版次只指书籍印刷的次序，手机、软件的更新要用版本。"}, {"text": "请你按版次排好队。", "explanation": "这里是“次序”的意思，但版次只指书籍印刷的次序，不能用来给人排队。"}, {"text": "这本书是第一版，版次是第三次印刷。", "explanation": "这里应该用〈印次〉。版次指第几版，同一版再次印刷要用印次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91482, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "版次", "is_correct": true, "explanation": "正确：版次指印刷的次序，两本书版次不同，所以不一样。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体形，书没有身材。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重指人或动物的重量，书不说体重。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气是人的性格表现，与书的比较不合。"}], "explanations": {"版次": "正确：版次指印刷的次序，两本书版次不同，所以不一样。", "身材": "体貌：身材指人的体形，书没有身材。", "体重": "语义：体重指人或动物的重量，书不说体重。", "脾气": "语义：脾气是人的性格表现，与书的比较不合。"}, "sentence_index": 6, "correct_answer": "版次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的版次一共印了三万本。", "explanation": "这里应该用〈印数〉。版次指第几版，一次印了多少本要用印数。"}, {"text": "我每天去图书馆的版次很多。", "explanation": "这里应该用〈次数〉。版次只指书籍的版本次序，去图书馆的次数要用次数。"}, {"text": "这本书的版次有三百页。", "explanation": "这里应该用〈页数〉。版次指第几版，书有多少页要用页数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91482, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本版次的书很好看。", "corrected_sentence": "这个版次的书很好看。", "error_description": "量词错误：“版次”前应用“个”，写作“这个版次”；“本”只用于书籍本身，不用来修饰“版次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91482, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书版次是第三版。", "corrected_sentence": "这本书的版次是第三版。", "error_description": "“的”缺失：名词“书”修饰“版次”时要用“的”，应为“这本书的版次是第三版。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
