INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91483, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "禁止", "is_correct": true, "explanation": "禁止：不准，与“许可”的意思相反。"}, {"text": "调查", "is_correct": false, "explanation": "调查：了解情况，与“许可”没有反义关系。"}, {"text": "吸引", "is_correct": false, "explanation": "吸引：引起注意或兴趣，与“许可”没有反义关系。"}, {"text": "组织", "is_correct": false, "explanation": "组织：安排人员或活动，与“许可”没有反义关系。"}], "correct_answer": "禁止", "explanations": {"禁止": "禁止：不准，与“许可”的意思相反。", "调查": "调查：了解情况，与“许可”没有反义关系。", "吸引": "吸引：引起注意或兴趣，与“许可”没有反义关系。", "组织": "组织：安排人员或活动，与“许可”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91483, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "许可是让别人可以做一件事，说：可以。", "primary_collocate": null, "pronunciation": "xǔ kě", "ipa": "ɕy˨˩˦ kʰɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "老师许可我们在教室里看书。", "target_word": "许可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理许可了我明天请假。", "target_word": "许可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校许可学生在操场上打篮球。", "target_word": "许可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈许可我周末去朋友家玩。", "target_word": "许可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生许可他下午去散步。", "target_word": "许可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司许可员工在家上班。", "target_word": "许可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆许可读者借三本书。", "target_word": "许可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸许可我一个人去。", "target_word": "许可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师许可我们早点回家。", "target_word": "许可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个博物馆许可游客拍照。", "target_word": "许可", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "许可了", "label": "体标"}, {"form": "许可证", "label": "复合"}], "register": "书面", "sense_fingerprint": "许可：同意别人做某事，说“可以”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c40d4862-37ee-47f3-905b-3a171e8ebee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91483, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "许可", "is_correct": true, "explanation": "许可：准许，允许别人做某事，这里正确。"}, {"text": "收", "is_correct": false, "explanation": "配价：“收”要带具体的东西作宾语，不能带“我们在教室里看书”这样的动作。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”带场所或卫生类对象，与“看书”的动作不搭配。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”是修理的意思，与准许无关。"}], "explanations": {"许可": "许可：准许，允许别人做某事，这里正确。", "收": "配价：“收”要带具体的东西作宾语，不能带“我们在教室里看书”这样的动作。", "打扫": "搭配：“打扫”带场所或卫生类对象，与“看书”的动作不搭配。", "修": "语义：“修”是修理的意思，与准许无关。"}, "sentence_index": 0, "correct_answer": "许可"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我许可你的这个建议。", "explanation": "这里应该用〈同意〉。“许可”指准许别人做某事，不用于表示赞成意见。"}, {"text": "学校许可了他的学历。", "explanation": "这里应该用〈认可〉。学历、成果要用“认可”，“许可”只用于准许做某事。"}, {"text": "他许可我一块新手表。", "explanation": "这里应该用〈许诺〉。许诺指答应给别人某物，“许可”指准许别人做某事，不能用于给予东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91483, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "许可", "is_correct": true, "explanation": "许可：准许，图书馆准许读者借书，这里正确。"}, {"text": "布置", "is_correct": false, "explanation": "语义：“布置”是安排或装饰的意思，与借书无关。"}, {"text": "整理", "is_correct": false, "explanation": "搭配：“整理”带物品或资料作宾语，不能带“读者借三本书”。"}, {"text": "运送", "is_correct": false, "explanation": "配价：“运送”要带货物作宾语，不能带一个借书的动作。"}], "explanations": {"许可": "许可：准许，图书馆准许读者借书，这里正确。", "布置": "语义：“布置”是安排或装饰的意思，与借书无关。", "整理": "搭配：“整理”带物品或资料作宾语，不能带“读者借三本书”。", "运送": "配价：“运送”要带货物作宾语，不能带一个借书的动作。"}, "sentence_index": 6, "correct_answer": "许可"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他许可自己说错了。", "explanation": "这里应该用〈承认〉。“许可”是准许做某事，不用于承认自己说错。"}, {"text": "老师许可这本书，大家都该读。", "explanation": "这里应该用〈推荐〉。“许可”是准许某人做某事，不用于推荐物品。"}, {"text": "妈妈许可我的想法。", "explanation": "这里应该用〈赞同〉。“许可”不用于对想法表示赞成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91483, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经理许可他了明天请假。", "corrected_sentence": "经理许可了他明天请假。", "error_description": "“了”位置错：“了”要紧跟动词“许可”，应说“许可了他”，不能放在宾语“他”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
