INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91484, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "允许；准许。", "primary_collocate": null, "pronunciation": "xǔ kě", "ipa": "ɕy˨˩˦ kʰɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "法律许可公民自由集会。", "target_word": "许可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主人许可客人进了房间。", "target_word": "许可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公园许可带狗进来。", "target_word": "许可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店许可顾客试穿衣服。", "target_word": "许可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长许可学生用手机查资料。", "target_word": "许可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院许可家属在下午探望病人。", "target_word": "许可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板许可我今天早点下班。", "target_word": "许可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里许可大家在草坪上野餐。", "target_word": "许可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈许可孩子玩一会儿游戏。", "target_word": "许可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷许可我们周末去爬山。", "target_word": "许可", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "许可了", "label": "体标"}, {"form": "许可证", "label": "复合"}], "register": "书面", "sense_fingerprint": "许可：允许、准许", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c40d4862-37ee-47f3-905b-3a171e8ebee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91484, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "许可", "is_correct": true, "explanation": "许可：允许、准许，法律允许公民集会，这里正确。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”是修理的意思，与法律、集会无关。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”带场所或卫生类对象，不能带“公民自由集会”。"}, {"text": "收", "is_correct": false, "explanation": "配价：“收”要带具体的物品作宾语，不能带一个集会。"}], "explanations": {"许可": "许可：允许、准许，法律允许公民集会，这里正确。", "修": "语义：“修”是修理的意思，与法律、集会无关。", "打扫": "搭配：“打扫”带场所或卫生类对象，不能带“公民自由集会”。", "收": "配价：“收”要带具体的物品作宾语，不能带一个集会。"}, "sentence_index": 0, "correct_answer": "许可"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我许可你的看法。", "explanation": "这里应该用〈同意〉。“许可”指准许别人做某事，不用于对看法表示赞成。"}, {"text": "他许可了自己的错误。", "explanation": "这里应该用〈承认〉。“许可”是准许做事，不能用于承认错误。"}, {"text": "他许可我一辆新车。", "explanation": "这里应该用〈许诺〉。许诺指答应给别人某物，“许可”指准许别人做某事，不能用于给予东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91484, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "许可", "is_correct": true, "explanation": "许可：允许、准许，老板准许我早点下班，这里正确。"}, {"text": "赔偿", "is_correct": false, "explanation": "配价：“赔偿”要带损失或财物作宾语，不能带“我早点下班”。"}, {"text": "粉刷", "is_correct": false, "explanation": "语义：“粉刷”是刷墙的意思，与下班无关。"}, {"text": "搬运", "is_correct": false, "explanation": "配价：“搬运”要带货物作宾语，不能带“我早点下班”这样的动作。"}], "explanations": {"许可": "许可：允许、准许，老板准许我早点下班，这里正确。", "赔偿": "配价：“赔偿”要带损失或财物作宾语，不能带“我早点下班”。", "粉刷": "语义：“粉刷”是刷墙的意思，与下班无关。", "搬运": "配价：“搬运”要带货物作宾语，不能带“我早点下班”这样的动作。"}, "sentence_index": 6, "correct_answer": "许可"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朋友许可这家餐厅。", "explanation": "这里应该用〈推荐〉。“许可”是准许做某事，不用于推荐地方。"}, {"text": "老师许可了他的努力。", "explanation": "这里应该用〈肯定〉。“许可”是准许做某事，不用于对别人的努力表示认可。"}, {"text": "大家都许可他是好人。", "explanation": "这里应该用〈认定〉。“许可”是准许，不用于认定某人的身份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
