INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91487, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "输入是把字或数字放进电脑里。", "primary_collocate": null, "pronunciation": "shū rù", "ipa": "ʂu˥ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "请在电脑上输入你的名字。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在输入一个很长的数字。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把电话号码输入了电脑。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她输入汉字很快，一分钟能打六十个。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们把课文输入电脑里。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他输入错了一个数字，表格就不对了。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明用拼音输入汉字。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先输入这几个数字，再点一下确定。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在电脑里输入过很多字。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天要输入几百个数字。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "输入了", "label": "体标"}, {"form": "输入过", "label": "体标"}, {"form": "输入法", "label": "复合"}, {"form": "輸入", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用键盘把字或数字打进电脑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfa04d34-6d12-4e16-bb64-7be55add196d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91487, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "输入", "is_correct": true, "explanation": "正确：“输入”是用键盘把名字打进电脑，与句中的“在电脑上”搭配。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能用来处理名字。"}, {"text": "种", "is_correct": false, "explanation": "语义：“种”指栽种植物，与在电脑上写名字的动作无关。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”是切开东西，不能用于在电脑上输入名字。"}], "explanations": {"输入": "正确：“输入”是用键盘把名字打进电脑，与句中的“在电脑上”搭配。", "煮": "搭配：“煮”的对象是食物，不能用来处理名字。", "种": "语义：“种”指栽种植物，与在电脑上写名字的动作无关。", "切": "搭配：“切”是切开东西，不能用于在电脑上输入名字。"}, "sentence_index": 0, "correct_answer": "输入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电脑把结果输入到了打印机上。", "explanation": "这里应该用〈输出〉。结果从电脑送到打印机，方向是输出；输入是把数据送进电脑。"}, {"text": "妈妈把饼干输入了盒子里。", "explanation": "这里应该用〈放〉。输入只用于电脑等设备，把饼干放进盒子要用“放”。"}, {"text": "她把汉字输入到了纸上。", "explanation": "这里应该用〈写〉。输入的对象是电脑等设备，在纸上写字要用“写”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e89a61-d62c-42c5-87ed-4c30668c8358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91487, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "输入", "is_correct": true, "explanation": "正确：句中用拼音把汉字打进电脑，“输入”正合适。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是发出声音，不能用来输入汉字。"}, {"text": "刻", "is_correct": false, "explanation": "搭配：“刻”多用于刻在石头、木头上，不用于拼音输入。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”是清洗的动作，与用拼音输入汉字无关。"}], "explanations": {"输入": "正确：句中用拼音把汉字打进电脑，“输入”正合适。", "唱": "语义：“唱”是发出声音，不能用来输入汉字。", "刻": "搭配：“刻”多用于刻在石头、木头上，不用于拼音输入。", "洗": "语义：“洗”是清洗的动作，与用拼音输入汉字无关。"}, "sentence_index": 6, "correct_answer": "输入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我从网上输入了一首歌。", "explanation": "这里应该用〈下载〉。从网上取得歌曲要用下载，输入是把字或数字送进电脑。"}, {"text": "工人把货物输入了仓库。", "explanation": "这里应该用〈搬〉。输入只用于电脑等系统，把货物搬进仓库要用“搬”。"}, {"text": "他把脏衣服输入了洗衣机。", "explanation": "这里应该用〈放〉。输入是把字或数字打进电脑，把衣服放进洗衣机要用“放”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e89a61-d62c-42c5-87ed-4c30668c8358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91487, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我输入了过很多文章。", "corrected_sentence": "我输入过很多文章。", "error_description": "错误在“输入”后同时用了“了”和“过”。“了”和“过”不能同时用在同一个动词后，应只说“输入过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e89a61-d62c-42c5-87ed-4c30668c8358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91487, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把名字输入给了电脑。", "corrected_sentence": "他把名字输入了电脑。", "error_description": "错误在“输入”后多加了“给”。输入的对象是电脑，直接接在动词后，应说“输入了电脑”，不能说“输入给了电脑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e89a61-d62c-42c5-87ed-4c30668c8358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
