INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91488, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把外面的东西送进内部；用键盘等向计算机送入数据。", "primary_collocate": null, "pronunciation": "shū rù", "ipa": "ʂu˥ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "工人向机器输入了新的数据。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先输入密码，再打开手机。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生往病人身体里输入营养液。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这些数据输入了系统。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师向机器输入指令，机器就开始工作了。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器需要输入电流才能工作。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管子把水输入了水箱。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "输入错误的数据，电脑会给出错误的结果。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把考试成绩输入系统。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她输入了一串密码，门就开了。", "target_word": "输入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "输入了", "label": "体标"}, {"form": "输入过", "label": "体标"}, {"form": "输入法", "label": "复合"}, {"form": "輸入", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把数据、指令等外面的东西送进机器或系统内部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfa04d34-6d12-4e16-bb64-7be55add196d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91488, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "输入", "is_correct": true, "explanation": "正确：句中是把新数据送进机器内部，“输入”正合适。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是发声，不能用来向机器送入数据。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能用于向机器送数据。"}, {"text": "钓", "is_correct": false, "explanation": "语义：“钓”是用鱼竿捕鱼，与向机器送数据无关。"}], "explanations": {"输入": "正确：句中是把新数据送进机器内部，“输入”正合适。", "唱": "语义：“唱”是发声，不能用来向机器送入数据。", "煮": "搭配：“煮”的对象是食物，不能用于向机器送数据。", "钓": "语义：“钓”是用鱼竿捕鱼，与向机器送数据无关。"}, "sentence_index": 0, "correct_answer": "输入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "系统把结果输入到了屏幕上。", "explanation": "这里应该用〈输出〉。结果从系统送到屏幕上，方向是输出，不是输入。"}, {"text": "他把书输入了书包。", "explanation": "这里应该用〈放〉。输入多用于把数据、水、电等送进机器、系统或身体，日常把东西放进书包要用“放”。"}, {"text": "他把文件输入给了朋友。", "explanation": "这里应该用〈发送〉。输入是送进机器或系统内部，送给别人要用发送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e89a61-d62c-42c5-87ed-4c30668c8358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91488, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "输入", "is_correct": true, "explanation": "正确：管子把水送进水箱内部，“输入”正合适。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”是用火加热，不能用来形容管子送水。"}, {"text": "织", "is_correct": false, "explanation": "搭配：“织”的对象是布、线等，不能与“把水”搭配。"}, {"text": "剪", "is_correct": false, "explanation": "语义：“剪”是剪断，与管子把水送进水箱无关。"}], "explanations": {"输入": "正确：管子把水送进水箱内部，“输入”正合适。", "烤": "语义：“烤”是用火加热，不能用来形容管子送水。", "织": "搭配：“织”的对象是布、线等，不能与“把水”搭配。", "剪": "语义：“剪”是剪断，与管子把水送进水箱无关。"}, "sentence_index": 6, "correct_answer": "输入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我从网上输入了一张照片。", "explanation": "这里应该用〈下载〉。从网上取得照片要用下载，输入是送进系统内部，方向相反。"}, {"text": "他把钱输入了口袋。", "explanation": "这里应该用〈装〉。输入多用于把数据、水、电等送进机器、系统或身体，日常把钱放进口袋要用“装”。"}, {"text": "他从保险箱里输入了钱。", "explanation": "这里应该用〈取出〉。从里面拿出来要用取出，输入是送进去，方向相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e89a61-d62c-42c5-87ed-4c30668c8358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91488, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人正在把新数据输入了机器。", "corrected_sentence": "工人正在把新数据输入机器。", "error_description": "错误在“正在”和“了”不能同时用。表示正在进行的动作时，“输入”后不加“了”，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e89a61-d62c-42c5-87ed-4c30668c8358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91488, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "管理员把考试成绩输入给了系统。", "corrected_sentence": "管理员把考试成绩输入了系统。", "error_description": "错误在“输入”后多加了“给”。输入的对象是系统，直接接在动词后，应说“输入了系统”，不能说“输入给了系统”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e89a61-d62c-42c5-87ed-4c30668c8358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
