INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91489, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "乡下很多人家住在一起的地方。", "primary_collocate": null, "pronunciation": "cūn zhuāng", "ipa": "tsʰuən˥ ʈʂwɑŋ˥", "syllable_count": 2, "sentences": [{"text": "村庄里的路很窄。", "target_word": "村庄", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "河边有一个安静的村庄。", "target_word": "村庄", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我奶奶住在山脚下的村庄。", "target_word": "村庄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个村庄很小，只有二十户人家。", "target_word": "村庄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天，村庄里到处都是树。", "target_word": "村庄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个村庄的人都很热情。", "target_word": "村庄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小在一个小村庄长大。", "target_word": "村庄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们坐了一个小时的车，才到那个村庄。", "target_word": "村庄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的村庄冬天很冷，大家都烧火取暖。", "target_word": "村庄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每到晚上，村庄里的灯一盏一盏亮起来。", "target_word": "村庄", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "村莊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "乡下人家聚在一起生活的地方，强调居住和生活", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bca58ee-d389-40eb-ad5d-f4ddb4ef8f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91489, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "村庄", "is_correct": true, "explanation": "“村庄”指乡下人家聚居的地方，可以作“里”的处所，与“路很窄”搭配，句意通顺。"}, {"text": "大海", "is_correct": false, "explanation": "语义：“大海”是海洋，不能有村里那样的路，句意不通。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”没有可以走的路，与“路很窄”的描述不相符。"}, {"text": "词语", "is_correct": false, "explanation": "搭配：“里”需要搭配可以作处所的名词，“词语”不是地点，不能说“词语里的路”。"}], "explanations": {"村庄": "“村庄”指乡下人家聚居的地方，可以作“里”的处所，与“路很窄”搭配，句意通顺。", "大海": "语义：“大海”是海洋，不能有村里那样的路，句意不通。", "天空": "语义：“天空”没有可以走的路，与“路很窄”的描述不相符。", "词语": "搭配：“里”需要搭配可以作处所的名词，“词语”不是地点，不能说“词语里的路”。"}, "sentence_index": 0, "correct_answer": "村庄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把村庄放进了书包里。", "explanation": "这里应该用〈东西〉之类的小物品。“村庄”是许多人家聚居的地方，不能放进书包。"}, {"text": "这个村庄的客厅很大，我们经常在那里聚会。", "explanation": "这里应该用〈房子〉。“村庄”指乡下人家聚居的地方，不是一座房子，所以不会有客厅。"}, {"text": "这个村庄有三层楼，楼下是商店。", "explanation": "这里应该用〈楼房〉。“村庄”指许多人家聚在一起的地方，不能指一栋楼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91489, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "村庄", "is_correct": true, "explanation": "“村庄”指乡下人家聚居的地方，可以作“在……长大”的场所，与句意相符。"}, {"text": "小说", "is_correct": false, "explanation": "搭配：“在……长大”要求场所，“小说”不是地方，不能说“在一个小说长大”。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：“小猫”是动物，不是可以让人成长的场所，句意不通。"}, {"text": "小吃", "is_correct": false, "explanation": "搭配：“小吃”是食物，不能作“在……长大”的场所，搭配不当。"}], "explanations": {"村庄": "“村庄”指乡下人家聚居的地方，可以作“在……长大”的场所，与句意相符。", "小说": "搭配：“在……长大”要求场所，“小说”不是地方，不能说“在一个小说长大”。", "小猫": "语义：“小猫”是动物，不是可以让人成长的场所，句意不通。", "小吃": "搭配：“小吃”是食物，不能作“在……长大”的场所，搭配不当。"}, "sentence_index": 6, "correct_answer": "村庄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个村庄是我最好的朋友。", "explanation": "这里应该用〈人〉。“村庄”指地方，不指人，不能用来作“朋友”。"}, {"text": "这个村庄是一家大公司，有几千名员工。", "explanation": "这里应该用〈公司〉。“村庄”指乡下人家聚居的地方，不指企业组织。"}, {"text": "村庄明天要参加期末考试。", "explanation": "这里应该用〈学生〉。“村庄”不能参加考试，只有人才能参加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91489, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只村庄的路很干净。", "corrected_sentence": "这个村庄的路很干净。", "error_description": "错误在量词“只”。“村庄”应该用量词“个”，“只”一般用于动物，应说“这个村庄”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91489, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直住在一小村庄里。", "corrected_sentence": "他一直住在一个小村庄里。", "error_description": "错误在缺少量词“个”。“一小村庄”漏掉了量词，应说“一个小村庄”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
