INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91490, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "农村中居民聚居的地方。", "primary_collocate": null, "pronunciation": "cūn zhuāng", "ipa": "tsʰuən˥ ʈʂwɑŋ˥", "syllable_count": 2, "sentences": [{"text": "这条河经过三个村庄。", "target_word": "村庄", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "地图上能看到这个村庄。", "target_word": "村庄", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "村庄附近有一片大湖。", "target_word": "村庄", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公路修到了村庄门口。", "target_word": "村庄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府在每个村庄都建了学校。", "target_word": "村庄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个村庄离县城有二十公里。", "target_word": "村庄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山那边有几个小村庄，人口都不多。", "target_word": "村庄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天来了，村庄四周的田里开满了花。", "target_word": "村庄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们沿着小路走了很久，终于看到一个村庄。", "target_word": "村庄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村庄有两百年的历史，现在住着三百多人。", "target_word": "村庄", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "村莊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "农村里居民聚居的居民点，强调地理位置和规模", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bca58ee-d389-40eb-ad5d-f4ddb4ef8f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91490, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "村庄", "is_correct": true, "explanation": "“村庄”是居民聚居的地理实体，可以被河流经过，与句意相符。"}, {"text": "房间", "is_correct": false, "explanation": "语义：河流不会经过房间，“经过三个房间”句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：河流不能经过桌子，与“经过”的地理含义不符。"}, {"text": "学生", "is_correct": false, "explanation": "搭配：“经过”后面要接地理实体，不能接“学生”这类人。"}], "explanations": {"村庄": "“村庄”是居民聚居的地理实体，可以被河流经过，与句意相符。", "房间": "语义：河流不会经过房间，“经过三个房间”句意不通。", "桌子": "语义：河流不能经过桌子，与“经过”的地理含义不符。", "学生": "搭配：“经过”后面要接地理实体，不能接“学生”这类人。"}, "sentence_index": 0, "correct_answer": "村庄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在厨房里煮了一锅村庄。", "explanation": "这里应该用〈饭〉之类的食物。“村庄”是农村居民聚居的地方，不能拿来煮。"}, {"text": "这座村庄有五百万人口，是一座大城市。", "explanation": "这里“村庄”的含义被误用为〈大都市〉。“村庄”指农村中居民聚居的小地方，不能指五百万人口的大都市。"}, {"text": "我家的村庄很小，只有两个房间。", "explanation": "这里应该用〈房子〉。“村庄”指许多居民聚居的地方，不能指一个家的住所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91490, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "村庄", "is_correct": true, "explanation": "“村庄”有居民，可以说“人口”，与“几个小村庄，人口都不多”搭配，句意通顺。"}, {"text": "小说", "is_correct": false, "explanation": "搭配：“人口”只能用于地方或人群，不能说书的“人口”，搭配不当。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：“小猫”是动物，不谈“人口”，句意不通。"}, {"text": "小树", "is_correct": false, "explanation": "语义：树木没有人口，“人口都不多”的描述不适用于树。"}], "explanations": {"村庄": "“村庄”有居民，可以说“人口”，与“几个小村庄，人口都不多”搭配，句意通顺。", "小说": "搭配：“人口”只能用于地方或人群，不能说书的“人口”，搭配不当。", "小猫": "语义：“小猫”是动物，不谈“人口”，句意不通。", "小树": "语义：树木没有人口，“人口都不多”的描述不适用于树。"}, "sentence_index": 6, "correct_answer": "村庄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个村庄是我的老师，教我很多道理。", "explanation": "这里应该用〈人〉。“村庄”指地方，不指人，不能用来作“老师”。"}, {"text": "这个村庄是一家大医院，有很多医生。", "explanation": "这里应该用〈医疗机构〉。“村庄”指乡下人家聚居的地方，不指医疗机构。"}, {"text": "这个村庄在学校里考试得了第一名。", "explanation": "这里应该用〈学生〉。“村庄”不能参加考试，只有学生才能考试得名次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91490, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只村庄通了电和水。", "corrected_sentence": "这个村庄通了电和水。", "error_description": "错误在量词“只”。“村庄”应该用量词“个”，“只”一般用于动物，应说“这个村庄”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91490, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个老人住在一小村庄里。", "corrected_sentence": "那个老人住在一个小村庄里。", "error_description": "错误在缺少量词“个”。“一小村庄”漏掉了量词，应说“一个小村庄”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
