INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91491, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "狠狠是用很大的力气，很用力。", "primary_collocate": null, "pronunciation": "hěn hěn", "ipa": "xən˨˩˦ xən˨˩˦", "syllable_count": 2, "sentences": [{"text": "他狠狠地踢了一脚球。", "target_word": "狠狠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她狠狠地关上了门。", "target_word": "狠狠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他狠狠地打了一下桌子。", "target_word": "狠狠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗狠狠咬住了骨头。", "target_word": "狠狠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把球狠狠扔到墙上。", "target_word": "狠狠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师狠狠拍了一下黑板。", "target_word": "狠狠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟狠狠地摔了一下书包。", "target_word": "狠狠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他狠狠地抓住我的手。", "target_word": "狠狠", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他狠狠踩了一脚油门。", "target_word": "狠狠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她狠狠地咬了一口苹果。", "target_word": "狠狠", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "狠狠地", "label": "状语形式"}], "register": "口语", "sense_fingerprint": "狠狠：动作用力很大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03f6c3ff-8465-4cfa-85d4-ff2eb6f04201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91491, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "狠狠", "is_correct": true, "explanation": "狠狠表示用很大的力气，与“踢一脚球”的用力动作相符。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：温柔指轻柔的态度或动作，与用力踢球的动作冲突。"}, {"text": "礼貌", "is_correct": false, "explanation": "语义：礼貌指待人接物的态度，与踢球这种动作无关。"}, {"text": "恭敬", "is_correct": false, "explanation": "语义：恭敬指郑重有礼的态度，与用力踢球的动作不合。"}], "explanations": {"狠狠": "狠狠表示用很大的力气，与“踢一脚球”的用力动作相符。", "温柔": "语义：温柔指轻柔的态度或动作，与用力踢球的动作冲突。", "礼貌": "语义：礼貌指待人接物的态度，与踢球这种动作无关。", "恭敬": "语义：恭敬指郑重有礼的态度，与用力踢球的动作不合。"}, "sentence_index": 0, "correct_answer": "狠狠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她狠狠地把信纸折好，动作小心得像在捧着一件宝贝。", "explanation": "这里应该用〈轻轻〉。狠狠强调用很大力气，与“动作小心”的轻柔不合。"}, {"text": "他狠狠地溜出了教室。", "explanation": "这里应该用〈悄悄〉。狠狠强调用很大力气，与“溜出教室”要求的安静、隐秘不合。"}, {"text": "他狠狠地抚摸着那只受伤的小猫，小心翼翼地不敢用力。", "explanation": "这里应该用〈轻轻〉。狠狠强调用很大力气，与“小心翼翼地不敢用力”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91491, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "狠狠", "is_correct": true, "explanation": "狠狠表示用很大的力气，与“摔”这种用力的动作相符。"}, {"text": "客气", "is_correct": false, "explanation": "语义：客气指待人有礼、不随便，与摔书包的动作不合。"}, {"text": "小心翼翼", "is_correct": false, "explanation": "语义：小心翼翼表示谨慎轻缓，与“摔”的用力动作冲突。"}, {"text": "文雅", "is_correct": false, "explanation": "语义：文雅指举止斯文，与摔书包这种粗重动作不合。"}], "explanations": {"狠狠": "狠狠表示用很大的力气，与“摔”这种用力的动作相符。", "客气": "语义：客气指待人有礼、不随便，与摔书包的动作不合。", "小心翼翼": "语义：小心翼翼表示谨慎轻缓，与“摔”的用力动作冲突。", "文雅": "语义：文雅指举止斯文，与摔书包这种粗重动作不合。"}, "sentence_index": 6, "correct_answer": "狠狠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她狠狠地用了一点点力气，把门推开了。", "explanation": "这里应该用〈轻轻〉。狠狠强调用很大力气，与“一点点力气”相矛盾。"}, {"text": "他狠狠地站在窗前，慢慢地呼吸着清晨的空气。", "explanation": "这里应该用〈安静〉。狠狠强调用很大力气，与“慢慢呼吸”的平静不合。"}, {"text": "我狠狠地擦了擦眼泪，却没有用一点力气。", "explanation": "这里应该用〈轻柔〉。狠狠强调用很大力气，与“没有用一点力气”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91491, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把门很狠狠地关上了。", "corrected_sentence": "他把门狠狠地关上了。", "error_description": "错误：“很狠狠地”。正确：“狠狠地”。狠狠本身已表示用力的程度，前面不能再加“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91491, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她狠狠的摔了一跤。", "corrected_sentence": "她狠狠地摔了一跤。", "error_description": "错误：“狠狠的”。正确：“狠狠地”。狠狠在这里作状语修饰动词，应用“地”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
