INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91492, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "副词，表示态度凶狠或程度很深。", "primary_collocate": null, "pronunciation": "hěn hěn", "ipa": "xən˨˩˦ xən˨˩˦", "syllable_count": 2, "sentences": [{"text": "妈妈狠狠地批评了我。", "target_word": "狠狠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板狠狠瞪了他一眼。", "target_word": "狠狠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他狠狠地骂了弟弟一顿。", "target_word": "狠狠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要狠狠地教训他一下。", "target_word": "狠狠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他狠狠地说：“我不会原谅你。”", "target_word": "狠狠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她狠狠地瞪着我，一句话也不说。", "target_word": "狠狠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店狠狠宰了我一顿。", "target_word": "狠狠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年房价狠狠涨了一大截。", "target_word": "狠狠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他狠狠地责备自己，不该撒谎。", "target_word": "狠狠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师狠狠地训了迟到的同学。", "target_word": "狠狠", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "狠狠地", "label": "状语形式"}], "register": "口语", "sense_fingerprint": "狠狠：态度凶狠或程度很深", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03f6c3ff-8465-4cfa-85d4-ff2eb6f04201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91492, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "狠狠", "is_correct": true, "explanation": "狠狠表示态度严厉，与“批评”的严厉态度相符。"}, {"text": "愉快", "is_correct": false, "explanation": "语义：愉快表示高兴，与“批评”的严厉态度不合。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“热情”多用于待人接物，一般不说“热情地批评”。"}, {"text": "亲热", "is_correct": false, "explanation": "语义：亲热表示亲近，与“批评”的态度相反。"}], "explanations": {"狠狠": "狠狠表示态度严厉，与“批评”的严厉态度相符。", "愉快": "语义：愉快表示高兴，与“批评”的严厉态度不合。", "热情": "搭配：“热情”多用于待人接物，一般不说“热情地批评”。", "亲热": "语义：亲热表示亲近，与“批评”的态度相反。"}, "sentence_index": 0, "correct_answer": "狠狠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他狠狠地欢迎了客人。", "explanation": "这里应该用〈热情〉。狠狠表示态度凶狠，与“欢迎客人”的友好态度相反。"}, {"text": "他狠狠地喝了一小口水。", "explanation": "这里应该用〈轻轻〉。狠狠表示用力大或程度深，与“一小口”的少量不合。"}, {"text": "她狠狠地微笑着，对每个人都很亲切。", "explanation": "这里应该用〈友好〉。狠狠表示态度凶狠，与“对每个人都很亲切”的友好态度相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91492, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "狠狠", "is_correct": true, "explanation": "狠狠表示下手很重，与“宰了我一顿”的狠相符。"}, {"text": "稍微", "is_correct": false, "explanation": "语义：稍微表示轻微，与“宰了我一顿”的程度不合。"}, {"text": "轻轻", "is_correct": false, "explanation": "搭配：“轻轻”不修饰“宰”这种狠的动作。"}, {"text": "亲切", "is_correct": false, "explanation": "语义：亲切表示友好，与“宰”的态度相反。"}], "explanations": {"狠狠": "狠狠表示下手很重，与“宰了我一顿”的狠相符。", "稍微": "语义：稍微表示轻微，与“宰了我一顿”的程度不合。", "轻轻": "搭配：“轻轻”不修饰“宰”这种狠的动作。", "亲切": "语义：亲切表示友好，与“宰”的态度相反。"}, "sentence_index": 6, "correct_answer": "狠狠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她狠狠地安慰了伤心的孩子，语气却温柔得像春风。", "explanation": "这里应该用〈柔和〉。狠狠表示态度凶或用力大，与“语气温柔得像春风”相矛盾。"}, {"text": "她狠狠地向新同学问好，脸上带着温和的笑。", "explanation": "这里应该用〈热情〉。狠狠表示态度凶狠，与温和问好的友好态度不合。"}, {"text": "奶奶狠狠地夸了我几句，笑得特别开心。", "explanation": "这里应该用〈高兴〉。狠狠表示态度凶狠，与奶奶开心夸奖的友好态度相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91492, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父亲很狠狠地责备了弟弟。", "corrected_sentence": "父亲狠狠地责备了弟弟。", "error_description": "错误：“很狠狠地”。正确：“狠狠地”。狠狠本身已表示程度很深，前面不能再加“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91492, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板狠狠的罚了他一笔钱。", "corrected_sentence": "老板狠狠地罚了他一笔钱。", "error_description": "错误：“狠狠的”。正确：“狠狠地”。狠狠在这里作状语修饰动词，应用“地”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
