INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91493, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91493, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "道歉是做错事后，对别人说：对不起。", "primary_collocate": null, "pronunciation": "dào qiàn", "ipa": "taʊ˥˩ tɕʰjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我做错了事，应该向他道歉。", "target_word": "道歉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他迟到了，马上向老师道歉。", "target_word": "道歉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明打破了杯子，向妈妈道歉。", "target_word": "道歉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事是我不对，我向你道歉。", "target_word": "道歉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为说错话向朋友道歉。", "target_word": "道歉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你踩了别人的脚，快去道歉。", "target_word": "道歉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他明明做错了事，却不愿意向同学道歉。", "target_word": "道歉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟哭着向姐姐道歉。", "target_word": "道歉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天忘了来，今天特意来道歉。", "target_word": "道歉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机向乘客道歉了。", "target_word": "道歉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "道了歉", "label": "离合"}, {"form": "道过歉", "label": "离合"}, {"form": "道个歉", "label": "离合"}], "register": "中性", "sense_fingerprint": "道歉：做错事后向别人说对不起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c40d4862-37ee-47f3-905b-3a171e8ebee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91493, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "道歉", "is_correct": true, "explanation": "正确。“道歉”指做错事后向人表示歉意，与句中的“做错了事”相符。"}, {"text": "报喜", "is_correct": false, "explanation": "语义：“报喜”是告知好消息，与“做错了事”的语境相反。"}, {"text": "致谢", "is_correct": false, "explanation": "语义：“致谢”是表示感谢，与前文的过错语境不符。"}, {"text": "道喜", "is_correct": false, "explanation": "语义：“道喜”是向人表示祝贺，与“做错了事”的语境相反。"}], "explanations": {"道歉": "正确。“道歉”指做错事后向人表示歉意，与句中的“做错了事”相符。", "报喜": "语义：“报喜”是告知好消息，与“做错了事”的语境相反。", "致谢": "语义：“致谢”是表示感谢，与前文的过错语境不符。", "道喜": "语义：“道喜”是向人表示祝贺，与“做错了事”的语境相反。"}, "sentence_index": 0, "correct_answer": "道歉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "谢谢你帮我搬家，我向你道歉。", "explanation": "这里应该用〈道谢〉。道歉是为自己的错误向人致歉，感谢别人的帮助要用道谢。"}, {"text": "他结婚了，我向他道歉。", "explanation": "这里应该用〈道喜〉。道歉用于因过错而致歉，对别人的喜事要用道喜。"}, {"text": "他要出国了，我向他道歉，祝他一路顺风。", "explanation": "这里应该用〈道别〉。道歉是为过错致歉，临别时向人告别要用道别。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91493, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "道歉", "is_correct": true, "explanation": "正确。“道歉”表示因过错向人致歉，符合“不愿意”认错的语境。"}, {"text": "致敬", "is_correct": false, "explanation": "语义：“致敬”表示敬重，多用于对前辈、英雄，与“不愿意”的语境不符。"}, {"text": "报到", "is_correct": false, "explanation": "搭配：“报到”的对象是学校、单位，不说向同学报到。"}, {"text": "请示", "is_correct": false, "explanation": "搭配：“请示”多用于下级向上级，对同学不这样说。"}], "explanations": {"道歉": "正确。“道歉”表示因过错向人致歉，符合“不愿意”认错的语境。", "致敬": "语义：“致敬”表示敬重，多用于对前辈、英雄，与“不愿意”的语境不符。", "报到": "搭配：“报到”的对象是学校、单位，不说向同学报到。", "请示": "搭配：“请示”多用于下级向上级，对同学不这样说。"}, "sentence_index": 6, "correct_answer": "道歉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拿到了冠军，我们都向他道歉。", "explanation": "这里应该用〈祝贺〉。道歉用于因过错致歉，对别人的喜事要用祝贺。"}, {"text": "这次活动多亏了大家，我向每位志愿者道歉。", "explanation": "这里应该用〈致谢〉。道歉是为过错致歉，感谢别人的帮助要用致谢。"}, {"text": "爷爷八十大寿，我们向他道歉。", "explanation": "这里应该用〈祝寿〉。道歉用于因过错致歉，给长辈庆生要用祝寿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91493, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你去向她道歉个吧。", "corrected_sentence": "你去向她道个歉吧。", "error_description": "“道歉”是离合词，量词“个”要插在“道”和“歉”之间，应说“道个歉”，不能说“道歉个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91493, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从老师道歉。", "corrected_sentence": "他向老师道歉。", "error_description": "“道歉”引出对象要用介词“向”，“从”不能引出道歉的对象，应说“向老师道歉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
