INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91494, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91494, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "因做错事向别人表示歉意。", "primary_collocate": null, "pronunciation": "dào qiàn", "ipa": "taʊ˥˩ tɕʰjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "公司向客户道歉。", "target_word": "道歉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为说谎向大家道歉。", "target_word": "道歉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板为服务不好向客人道歉。", "target_word": "道歉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你错了就要道歉。", "target_word": "道歉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他早就向我道歉了，我不生气了。", "target_word": "道歉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子打了人，妈妈带他去道歉。", "target_word": "道歉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校为这次漏水事故向家长道歉。", "target_word": "道歉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "航空公司向乘客道歉，因为飞机晚点了。", "target_word": "道歉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想当面向她道歉。", "target_word": "道歉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一封信来道歉。", "target_word": "道歉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "道了歉", "label": "离合"}, {"form": "道过歉", "label": "离合"}, {"form": "道个歉", "label": "离合"}], "register": "中性", "sense_fingerprint": "道歉：因错误向人表示歉意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c40d4862-37ee-47f3-905b-3a171e8ebee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91494, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "道歉", "is_correct": true, "explanation": "正确。“道歉”指因错误向人表示歉意，与“公司向客户”的句意相符。"}, {"text": "请示", "is_correct": false, "explanation": "搭配：“请示”多用于下级向上级，公司对客户不这样说。"}, {"text": "报到", "is_correct": false, "explanation": "搭配：“报到”是到单位或学校登记，不能对客户说。"}, {"text": "投诉", "is_correct": false, "explanation": "语义：“投诉”是客户向公司提出不满，方向与句意相反。"}], "explanations": {"道歉": "正确。“道歉”指因错误向人表示歉意，与“公司向客户”的句意相符。", "请示": "搭配：“请示”多用于下级向上级，公司对客户不这样说。", "报到": "搭配：“报到”是到单位或学校登记，不能对客户说。", "投诉": "语义：“投诉”是客户向公司提出不满，方向与句意相反。"}, "sentence_index": 0, "correct_answer": "道歉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "谢谢你的帮助，我向你道歉。", "explanation": "这里应该用〈致谢〉。道歉用于因错误而致歉，感谢别人的帮助要用致谢。"}, {"text": "他升职了，我们向他道歉。", "explanation": "这里应该用〈祝贺〉。道歉用于因错误致歉，对别人的喜事要用祝贺。"}, {"text": "奶奶八十大寿，我们向她道歉。", "explanation": "这里应该用〈祝寿〉。道歉用于因错误致歉，给长辈庆生要用祝寿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91494, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "道歉", "is_correct": true, "explanation": "正确。“道歉”表示因错误向人致歉，与“漏水事故”的负面语境相符。"}, {"text": "祝寿", "is_correct": false, "explanation": "语义：“祝寿”是给长辈庆生，与“漏水事故”的负面语境不符。"}, {"text": "庆贺", "is_correct": false, "explanation": "语义：“庆贺”用于喜事，与“漏水事故”的负面语境不符。"}, {"text": "报喜", "is_correct": false, "explanation": "语义：“报喜”是告知好消息，与“漏水事故”的负面语境相反。"}], "explanations": {"道歉": "正确。“道歉”表示因错误向人致歉，与“漏水事故”的负面语境相符。", "祝寿": "语义：“祝寿”是给长辈庆生，与“漏水事故”的负面语境不符。", "庆贺": "语义：“庆贺”用于喜事，与“漏水事故”的负面语境不符。", "报喜": "语义：“报喜”是告知好消息，与“漏水事故”的负面语境相反。"}, "sentence_index": 6, "correct_answer": "道歉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他考上了大学，我向他道歉。", "explanation": "这里应该用〈道喜〉。道歉用于因错误致歉，对别人的喜事要用道喜。"}, {"text": "我向父母道歉，说我考上了大学。", "explanation": "这里应该用〈报喜〉。道歉是为错误致歉，告诉父母好消息要用报喜。"}, {"text": "春节到了，我们向长辈道歉。", "explanation": "这里应该用〈拜年〉。道歉用于因错误致歉，春节向长辈问候要用拜年。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91494, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们好好跟他道歉个吧。", "corrected_sentence": "我们好好跟他道个歉吧。", "error_description": "“道歉”是离合词，量词“个”要插在“道”和“歉”之间，应说“道个歉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91494, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把我道歉了。", "corrected_sentence": "他向我道歉了。", "error_description": "“道歉”不能用“把”引出对象，道歉的对象要用介词“向”引出，应说“向我道歉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
