INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91496, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "工作或事业上取得的成绩。", "primary_collocate": null, "pronunciation": "yè jì", "ipa": "jɛ˥˩ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "他在这家公司做出了很大的业绩。", "target_word": "业绩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生在医院里取得了很好的业绩。", "target_word": "业绩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老总用十年时间创下了好业绩。", "target_word": "业绩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王教授在研究工作中取得了不少业绩。", "target_word": "业绩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年轻时就在工作上取得了不错的业绩。", "target_word": "业绩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些年，她的业绩让大家很佩服。", "target_word": "业绩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的同事想早点做出业绩。", "target_word": "业绩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为国家的建设做出了不少业绩。", "target_word": "业绩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看一个人的能力，要看他有什么业绩。", "target_word": "业绩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位经理的业绩被写进了报纸。", "target_word": "业绩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "業績", "label": "繁体"}], "register": "正式", "sense_fingerprint": "业绩：工作或事业上取得的成就，指个人事业成果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae461367-2454-4efb-ad9b-fb4db9b634ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91496, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "业绩", "is_correct": true, "explanation": "业绩：工作或事业上取得的成绩，这里指他在公司的工作成果。"}, {"text": "距离", "is_correct": false, "explanation": "语义：「距离」不是人做出来的成果，「做出很大的距离」与句意不合。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：脾气要说「发脾气」，不说「做出脾气」。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：价格一般说「定价格」，不说「做出很大的价格」。"}], "explanations": {"业绩": "业绩：工作或事业上取得的成绩，这里指他在公司的工作成果。", "距离": "语义：「距离」不是人做出来的成果，「做出很大的距离」与句意不合。", "脾气": "搭配：脾气要说「发脾气」，不说「做出脾气」。", "价格": "搭配：价格一般说「定价格」，不说「做出很大的价格」。"}, "sentence_index": 0, "correct_answer": "业绩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个学期，他在学习上取得了不少业绩。", "explanation": "这里应该用〈成绩〉。业绩指工作或事业上的成果，学习上的好结果要用成绩。"}, {"text": "这个孩子在幼儿园取得了不少业绩。", "explanation": "这里应该用〈表现〉。业绩指工作或事业上的成果，孩子在幼儿园的表现不能用业绩。"}, {"text": "王教授在研究工作中写了不少业绩。", "explanation": "这里应该用〈论文〉。业绩是取得的成果，不能写出来，写的是论文。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36cfc26a-16e9-4aec-93c8-c601166373e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91496, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "业绩", "is_correct": true, "explanation": "业绩：工作或事业上取得的成绩，这里指新同事做出的工作成果。"}, {"text": "梦", "is_correct": false, "explanation": "搭配：「做梦」是做梦，不说「做出梦」。"}, {"text": "家务", "is_correct": false, "explanation": "搭配：「做家务」是动词加宾语，「做出家务」说不通。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是人做出的成果，与「想早点做出」不合。"}], "explanations": {"业绩": "业绩：工作或事业上取得的成绩，这里指新同事做出的工作成果。", "梦": "搭配：「做梦」是做梦，不说「做出梦」。", "家务": "搭配：「做家务」是动词加宾语，「做出家务」说不通。", "空气": "语义：空气不是人做出的成果，与「想早点做出」不合。"}, "sentence_index": 6, "correct_answer": "业绩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次期末考试，他的业绩是全班第一。", "explanation": "这里应该用〈成绩〉。业绩指工作或事业上的成果，考试的分数和名次要说成绩。"}, {"text": "这家公司的业绩是卖电脑和手机。", "explanation": "这里应该用〈业务〉。业绩是工作取得的成果，公司做什么生意、经营什么要说业务。"}, {"text": "他很诚实，业绩也很好，从来不骗人。", "explanation": "这里应该用〈品德〉。业绩指工作上的成果，诚实、不骗人说的是人的品德。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36cfc26a-16e9-4aec-93c8-c601166373e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91496, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在工作中取得了一部很好的业绩。", "corrected_sentence": "他在工作中取得了一项很好的业绩。", "error_description": "「业绩」的量词应该用「项」，「部」用于书、电影、机器等，不能用来数业绩。正确写法是「他在工作中取得了一项很好的业绩。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36cfc26a-16e9-4aec-93c8-c601166373e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91496, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年取得了一条很好的业绩。", "corrected_sentence": "他去年取得了一项很好的业绩。", "error_description": "「业绩」的量词应该用「项」，「条」用于细长的东西或消息，不能用来数业绩。正确写法是「他去年取得了一项很好的业绩。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36cfc26a-16e9-4aec-93c8-c601166373e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
