INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91497, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "那时候是过去的某一个时间。", "primary_collocate": null, "pronunciation": "nà shí hou", "ipa": "na˥˩ ʂɨ˧˥ xoʊ", "syllable_count": 3, "sentences": [{"text": "那时候我还很小。", "target_word": "那时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时候这里没有高楼。", "target_word": "那时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们那时候常常一起玩。", "target_word": "那时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时候爷爷住在农村。", "target_word": "那时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时候没有手机，我们写信。", "target_word": "那时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他那时候在上海工作。", "target_word": "那时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时候的天气比现在冷。", "target_word": "那时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我记得那时候你很爱笑。", "target_word": "那时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时候我每天走路去学校。", "target_word": "那时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时候，妈妈做饭做得很好吃。", "target_word": "那时候", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "那个时候", "label": "变体"}, {"form": "那时", "label": "简称"}], "register": "口语", "sense_fingerprint": "那时候：过去的某个时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c40d4862-37ee-47f3-905b-3a171e8ebee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91497, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "那时候", "is_correct": true, "explanation": "正确。“那时候”指过去的某个时间，与“还很小”的童年语境相符。"}, {"text": "晚上", "is_correct": false, "explanation": "语义：“晚上”指夜间，与“还很小”的童年语境不符。"}, {"text": "北京", "is_correct": false, "explanation": "搭配：“北京”是地点，不能充当表示时间的状语。"}, {"text": "星期天", "is_correct": false, "explanation": "语义：“星期天”是具体的某一天，与“还很小”的童年语境不符。"}], "explanations": {"那时候": "正确。“那时候”指过去的某个时间，与“还很小”的童年语境相符。", "晚上": "语义：“晚上”指夜间，与“还很小”的童年语境不符。", "北京": "搭配：“北京”是地点，不能充当表示时间的状语。", "星期天": "语义：“星期天”是具体的某一天，与“还很小”的童年语境不符。"}, "sentence_index": 0, "correct_answer": "那时候"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把那时候借给了朋友。", "explanation": "〈那时候〉是时间词，不能像书或钱一样被借出去，这里把它当作可以借给别人的东西，用法不通。"}, {"text": "我把那时候放进了书包。", "explanation": "〈那时候〉是时间词，表示时间，不能像具体物品一样被放进书包。"}, {"text": "我给那时候打了个电话。", "explanation": "〈那时候〉是时间词，不能当作打电话的对象，用法不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91497, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "那时候", "is_correct": true, "explanation": "正确。“那时候”指过去的某个时间，与“比现在冷”的时间对比相符。"}, {"text": "此刻", "is_correct": false, "explanation": "语义：“此刻”就是现在，不能与“现在”构成过去与现在的对比。"}, {"text": "这时候", "is_correct": false, "explanation": "语义：“这时候”就是现在，与句中的“现在”指同一时间，无法构成过去与现在的对比。"}, {"text": "现在", "is_correct": false, "explanation": "搭配：句中已用“现在”作比较基准，再用它作主语，搭配不通。"}], "explanations": {"那时候": "正确。“那时候”指过去的某个时间，与“比现在冷”的时间对比相符。", "此刻": "语义：“此刻”就是现在，不能与“现在”构成过去与现在的对比。", "这时候": "语义：“这时候”就是现在，与句中的“现在”指同一时间，无法构成过去与现在的对比。", "现在": "搭配：句中已用“现在”作比较基准，再用它作主语，搭配不通。"}, "sentence_index": 6, "correct_answer": "那时候"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一个那时候。", "explanation": "〈那时候〉是时间词，不能像具体东西一样用量词计算。"}, {"text": "我们一起去那时候吃饭。", "explanation": "〈那时候〉是时间，不能作为去的处所。"}, {"text": "我坐在那时候上。", "explanation": "〈那时候〉不是可以坐的地方，这里把它当作地点，说法不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91497, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那时候得农村很安静。", "corrected_sentence": "那时候的农村很安静。", "error_description": "“那时候”修饰名词“农村”时要用结构助词“的”，不能用“得”（“得”多用于动词、形容词后的补语）。应说“那时候的农村很安静”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91497, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我那时候的在北京上学。", "corrected_sentence": "我那时候在北京上学。", "error_description": "“那时候”在这里作状语，后面直接接动词短语，不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
