INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91498, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指过去或将来的某个时间。", "primary_collocate": null, "pronunciation": "nà shí hou", "ipa": "na˥˩ ʂɨ˧˥ xoʊ", "syllable_count": 3, "sentences": [{"text": "明年夏天我们去海边，那时候天气很热。", "target_word": "那时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等你长大了，那时候你就明白了。", "target_word": "那时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下个月我毕业，那时候我去找工作。", "target_word": "那时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时候我们还没有认识。", "target_word": "那时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节快到了，那时候火车票很难买。", "target_word": "那时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我小学时住在北京，那时候常去公园。", "target_word": "那时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三年后，那时候你可能已经结婚了。", "target_word": "那时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时候他刚来中国，不会说汉语。", "target_word": "那时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我有空，那时候我们见面吧。", "target_word": "那时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时候的朋友，我现在还记得。", "target_word": "那时候", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "那个时候", "label": "变体"}, {"form": "那时", "label": "简称"}], "register": "口语", "sense_fingerprint": "那时候：上文所说的过去或将来的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c40d4862-37ee-47f3-905b-3a171e8ebee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91498, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "那时候", "is_correct": true, "explanation": "正确。“那时候”指上文所说的将来某个时间，与“明年夏天”相呼应。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”指过去，与“明年夏天”的将来时间矛盾。"}, {"text": "冬天", "is_correct": false, "explanation": "语义：“冬天”与句中的“夏天”冲突，不能指同一段时间。"}, {"text": "小时候", "is_correct": false, "explanation": "语义：“小时候”指童年，与“明年”的将来时间不合。"}], "explanations": {"那时候": "正确。“那时候”指上文所说的将来某个时间，与“明年夏天”相呼应。", "昨天": "语义：“昨天”指过去，与“明年夏天”的将来时间矛盾。", "冬天": "语义：“冬天”与句中的“夏天”冲突，不能指同一段时间。", "小时候": "语义：“小时候”指童年，与“明年”的将来时间不合。"}, "sentence_index": 0, "correct_answer": "那时候"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和那时候一起吃饭。", "explanation": "〈那时候〉只表示时间，不能当作一起吃饭的人，用法不通。"}, {"text": "我们把那时候带到了公园。", "explanation": "〈那时候〉是时间，不能被带到某个地方。"}, {"text": "他用那时候写了一封信。", "explanation": "〈那时候〉不能当作工具使用，这里用它来写信，用法不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91498, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "那时候", "is_correct": true, "explanation": "正确。“那时候”指上文所说的将来某个时间，与“三年后”相呼应。"}, {"text": "从前", "is_correct": false, "explanation": "语义：“从前”指过去，与“三年后”的将来时间矛盾。"}, {"text": "上周", "is_correct": false, "explanation": "语义：“上周”指过去的时间，与“三年后”不能搭配。"}, {"text": "那里", "is_correct": false, "explanation": "搭配：“那里”是处所词，不能用来表示时间。"}], "explanations": {"那时候": "正确。“那时候”指上文所说的将来某个时间，与“三年后”相呼应。", "从前": "语义：“从前”指过去，与“三年后”的将来时间矛盾。", "上周": "语义：“上周”指过去的时间，与“三年后”不能搭配。", "那里": "搭配：“那里”是处所词，不能用来表示时间。"}, "sentence_index": 6, "correct_answer": "那时候"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们爬上了那时候。", "explanation": "〈那时候〉是时间词，不能像山一样被爬上去。"}, {"text": "我在那时候的旁边坐着。", "explanation": "〈那时候〉表示时间，不能像方位词一样说“旁边”。"}, {"text": "我穿上了那时候。", "explanation": "〈那时候〉不能穿在身上，这里把它当作衣物，用法不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91498, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我现在还记得那时候事情。", "corrected_sentence": "我现在还记得那时候的事情。", "error_description": "“那时候”作定语修饰“事情”时，中间要加“的”，应说“那时候的事情”，不能说“那时候事情”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91498, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那时候地朋友，我现在还记得。", "corrected_sentence": "那时候的朋友，我现在还记得。", "error_description": "“那时候”作定语修饰名词“朋友”时，要用结构助词“的”，不能用“地”（“地”用在状语和动词之间）。应说“那时候的朋友”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91500, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "耻辱", "is_correct": true, "explanation": "“耻辱”与“荣耀”意义相反，指使人羞愧的名声，是这一义项的反义词。"}, {"text": "河流", "is_correct": false, "explanation": "“河流”与“荣耀”没有反义关系，只是一般的自然事物名词。"}, {"text": "课本", "is_correct": false, "explanation": "“课本”与“荣耀”没有反义关系，只是学习用的书籍。"}, {"text": "窗户", "is_correct": false, "explanation": "“窗户”与“荣耀”没有反义关系，只是房屋的组成部分。"}], "correct_answer": "耻辱", "explanations": {"耻辱": "“耻辱”与“荣耀”意义相反，指使人羞愧的名声，是这一义项的反义词。", "河流": "“河流”与“荣耀”没有反义关系，只是一般的自然事物名词。", "课本": "“课本”与“荣耀”没有反义关系，只是学习用的书籍。", "窗户": "“窗户”与“荣耀”没有反义关系，只是房屋的组成部分。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91500, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91500, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "光荣；荣誉和尊荣。", "primary_collocate": null, "pronunciation": "róng yào", "ipa": "ɻʊŋ˧˥ jɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "为国争光是运动员最大的荣耀。", "target_word": "荣耀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这枚金牌是全队的荣耀。", "target_word": "荣耀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把荣耀带给了自己的家人。", "target_word": "荣耀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "获得冠军后，他和大家一起分享荣耀。", "target_word": "荣耀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座城市有悠久的历史和荣耀。", "target_word": "荣耀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球队赢了比赛，荣耀属于每一个球员。", "target_word": "荣耀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "能代表学校参加比赛，是我的荣耀。", "target_word": "荣耀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不在乎金钱，只在乎家族的荣耀。", "target_word": "荣耀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "军人们戴着奖章，为国家的荣耀而骄傲。", "target_word": "荣耀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷常常讲起当年的荣耀。", "target_word": "荣耀", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份荣耀", "label": "量词"}, {"form": "荣耀感", "label": "复合"}, {"form": "榮耀", "label": "繁体"}], "register": "中性", "sense_fingerprint": "个人、集体或国家获得的荣誉与尊荣", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a539d2-b9bf-4579-bf7e-a6cf9155014c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91500, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "荣耀", "is_correct": true, "explanation": "“荣耀”指光荣、荣誉和尊荣，是本题的正确答案。"}, {"text": "容貌", "is_correct": false, "explanation": "róng mào 与 róng yào 只有第二个音节的声母不同（m / y），意思是脸的样子。"}, {"text": "容易", "is_correct": false, "explanation": "róng yì 与 róng yào 只有第二个音节的韵母不同（i / ao），意思是不困难。"}, {"text": "溶液", "is_correct": false, "explanation": "róng yè 与 róng yào 只有第二个音节的韵母不同（e / ao），意思是溶解了物质的液体。"}], "explanations": {"荣耀": "“荣耀”指光荣、荣誉和尊荣，是本题的正确答案。", "容貌": "róng mào 与 róng yào 只有第二个音节的声母不同（m / y），意思是脸的样子。", "容易": "róng yì 与 róng yào 只有第二个音节的韵母不同（i / ao），意思是不困难。", "溶液": "róng yè 与 róng yào 只有第二个音节的韵母不同（e / ao），意思是溶解了物质的液体。"}, "sentence_index": null, "correct_answer": "荣耀"}, "level_3": {"options": [{"text": "荣耀", "is_correct": true, "explanation": "“荣耀”指光荣，与“为国争光是运动员最大的……”的语境相符。"}, {"text": "失败", "is_correct": false, "explanation": "语义：“失败”与“为国争光”的光荣意义相反，语义冲突。"}, {"text": "灾难", "is_correct": false, "explanation": "语义：“灾难”表示严重的不幸，不能用来形容为国争光。"}, {"text": "镜子", "is_correct": false, "explanation": "搭配：“镜子”不能作为“最大的……”的评价对象，与“为国争光”不搭配。"}], "explanations": {"荣耀": "“荣耀”指光荣，与“为国争光是运动员最大的……”的语境相符。", "失败": "语义：“失败”与“为国争光”的光荣意义相反，语义冲突。", "灾难": "语义：“灾难”表示严重的不幸，不能用来形容为国争光。", "镜子": "搭配：“镜子”不能作为“最大的……”的评价对象，与“为国争光”不搭配。"}, "sentence_index": 0, "correct_answer": "荣耀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脚被玻璃割伤了，这是他的荣耀。", "explanation": "这里应该用〈痛苦〉。“荣耀”指光荣，脚伤带来的是痛苦，两者无关。"}, {"text": "他在比赛中作弊，心里满是荣耀。", "explanation": "这里应该用〈羞愧〉。“荣耀”指光荣或荣誉，作弊后的心情是羞愧，与光荣相反。"}, {"text": "这次因违规被罚下场，是全队的荣耀。", "explanation": "这里应该用〈耻辱〉。“荣耀”指光荣，因违规被罚下场是不光彩的事，两者语义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91500, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "荣耀", "is_correct": true, "explanation": "“荣耀”指光荣，与“能代表学校参加比赛，是我的……”的语境相符。"}, {"text": "耻辱", "is_correct": false, "explanation": "语义：“耻辱”表示羞辱，代表学校参赛不会是耻辱。"}, {"text": "眼泪", "is_correct": false, "explanation": "搭配：“眼泪”不能用“是……的”来评价参加比赛这件事，搭配不当。"}, {"text": "罪过", "is_correct": false, "explanation": "语义：“罪过”指过错，与代表学校参加比赛的光荣语境相冲突。"}], "explanations": {"荣耀": "“荣耀”指光荣，与“能代表学校参加比赛，是我的……”的语境相符。", "耻辱": "语义：“耻辱”表示羞辱，代表学校参赛不会是耻辱。", "眼泪": "搭配：“眼泪”不能用“是……的”来评价参加比赛这件事，搭配不当。", "罪过": "语义：“罪过”指过错，与代表学校参加比赛的光荣语境相冲突。"}, "sentence_index": 6, "correct_answer": "荣耀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爷爷常常讲起那次受的冤枉，这是他一生的荣耀。", "explanation": "这里应该用〈委屈〉。“荣耀”指光荣，被冤枉的经历是委屈，不是光荣的事。"}, {"text": "爷爷常常讲起当年的挫折，心里充满荣耀。", "explanation": "这里应该用〈伤痛〉。“荣耀”指光彩，挫折带来的是伤痛，两者语义相反。"}, {"text": "爷爷常常讲起当年的债务，那是他一辈子的荣耀。", "explanation": "这里应该用〈负担〉。“荣耀”指光荣，债务是负担，不是光荣的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91500, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是我们学校的荣耀的。", "corrected_sentence": "这是我们学校的荣耀。", "error_description": "句末多出一个“的”。“这是我们学校的荣耀”中的“的”已位于定语之后，句末多余的“的”应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91500, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场胜利为球队带了来荣耀。", "corrected_sentence": "这场胜利为球队带来了荣耀。", "error_description": "“来”是“带”的趋向补语，“了”应放在“带来”之后，写作“带来了荣耀”；“带了来荣耀”把“了”插在“带”和“来”之间，语序错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
