INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91501, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "院是房子前面或四周围起来的一块空地。", "primary_collocate": null, "pronunciation": "yuàn", "ipa": "ɥɛn˥˩", "syllable_count": 1, "sentences": [{"text": "我家的院不大，但是很干净。", "target_word": "院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在院里晒衣服。", "target_word": "院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走到院里，看见爷爷坐着。", "target_word": "院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院里种着一棵苹果树。", "target_word": "院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，大家快到院里来吧。", "target_word": "院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只猫在院里睡觉。", "target_word": "院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院外有一条小路。", "target_word": "院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人每天早上在院里走路。", "target_word": "院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，院里开满了花。", "target_word": "院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把桌子搬到院里去了。", "target_word": "院", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "院子", "label": "复合"}], "register": "通用", "sense_fingerprint": "房子前面或四周围起来的一块空地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db945215-8bb7-469b-a806-7db5687ef759') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91501, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "院", "is_correct": true, "explanation": "正确答案，院（第四声）指房子前面或四周围起来的一块空地。"}, {"text": "远", "is_correct": false, "explanation": "yuǎn（第三声）与 yuàn（第四声）声调不同，意思是远。"}, {"text": "元", "is_correct": false, "explanation": "yuán（第二声）与 yuàn（第四声）声调不同，意思是货币单位“元”。"}, {"text": "燕", "is_correct": false, "explanation": "yàn（第四声）与 yuàn（第四声）只少了 u 介音，意思是燕子。"}, {"text": "劝", "is_correct": false, "explanation": "quàn（第四声）与 yuàn 声母不同（q 与 y），意思是劝说。"}], "explanations": {"院": "正确答案，院（第四声）指房子前面或四周围起来的一块空地。", "远": "yuǎn（第三声）与 yuàn（第四声）声调不同，意思是远。", "元": "yuán（第二声）与 yuàn（第四声）声调不同，意思是货币单位“元”。", "燕": "yàn（第四声）与 yuàn（第四声）只少了 u 介音，意思是燕子。", "劝": "quàn（第四声）与 yuàn 声母不同（q 与 y），意思是劝说。"}, "sentence_index": null, "correct_answer": "院"}, "level_3": {"options": [{"text": "院", "is_correct": true, "explanation": "院是房子前面或四周围起来的空地，“我家的院不大”符合句意。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海不能是“我家的”，也不能说“不大”。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不属于某一户人家，也不能说“不大”。"}, {"text": "高山", "is_correct": false, "explanation": "配价：“我家的”要求的是可以归属某家的事物，高山不能归某家所有。"}], "explanations": {"院": "院是房子前面或四周围起来的空地，“我家的院不大”符合句意。", "大海": "语义：大海不能是“我家的”，也不能说“不大”。", "天空": "语义：天空不属于某一户人家，也不能说“不大”。", "高山": "配价：“我家的”要求的是可以归属某家的事物，高山不能归某家所有。"}, "sentence_index": 0, "correct_answer": "院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他站在院的天花板下面，觉得很压抑。", "explanation": "这里应该用〈房间〉。院是房屋周围的空地，没有天花板，不能说“院的天花板”。"}, {"text": "他打开院的抽屉，拿出了一支笔。", "explanation": "这里应该用〈柜子〉。院是露天的空地，没有抽屉，不能说“打开院的抽屉”。"}, {"text": "他把被子叠好，放进了院的衣柜。", "explanation": "这里应该用〈卧室〉。院是房屋周围的空地，不能像卧室一样放衣柜，不能说“院的衣柜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91501, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "院", "is_correct": true, "explanation": "正确答案，院（第四声）指房子前面或四周围起来的一块空地。"}, {"text": "原", "is_correct": false, "explanation": "yuán（第二声）与 yuàn（第四声）声调不同，意思是原来。"}, {"text": "卷", "is_correct": false, "explanation": "juàn（第四声）与 yuàn 声母不同（j 与 y），意思是卷起。"}, {"text": "宴", "is_correct": false, "explanation": "yàn（第四声）与 yuàn（第四声）只少了 u 介音，意思是宴会。"}, {"text": "圆", "is_correct": false, "explanation": "yuán（第二声）与 yuàn（第四声）声调不同，意思是圆。"}], "explanations": {"院": "正确答案，院（第四声）指房子前面或四周围起来的一块空地。", "原": "yuán（第二声）与 yuàn（第四声）声调不同，意思是原来。", "卷": "juàn（第四声）与 yuàn 声母不同（j 与 y），意思是卷起。", "宴": "yàn（第四声）与 yuàn（第四声）只少了 u 介音，意思是宴会。", "圆": "yuán（第二声）与 yuàn（第四声）声调不同，意思是圆。"}, "sentence_index": null, "correct_answer": "院"}, "level_3": {"options": [{"text": "院", "is_correct": true, "explanation": "院在房子外面，“院外有一条小路”符合句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，外面不会有一条小路。"}, {"text": "杯子", "is_correct": false, "explanation": "体貌：杯子太小，外面不可能有一条小路。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装东西的，不能说书包外有一条小路。"}], "explanations": {"院": "院在房子外面，“院外有一条小路”符合句意。", "冰箱": "语义：冰箱是家用电器，外面不会有一条小路。", "杯子": "体貌：杯子太小，外面不可能有一条小路。", "书包": "语义：书包是装东西的，不能说书包外有一条小路。"}, "sentence_index": 6, "correct_answer": "院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把工资存进了院里。", "explanation": "这里应该用〈银行〉。存工资要去银行，院是房子周围的空地，不能存钱。"}, {"text": "我把米饭盛到院里吃。", "explanation": "这里应该用〈碗〉。盛饭要用碗，院是房子周围的空地，不能盛饭。"}, {"text": "他坐在院上写作业。", "explanation": "这里应该用〈椅子〉。坐着写作业要坐在椅子上，不能说“坐在院上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91501, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他跑进了在院里。", "corrected_sentence": "他跑进了院里。", "error_description": "多余的“在”：“跑进了”后面直接跟处所“院里”，不能再加“在”，应说“他跑进了院里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91501, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶把花盆搬进了的院里。", "corrected_sentence": "奶奶把花盆搬进了院里。", "error_description": "多余的“的”：“搬进了”后面不能加“的”，应说“搬进了院里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
