INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91503, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "所有的人，一个也不少。", "primary_collocate": null, "pronunciation": "měi ge rén", "ipa": "mei˨˩˦ kə ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "每个人都来了。", "target_word": "每个人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个周末，每个人都有空。", "target_word": "每个人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天的会，每个人都到了。", "target_word": "每个人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚饭好了，每个人都坐到桌子旁边。", "target_word": "每个人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师点名，每个人都在，没有人迟到。", "target_word": "每个人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在这个大家庭里，每个人都很爱笑。", "target_word": "每个人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到她进来，每个人都站起来鼓掌。", "target_word": "每个人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好消息传开以后，每个人都很高兴。", "target_word": "每个人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨的时候，公司里每个人都带着伞。", "target_word": "每个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行，我们十个人出发，每个人都平安回来了。", "target_word": "每个人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "泛指在场或相关的所有人，无一例外", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bca58ee-d389-40eb-ad5d-f4ddb4ef8f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91503, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "每个人", "is_correct": true, "explanation": "“每个人”与“都”搭配，表示在场或相关的所有人无一例外，句意通顺。"}, {"text": "某人", "is_correct": false, "explanation": "语义：“某人”指某个不确定的个别的人，不能表示全体，与“都来了”矛盾。"}, {"text": "这个", "is_correct": false, "explanation": "语义：“这个”指单个的事物或人，不能指所有的人，与“都来了”的全体含义不符。"}, {"text": "有人", "is_correct": false, "explanation": "搭配：“有人”表示存在的不定指人，不能与表示全体的“都”搭配，句意不通。"}], "explanations": {"每个人": "“每个人”与“都”搭配，表示在场或相关的所有人无一例外，句意通顺。", "某人": "语义：“某人”指某个不确定的个别的人，不能表示全体，与“都来了”矛盾。", "这个": "语义：“这个”指单个的事物或人，不能指所有的人，与“都来了”的全体含义不符。", "有人": "搭配：“有人”表示存在的不定指人，不能与表示全体的“都”搭配，句意不通。"}, "sentence_index": 0, "correct_answer": "每个人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "晚饭好了，只有每个人坐到了桌子旁边。", "explanation": "这里应该用〈有的人〉。“每个人”表示无一例外的全体，不能与“只有”表示的限定同用。"}, {"text": "晚饭好了，有的人坐到了桌子旁边，每个人都还站着。", "explanation": "这里应该用〈其他人〉。“每个人”指全体，不能与表示部分人的“有的人”并列对照。"}, {"text": "晚饭好了，每个人都坐下了，可是有两个人还在厨房。", "explanation": "这里应该用〈大部分人〉。“每个人”表示无一例外，后面又说有人没坐下，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91503, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "每个人", "is_correct": true, "explanation": "“每个人”与“都站起来鼓掌”搭配，表示在场的每一个人都站起来，句意通顺。"}, {"text": "没人", "is_correct": false, "explanation": "语义：“没人”表示无人，与“都站起来鼓掌”的全体动作相矛盾。"}, {"text": "这里", "is_correct": false, "explanation": "语义：“这里”指地点，不能作“都站起来鼓掌”的主语，句意不通。"}, {"text": "它", "is_correct": false, "explanation": "语义：“它”指物或动物，不能看人进来并鼓掌，句意不通。"}], "explanations": {"每个人": "“每个人”与“都站起来鼓掌”搭配，表示在场的每一个人都站起来，句意通顺。", "没人": "语义：“没人”表示无人，与“都站起来鼓掌”的全体动作相矛盾。", "这里": "语义：“这里”指地点，不能作“都站起来鼓掌”的主语，句意不通。", "它": "语义：“它”指物或动物，不能看人进来并鼓掌，句意不通。"}, "sentence_index": 6, "correct_answer": "每个人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试的第一名是每个人。", "explanation": "这里应该用〈某个人〉或具体的人名。“每个人”指全体中的每一个，不能指代一个确定的人。"}, {"text": "这个杯子是每个人。", "explanation": "这里应该用〈每个人的〉。“每个人”指人，不能说杯子“是每个人”。"}, {"text": "他把每个人都拿到了桌子上。", "explanation": "这里应该用〈每本书〉。“每个人”指人，不能作为“拿到桌子上”的物品来指称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91503, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每个人很都开心。", "corrected_sentence": "每个人都很开心。", "error_description": "错误在“都”的位置。“都”表示全体，应紧跟“每个人”，放在“很”之后不通顺，应说“每个人都很开心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91503, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每个人在都认真听讲。", "corrected_sentence": "每个人都在认真听讲。", "error_description": "错误在“都”的位置。“都”应紧跟“每个人”表示全体，应说“每个人都在认真听讲”；“在都”的语序不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
