INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91504, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指所有人当中的每一个人。", "primary_collocate": null, "pronunciation": "měi ge rén", "ipa": "mei˨˩˦ kə ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "每个人都有自己的名字。", "target_word": "每个人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师给每个人一本书。", "target_word": "每个人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "每个人的爱好都不一样。", "target_word": "每个人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生请每个人先量体温。", "target_word": "每个人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桌上有五个杯子，每个人一个。", "target_word": "每个人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天的作业，每个人要写一篇短文。", "target_word": "每个人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师叫每个人在黑板前说一句话。", "target_word": "每个人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们班有三十个学生，每个人都有一把椅子。", "target_word": "每个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人的房间里都放着一张小桌子。", "target_word": "每个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛开始前，每个人都拿到了自己的号码。", "target_word": "每个人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "逐一指代群体中的每一个人，强调个体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bca58ee-d389-40eb-ad5d-f4ddb4ef8f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91504, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "每个人", "is_correct": true, "explanation": "“每个人”指所有人中的每一个，与“都”搭配，表示全体都有自己的名字，句意通顺。"}, {"text": "某人", "is_correct": false, "explanation": "语义：“某人”指某个不确定的人，与“都”要求的全体含义相矛盾。"}, {"text": "这个", "is_correct": false, "explanation": "语义：“这个”指单个的事物或人，不能表示人群中的全体，与“都有自己的名字”搭配不当。"}, {"text": "有人", "is_correct": false, "explanation": "搭配：“有人”表示存在的不定指人，不能与表示全体的“都”搭配，应说“每个人都……”。"}], "explanations": {"每个人": "“每个人”指所有人中的每一个，与“都”搭配，表示全体都有自己的名字，句意通顺。", "某人": "语义：“某人”指某个不确定的人，与“都”要求的全体含义相矛盾。", "这个": "语义：“这个”指单个的事物或人，不能表示人群中的全体，与“都有自己的名字”搭配不当。", "有人": "搭配：“有人”表示存在的不定指人，不能与表示全体的“都”搭配，应说“每个人都……”。"}, "sentence_index": 0, "correct_answer": "每个人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "有的人去了食堂，每个人留在了教室里。", "explanation": "这里应该用〈其他人〉。“每个人”指全体中的每一个，不能与表示部分人的“有的人”并列对照。"}, {"text": "教室里有每个人在打电话。", "explanation": "这里应该用〈有人〉。“每个人”指全体中的每一位，存在句“有……”要用不定指的〈有人〉。"}, {"text": "我想找每个人帮忙，可是一个人也没找到。", "explanation": "这里应该用〈某个人〉。“每个人”指全体，与后面“一个人也没找到”的全部否定矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91504, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "每个人", "is_correct": true, "explanation": "“每个人”与“叫”搭配，表示老师让全班每一个人依次到黑板前说话，句意通顺。"}, {"text": "它", "is_correct": false, "explanation": "语义：“它”指物或动物，不能到黑板前说话，句意不通。"}, {"text": "自己", "is_correct": false, "explanation": "语义：“自己”回指句首的“老师”，句意变成老师叫自己上前说话，与“叫每个人”全班依次发言的情境不符。"}, {"text": "这里", "is_correct": false, "explanation": "语义：“这里”指地点，不能作“叫”的宾语去说话，句意不通。"}], "explanations": {"每个人": "“每个人”与“叫”搭配，表示老师让全班每一个人依次到黑板前说话，句意通顺。", "它": "语义：“它”指物或动物，不能到黑板前说话，句意不通。", "自己": "语义：“自己”回指句首的“老师”，句意变成老师叫自己上前说话，与“叫每个人”全班依次发言的情境不符。", "这里": "语义：“这里”指地点，不能作“叫”的宾语去说话，句意不通。"}, "sentence_index": 6, "correct_answer": "每个人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比赛的冠军是每个人。", "explanation": "这里应该用〈某个人〉或具体的人名。“每个人”指全体中的每一个，不能指代一个确定的人。"}, {"text": "这些箱子每个人重五十斤。", "explanation": "这里应该用〈每个箱子〉。“每个人”只指人，不能用来指称箱子。"}, {"text": "今天只来了每个人。", "explanation": "这里应该用〈只来了一个人〉。“只”表示限定，与“每个人”指全体的意思相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91504, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每个人们都很努力。", "corrected_sentence": "每个人都很努力。", "error_description": "错误在“每个人们”。“每个人”中的“人”已经指一个个的人，后面不能再加“们”，应说“每个人都很努力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91504, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每个人都都在努力工作。", "corrected_sentence": "每个人都在努力工作。", "error_description": "错误在“都”重复。“都”只需用一次，应紧跟“每个人”表示全体，说“每个人都在努力工作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91505, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "结婚", "is_correct": true, "explanation": "反义：「结婚」与「离婚」相对，离婚是解除婚姻，结婚是成立婚姻。"}, {"text": "恋爱", "is_correct": false, "explanation": "恋爱指男女交往，与离婚不构成反义关系。"}, {"text": "相处", "is_correct": false, "explanation": "相处指共同生活或交往，词典未将它列为离婚的反义词。"}, {"text": "生育", "is_correct": false, "explanation": "生育指生孩子，与离婚没有相对的关系。"}], "correct_answer": "结婚", "explanations": {"结婚": "反义：「结婚」与「离婚」相对，离婚是解除婚姻，结婚是成立婚姻。", "恋爱": "恋爱指男女交往，与离婚不构成反义关系。", "相处": "相处指共同生活或交往，词典未将它列为离婚的反义词。", "生育": "生育指生孩子，与离婚没有相对的关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91505, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "结婚", "is_correct": true, "explanation": "反义：「结婚」与「离婚」相对，离婚是解除婚姻，结婚是成立婚姻。"}, {"text": "相识", "is_correct": false, "explanation": "相识指彼此认识，与离婚没有反义关系。"}, {"text": "结交", "is_correct": false, "explanation": "结交指交朋友，不是离婚的反义词。"}, {"text": "生活", "is_correct": false, "explanation": "生活指日常过日子，与离婚没有相对的关系。"}], "correct_answer": "结婚", "explanations": {"结婚": "反义：「结婚」与「离婚」相对，离婚是解除婚姻，结婚是成立婚姻。", "相识": "相识指彼此认识，与离婚没有反义关系。", "结交": "结交指交朋友，不是离婚的反义词。", "生活": "生活指日常过日子，与离婚没有相对的关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91505, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "离婚是爸爸妈妈不再做夫妻，不住在一起了。", "primary_collocate": null, "pronunciation": "lí hūn", "ipa": "li³⁵ xwən⁵⁵", "syllable_count": 2, "sentences": [{"text": "爸爸妈妈离婚了，我跟妈妈住。", "target_word": "离婚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们结婚五年就离婚了。", "target_word": "离婚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的父母去年离婚了。", "target_word": "离婚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想离婚，因为舍不得孩子。", "target_word": "离婚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离婚以后，爸爸住在别的地方。", "target_word": "离婚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸妈妈离婚，我很难过。", "target_word": "离婚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们已经离婚三年了。", "target_word": "离婚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问：“你们为什么要离婚？”", "target_word": "离婚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说她爸妈离婚的时候，她才六岁。", "target_word": "离婚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸和妈妈离婚后，我每个周末去看爸爸。", "target_word": "离婚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "离了婚", "label": "体标"}, {"form": "离过婚", "label": "体标"}, {"form": "離婚", "label": "繁体"}], "register": "中性", "sense_fingerprint": "夫妻不再做夫妻，不住在一起，日常说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f8102f3-2b9d-4b5e-9770-fb2903a345ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91505, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "离婚", "is_correct": true, "explanation": "正确。「爸爸妈妈离婚了」指夫妻解除婚姻关系，之后孩子跟一方生活。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：「结婚」是成立婚姻，与后半句「我跟妈妈住」所说的父母分开的情况矛盾。"}, {"text": "去世", "is_correct": false, "explanation": "语义：「去世」说妈妈也已去世，与后半句「我跟妈妈住」矛盾。"}, {"text": "出生", "is_correct": false, "explanation": "搭配：「出生」的主语是新生的人，不能用于父母。"}], "explanations": {"离婚": "正确。「爸爸妈妈离婚了」指夫妻解除婚姻关系，之后孩子跟一方生活。", "结婚": "语义：「结婚」是成立婚姻，与后半句「我跟妈妈住」所说的父母分开的情况矛盾。", "去世": "语义：「去世」说妈妈也已去世，与后半句「我跟妈妈住」矛盾。", "出生": "搭配：「出生」的主语是新生的人，不能用于父母。"}, "sentence_index": 0, "correct_answer": "离婚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们交往了半年，后来还是离婚了。", "explanation": "这里应该用〈分手〉。离婚指已结婚的夫妻依法解除婚姻，恋人之间分开只能说分手。"}, {"text": "他因为这件事，和朋友离婚了。", "explanation": "这里应该用〈绝交〉。离婚只用于夫妻关系，朋友之间断绝往来要说绝交。"}, {"text": "他们俩合伙开店，去年离婚了。", "explanation": "这里应该用〈散伙〉。离婚只用于夫妻，合伙人之间结束合作要说散伙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91505, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "离婚", "is_correct": true, "explanation": "正确。「他们已经离婚三年了」指离婚已经持续三年。"}, {"text": "下班", "is_correct": false, "explanation": "语义：「下班」是每天结束工作的动作，不能说「已经下班三年了」。"}, {"text": "怀孕", "is_correct": false, "explanation": "搭配：「怀孕」通常指女性，不能用于「他们」，句子说不通。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：「发烧」是短暂的病症，不能持续三年。"}], "explanations": {"离婚": "正确。「他们已经离婚三年了」指离婚已经持续三年。", "下班": "语义：「下班」是每天结束工作的动作，不能说「已经下班三年了」。", "怀孕": "搭配：「怀孕」通常指女性，不能用于「他们」，句子说不通。", "发烧": "语义：「发烧」是短暂的病症，不能持续三年。"}, "sentence_index": 6, "correct_answer": "离婚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们订婚后，因为性格不合，离婚了。", "explanation": "这里应该用〈退婚〉。离婚要求双方已经结婚，两人只是订了婚时应说退婚。"}, {"text": "他因为观点不同，和老师离婚了。", "explanation": "这里应该用〈闹翻〉。离婚只用于夫妻，师生之间因矛盾不再来往要说闹翻。"}, {"text": "他和同学慢慢疏远，最后离婚了。", "explanation": "这里应该用〈绝交〉。离婚只用于夫妻，同学之间彼此断绝往来要说绝交。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91505, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他离婚过，现在一个人住。", "corrected_sentence": "他离过婚，现在一个人住。", "error_description": "错误：「离婚过」；正确：「离过婚」。离婚是离合词，体标「过」要放在「离」和「婚」之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91505, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他向妻子离婚了，现在一个人住。", "corrected_sentence": "他和妻子离婚了，现在一个人住。", "error_description": "错误：「向妻子离婚」；正确：「和妻子离婚」。离婚的对象要用「和…离婚」引出，不能用「向」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91506, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "结婚", "is_correct": true, "explanation": "反义：「结婚」与「离婚」相对，离婚是依法解除婚姻，结婚是成立婚姻。"}, {"text": "恋爱", "is_correct": false, "explanation": "恋爱指男女交往，与离婚不构成反义关系。"}, {"text": "相处", "is_correct": false, "explanation": "相处指共同生活或交往，词典未将它列为离婚的反义词。"}, {"text": "生育", "is_correct": false, "explanation": "生育指生孩子，与离婚没有相对的关系。"}], "correct_answer": "结婚", "explanations": {"结婚": "反义：「结婚」与「离婚」相对，离婚是依法解除婚姻，结婚是成立婚姻。", "恋爱": "恋爱指男女交往，与离婚不构成反义关系。", "相处": "相处指共同生活或交往，词典未将它列为离婚的反义词。", "生育": "生育指生孩子，与离婚没有相对的关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
