INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91506, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "夫妻依法解除婚姻关系。", "primary_collocate": null, "pronunciation": "lí hūn", "ipa": "li³⁵ xwən⁵⁵", "syllable_count": 2, "sentences": [{"text": "夫妻双方同意离婚。", "target_word": "离婚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们到民政局办理了离婚手续。", "target_word": "离婚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院判决他们离婚。", "target_word": "离婚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她向法院提出离婚。", "target_word": "离婚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感情破裂的夫妻可以依法离婚。", "target_word": "离婚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离婚需要双方签字。", "target_word": "离婚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们离婚时，把房子留给了孩子。", "target_word": "离婚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对夫妻已经离婚十年了。", "target_word": "离婚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妻子提出离婚，丈夫不同意。", "target_word": "离婚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律规定，离婚后孩子由一方照顾。", "target_word": "离婚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "离了婚", "label": "体标"}, {"form": "离过婚", "label": "体标"}, {"form": "離婚", "label": "繁体"}], "register": "正式", "sense_fingerprint": "夫妻依法解除婚姻关系，法律场合用语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f8102f3-2b9d-4b5e-9770-fb2903a345ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91506, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "离婚", "is_correct": true, "explanation": "正确。「夫妻双方同意离婚」是法律上的常用说法。"}, {"text": "失业", "is_correct": false, "explanation": "语义：「同意」的对象应是离婚，「失业」不需要双方同意，句子说不通。"}, {"text": "出生", "is_correct": false, "explanation": "搭配：「出生」的主语是新生的人，不能用于夫妻双方。"}, {"text": "生病", "is_correct": false, "explanation": "语义：「生病」不是需要双方同意的事，句子说不通。"}], "explanations": {"离婚": "正确。「夫妻双方同意离婚」是法律上的常用说法。", "失业": "语义：「同意」的对象应是离婚，「失业」不需要双方同意，句子说不通。", "出生": "搭配：「出生」的主语是新生的人，不能用于夫妻双方。", "生病": "语义：「生病」不是需要双方同意的事，句子说不通。"}, "sentence_index": 0, "correct_answer": "离婚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向公司提出离婚。", "explanation": "这里应该用〈离职〉。离婚只用于夫妻关系，向公司辞去工作要说离职。"}, {"text": "他向女友提出离婚。", "explanation": "这里应该用〈分手〉。离婚指已结婚的夫妻依法解除婚姻，恋人之间提出分开要说分手。"}, {"text": "她向未婚夫提出离婚。", "explanation": "这里应该用〈退婚〉。离婚要求已经结婚，未婚夫妻解除婚约要说退婚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91506, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "离婚", "is_correct": true, "explanation": "正确。「他们离婚时，把房子留给了孩子」指离婚时的财产安排。"}, {"text": "出嫁", "is_correct": false, "explanation": "搭配：「出嫁」只用于女性，不能用于「他们」。"}, {"text": "分娩", "is_correct": false, "explanation": "搭配：「分娩」是女性生育的过程，主语不能是「他们」。"}, {"text": "失恋", "is_correct": false, "explanation": "语义：「失恋」指恋爱受挫，与已有孩子的夫妻情境不符。"}], "explanations": {"离婚": "正确。「他们离婚时，把房子留给了孩子」指离婚时的财产安排。", "出嫁": "搭配：「出嫁」只用于女性，不能用于「他们」。", "分娩": "搭配：「分娩」是女性生育的过程，主语不能是「他们」。", "失恋": "语义：「失恋」指恋爱受挫，与已有孩子的夫妻情境不符。"}, "sentence_index": 6, "correct_answer": "离婚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两人合伙开店，后来决定离婚。", "explanation": "这里应该用〈散伙〉。离婚只用于夫妻，合伙人停止合作要说散伙。"}, {"text": "他因为工作上的矛盾，和同事离婚了。", "explanation": "这里应该用〈闹翻〉。离婚只用于夫妻，同事之间闹翻、不再来往要说闹翻。"}, {"text": "这两个兄弟因为家产，最后离婚了。", "explanation": "这里应该用〈反目〉。离婚只用于夫妻，兄弟之间翻脸要说反目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91506, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "被告曾经离婚过。", "corrected_sentence": "被告曾经离过婚。", "error_description": "错误：「离婚过」；正确：「离过婚」。离婚是离合词，体标「过」要放在「离」和「婚」之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91506, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她依法向丈夫离婚了。", "corrected_sentence": "她依法和丈夫离婚了。", "error_description": "错误：「向丈夫离婚」；正确：「和丈夫离婚」。离婚的对象要用「和…离婚」引出，不能用「向」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91508, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "专制政治", "is_correct": true, "explanation": "反义：〈专制政治〉指由个人或少数人独掌大权、人民不能当家作主的制度，与〈民主政治〉相对。"}, {"text": "经济制度", "is_correct": false, "explanation": "无反义关系：〈经济制度〉指经济的组织与分配方式，不是与民主政治相对的政治制度。"}, {"text": "教育体制", "is_correct": false, "explanation": "无反义关系：〈教育体制〉是教育的管理制度，与民主政治没有对立关系。"}, {"text": "文化传统", "is_correct": false, "explanation": "无反义关系：〈文化传统〉指长期形成的文化习俗，与政治制度不构成反义。"}], "correct_answer": "专制政治", "explanations": {"专制政治": "反义：〈专制政治〉指由个人或少数人独掌大权、人民不能当家作主的制度，与〈民主政治〉相对。", "经济制度": "无反义关系：〈经济制度〉指经济的组织与分配方式，不是与民主政治相对的政治制度。", "教育体制": "无反义关系：〈教育体制〉是教育的管理制度，与民主政治没有对立关系。", "文化传统": "无反义关系：〈文化传统〉指长期形成的文化习俗，与政治制度不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91508, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "独裁政治", "is_correct": true, "explanation": "反义：〈独裁政治〉指由一人独揽权力、排斥人民参与的制度，与〈民主政治〉相对。"}, {"text": "经济基础", "is_correct": false, "explanation": "无反义关系：〈经济基础〉指社会经济结构，与政治制度不构成对立。"}, {"text": "文化遗产", "is_correct": false, "explanation": "无反义关系：〈文化遗产〉指历史上留下的文化成果，与民主政治不是反义词。"}, {"text": "社会风气", "is_correct": false, "explanation": "无反义关系：〈社会风气〉指社会的普遍习惯与态度，与政治制度不构成反义。"}], "correct_answer": "独裁政治", "explanations": {"独裁政治": "反义：〈独裁政治〉指由一人独揽权力、排斥人民参与的制度，与〈民主政治〉相对。", "经济基础": "无反义关系：〈经济基础〉指社会经济结构，与政治制度不构成对立。", "文化遗产": "无反义关系：〈文化遗产〉指历史上留下的文化成果，与民主政治不是反义词。", "社会风气": "无反义关系：〈社会风气〉指社会的普遍习惯与态度，与政治制度不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91508, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "公民通过选举等方式参与国家事务、人民当家作主的政治制度。", "primary_collocate": null, "pronunciation": "mín zhǔ zhèng zhì", "ipa": "min˧˥ tʂu˨˩ tʂɤŋ˥˩ tʂɻ̩˥˩", "syllable_count": 4, "sentences": [{"text": "民主政治需要公民参与选举。", "target_word": "民主政治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家实行民主政治已经几十年了。", "target_word": "民主政治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民主政治让人民可以参与国家事务。", "target_word": "民主政治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史课上，老师讲了公民选举和民主政治的发展。", "target_word": "民主政治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民主政治的基础是公民有选举的权利。", "target_word": "民主政治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家都在努力建设民主政治。", "target_word": "民主政治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民主政治的特点是人民选出政府。", "target_word": "民主政治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民主政治要靠法律来保护人民的权利。", "target_word": "民主政治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究民主政治，写了一本书。", "target_word": "民主政治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在民主政治里，人民可以选出自己的代表。", "target_word": "民主政治", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "公民通过选举参与国家事务的政治制度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600a7bce-3638-4377-bbfd-4ecbfb4cb6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91508, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "君主政治", "is_correct": false, "explanation": "语义：君主政治由君主掌权，不由公民选举，与“公民参与选举”相矛盾。"}, {"text": "民主政治", "is_correct": true, "explanation": "正确：句中“公民参与选举”说明的是民主政治制度，只有它符合语境。"}, {"text": "专制统治", "is_correct": false, "explanation": "语义：专制统治不允许公民参与选举，与句中“需要公民参与选举”冲突。"}, {"text": "经济", "is_correct": false, "explanation": "搭配：“经济”是领域名词，不与“需要公民参与选举”这类政治述语搭配。"}], "explanations": {"君主政治": "语义：君主政治由君主掌权，不由公民选举，与“公民参与选举”相矛盾。", "民主政治": "正确：句中“公民参与选举”说明的是民主政治制度，只有它符合语境。", "专制统治": "语义：专制统治不允许公民参与选举，与句中“需要公民参与选举”冲突。", "经济": "搭配：“经济”是领域名词，不与“需要公民参与选举”这类政治述语搭配。"}, "sentence_index": 0, "correct_answer": "民主政治"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我们一起去民主政治玩。", "explanation": "〈民主政治〉是国家制度，不是地点，不能用“去”；这里应该用〈公园〉。"}, {"text": "我们吃了一顿民主政治的晚饭。", "explanation": "〈民主政治〉指国家制度，不能修饰“晚饭”；这里直接说“一顿晚饭”即可。"}, {"text": "这套制度有一把民主政治。", "explanation": "这里应该用〈种〉。〈民主政治〉是抽象的制度，前面用量词〈种〉；〈把〉用于有柄的器具，不能用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91508, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "封建制度", "is_correct": false, "explanation": "语义：封建制度不是由人民选出政府，与句中“人民选出政府”的特点相反。"}, {"text": "民主政治", "is_correct": true, "explanation": "正确：句子说的是“人民选出政府”的制度特点，只有民主政治符合。"}, {"text": "皇权", "is_correct": false, "explanation": "搭配：“皇权”多与“独揽”“世袭”等搭配，不说“皇权的特点是人民选出政府”。"}, {"text": "世袭制", "is_correct": false, "explanation": "语义：世袭制靠血缘传承权力，不靠人民选出政府，与句中所述特点冲突。"}], "explanations": {"封建制度": "语义：封建制度不是由人民选出政府，与句中“人民选出政府”的特点相反。", "民主政治": "正确：句子说的是“人民选出政府”的制度特点，只有民主政治符合。", "皇权": "搭配：“皇权”多与“独揽”“世袭”等搭配，不说“皇权的特点是人民选出政府”。", "世袭制": "语义：世袭制靠血缘传承权力，不靠人民选出政府，与句中所述特点冲突。"}, "sentence_index": 6, "correct_answer": "民主政治"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们把民主政治装进了书包，带去了学校。", "explanation": "〈民主政治〉是抽象的国家制度，不能被“装进”书包；这里应该用实体的〈文件〉。"}, {"text": "我的好朋友是民主政治，我们常常一起玩。", "explanation": "这里把〈民主政治〉当成指人的名词，但它只指国家制度；若要说一个人讲民主，应用形容词〈民主〉，如“他很民主”。"}, {"text": "我的手机坏了，要去修理民主政治。", "explanation": "这里应该用有形的器物，如〈电脑〉；〈民主政治〉指抽象的制度，不是可以修理的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91508, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家实行了一把民主政治。", "corrected_sentence": "这个国家实行了民主政治。", "error_description": "〈民主政治〉是抽象的制度名词，不能用量词〈把〉（〈把〉用于有柄的器具）。应去掉“一把”，说“实行了民主政治”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91508, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "民主政治地发展需要很长时间。", "corrected_sentence": "民主政治的发展需要很长时间。", "error_description": "〈民主政治〉是名词，修饰名词〈发展〉时应用〈的〉，不能用〈地〉。〈地〉用于修饰动词或形容词，此处应改为〈的〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
