INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91509, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "高校是大学，是人们长大后继续学习的学校。", "primary_collocate": null, "pronunciation": "gāo xiào", "ipa": "kaʊ˥ ɕi̯aʊ˥˩", "syllable_count": 2, "sentences": [{"text": "高中毕业后，她去了南方的高校。", "target_word": "高校", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在高校学了四年中文。", "target_word": "高校", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐已经在高校读书了。", "target_word": "高校", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这所高校有一座很老的钟楼。", "target_word": "高校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想在高校里继续学习历史。", "target_word": "高校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高校的校园又大又漂亮。", "target_word": "高校", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我上的高校，食堂饭菜便宜。", "target_word": "高校", "complexity_tier": "T3", "furigana": "wǒ shàng de gāoxiào, shítáng fàncài piányi", "sentence_source": "generated"}, {"text": "她在高校认识了很多朋友。", "target_word": "高校", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大学生活从进入高校开始。", "target_word": "高校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暑假里，高校里的学生少了很多。", "target_word": "高校", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所", "label": "量词"}, {"form": "高等学校", "label": "全称"}], "register": "中性", "sense_fingerprint": "人们长大后继续学习的大学：在高校读书、高校校园、高校生活", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f7f4cc0-d72a-4bc5-95a4-88c0d7487b96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91509, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "高校", "is_correct": true, "explanation": "高校是高等学校的简称，指大学、专科等高等教育机构。"}, {"text": "搞笑", "is_correct": false, "explanation": "gǎo（第三声）与 gāo（第一声）声调不同，意思是引人发笑，与“高校”（gāo xiào）不同。"}, {"text": "该校", "is_correct": false, "explanation": "gāi 与 gāo 韵母不同（ai 与 ao），意思是“这所学校”，与“高校”不同。"}, {"text": "高小", "is_correct": false, "explanation": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是旧时的高等小学，较少用。"}], "explanations": {"高校": "高校是高等学校的简称，指大学、专科等高等教育机构。", "搞笑": "gǎo（第三声）与 gāo（第一声）声调不同，意思是引人发笑，与“高校”（gāo xiào）不同。", "该校": "gāi 与 gāo 韵母不同（ai 与 ao），意思是“这所学校”，与“高校”不同。", "高小": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是旧时的高等小学，较少用。"}, "sentence_index": null, "correct_answer": "高校"}, "level_3": {"options": [{"text": "高校", "is_correct": true, "explanation": "正确。“去了南方的”后接高等学校，符合“高中毕业后继续读书”的语境。"}, {"text": "幼儿园", "is_correct": false, "explanation": "语义：高中毕业后不会再去幼儿园，与句中的时间顺序矛盾。"}, {"text": "海洋", "is_correct": false, "explanation": "搭配：“去”后接“海洋”不自然，人去海边或下海，不说“去南方的海洋”。"}, {"text": "墓地", "is_correct": false, "explanation": "语义：墓地不是人去读书的地方，与“高中毕业后”去求学的语境矛盾。"}], "explanations": {"高校": "正确。“去了南方的”后接高等学校，符合“高中毕业后继续读书”的语境。", "幼儿园": "语义：高中毕业后不会再去幼儿园，与句中的时间顺序矛盾。", "海洋": "搭配：“去”后接“海洋”不自然，人去海边或下海，不说“去南方的海洋”。", "墓地": "语义：墓地不是人去读书的地方，与“高中毕业后”去求学的语境矛盾。"}, "sentence_index": 0, "correct_answer": "高校"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他五岁时进了高校。", "explanation": "这里应该用〈幼儿园〉。五岁的孩子进的是幼儿园，高校是高等学校，不能用于这里。"}, {"text": "我表妹四岁，每天去高校玩游戏、唱儿歌。", "explanation": "这里应该用〈幼儿园〉。四岁的孩子上的是幼儿园，高校指大学、专科等高等学校。"}, {"text": "我弟弟十二岁，刚上高校。", "explanation": "这里应该用〈中学〉。十二岁的学生刚上的是中学，高校指大学、专科等高等学校。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91509, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高校", "is_correct": true, "explanation": "正确。“我上的”后接高等学校，指学生就读的学校，符合句意。"}, {"text": "动物园", "is_correct": false, "explanation": "语义：动物园不设学生食堂，与“我上的”的语境矛盾。"}, {"text": "森林", "is_correct": false, "explanation": "语义：森林不是人“上”学的地方，与“食堂”的语境矛盾。"}, {"text": "游乐场", "is_correct": false, "explanation": "搭配：“上”一般接“学校、班”等，“上游乐场”不自然。"}], "explanations": {"高校": "正确。“我上的”后接高等学校，指学生就读的学校，符合句意。", "动物园": "语义：动物园不设学生食堂，与“我上的”的语境矛盾。", "森林": "语义：森林不是人“上”学的地方，与“食堂”的语境矛盾。", "游乐场": "搭配：“上”一般接“学校、班”等，“上游乐场”不自然。"}, "sentence_index": 6, "correct_answer": "高校"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我侄子初三毕业后，进了一所高校。", "explanation": "这里应该用〈中专〉。初三毕业后上的是中专或高中，高校指大学、专科等高等学校。"}, {"text": "我弟弟六岁，暑假就要进高校读书。", "explanation": "这里应该用〈小学〉。六岁的孩子升入的是小学，高校指大学、专科等高等学校。"}, {"text": "我妹妹十五岁，下学期要上高校。", "explanation": "这里应该用〈高中〉。十五岁的学生下学期上的是高中，高校指大学、专科等高等学校。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91509, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在一只高校读书。", "corrected_sentence": "她在一所高校读书。", "error_description": "量词错误：错误形式“一只高校”，正确形式“一所高校”。“高校”是机构，量词用“所”，“只”多用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91509, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这辆高校的老师很有名。", "corrected_sentence": "这所高校的老师很有名。", "error_description": "量词错误：错误形式“这辆高校”，正确形式“这所高校”。“高校”是机构，量词用“所”，“辆”只用于车辆。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
