INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91513, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人体是人的整个身体。", "primary_collocate": null, "pronunciation": "rén tǐ", "ipa": "ɻən˧˥ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "人体百分之七十是水。", "target_word": "人体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图画的是人体的骨头。", "target_word": "人体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人体需要每天喝足够的水。", "target_word": "人体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生给我们讲了人体的结构。", "target_word": "人体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人体一共有二百多块骨头。", "target_word": "人体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太冷的天气对人体不好。", "target_word": "人体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在课上学习人体结构。", "target_word": "人体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭对人体很重要。", "target_word": "人体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晒太阳能帮助人体合成维生素。", "target_word": "人体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人体的温度一般是三十七度。", "target_word": "人体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人体模型", "label": "复合"}], "register": "通用", "sense_fingerprint": "人的整个身体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db945215-8bb7-469b-a806-7db5687ef759') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91513, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人体", "is_correct": true, "explanation": "正确：人体指人的整个身体，与“百分之七十是水”相符。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指体形胖瘦，不指身体所含水分的比例。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，不是生物体，不能说含多少水分。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间是空间，不能说百分之七十是水。"}], "explanations": {"人体": "正确：人体指人的整个身体，与“百分之七十是水”相符。", "身材": "体貌：身材指体形胖瘦，不指身体所含水分的比例。", "汽车": "语义：汽车是交通工具，不是生物体，不能说含多少水分。", "房间": "语义：房间是空间，不能说百分之七十是水。"}, "sentence_index": 0, "correct_answer": "人体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他坚持锻炼，人体比以前好多了。", "explanation": "这里应该用〈身体〉。描述一个人的健康状况要用身体，人体指作为研究对象的人体结构。"}, {"text": "车间里缺人体，需要招聘工人。", "explanation": "这里应该用〈人手〉。缺的是能干活的人手，不能说缺人体。"}, {"text": "她的人体很苗条。", "explanation": "这里应该用〈身材〉。形容胖瘦、体形要用身材，人体不这么用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91513, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人体", "is_correct": true, "explanation": "正确：人体结构是课上学习的内容，符合语境。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是一个数值，没有“结构”可以学习。"}, {"text": "夜宵", "is_correct": false, "explanation": "语义：夜宵是夜间吃的食物，不是课上学习的内容。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是情绪，不能说学习心情结构。"}], "explanations": {"人体": "正确：人体结构是课上学习的内容，符合语境。", "体重": "语义：体重是一个数值，没有“结构”可以学习。", "夜宵": "语义：夜宵是夜间吃的食物，不是课上学习的内容。", "心情": "语义：心情是情绪，不能说学习心情结构。"}, "sentence_index": 6, "correct_answer": "人体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城市的人体有两百万。", "explanation": "这里应该用〈人口〉。说一个城市的人数要用人口，人体指身体的构造。"}, {"text": "学校培养了很多人体。", "explanation": "这里应该用〈人才〉。培养的是人才，不能说培养人体。"}, {"text": "街上的人体很多。", "explanation": "这里应该用〈人群〉。街上一群一群的人要说人群，人体指身体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91513, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师拿来一张人体模型给我们看。", "corrected_sentence": "老师拿来一个人体模型给我们看。", "error_description": "量词错误：“人体模型”是立体的，量词应用“个”，不能用“张”（“张”用于平面的东西）。应改为“一个人体模型”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91513, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种食物向人体很有好处。", "corrected_sentence": "这种食物对人体很有好处。", "error_description": "错误：向人体；正确：对人体。表示有益于人体时用“对”，“向”表示动作的方向，不能用于“很有好处”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91515, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "熄灭", "is_correct": true, "explanation": "熄灭表示火或光不再燃烧，与“燃烧”构成反义关系。"}, {"text": "漂浮", "is_correct": false, "explanation": "漂浮指物体浮在液体或空气表面，与“燃烧”没有反义关系。"}, {"text": "生长", "is_correct": false, "explanation": "生长指生物逐渐长大，与“燃烧”没有反义关系。"}, {"text": "旋转", "is_correct": false, "explanation": "旋转指物体绕中心转动，与“燃烧”没有反义关系。"}], "correct_answer": "熄灭", "explanations": {"熄灭": "熄灭表示火或光不再燃烧，与“燃烧”构成反义关系。", "漂浮": "漂浮指物体浮在液体或空气表面，与“燃烧”没有反义关系。", "生长": "生长指生物逐渐长大，与“燃烧”没有反义关系。", "旋转": "旋转指物体绕中心转动，与“燃烧”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91515, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "熄灭", "is_correct": true, "explanation": "熄灭表示火或光不再燃烧，与“燃烧”构成反义关系。"}, {"text": "游动", "is_correct": false, "explanation": "游动指在水中或空中活动，与“燃烧”没有反义关系。"}, {"text": "哭泣", "is_correct": false, "explanation": "哭泣指因悲伤而流泪出声，与“燃烧”没有反义关系。"}, {"text": "摇晃", "is_correct": false, "explanation": "摇晃指物体来回晃动，与“燃烧”没有反义关系。"}], "correct_answer": "熄灭", "explanations": {"熄灭": "熄灭表示火或光不再燃烧，与“燃烧”构成反义关系。", "游动": "游动指在水中或空中活动，与“燃烧”没有反义关系。", "哭泣": "哭泣指因悲伤而流泪出声，与“燃烧”没有反义关系。", "摇晃": "摇晃指物体来回晃动，与“燃烧”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91515, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西着了火，一直在烧。", "primary_collocate": null, "pronunciation": "rán shāo", "ipa": "ɻan˧˥ ʂɑʊ˥", "syllable_count": 2, "sentences": [{"text": "大火在山上燃烧了一整夜。", "target_word": "燃烧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房子着火了，火一直燃烧着。", "target_word": "燃烧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木头在火里燃烧，发出啪啪的声音。", "target_word": "燃烧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜡烛燃烧着，房间里很亮。", "target_word": "燃烧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火堆燃烧得很旺，大家围着它唱歌。", "target_word": "燃烧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里的火燃烧了三天，还没有灭。", "target_word": "燃烧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汽车着火后，车身很快燃烧起来。", "target_word": "燃烧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "煤气灶上，蓝色的火正在燃烧。", "target_word": "燃烧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "垃圾堆燃烧时，冒出了黑色的烟。", "target_word": "燃烧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雷劈中了大树，大树燃烧了好几个小时。", "target_word": "燃烧", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "燃烧着", "label": "持续体"}, {"form": "燃烧了", "label": "完成体"}, {"form": "燃烧过", "label": "经历体"}, {"form": "燃燒", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西着火后持续地烧（大火、木头、蜡烛等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a539d2-b9bf-4579-bf7e-a6cf9155014c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91515, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "燃烧", "is_correct": true, "explanation": "正确：燃烧指东西着火后持续地烧，与“一整夜”的持续时间相合。"}, {"text": "漂浮", "is_correct": false, "explanation": "语义：漂浮指物体浮在液体或空气表面，大火不会在山上漂浮。"}, {"text": "烧毁", "is_correct": false, "explanation": "体貌：烧毁表示烧坏、毁掉的结果，是一次完成的动作，不能和表示持续的“一整夜”搭配。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：熄灭表示火停止燃烧，与“大火在山上烧了一整夜”的意思相反。"}], "explanations": {"燃烧": "正确：燃烧指东西着火后持续地烧，与“一整夜”的持续时间相合。", "漂浮": "语义：漂浮指物体浮在液体或空气表面，大火不会在山上漂浮。", "烧毁": "体貌：烧毁表示烧坏、毁掉的结果，是一次完成的动作，不能和表示持续的“一整夜”搭配。", "熄灭": "语义：熄灭表示火停止燃烧，与“大火在山上烧了一整夜”的意思相反。"}, "sentence_index": 0, "correct_answer": "燃烧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用火柴燃烧了蜡烛。", "explanation": "这里应该用〈点燃〉。燃烧是不及物动词，不能带“蜡烛”作宾语；使东西开始着火要用“点燃”。"}, {"text": "节日夜里，人们燃烧了很多烟花。", "explanation": "这里应该用〈燃放〉。燃放指点燃烟花爆竹使其发射、爆响，燃烧不能这样说。"}, {"text": "妈妈在厨房里燃烧水。", "explanation": "这里应该用〈烧〉。燃烧不能带宾语，给水加热要说“烧水”，燃烧只指东西着火。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91515, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "燃烧", "is_correct": true, "explanation": "正确：燃烧表示东西着火后持续地烧，“车身很快……起来”描述的正是车身着火。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：跳舞是人或动物的动作，车身不能跳舞。"}, {"text": "冻结", "is_correct": false, "explanation": "语义：冻结指液体变成固体，车身着火不会冻结。"}, {"text": "生长", "is_correct": false, "explanation": "语义：生长指生物逐渐长大，车身不会生长。"}], "explanations": {"燃烧": "正确：燃烧表示东西着火后持续地烧，“车身很快……起来”描述的正是车身着火。", "跳舞": "语义：跳舞是人或动物的动作，车身不能跳舞。", "冻结": "语义：冻结指液体变成固体，车身着火不会冻结。", "生长": "语义：生长指生物逐渐长大，车身不会生长。"}, "sentence_index": 6, "correct_answer": "燃烧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶在锅里燃烧了一锅汤。", "explanation": "这里应该用〈煮〉。煮是把食物放在水里加热弄熟，燃烧指东西着火，不能用来说做汤。"}, {"text": "妈妈在烤箱里燃烧了一块蛋糕。", "explanation": "这里应该用〈烤〉。烤是用热力把食物弄熟，燃烧指东西着火，不能用来说烤蛋糕。"}, {"text": "一颗火星燃烧了干草。", "explanation": "这里应该用〈引燃〉。“引燃”表示使某物开始着火，可以带宾语“干草”；燃烧不能带宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91515, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "炉子里的火燃烧很旺。", "corrected_sentence": "炉子里的火燃烧得很旺。", "error_description": "错误在于“燃烧”后漏掉了程度补语的助词“得”。表示程度的“很旺”要说“燃烧得很旺”，不能直接说“燃烧很旺”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91515, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "汽车着火后，车身很快燃烧上来。", "corrected_sentence": "汽车着火后，车身很快燃烧起来。", "error_description": "错误在于趋向补语。表示开始燃烧并持续下去要用“燃烧起来”，不能说“燃烧上来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
