INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91516, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "物质剧烈氧化，发光发热。", "primary_collocate": null, "pronunciation": "rán shāo", "ipa": "ɻan˧˥ ʂɑʊ˥", "syllable_count": 2, "sentences": [{"text": "物质燃烧需要氧气。", "target_word": "燃烧", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "镁条燃烧时，会发出很亮的白光。", "target_word": "燃烧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "煤燃烧会放出很多热。", "target_word": "燃烧", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "没有氧气，火就不能燃烧。", "target_word": "燃烧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汽油燃烧得很快，还会产生热量。", "target_word": "燃烧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验课上，老师让我们观察铁丝燃烧。", "target_word": "燃烧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "木炭燃烧后，会变成灰和二氧化碳。", "target_word": "燃烧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "燃烧是发光发热的化学反应。", "target_word": "燃烧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把盖子盖上，蜡烛没有氧气就会停止燃烧。", "target_word": "燃烧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天然气燃烧时，会产生热和二氧化碳。", "target_word": "燃烧", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "燃烧着", "label": "持续体"}, {"form": "燃烧了", "label": "完成体"}, {"form": "燃烧过", "label": "经历体"}, {"form": "燃燒", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物质与氧气剧烈反应，发光发热（化学、科学语境）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a539d2-b9bf-4579-bf7e-a6cf9155014c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91516, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "燃烧", "is_correct": true, "explanation": "正确：燃烧指物质与氧气剧烈反应，发光发热，句子说的正是物质需要氧气才能这样反应。"}, {"text": "融化", "is_correct": false, "explanation": "语义：融化指固体受热变成液体，与“需要氧气”无关，句子说的是物质与氧气的反应。"}, {"text": "蔓延", "is_correct": false, "explanation": "搭配：蔓延多指火势或灾害扩散，不说“物质蔓延”。"}, {"text": "生长", "is_correct": false, "explanation": "语义：生长指生物逐渐长大，无机物质的反应不是生长。"}], "explanations": {"燃烧": "正确：燃烧指物质与氧气剧烈反应，发光发热，句子说的正是物质需要氧气才能这样反应。", "融化": "语义：融化指固体受热变成液体，与“需要氧气”无关，句子说的是物质与氧气的反应。", "蔓延": "搭配：蔓延多指火势或灾害扩散，不说“物质蔓延”。", "生长": "语义：生长指生物逐渐长大，无机物质的反应不是生长。"}, "sentence_index": 0, "correct_answer": "燃烧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "实验员用酒精灯燃烧了镁条。", "explanation": "这里应该用〈点燃〉。燃烧不带宾语，用火使镁条开始燃烧要说“点燃”。"}, {"text": "铁在潮湿的空气中燃烧生锈了。", "explanation": "这里应该用〈氧化〉。燃烧是剧烈氧化、发光发热，铁生锈是缓慢氧化，不发光也不剧烈，不能说“燃烧生锈”。"}, {"text": "他在炉子上燃烧了一壶水。", "explanation": "这里应该用〈烧〉或〈加热〉。燃烧是物质与氧气剧烈反应、着火，给水加热要说“烧水”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91516, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "燃烧", "is_correct": true, "explanation": "正确：燃烧指物质与氧气剧烈反应，木炭燃烧后才会变成灰和二氧化碳。"}, {"text": "冷却", "is_correct": false, "explanation": "语义：冷却指温度降低，不会让木炭变成灰和二氧化碳。"}, {"text": "腐烂", "is_correct": false, "explanation": "搭配：腐烂多用于有机物的分解，木炭不说腐烂后变成灰。"}, {"text": "漂浮", "is_correct": false, "explanation": "语义：漂浮指物体浮在液体或空气表面，与木炭变成灰和二氧化碳的变化无关。"}], "explanations": {"燃烧": "正确：燃烧指物质与氧气剧烈反应，木炭燃烧后才会变成灰和二氧化碳。", "冷却": "语义：冷却指温度降低，不会让木炭变成灰和二氧化碳。", "腐烂": "搭配：腐烂多用于有机物的分解，木炭不说腐烂后变成灰。", "漂浮": "语义：漂浮指物体浮在液体或空气表面，与木炭变成灰和二氧化碳的变化无关。"}, "sentence_index": 6, "correct_answer": "燃烧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨师用烤箱燃烧了一只鸡。", "explanation": "这里应该用〈烤〉。烤是用热力把食物弄熟，燃烧指物质着火，不能用来说烤鸡。"}, {"text": "妈妈用火燃烧了一锅汤。", "explanation": "这里应该用〈煮〉。煮是在水里加热食物，燃烧指物质与氧气剧烈反应，不能用来说做汤。"}, {"text": "一根火柴燃烧了纸团。", "explanation": "这里应该用〈引燃〉。“引燃”表示使某物开始着火，可以带宾语“纸团”；燃烧不能带宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91516, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "镁条在空气中燃烧很亮。", "corrected_sentence": "镁条在空气中燃烧得很亮。", "error_description": "错误在于“燃烧”后漏掉了程度补语的助词“得”。表示程度的“很亮”要说“燃烧得很亮”，不能直接说“燃烧很亮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91516, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "酒精燃烧很快，还会放出热量。", "corrected_sentence": "酒精燃烧得很快，还会放出热量。", "error_description": "错误在于“燃烧”后漏掉了程度补语的助词“得”。表示程度的“很快”要说“燃烧得很快”，不能直接说“燃烧很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
