INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91517, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用来说明道理的具体事情。", "primary_collocate": null, "pronunciation": "lì", "ipa": "li˥˩", "syllable_count": 1, "sentences": [{"text": "老师给我们举了一个例。", "target_word": "例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个道理不好懂，你能举个例吗？", "target_word": "例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上的这个例很简单，我一看就懂。", "target_word": "例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你再举一个例，我还是不太明白。", "target_word": "例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他举的这个例很有意思。", "target_word": "例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了说明这个问题，我想举个例。", "target_word": "例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个例太难了，我没有看懂。", "target_word": "例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写了一个例。", "target_word": "例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说得太快了，能不能举个例？", "target_word": "例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个例说明学习要花时间。", "target_word": "例", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "用来说明道理的一个具体事情，常说举个例", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f8102f3-2b9d-4b5e-9770-fb2903a345ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91517, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "例", "is_correct": true, "explanation": "正确。例 lì（第四声）指用来说明道理的具体事情。"}, {"text": "理", "is_correct": false, "explanation": "理 lǐ（第三声）与 lì（第四声）声调不同，意思是道理。"}, {"text": "梨", "is_correct": false, "explanation": "梨 lí（第二声）与 lì（第四声）声调不同，意思是梨子。"}, {"text": "腻", "is_correct": false, "explanation": "腻 nì（第四声）与 lì 声母不同（n 与 l），意思是油腻。"}], "explanations": {"例": "正确。例 lì（第四声）指用来说明道理的具体事情。", "理": "理 lǐ（第三声）与 lì（第四声）声调不同，意思是道理。", "梨": "梨 lí（第二声）与 lì（第四声）声调不同，意思是梨子。", "腻": "腻 nì（第四声）与 lì 声母不同（n 与 l），意思是油腻。"}, "sentence_index": null, "correct_answer": "例"}, "level_3": {"options": [{"text": "例", "is_correct": true, "explanation": "正确。「举了一个例」指举出一个具体事情来说明道理。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：「举」用于举例、举办等，不能说「举了一个作业」。"}, {"text": "教室", "is_correct": false, "explanation": "语义：「教室」是上课的地方，不能被老师举出来说明道理。"}, {"text": "盆栽", "is_correct": false, "explanation": "语义：「盆栽」是植物，不能被老师举出来作为说明道理的事情。"}], "explanations": {"例": "正确。「举了一个例」指举出一个具体事情来说明道理。", "作业": "搭配：「举」用于举例、举办等，不能说「举了一个作业」。", "教室": "语义：「教室」是上课的地方，不能被老师举出来说明道理。", "盆栽": "语义：「盆栽」是植物，不能被老师举出来作为说明道理的事情。"}, "sentence_index": 0, "correct_answer": "例"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家医院上个月收治了三例。", "explanation": "这里的「例」指病例，即病人的病情，不是用来说明道理的事例，此义项没有可替换的词。"}, {"text": "按老例，我们每周一开会。", "explanation": "这里的「例」指惯例，即长期形成的做法，不是用来说明道理的事例，此义项没有可替换的词。"}, {"text": "这件事开了例，以后大家都这样做。", "explanation": "这里的「例」指先例（可作依据的前例），属于另一义项，不是用来说明道理的事例。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91517, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "例", "is_correct": true, "explanation": "正确。例 lì（第四声）指用来说明道理的具体事情。"}, {"text": "离", "is_correct": false, "explanation": "离 lí（第二声）与 lì（第四声）声调不同，意思是离开。"}, {"text": "礼", "is_correct": false, "explanation": "礼 lǐ（第三声）与 lì（第四声）声调不同，意思是礼物或礼节。"}, {"text": "逆", "is_correct": false, "explanation": "逆 nì（第四声）与 lì 声母不同（n 与 l），意思是相反、颠倒。"}], "explanations": {"例": "正确。例 lì（第四声）指用来说明道理的具体事情。", "离": "离 lí（第二声）与 lì（第四声）声调不同，意思是离开。", "礼": "礼 lǐ（第三声）与 lì（第四声）声调不同，意思是礼物或礼节。", "逆": "逆 nì（第四声）与 lì 声母不同（n 与 l），意思是相反、颠倒。"}, "sentence_index": null, "correct_answer": "例"}, "level_3": {"options": [{"text": "例", "is_correct": true, "explanation": "正确。「这个例太难了」指用来说明道理的事例太难懂。"}, {"text": "饭", "is_correct": false, "explanation": "语义：「饭」是食物，不能用「太难了，我没有看懂」来形容。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：「看懂」用于文字或内容，不能搭配「蛋糕」。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：「窗户」是建筑部件，不是需要看懂的内容。"}], "explanations": {"例": "正确。「这个例太难了」指用来说明道理的事例太难懂。", "饭": "语义：「饭」是食物，不能用「太难了，我没有看懂」来形容。", "蛋糕": "搭配：「看懂」用于文字或内容，不能搭配「蛋糕」。", "窗户": "语义：「窗户」是建筑部件，不是需要看懂的内容。"}, "sentence_index": 6, "correct_answer": "例"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种情况只是个例，不能说明什么。", "explanation": "这里的「例」指个别情况，即特殊的情况，不是用来说明道理的事例，此义项没有可替换的词。"}, {"text": "按往年的例，春节放七天假。", "explanation": "这里的「例」指惯例，即以往一直这样做的做法，不是用来说明道理的事例。"}, {"text": "这次老板破了例，允许他请假。", "explanation": "这里的「例」指惯例，「破例」指打破常规，不是用来说明道理的事例，此义项没有可替换的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91517, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他举了一只例，大家就明白了。", "corrected_sentence": "他举了一个例，大家就明白了。", "error_description": "错误：「一只例」；正确：「一个例」。「只」多用于动物等，「例」前应用「个」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91517, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师讲的这只例很清楚。", "corrected_sentence": "老师讲的这个例很清楚。", "error_description": "错误：「这只例」；正确：「这个例」。「只」多用于动物等，「例」前应用「个」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
