INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91518, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "可作依据或说明的事物；例子。", "primary_collocate": null, "pronunciation": "lì", "ipa": "li˥˩", "syllable_count": 1, "sentences": [{"text": "这件事以前没有例可循，我们只能自己想办法。", "target_word": "例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个例不能开，不然大家都会迟到。", "target_word": "例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "词典里每个词后面都有一个例。", "target_word": "例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们照着书上的例做练习。", "target_word": "例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的例选得很好。", "target_word": "例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想多看几个例，再做题。", "target_word": "例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个例和上一个例不太一样。", "target_word": "例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲课时用了很多生活中的例。", "target_word": "例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个例后面都有一句说明。", "target_word": "例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先看懂这个例，再做后面的题。", "target_word": "例", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "可以照着做或参考的现成事例，如书上的例、先开的例", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f8102f3-2b9d-4b5e-9770-fb2903a345ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91518, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "例", "is_correct": true, "explanation": "正确。例 lì（第四声）指可以照着做或参考的现成事例。"}, {"text": "理", "is_correct": false, "explanation": "理 lǐ（第三声）与 lì（第四声）声调不同，意思是道理。"}, {"text": "梨", "is_correct": false, "explanation": "梨 lí（第二声）与 lì（第四声）声调不同，意思是梨子。"}, {"text": "腻", "is_correct": false, "explanation": "腻 nì（第四声）与 lì 声母不同（n 与 l），意思是油腻。"}], "explanations": {"例": "正确。例 lì（第四声）指可以照着做或参考的现成事例。", "理": "理 lǐ（第三声）与 lì（第四声）声调不同，意思是道理。", "梨": "梨 lí（第二声）与 lì（第四声）声调不同，意思是梨子。", "腻": "腻 nì（第四声）与 lì 声母不同（n 与 l），意思是油腻。"}, "sentence_index": null, "correct_answer": "例"}, "level_3": {"options": [{"text": "例", "is_correct": true, "explanation": "正确。「没有例可循」指没有现成的事例可以参考。"}, {"text": "衣服", "is_correct": false, "explanation": "语义：「衣服」不是可以参考的事例，「没有衣服可循」说不通。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：「早饭」不是可以参考的事例，句子说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「可循」搭配「规律、先例、线索」，不说「颜色可循」。"}], "explanations": {"例": "正确。「没有例可循」指没有现成的事例可以参考。", "衣服": "语义：「衣服」不是可以参考的事例，「没有衣服可循」说不通。", "早饭": "语义：「早饭」不是可以参考的事例，句子说不通。", "颜色": "搭配：「可循」搭配「规律、先例、线索」，不说「颜色可循」。"}, "sentence_index": 0, "correct_answer": "例"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这一带上周新增了五例。", "explanation": "这里的「例」指病例，即病人的病情，不是可以照着做的事例，此义项没有可替换的词。"}, {"text": "这种情况只是个例，不能照着做。", "explanation": "这里的「例」指个别情况，不是可以照着做的现成事例，属于另一义项。"}, {"text": "按老例，大家过年都要回家。", "explanation": "这里的「例」指惯例，即长期形成的做法，不是可以参考的具体事例。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings =