INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91518, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "例", "is_correct": true, "explanation": "正确。例 lì（第四声）指可以照着做或参考的现成事例。"}, {"text": "离", "is_correct": false, "explanation": "离 lí（第二声）与 lì（第四声）声调不同，意思是离开。"}, {"text": "礼", "is_correct": false, "explanation": "礼 lǐ（第三声）与 lì（第四声）声调不同，意思是礼物或礼节。"}, {"text": "逆", "is_correct": false, "explanation": "逆 nì（第四声）与 lì 声母不同（n 与 l），意思是相反、颠倒。"}], "explanations": {"例": "正确。例 lì（第四声）指可以照着做或参考的现成事例。", "离": "离 lí（第二声）与 lì（第四声）声调不同，意思是离开。", "礼": "礼 lǐ（第三声）与 lì（第四声）声调不同，意思是礼物或礼节。", "逆": "逆 nì（第四声）与 lì 声母不同（n 与 l），意思是相反、颠倒。"}, "sentence_index": null, "correct_answer": "例"}, "level_3": {"options": [{"text": "例", "is_correct": true, "explanation": "正确。「这个例和上一个例不太一样」指两个可参考的事例不同。"}, {"text": "生气", "is_correct": false, "explanation": "语法：「这个」后要接名词，「生气」是动词或形容词，「这个生气」不成立。"}, {"text": "跑", "is_correct": false, "explanation": "语法：「这个」后要接名词，「跑」是动词，「这个跑」不成立。"}, {"text": "睡觉", "is_correct": false, "explanation": "语法：「这个」后要接名词，「睡觉」是动词性短语，「这个睡觉」不成立。"}], "explanations": {"例": "正确。「这个例和上一个例不太一样」指两个可参考的事例不同。", "生气": "语法：「这个」后要接名词，「生气」是动词或形容词，「这个生气」不成立。", "跑": "语法：「这个」后要接名词，「跑」是动词，「这个跑」不成立。", "睡觉": "语法：「这个」后要接名词，「睡觉」是动词性短语，「这个睡觉」不成立。"}, "sentence_index": 6, "correct_answer": "例"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只是个例，不能代表大多数人。", "explanation": "这里的「例」指个别情况，不是可以照着做或参考的事例。"}, {"text": "这次破例让他提前离开，只此一次。", "explanation": "这里的「例」指惯例，「破例」指打破常规，不是可以照着做的事例，此义项没有可替换的词。"}, {"text": "这一带昨天又新增了两例。", "explanation": "这里的「例」指病例，即病人的病情，不是可以照着做的事例，此义项没有可替换的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
