INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91520, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国家划出、实行特殊政策和管理方式的地区。", "primary_collocate": null, "pronunciation": "tè qū", "ipa": "tʰɤ˥˩ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "深圳是中国最早设立的特区之一。", "target_word": "特区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家在这里划出了一个特区。", "target_word": "特区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "特区实行特别的政策。", "target_word": "特区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个特区的管理方式很新。", "target_word": "特区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多外国公司来特区投资。", "target_word": "特区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "特区的经济发展得很快。", "target_word": "特区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在特区工作了十年。", "target_word": "特区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家准备再办几个特区。", "target_word": "特区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "特区的政策吸引了很多年轻人。", "target_word": "特区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个特区建在海边，交通很方便。", "target_word": "特区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "经济特区", "label": "复合"}, {"form": "特區", "label": "繁体"}], "register": "中性", "sense_fingerprint": "国家划出的、实行特殊政策和管理方式的地区", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a539d2-b9bf-4579-bf7e-a6cf9155014c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91520, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "特区", "is_correct": true, "explanation": "正确：“最早设立的特区之一”指国家最早设立的实行特殊政策的地区，符合句意。"}, {"text": "海风", "is_correct": false, "explanation": "语义：海风是自然现象，不能被设立，“设立的海风”不成立。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“设立”不搭配歌曲，歌曲是“创作”或“演唱”的对象。"}, {"text": "诗", "is_correct": false, "explanation": "搭配：“设立”不用于诗，“诗”应说“写”或“创作”。"}], "explanations": {"特区": "正确：“最早设立的特区之一”指国家最早设立的实行特殊政策的地区，符合句意。", "海风": "语义：海风是自然现象，不能被设立，“设立的海风”不成立。", "歌曲": "搭配：“设立”不搭配歌曲，歌曲是“创作”或“演唱”的对象。", "诗": "搭配：“设立”不用于诗，“诗”应说“写”或“创作”。"}, "sentence_index": 0, "correct_answer": "特区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在南方设了一台特区。", "explanation": "这里的量词应为〈个〉。“台”用于机器等器物，不用于地区。"}, {"text": "这座小镇的风景很有特区。", "explanation": "这里应该用〈特色〉。“有特色”形容事物与众不同，“特区”只指国家划定的地区，不能修饰风景。"}, {"text": "这个特区一边走路一边唱歌。", "explanation": "这里应该用〈游客〉。特区是地方，不会走路、唱歌；这类动作的主语应是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91520, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特区", "is_correct": true, "explanation": "正确：“在特区工作”指在国家划定的特殊地区工作，符合句意。"}, {"text": "墙壁", "is_correct": false, "explanation": "语义：墙壁是建筑的构件，不是可以工作的地方。"}, {"text": "粉笔", "is_correct": false, "explanation": "语义：粉笔是书写用的物件，不是可以工作的地方。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器是演奏用的物件，不是可以工作的地方。"}], "explanations": {"特区": "正确：“在特区工作”指在国家划定的特殊地区工作，符合句意。", "墙壁": "语义：墙壁是建筑的构件，不是可以工作的地方。", "粉笔": "语义：粉笔是书写用的物件，不是可以工作的地方。", "乐器": "语义：乐器是演奏用的物件，不是可以工作的地方。"}, "sentence_index": 6, "correct_answer": "特区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在这里享有特区。", "explanation": "这里应该用〈特权〉。“享有”后接的是权利，特区是地方，不能被享有。"}, {"text": "这个地方的特区是海鲜。", "explanation": "这里应该用〈特产〉。特区是地方，不是产品，不能说“特区是海鲜”。"}, {"text": "我家附近有一条特区。", "explanation": "这里的量词应为〈个〉。“条”用于路、河等长条形的事物，不用于地区。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91520, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那本特区吸引了很多外国投资。", "corrected_sentence": "那个特区吸引了很多外国投资。", "error_description": "错误在于“特区”的量词用错了。“本”用于书册，“特区”要用量词“个”，应说“那个特区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91520, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他特区开了一家公司，生意很好。", "corrected_sentence": "他在特区开了一家公司，生意很好。", "error_description": "错误在于“特区”前漏掉了介词“在”。表示地点要说“在特区开公司”，不能说“特区开公司”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
