INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91521, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "依法是照着国家的规矩去做。", "primary_collocate": null, "pronunciation": "yī fǎ", "ipa": "i˥ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们要依法做事，不能乱来。", "target_word": "依法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他依法交了税，心里很踏实。", "target_word": "依法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校依法保护孩子的安全。", "target_word": "依法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都应该依法开车。", "target_word": "依法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位市长一直依法办事，大家都很放心。", "target_word": "依法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子的买卖要依法登记。", "target_word": "依法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院依法给病人保密。", "target_word": "依法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们依法登记结婚，拿到了证书。", "target_word": "依法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板依法签了合同。", "target_word": "依法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有问题时，我们可以依法向法院说明。", "target_word": "依法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "照着国家的规矩去做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '058bf7b9-c599-498a-840c-e5af9b2c9c86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91521, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "依法", "is_correct": true, "explanation": "依法是副词，修饰“做事”，表示按照规矩和法律行事。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”表示事情忽然发生，与“做事要守规矩”的语境不符。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“故意”强调刻意去做，与“不能乱来”的要求相反，句意不通。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：“十分”修饰形容词或心理动词，不修饰“做事”这类动作。"}], "explanations": {"依法": "依法是副词，修饰“做事”，表示按照规矩和法律行事。", "突然": "语义：“突然”表示事情忽然发生，与“做事要守规矩”的语境不符。", "故意": "语义：“故意”强调刻意去做，与“不能乱来”的要求相反，句意不通。", "十分": "搭配：“十分”修饰形容词或心理动词，不修饰“做事”这类动作。"}, "sentence_index": 0, "correct_answer": "依法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们应该依法吃饭。", "explanation": "这里应该用〈按时〉。依法指依照法律行事，吃饭不涉及法律规定，应说“按时吃饭”。"}, {"text": "小明每天依法练琴。", "explanation": "这里应该用〈坚持〉。依法说明依据法律，练琴是个人习惯，应说“每天坚持练琴”。"}, {"text": "他依法穿衣服。", "explanation": "这里应该用〈根据〉。依法的依据是法律，穿衣服要看天气，应说“根据天气穿衣服”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91521, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "依法", "is_correct": true, "explanation": "依法是副词，表示依照法律规定给病人保密。"}, {"text": "当众", "is_correct": false, "explanation": "语义：“当众”指在大家面前公开，与“给病人保密”的语义相反。"}, {"text": "大声", "is_correct": false, "explanation": "语义：“大声”指声音很响，给病人保密不能大声说出来。"}, {"text": "随口", "is_correct": false, "explanation": "搭配：“随口”表示不经考虑地说，不修饰“保密”这类需要认真对待的事。"}], "explanations": {"依法": "依法是副词，表示依照法律规定给病人保密。", "当众": "语义：“当众”指在大家面前公开，与“给病人保密”的语义相反。", "大声": "语义：“大声”指声音很响，给病人保密不能大声说出来。", "随口": "搭配：“随口”表示不经考虑地说，不修饰“保密”这类需要认真对待的事。"}, "sentence_index": 6, "correct_answer": "依法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们依法判断天气。", "explanation": "这里应该用〈凭〉。依法的依据必须是法律，判断天气靠经验，应说“凭经验判断天气”。"}, {"text": "孩子们依法读书。", "explanation": "这里应该用〈按照〉。依法强调依据法律，读书是按照老师的要求进行的，应说“按照老师的要求读书”。"}, {"text": "他每天依法散步。", "explanation": "这里应该用〈按时〉。依法的依据必须是法律，散步是个人习惯，应说“每天按时散步”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91521, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校应该依法着管理学生。", "corrected_sentence": "学校应该依法管理学生。", "error_description": "“依法”是副词，后面不能加“着”。应直接说“依法管理学生”，去掉“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91521, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司很依法办理了营业执照。", "corrected_sentence": "这家公司依法办理了营业执照。", "error_description": "“依法”是表示方式的副词，不能被程度副词“很”修饰，应说“依法办理”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
