INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91522, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "按照法律或法令。", "primary_collocate": null, "pronunciation": "yī fǎ", "ipa": "i˥ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "公司要依法纳税。", "target_word": "依法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察依法抓住了小偷。", "target_word": "依法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板依法给工人发工资。", "target_word": "依法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院依法处理了这件事。", "target_word": "依法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开店之前，依法办好了手续。", "target_word": "依法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作中受伤的人，可以依法得到帮助。", "target_word": "依法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们每个人都有权利依法保护自己。", "target_word": "依法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店依法不能卖假东西。", "target_word": "依法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车喝酒的人，警察会依法处理。", "target_word": "依法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂没有依法办手续，所以关门了。", "target_word": "依法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "依照法律或法令来做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '058bf7b9-c599-498a-840c-e5af9b2c9c86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91522, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "依法", "is_correct": true, "explanation": "依法是副词，修饰动词“纳税”，表示按照法律规定去做。"}, {"text": "随意", "is_correct": false, "explanation": "搭配：“随意”指随自己的心意，不能修饰纳税这样的法定义务。"}, {"text": "偷偷", "is_correct": false, "explanation": "语义：“偷偷”指暗中进行、不让人知道，而公司纳税是公开的法定义务，句意矛盾。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“故意”强调有意去做，句子说的是公司应尽的义务，不是刻意去做的事。"}], "explanations": {"依法": "依法是副词，修饰动词“纳税”，表示按照法律规定去做。", "随意": "搭配：“随意”指随自己的心意，不能修饰纳税这样的法定义务。", "偷偷": "语义：“偷偷”指暗中进行、不让人知道，而公司纳税是公开的法定义务，句意矛盾。", "故意": "语义：“故意”强调有意去做，句子说的是公司应尽的义务，不是刻意去做的事。"}, "sentence_index": 0, "correct_answer": "依法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子应该依法睡觉。", "explanation": "这里应该用〈按时〉。依法指依照法律规定做事，睡觉不涉及法律，应说“按时睡觉”。"}, {"text": "妈妈一直依法锻炼。", "explanation": "这里应该用〈坚持〉。依法说明按照法律行事，锻炼身体是个人习惯，应说“一直坚持锻炼”。"}, {"text": "他依法吃药。", "explanation": "这里应该用〈按时〉。依法的依据必须是法律，吃药与法律无关，应说“他按时吃药”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91522, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "依法", "is_correct": true, "explanation": "依法是副词，表示依照法律保护自己的权利。"}, {"text": "随便", "is_correct": false, "explanation": "语义：“随便”表示不认真、不在意，与“有权利保护自己”的严肃语义不符。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”表示事情忽然发生，与“有权利保护自己”这种持续的状态不符。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：“十分”修饰形容词或心理动词，不修饰“保护”这类动作。"}], "explanations": {"依法": "依法是副词，表示依照法律保护自己的权利。", "随便": "语义：“随便”表示不认真、不在意，与“有权利保护自己”的严肃语义不符。", "突然": "语义：“突然”表示事情忽然发生，与“有权利保护自己”这种持续的状态不符。", "十分": "搭配：“十分”修饰形容词或心理动词，不修饰“保护”这类动作。"}, "sentence_index": 6, "correct_answer": "依法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们依法安排行程。", "explanation": "这里应该用〈根据〉。依法的依据是法律，安排行程要看天气，应说“根据天气安排行程”。"}, {"text": "他依法做饭。", "explanation": "这里应该用〈凭〉。依法的依据必须是法律，做饭靠经验，应说“凭经验做饭”。"}, {"text": "我们依法出发。", "explanation": "这里应该用〈按照〉。依法强调依据法律，出发是按时间表进行的，应说“按照时间表出发”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91522, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂应该依法了排污。", "corrected_sentence": "工厂应该依法排污。", "error_description": "“依法”是副词，不能直接带“了”，“依法了排污”是错误的，应说“依法排污”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91522, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他依法依法领取了养老金。", "corrected_sentence": "他依法领取了养老金。", "error_description": "“依法”已是副词，只用一次，应说“依法领取”，不能重复说“依法依法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91523, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "民主", "is_correct": true, "explanation": "反义：“民主”指大家共同商量、决定，与“独裁”一个人说了算正相反。"}, {"text": "安静", "is_correct": false, "explanation": "与“独裁”没有反义关系：“安静”形容声音或环境，与权力分配无关。"}, {"text": "美丽", "is_correct": false, "explanation": "与“独裁”没有反义关系：“美丽”形容外貌或景色，与权力无关。"}, {"text": "清楚", "is_correct": false, "explanation": "与“独裁”没有反义关系：“清楚”形容明白、不模糊，与独断无关。"}], "correct_answer": "民主", "explanations": {"民主": "反义：“民主”指大家共同商量、决定，与“独裁”一个人说了算正相反。", "安静": "与“独裁”没有反义关系：“安静”形容声音或环境，与权力分配无关。", "美丽": "与“独裁”没有反义关系：“美丽”形容外貌或景色，与权力无关。", "清楚": "与“独裁”没有反义关系：“清楚”形容明白、不模糊，与独断无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91523, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "民主", "is_correct": true, "explanation": "反义：“民主”强调大家共同参与、共同决定，与“独裁”一个人说了算相反。"}, {"text": "聪明", "is_correct": false, "explanation": "与“独裁”没有反义关系：“聪明”形容头脑灵活，与权力无关。"}, {"text": "快乐", "is_correct": false, "explanation": "与“独裁”没有反义关系：“快乐”形容心情，与是否独断无关。"}, {"text": "整齐", "is_correct": false, "explanation": "与“独裁”没有反义关系：“整齐”形容排列有序，与权力分配无关。"}], "correct_answer": "民主", "explanations": {"民主": "反义：“民主”强调大家共同参与、共同决定，与“独裁”一个人说了算相反。", "聪明": "与“独裁”没有反义关系：“聪明”形容头脑灵活，与权力无关。", "快乐": "与“独裁”没有反义关系：“快乐”形容心情，与是否独断无关。", "整齐": "与“独裁”没有反义关系：“整齐”形容排列有序，与权力分配无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91523, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一个人说了算，别人不能说话。", "primary_collocate": null, "pronunciation": "dú cái", "ipa": "tu˧˥ tsʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "老板太独裁了，从不听我们的话。", "target_word": "独裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在家里很独裁，什么都自己决定。", "target_word": "独裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人独裁，别人就不能说话。", "target_word": "独裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理独裁了几年，大家都很不满。", "target_word": "独裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢独裁的人。", "target_word": "独裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个班里，班长不能独裁。", "target_word": "独裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是独裁，从来不问别人的意见。", "target_word": "独裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲一向独裁，孩子们不敢开口。", "target_word": "独裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会的时候，你不要独裁。", "target_word": "独裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他独裁惯了，听不进别人的话。", "target_word": "独裁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "独裁者", "label": "复合"}, {"form": "獨裁", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在家庭、公司等小范围里一个人说了算，不听别人的意见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61745b1a-f27b-4aaf-b958-4b5b5e37ece2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91523, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "独裁", "is_correct": true, "explanation": "独裁：一个人说了算、别人不能说话，与“从不听我们的话”相合。"}, {"text": "慷慨", "is_correct": false, "explanation": "语义：“慷慨”指大方、不吝啬，与“从不听我们的话”矛盾。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”指风趣，与“从不听我们的话”的强硬态度不协调。"}, {"text": "透明", "is_correct": false, "explanation": "搭配：“透明”多用于账目、制度，一般不用来形容老板的为人。"}], "explanations": {"独裁": "独裁：一个人说了算、别人不能说话，与“从不听我们的话”相合。", "慷慨": "语义：“慷慨”指大方、不吝啬，与“从不听我们的话”矛盾。", "幽默": "语义：“幽默”指风趣，与“从不听我们的话”的强硬态度不协调。", "透明": "搭配：“透明”多用于账目、制度，一般不用来形容老板的为人。"}, "sentence_index": 0, "correct_answer": "独裁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的画风很独裁。", "explanation": "这里应该用〈独特〉。独裁指一个人说了算、压制别人，不能用来形容画风的特色；形容画风与众不同要说独特。"}, {"text": "我们一起独裁了这块蛋糕。", "explanation": "这里应该用〈分享〉。独裁是压制别人，与大家一起吃、共同分享的含义相反。"}, {"text": "大家一起独裁了这件事。", "explanation": "这里应该用〈商量〉。独裁是一个人说了算，不能用于大家一起商量后再决定的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91523, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "独裁", "is_correct": true, "explanation": "独裁：一个人说了算，与“从来不问别人的意见”相合。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”需要多人参与、常带“问题”作宾语，单独作谓语与“一个人决定”不搭。"}, {"text": "热情", "is_correct": false, "explanation": "语义：“热情”指待人友好、主动，与“从来不问别人的意见”矛盾。"}, {"text": "谦虚", "is_correct": false, "explanation": "语义：“谦虚”指虚心听取别人，与“从来不问别人的意见”矛盾。"}], "explanations": {"独裁": "独裁：一个人说了算，与“从来不问别人的意见”相合。", "讨论": "搭配：“讨论”需要多人参与、常带“问题”作宾语，单独作谓语与“一个人决定”不搭。", "热情": "语义：“热情”指待人友好、主动，与“从来不问别人的意见”矛盾。", "谦虚": "语义：“谦虚”指虚心听取别人，与“从来不问别人的意见”矛盾。"}, "sentence_index": 6, "correct_answer": "独裁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他热情地独裁了客人。", "explanation": "这里应该用〈招待〉。独裁指压制别人、不许别人说话，不能用来形容热情地对待客人。"}, {"text": "我们班每年都投票独裁班长。", "explanation": "这里应该用〈选举〉。独裁指一个人说了算、别人不能说话，不能用来说大家投票产生班长。"}, {"text": "大家都独裁他的帮助。", "explanation": "这里应该用〈感谢〉。独裁是掌控别人，不能用来表达对别人帮助的感激。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91523, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个社团的会长一向独裁者，大家都不愿意再参加。", "corrected_sentence": "那个社团的会长一向独裁，大家都不愿意再参加。", "error_description": "错误：「一向独裁者」，「独裁者」是名词，不能直接作谓语。正确：「一向独裁」，「独裁」是动词，可以直接作谓语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91523, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老师上课时总是把独裁，从不让学生提问。", "corrected_sentence": "这位老师上课时总是独裁，从不让学生提问。", "error_description": "把字用错：“把”后面要有受事和结果成分，“把独裁”不成立，应去掉“把”，说“总是独裁”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91524, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "民主", "is_correct": true, "explanation": "反义：“民主”指人民共同决定国家事务，与“独裁”少数人掌握权力正相反。"}, {"text": "丰富", "is_correct": false, "explanation": "与“独裁”没有反义关系：“丰富”形容数量多、内容多，与权力无关。"}, {"text": "活泼", "is_correct": false, "explanation": "与“独裁”没有反义关系：“活泼”形容性格开朗，与政治制度无关。"}, {"text": "遥远", "is_correct": false, "explanation": "与“独裁”没有反义关系：“遥远”形容距离，与权力无关。"}], "correct_answer": "民主", "explanations": {"民主": "反义：“民主”指人民共同决定国家事务，与“独裁”少数人掌握权力正相反。", "丰富": "与“独裁”没有反义关系：“丰富”形容数量多、内容多，与权力无关。", "活泼": "与“独裁”没有反义关系：“活泼”形容性格开朗，与政治制度无关。", "遥远": "与“独裁”没有反义关系：“遥远”形容距离，与权力无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91524, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "民主", "is_correct": true, "explanation": "反义：“民主”强调大家共同参与、共同决定，与“独裁”少数人掌权相反。"}, {"text": "简单", "is_correct": false, "explanation": "与“独裁”没有反义关系：“简单”形容不复杂，与权力分配无关。"}, {"text": "健康", "is_correct": false, "explanation": "与“独裁”没有反义关系：“健康”形容身体状况，与政治无关。"}, {"text": "明亮", "is_correct": false, "explanation": "与“独裁”没有反义关系：“明亮”形容光线或颜色，与权力无关。"}], "correct_answer": "民主", "explanations": {"民主": "反义：“民主”强调大家共同参与、共同决定，与“独裁”少数人掌权相反。", "简单": "与“独裁”没有反义关系：“简单”形容不复杂，与权力分配无关。", "健康": "与“独裁”没有反义关系：“健康”形容身体状况，与政治无关。", "明亮": "与“独裁”没有反义关系：“明亮”形容光线或颜色，与权力无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91524, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "个人或少数人掌握全部权力，独断专行。", "primary_collocate": null, "pronunciation": "dú cái", "ipa": "tu˧˥ tsʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "国王一个人独裁，别人都不能管国家大事。", "target_word": "独裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他掌握着全部权力，在国内独裁了很多年。", "target_word": "独裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王独裁，人民没有自由。", "target_word": "独裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上有些国王曾经独裁。", "target_word": "独裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想独裁，所以不让别人参加选举。", "target_word": "独裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少数人独裁的国家，常常没有自由。", "target_word": "独裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统独裁以后，报纸都不能乱说话。", "target_word": "独裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人民不喜欢独裁，他们想要自由。", "target_word": "独裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位领导人独裁了二十年。", "target_word": "独裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把权力都拿在手里，开始独裁。", "target_word": "独裁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "独裁者", "label": "复合"}, {"form": "獨裁", "label": "繁体"}], "register": "中性", "sense_fingerprint": "个人或少数人掌握国家全部权力并独断专行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61745b1a-f27b-4aaf-b958-4b5b5e37ece2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91524, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "独裁", "is_correct": true, "explanation": "独裁：一个人掌握全部权力，与“一个人”“别人都不能管国家大事”相合。"}, {"text": "共治", "is_correct": false, "explanation": "语义：“共治”指多人共同治理，与“一个人”矛盾。"}, {"text": "陪伴", "is_correct": false, "explanation": "配价：“陪伴”需要带陪伴的对象，不能单独作谓语，也与“别人都不能管国家大事”不合。"}, {"text": "合作", "is_correct": false, "explanation": "语义：“合作”需要双方或多方，与“一个人”矛盾。"}], "explanations": {"独裁": "独裁：一个人掌握全部权力，与“一个人”“别人都不能管国家大事”相合。", "共治": "语义：“共治”指多人共同治理，与“一个人”矛盾。", "陪伴": "配价：“陪伴”需要带陪伴的对象，不能单独作谓语，也与“别人都不能管国家大事”不合。", "合作": "语义：“合作”需要双方或多方，与“一个人”矛盾。"}, "sentence_index": 0, "correct_answer": "独裁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "人民独裁了新的领导人。", "explanation": "这里应该用〈选举〉。独裁指个人或少数人掌握全部权力，不能用来说人民选出领导人。"}, {"text": "他独裁了一本小说。", "explanation": "这里应该用〈写〉。独裁指掌握权力、压制他人，不能用来说写作。"}, {"text": "大家一起独裁了国家大事。", "explanation": "这里应该用〈讨论〉。独裁是一个人或少数人说了算，不能用于大家一起讨论国家大事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91524, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "独裁", "is_correct": true, "explanation": "独裁：总统掌握全部权力，与后句“报纸都不能乱说话”的管控相合。"}, {"text": "开放", "is_correct": false, "explanation": "语义：“开放”指放宽限制，与“报纸都不能乱说话”的管控正相反。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”指离开职位，与“报纸都不能乱说话”没有因果关系。"}, {"text": "出访", "is_correct": false, "explanation": "搭配：“出访”指出国访问，后面的“报纸都不能乱说话”与出访没有关联，语境不搭。"}], "explanations": {"独裁": "独裁：总统掌握全部权力，与后句“报纸都不能乱说话”的管控相合。", "开放": "语义：“开放”指放宽限制，与“报纸都不能乱说话”的管控正相反。", "退休": "语义：“退休”指离开职位，与“报纸都不能乱说话”没有因果关系。", "出访": "搭配：“出访”指出国访问，后面的“报纸都不能乱说话”与出访没有关联，语境不搭。"}, "sentence_index": 6, "correct_answer": "独裁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府独裁了民主制度。", "explanation": "这里应该用〈建立〉。独裁是压制他人，与“民主制度”的含义相反，不能接“民主制度”作对象。"}, {"text": "他为人民独裁。", "explanation": "这里应该用〈服务〉。独裁是压制人民，不能用来说为人民做事。"}, {"text": "大家独裁新总统。", "explanation": "这里应该用〈欢迎〉。独裁指压制他人、掌握权力，不能用来表示对新总统的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91524, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个国家的首领一向把独裁，人民没有任何发言权。", "corrected_sentence": "那个国家的首领一向独裁，人民没有任何发言权。", "error_description": "把字用错：“把”后面要带受事并有处置结果，“把独裁”不成立，应去掉“把”，说“一向独裁”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91524, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位元首二十年来一直独裁者，没有人敢公开批评。", "corrected_sentence": "这位元首二十年来一直独裁，没有人敢公开批评。", "error_description": "词性错：「独裁者」是名词，不能直接作谓语，应去掉「者」，说「一直独裁」。「独裁」是动词，可以直接作谓语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
