INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91526, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "担保，保证某事一定如此。", "primary_collocate": null, "pronunciation": "bǎo", "ipa": "pau̯˨˩˦", "syllable_count": 1, "sentences": [{"text": "这件事你放心，我保你没问题。", "target_word": "保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我保他明天一定来。", "target_word": "保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的鱼很新鲜，我保你满意。", "target_word": "保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把伞我保你不被雨淋。", "target_word": "保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要你来，我保你吃好。", "target_word": "保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做，我保你不会错。", "target_word": "保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我保这个办法有用。", "target_word": "保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你放心，我保这次不会出事。", "target_word": "保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你放心，这次考试我保你过。", "target_word": "保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我敢保他是个好人。", "target_word": "保", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "口语中单用，表示担保、保证某事一定如此", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '058bf7b9-c599-498a-840c-e5af9b2c9c86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91526, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "保", "is_correct": true, "explanation": "保 bǎo，口语中表示担保、保证某事一定如此。"}, {"text": "包", "is_correct": false, "explanation": "包 bāo（第一声）与 bǎo（第三声）声调不同，意思是包裹。"}, {"text": "报", "is_correct": false, "explanation": "报 bào（第四声）与 bǎo（第三声）声调不同，意思是报告。"}, {"text": "抱", "is_correct": false, "explanation": "抱 bào（第四声）与 bǎo（第三声）声调不同，意思是拥抱。"}, {"text": "好", "is_correct": false, "explanation": "好 hǎo 与 bǎo 只在声母上不同（h 与 b），意思是好。"}], "explanations": {"保": "保 bǎo，口语中表示担保、保证某事一定如此。", "包": "包 bāo（第一声）与 bǎo（第三声）声调不同，意思是包裹。", "报": "报 bào（第四声）与 bǎo（第三声）声调不同，意思是报告。", "抱": "抱 bào（第四声）与 bǎo（第三声）声调不同，意思是拥抱。", "好": "好 hǎo 与 bǎo 只在声母上不同（h 与 b），意思是好。"}, "sentence_index": null, "correct_answer": "保"}, "level_3": {"options": [{"text": "保", "is_correct": true, "explanation": "保：表示担保，说话人替对方保证“没问题”，与“你放心”一致。"}, {"text": "怕", "is_correct": false, "explanation": "语义：“怕”表示担心，与前句“你放心”矛盾。"}, {"text": "怪", "is_correct": false, "explanation": "语义：“怪”是责怪，与“你放心”的安慰语气相反。"}, {"text": "赔", "is_correct": false, "explanation": "配价：“赔”要带“钱”或“损失”作宾语，“赔你没问题”不成立。"}], "explanations": {"保": "保：表示担保，说话人替对方保证“没问题”，与“你放心”一致。", "怕": "语义：“怕”表示担心，与前句“你放心”矛盾。", "怪": "语义：“怪”是责怪，与“你放心”的安慰语气相反。", "赔": "配价：“赔”要带“钱”或“损失”作宾语，“赔你没问题”不成立。"}, "sentence_index": 0, "correct_answer": "保"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天早上保一杯牛奶。", "explanation": "这里应该用〈倒〉。保是担保、保证某事一定如此，倒牛奶要用“倒”。"}, {"text": "护士每天保病人。", "explanation": "这里应该用〈照顾〉。保表示担保某事一定如此，照料病人要用“照顾”。"}, {"text": "我昨天保了这本书。", "explanation": "这里应该用〈读〉。保表示担保某事一定如此，看书要用“读”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91526, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "保", "is_correct": true, "explanation": "保 bǎo，口语中表示担保、保证某事一定如此。"}, {"text": "暴", "is_correct": false, "explanation": "暴 bào（第四声）与 bǎo（第三声）声调不同，意思是凶暴。"}, {"text": "爆", "is_correct": false, "explanation": "爆 bào（第四声）与 bǎo（第三声）声调不同，意思是爆炸。"}, {"text": "跑", "is_correct": false, "explanation": "跑 pǎo 与 bǎo 只在声母上不同（送气的 p 与不送气的 b），意思是跑步。"}], "explanations": {"保": "保 bǎo，口语中表示担保、保证某事一定如此。", "暴": "暴 bào（第四声）与 bǎo（第三声）声调不同，意思是凶暴。", "爆": "爆 bào（第四声）与 bǎo（第三声）声调不同，意思是爆炸。", "跑": "跑 pǎo 与 bǎo 只在声母上不同（送气的 p 与不送气的 b），意思是跑步。"}, "sentence_index": null, "correct_answer": "保"}, "level_3": {"options": [{"text": "保", "is_correct": true, "explanation": "保：表示担保，说话人替这个办法的效果作保，与句意一致。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”的对象是具体物品，不能与“办法”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能带“办法”作宾语，“吃这个办法”不成立。"}, {"text": "骂", "is_correct": false, "explanation": "语义：“骂”是责备，与“有用”的肯定评价不合。"}], "explanations": {"保": "保：表示担保，说话人替这个办法的效果作保，与句意一致。", "扔": "搭配：“扔”的对象是具体物品，不能与“办法”搭配。", "吃": "搭配：“吃”不能带“办法”作宾语，“吃这个办法”不成立。", "骂": "语义：“骂”是责备，与“有用”的肯定评价不合。"}, "sentence_index": 6, "correct_answer": "保"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要保火，注意安全。", "explanation": "这里应该用〈防〉。保表示担保某事一定如此，防范火灾要用“防”。"}, {"text": "医生正在保病。", "explanation": "这里应该用〈治〉。保表示担保某事一定如此，治疗疾病要用“治”。"}, {"text": "妈妈在厨房保饭。", "explanation": "这里应该用〈做〉。保表示担保某事一定如此，做饭要用“做”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91526, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你别担心，我你保今天准时到。", "corrected_sentence": "你别担心，我保你今天准时到。", "error_description": "“保”是动词，宾语“你”要紧跟其后，应说“我保你”，不能把“你”放到“保”前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91526, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我保着这个方案能成功。", "corrected_sentence": "我保这个方案能成功。", "error_description": "“保”表示担保，是一次性的表态，不能带“着”，应说“我保这个方案能成功”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c459049e-8d25-4d6b-8325-dcd7dc09ac51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
