INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91527, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "比赛以后，得到了奖。", "primary_collocate": null, "pronunciation": "huò jiǎng", "ipa": "xwo˥˩ tɕjaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "比赛结束后，我们班获奖了。", "target_word": "获奖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他跑得最快，所以获奖了。", "target_word": "获奖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次演讲比赛，只有三个人获奖。", "target_word": "获奖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到自己获奖，她高兴得哭了。", "target_word": "获奖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟练了一年钢琴，比赛时终于获奖了。", "target_word": "获奖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "参加比赛的人很多，但获奖的人不多。", "target_word": "获奖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的歌在比赛里获奖，大家都为他鼓掌。", "target_word": "获奖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我没有获奖，但我很开心。", "target_word": "获奖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛前她很紧张，没想到最后获奖了。", "target_word": "获奖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她拿到比赛结果，才知道自己获奖。", "target_word": "获奖", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "獲獎", "label": "繁体"}, {"form": "获奖者", "label": "复合"}, {"form": "获过奖", "label": "体标"}], "register": "中性", "sense_fingerprint": "获奖|动作|比赛结束后得奖", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad9311d-2259-4b31-9471-d7d48a98239a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91527, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "获奖", "is_correct": true, "explanation": "正确。「获奖」指比赛后得奖，与「比赛结束后」相符。"}, {"text": "生病", "is_correct": false, "explanation": "语义：班级不会「生病」，与比赛结束后的情形矛盾。"}, {"text": "下雨", "is_correct": false, "explanation": "搭配：「下雨」不能以「我们班」为主语，搭配不当。"}, {"text": "失踪", "is_correct": false, "explanation": "语义：班级不会「失踪」，与比赛的结果毫无关联。"}], "explanations": {"获奖": "正确。「获奖」指比赛后得奖，与「比赛结束后」相符。", "生病": "语义：班级不会「生病」，与比赛结束后的情形矛盾。", "下雨": "搭配：「下雨」不能以「我们班」为主语，搭配不当。", "失踪": "语义：班级不会「失踪」，与比赛的结果毫无关联。"}, "sentence_index": 0, "correct_answer": "获奖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他高考结束后就获奖了，不知道能不能上大学。", "explanation": "这里应该用〈录取〉。「获奖」指比赛后得到奖项，不能用于被学校接收。"}, {"text": "她这次体检获奖了。", "explanation": "这里应该用〈合格〉。「获奖」指比赛后得奖，不能用来说体检达标。"}, {"text": "他在选举中获奖了，大家都说他很能干。", "explanation": "这里应该用〈当选〉。「获奖」指比赛后得奖，不能用于选举中被选上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91527, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "获奖", "is_correct": true, "explanation": "正确。「获奖」指得到奖项，与「大家都为他鼓掌」的情形相符。"}, {"text": "跑步", "is_correct": false, "explanation": "搭配：歌曲不能「跑步」，「在比赛里」的说法不能与「跑步」搭配。"}, {"text": "跳舞", "is_correct": false, "explanation": "搭配：「跳舞」是动作，不能用来描述歌曲在比赛中的情况。"}, {"text": "摔倒", "is_correct": false, "explanation": "语义：歌曲「摔倒」与后句「大家都为他鼓掌」矛盾。"}], "explanations": {"获奖": "正确。「获奖」指得到奖项，与「大家都为他鼓掌」的情形相符。", "跑步": "搭配：歌曲不能「跑步」，「在比赛里」的说法不能与「跑步」搭配。", "跳舞": "搭配：「跳舞」是动作，不能用来描述歌曲在比赛中的情况。", "摔倒": "语义：歌曲「摔倒」与后句「大家都为他鼓掌」矛盾。"}, "sentence_index": 6, "correct_answer": "获奖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的钱包昨天获奖了。", "explanation": "这里应该用〈丢失〉。「获奖」指比赛后得到奖项，不能用来说东西丢了。"}, {"text": "他的旅费上周获奖了，终于可以回家了。", "explanation": "这里应该用〈报销〉。「获奖」指比赛后得到奖项，不能用于费用被批准退还。"}, {"text": "她的数学成绩获奖了。", "explanation": "这里应该用〈及格〉。「获奖」指比赛后得到奖项，不表示成绩达到标准。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91527, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "比赛结束后，我们班获奖了奖。", "corrected_sentence": "比赛结束后，我们班获了奖。", "error_description": "重复宾语：「获奖」本身已含「奖」，不能再加一个「奖」；拆开说应为「获了奖」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91527, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他获奖着，大家都为他鼓掌。", "corrected_sentence": "他获奖了，大家都为他鼓掌。", "error_description": "体标用错：获奖是一次完成的事，应用「了」说「获奖了」，不能用「着」说「获奖着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
