INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91530, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "质地细腻、温润有光泽的美石，常用来做饰品和器物。", "primary_collocate": null, "pronunciation": "yù", "ipa": "y˥˩", "syllable_count": 1, "sentences": [{"text": "好玉摸起来温润细腻。", "target_word": "玉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块玉质地细腻，很有光泽。", "target_word": "玉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用玉做了一个小饰品。", "target_word": "玉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人常常把玉戴在身上。", "target_word": "玉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她买了一块白色的玉。", "target_word": "玉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块玉的光泽很温润。", "target_word": "玉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用玉做一个小盒子。", "target_word": "玉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块玉是从云南买来的。", "target_word": "玉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玉在中国文化里很重要。", "target_word": "玉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里有很多漂亮的玉。", "target_word": "玉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "玉石", "label": "复合词"}, {"form": "玉器", "label": "复合词"}], "register": "中性", "sense_fingerprint": "质地细腻温润有光泽的美石，做饰品器物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e23a7c-9131-4a56-a854-f3c79c067e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91530, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "玉", "is_correct": true, "explanation": "玉（yù，第四声）：正确答案，指质地细腻温润的美石。"}, {"text": "语", "is_correct": false, "explanation": "语（yǔ，第三声）与玉（yù，第四声）声调不同，意思是语言。"}, {"text": "余", "is_correct": false, "explanation": "余（yú，第二声）与玉（yù，第四声）声调不同，意思是剩下的。"}, {"text": "序", "is_correct": false, "explanation": "序（xù）与玉（yù）声母不同，意思是次序。"}, {"text": "句", "is_correct": false, "explanation": "句（jù，第四声）与玉（yù，第四声）只差声母，意思是句子。"}, {"text": "悦", "is_correct": false, "explanation": "悦（yuè）与玉（yù）韵母不同，多一个 e，意思是高兴。"}], "explanations": {"玉": "玉（yù，第四声）：正确答案，指质地细腻温润的美石。", "语": "语（yǔ，第三声）与玉（yù，第四声）声调不同，意思是语言。", "余": "余（yú，第二声）与玉（yù，第四声）声调不同，意思是剩下的。", "序": "序（xù）与玉（yù）声母不同，意思是次序。", "句": "句（jù，第四声）与玉（yù，第四声）只差声母，意思是句子。", "悦": "悦（yuè）与玉（yù）韵母不同，多一个 e，意思是高兴。"}, "sentence_index": null, "correct_answer": "玉"}, "level_3": {"options": [{"text": "玉", "is_correct": true, "explanation": "玉：质地温润细腻，与「温润细腻」的描写相符。"}, {"text": "铁", "is_correct": false, "explanation": "语义：铁坚硬冰凉，不是温润细腻的，与句中描写矛盾。"}, {"text": "沙子", "is_correct": false, "explanation": "语义：沙子粗糙，与「温润细腻」的感觉矛盾。"}, {"text": "砖头", "is_correct": false, "explanation": "语义：砖头粗糙坚硬，与「温润细腻」的描写矛盾。"}], "explanations": {"玉": "玉：质地温润细腻，与「温润细腻」的描写相符。", "铁": "语义：铁坚硬冰凉，不是温润细腻的，与句中描写矛盾。", "沙子": "语义：沙子粗糙，与「温润细腻」的感觉矛盾。", "砖头": "语义：砖头粗糙坚硬，与「温润细腻」的描写矛盾。"}, "sentence_index": 0, "correct_answer": "玉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冬天家里烧玉取暖。", "explanation": "这里应该用〈煤〉。玉是石料，不能燃烧，取暖的燃料要用煤。"}, {"text": "他用玉写字。", "explanation": "这里应该用〈墨水〉。玉是石料，不能用来写字。"}, {"text": "工地上堆着很多玉，准备用来盖房子。", "explanation": "这里应该用〈石头〉。玉是贵重的美石，常用来做饰品，不能当建材堆在工地上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91530, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "玉", "is_correct": true, "explanation": "玉（yù，第四声）：正确答案，指质地细腻温润的美石。"}, {"text": "雨", "is_correct": false, "explanation": "雨（yǔ，第三声）与玉（yù，第四声）声调不同，意思是雨水。"}, {"text": "鱼", "is_correct": false, "explanation": "鱼（yú，第二声）与玉（yù，第四声）声调不同，意思是鱼类。"}, {"text": "绪", "is_correct": false, "explanation": "绪（xù）与玉（yù）声母不同，意思是情绪、头绪。"}, {"text": "律", "is_correct": false, "explanation": "律（lǜ，第四声）与玉（yù，第四声）只差声母 l，意思是法律、规律。"}, {"text": "剧", "is_correct": false, "explanation": "剧（jù，第四声）与玉（yù，第四声）只差声母，意思是戏剧。"}], "explanations": {"玉": "玉（yù，第四声）：正确答案，指质地细腻温润的美石。", "雨": "雨（yǔ，第三声）与玉（yù，第四声）声调不同，意思是雨水。", "鱼": "鱼（yú，第二声）与玉（yù，第四声）声调不同，意思是鱼类。", "绪": "绪（xù）与玉（yù）声母不同，意思是情绪、头绪。", "律": "律（lǜ，第四声）与玉（yù，第四声）只差声母 l，意思是法律、规律。", "剧": "剧（jù，第四声）与玉（yù，第四声）只差声母，意思是戏剧。"}, "sentence_index": null, "correct_answer": "玉"}, "level_3": {"options": [{"text": "玉", "is_correct": true, "explanation": "玉：可以用来制作小盒子的材料，与句意相符。"}, {"text": "雾", "is_correct": false, "explanation": "语义：雾没有固定的形状，无法用来做盒子。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：「空气」不能作为制作盒子的材料，搭配不当。"}, {"text": "云", "is_correct": false, "explanation": "语义：云是飘在天上的水汽，不能用来做盒子。"}], "explanations": {"玉": "玉：可以用来制作小盒子的材料，与句意相符。", "雾": "语义：雾没有固定的形状，无法用来做盒子。", "空气": "搭配：「空气」不能作为制作盒子的材料，搭配不当。", "云": "语义：云是飘在天上的水汽，不能用来做盒子。"}, "sentence_index": 6, "correct_answer": "玉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他饿了，吃了一块玉。", "explanation": "这里应该用〈糖〉。玉是石料，不能吃。"}, {"text": "他用玉捆住了箱子。", "explanation": "这里应该用〈绳子〉。玉质地坚硬，不能像绳子一样弯折捆扎，捆东西要用绳子。"}, {"text": "他用玉折了一只鹤。", "explanation": "这里应该用〈纸〉。玉质地坚硬，不能像纸一样折叠。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91530, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只玉质地细腻，我很喜欢它。", "corrected_sentence": "这块玉质地细腻，我很喜欢它。", "error_description": "错误：「这只玉」，正确：「这块玉」。玉是块状物，量词用「块」，不用「只」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91530, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把那玉块擦干净了。", "corrected_sentence": "他把那块玉擦干净了。", "error_description": "错误：「那玉块」，正确：「那块玉」。量词「块」应与指示词「那」一起放在名词「玉」之前，不能把「玉」插在「那」和「块」之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c402f0-507f-4605-be11-5b4d929f6bb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
