INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91531, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "个性是一个人和别人不一样的脾气和样子。", "primary_collocate": null, "pronunciation": "gè xìng", "ipa": "kɤ˥˩ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "她的个性很开朗。", "target_word": "个性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的个性和哥哥完全不同。", "target_word": "个性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个孩子都有自己的个性。", "target_word": "个性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子个性安静，不爱说话。", "target_word": "个性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢他温和的个性。", "target_word": "个性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说我的个性像爸爸。", "target_word": "个性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个姐妹的个性很不一样。", "target_word": "个性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的个性很急，做事总是很快。", "target_word": "个性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫也有自己的个性。", "target_word": "个性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师了解每个学生的个性。", "target_word": "个性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个性化", "label": "复合词"}, {"form": "個性", "label": "繁体"}, {"form": "一种个性", "label": "量词"}], "register": "通用", "sense_fingerprint": "一个人独有的脾气和性格", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b04d6d01-112c-4ea5-821a-a4681d4a9772') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91531, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "个性", "is_correct": true, "explanation": "正确。“个性”指一个人与别人不同的脾气和样子。"}, {"text": "歌星", "is_correct": false, "explanation": "gē（第一声）与 gè（第四声）、xīng（第一声）与 xìng（第四声）声调都不同，意思是歌坛明星。"}, {"text": "各项", "is_correct": false, "explanation": "xiàng 与 xìng 韵母不同（-iang 与 -ing），意思是各个项目。"}, {"text": "革新", "is_correct": false, "explanation": "gé（第二声）与 gè（第四声）声调不同，xīn 与 xìng 韵母和声调都不同，意思是改革更新。"}], "explanations": {"个性": "正确。“个性”指一个人与别人不同的脾气和样子。", "歌星": "gē（第一声）与 gè（第四声）、xīng（第一声）与 xìng（第四声）声调都不同，意思是歌坛明星。", "各项": "xiàng 与 xìng 韵母不同（-iang 与 -ing），意思是各个项目。", "革新": "gé（第二声）与 gè（第四声）声调不同，xīn 与 xìng 韵母和声调都不同，意思是改革更新。"}, "sentence_index": null, "correct_answer": "个性"}, "level_3": {"options": [{"text": "个性", "is_correct": true, "explanation": "正确。“个性”指人的脾气和样子，可以说“她的个性很开朗”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指身体的高矮胖瘦，不能用“开朗”来形容。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是人的特点，不能说“她的天气很开朗”。"}, {"text": "习惯", "is_correct": false, "explanation": "搭配：“习惯”可以说“好”或“坏”，不能用“开朗”来形容。"}], "explanations": {"个性": "正确。“个性”指人的脾气和样子，可以说“她的个性很开朗”。", "身材": "体貌：身材指身体的高矮胖瘦，不能用“开朗”来形容。", "天气": "语义：天气是自然现象，不是人的特点，不能说“她的天气很开朗”。", "习惯": "搭配：“习惯”可以说“好”或“坏”，不能用“开朗”来形容。"}, "sentence_index": 0, "correct_answer": "个性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的个性很高，班里最显眼。", "explanation": "这里应该用〈个子〉。“个性”指脾气性格，形容身材的高矮要用“个子”。"}, {"text": "这件事的个性很严重。", "explanation": "这里应该用〈性质〉。“个性”指人的脾气性格，说事情的本质或性质要用“性质”。"}, {"text": "他的个性长得很英俊。", "explanation": "这里应该用〈长相〉。“个性”指脾气性格，形容相貌要用“长相”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91531, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "个性", "is_correct": true, "explanation": "正确。“个性”指人的脾气和样子，“两个姐妹的个性很不一样”成立。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：海拔是地理高度，不能用来说两个人的特点。"}, {"text": "气温", "is_correct": false, "explanation": "语义：气温是空气的冷热，不是人的属性，“两个姐妹的气温”说不通。"}, {"text": "年代", "is_correct": false, "explanation": "搭配：“年代”指时代，不能说“两个姐妹的年代”。"}], "explanations": {"个性": "正确。“个性”指人的脾气和样子，“两个姐妹的个性很不一样”成立。", "海拔": "语义：海拔是地理高度，不能用来说两个人的特点。", "气温": "语义：气温是空气的冷热，不是人的属性，“两个姐妹的气温”说不通。", "年代": "搭配：“年代”指时代，不能说“两个姐妹的年代”。"}, "sentence_index": 6, "correct_answer": "个性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "个性同学今天都迟到了。", "explanation": "这里应该用〈个别〉。“个别”表示少数，修饰“同学”；“个性”是名词，不能这样修饰。"}, {"text": "这件衣服的个性很贵。", "explanation": "这里应该用〈价格〉。“个性”指特点，不能用来说价钱，说价格要用“价格”。"}, {"text": "他的个性是十八岁。", "explanation": "这里应该用〈年龄〉。“个性”指脾气性格，不能用来说岁数，说年龄要用“年龄”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91531, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一种很开朗个性。", "corrected_sentence": "他有一种很开朗的个性。", "error_description": "“很开朗”修饰“个性”，中间要用“的”连接，应说“很开朗的个性”。漏掉“的”是常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91531, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我姐姐地个性很温和。", "corrected_sentence": "我姐姐的个性很温和。", "error_description": "错误：“地”用错了。领属者“我姐姐”后面应用“的”，不能用“地”，应说“我姐姐的个性很温和”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91532, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "共性", "is_correct": true, "explanation": "正确。“共性”指事物共有的性质，与“个性”相对。"}, {"text": "窗户", "is_correct": false, "explanation": "与“个性”没有反义关系，“窗户”是建筑部件。"}, {"text": "花园", "is_correct": false, "explanation": "与“个性”没有反义关系，“花园”是种花草的场所。"}, {"text": "雨水", "is_correct": false, "explanation": "与“个性”没有反义关系，“雨水”是降水。"}], "correct_answer": "共性", "explanations": {"共性": "正确。“共性”指事物共有的性质，与“个性”相对。", "窗户": "与“个性”没有反义关系，“窗户”是建筑部件。", "花园": "与“个性”没有反义关系，“花园”是种花草的场所。", "雨水": "与“个性”没有反义关系，“雨水”是降水。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91532, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "共性", "is_correct": true, "explanation": "正确。“共性”指事物共有的性质，与“个性”相对。"}, {"text": "石头", "is_correct": false, "explanation": "与“个性”没有反义关系，“石头”是矿物。"}, {"text": "厨房", "is_correct": false, "explanation": "与“个性”没有反义关系，“厨房”是做饭的房间。"}, {"text": "秋天", "is_correct": false, "explanation": "与“个性”没有反义关系，“秋天”是季节。"}], "correct_answer": "共性", "explanations": {"共性": "正确。“共性”指事物共有的性质，与“个性”相对。", "石头": "与“个性”没有反义关系，“石头”是矿物。", "厨房": "与“个性”没有反义关系，“厨房”是做饭的房间。", "秋天": "与“个性”没有反义关系，“秋天”是季节。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91532, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人区别于他人的特点。", "primary_collocate": null, "pronunciation": "gè xìng", "ipa": "kɤ˥˩ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个女孩很有个性。", "target_word": "个性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的穿着很有个性。", "target_word": "个性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校应该尊重学生的个性。", "target_word": "个性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不愿跟别人一样，想要表现自己的个性。", "target_word": "个性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位歌手的个性很鲜明。", "target_word": "个性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要尊重每个人的个性。", "target_word": "个性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的老师会培养孩子的个性。", "target_word": "个性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢留短发，来表现自己的个性。", "target_word": "个性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有个性的人常常不怕和别人不同。", "target_word": "个性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的个性让他在班里很特别。", "target_word": "个性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个性化", "label": "复合词"}, {"form": "個性", "label": "繁体"}, {"form": "一种个性", "label": "量词"}], "register": "通用", "sense_fingerprint": "一个人区别于他人的独特之处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b04d6d01-112c-4ea5-821a-a4681d4a9772') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91532, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "个性", "is_correct": true, "explanation": "正确。“个性”指一个人区别于他人的特点。"}, {"text": "歌星", "is_correct": false, "explanation": "gē（第一声）与 gè（第四声）、xīng（第一声）与 xìng（第四声）声调都不同，意思是歌坛明星。"}, {"text": "各项", "is_correct": false, "explanation": "xiàng 与 xìng 韵母不同（-iang 与 -ing），意思是各个项目。"}, {"text": "革新", "is_correct": false, "explanation": "gé（第二声）与 gè（第四声）声调不同，xīn 与 xìng 韵母和声调都不同，意思是改革更新。"}], "explanations": {"个性": "正确。“个性”指一个人区别于他人的特点。", "歌星": "gē（第一声）与 gè（第四声）、xīng（第一声）与 xìng（第四声）声调都不同，意思是歌坛明星。", "各项": "xiàng 与 xìng 韵母不同（-iang 与 -ing），意思是各个项目。", "革新": "gé（第二声）与 gè（第四声）声调不同，xīn 与 xìng 韵母和声调都不同，意思是改革更新。"}, "sentence_index": null, "correct_answer": "个性"}, "level_3": {"options": [{"text": "个性", "is_correct": true, "explanation": "正确。“很有个性”指与众不同的特点，可以这样说。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是人可以“很有”的特点。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“很有”后接抽象的特点，不能接“桌子”这样的具体事物。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是地理事物，女孩不会“很有河流”。"}], "explanations": {"个性": "正确。“很有个性”指与众不同的特点，可以这样说。", "天气": "语义：天气是自然现象，不是人可以“很有”的特点。", "桌子": "搭配：“很有”后接抽象的特点，不能接“桌子”这样的具体事物。", "河流": "语义：河流是地理事物，女孩不会“很有河流”。"}, "sentence_index": 0, "correct_answer": "个性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的个性比同学都高。", "explanation": "这里应该用〈个子〉。“个性”指特点，不用来比较身高，比身高要用“个子”。"}, {"text": "这个孩子的个性是女的。", "explanation": "这里应该用〈性别〉。“个性”指特点，不能用来说人的性别，说性别要用“性别”。"}, {"text": "他的个性一米八。", "explanation": "这里应该用〈身高〉。“个性”不能指身高，说人的身高要用“身高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91532, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "个性", "is_correct": true, "explanation": "正确。“培养孩子的个性”符合语境。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“培养”多用于能力、习惯等，不能说“培养体重”。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：海拔是地理高度，不是可以培养的东西。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是矿物，不能被培养。"}], "explanations": {"个性": "正确。“培养孩子的个性”符合语境。", "体重": "搭配：“培养”多用于能力、习惯等，不能说“培养体重”。", "海拔": "语义：海拔是地理高度，不是可以培养的东西。", "石头": "语义：石头是矿物，不能被培养。"}, "sentence_index": 6, "correct_answer": "个性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的个性很苗条。", "explanation": "这里应该用〈身材〉。“苗条”形容体形，“个性”不能用来形容体形。"}, {"text": "这箱苹果的个性是十公斤。", "explanation": "这里应该用〈重量〉。“个性”指特点，不能用来说重量，说重量要用“重量”。"}, {"text": "个性同学今天都迟到了。", "explanation": "这里应该用〈个别〉。“个别”表示少数，修饰“同学”；“个性”不能这样修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91532, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老师有很个性。", "corrected_sentence": "这位老师很有个性。", "error_description": "语序错误：程度副词“很”要放在“有”前面，说“很有个性”，不能说“有很个性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91532, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一种很鲜明个性。", "corrected_sentence": "他有一种很鲜明的个性。", "error_description": "“很鲜明”修饰“个性”，中间要用“的”连接，应说“很鲜明的个性”。漏掉“的”是常见错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
