INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91533, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "就是那一天。", "primary_collocate": null, "pronunciation": "dāng rì", "ipa": "taŋ˥ ɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "当日我们一起爬山，现在想起来还很开心。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常常说起当日在学校的生活。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当日的朋友，现在都很少见面了。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当日的小店，现在已经变成了大商场。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回想当日，我们都还很年轻。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我永远记得当日的情景。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当日他说了什么，我已经忘了。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当日我们住的房子已经不在了。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当日的天气很冷，大家都穿着外套。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看书的时候，我想起了当日的事。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "当日：回头指说的那一天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a68bebce-125a-410b-b066-2e5bc672fe83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91533, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "闹钟", "is_correct": false, "explanation": "语义：“闹钟”是物品，不能表示过去的那段时候。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是物品，不能作时间状语。"}, {"text": "当日", "is_correct": true, "explanation": "当日：指过去的那一天，回头说起一起爬山的时候，与句意相符。"}, {"text": "礼堂", "is_correct": false, "explanation": "搭配：“礼堂”指场所，不能放在句首作时间状语。"}], "explanations": {"闹钟": "语义：“闹钟”是物品，不能表示过去的那段时候。", "书包": "语义：“书包”是物品，不能作时间状语。", "当日": "当日：指过去的那一天，回头说起一起爬山的时候，与句意相符。", "礼堂": "搭配：“礼堂”指场所，不能放在句首作时间状语。"}, "sentence_index": 0, "correct_answer": "当日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天当日店里很忙，客人很多。", "explanation": "这里应该删去〈当日〉。“当日”指前文说到的那一天，不能用来指说话的当天，二者冲突。"}, {"text": "他一直当日都来店里买东西。", "explanation": "这里应该用〈每天〉。“当日”只指特定的一天，不能用来表示持续重复。"}, {"text": "我们开业当日准备了半年。", "explanation": "这里应该把时段放在“开业当日”之前来表达，“当日”只指一天，不能与“半年”这样的时段连用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd360a919-9abe-40f8-8f86-b56d07902ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91533, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：“天气”不指某一天，不能用来指代“他说了什么”的那一天。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：“食堂”指场所，不能指说话的时间。"}, {"text": "讲台", "is_correct": false, "explanation": "搭配：“讲台”是处所，不能作时间状语。"}, {"text": "当日", "is_correct": true, "explanation": "当日：就是那一天，指前文说到的那天，与句意相符。"}], "explanations": {"天气": "语义：“天气”不指某一天，不能用来指代“他说了什么”的那一天。", "食堂": "语义：“食堂”指场所，不能指说话的时间。", "讲台": "搭配：“讲台”是处所，不能作时间状语。", "当日": "当日：就是那一天，指前文说到的那天，与句意相符。"}, "sentence_index": 6, "correct_answer": "当日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我一个当日就想起了那件事。", "explanation": "这里应该删去〈一个〉，说“我当日就想起了那件事”。“当日”前不能直接加数量词。"}, {"text": "我们还没认识，他当日就来找我了。", "explanation": "这里应该用〈那天〉并交代前文的日子。“当日”需要承接前文已确定的日子，这里前文没有依托。"}, {"text": "我的同学当日很高，每天都打篮球。", "explanation": "这里应该用〈身材〉之类的词。“当日”只指日期，不能用来形容人的高矮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd360a919-9abe-40f8-8f86-b56d07902ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91533, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "结婚当日的，我们拍了很多照片。", "corrected_sentence": "结婚当日，我们拍了很多照片。", "error_description": "错误：“当日”后面多加了“的”。正确：“当日”作时间状语，直接说“结婚当日，……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd360a919-9abe-40f8-8f86-b56d07902ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91533, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经忘了当日了的事。", "corrected_sentence": "我已经忘了当日的事。", "error_description": "错误：“当日”后面多加了“了”。正确：“当日”直接加“的”修饰“事”，说“当日的事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd360a919-9abe-40f8-8f86-b56d07902ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
