INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91534, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情发生的那一天；当天。", "primary_collocate": null, "pronunciation": "dàng rì", "ipa": "taŋ˥˩ ɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "活动当日，天气非常好。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张票只在当日有效。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当日就把信寄出去了。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店当日送货，不用等很久。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛当日，很多人来看。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事故当日，路上有很多车。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当日的会议很短。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你买的牛奶要当日喝完。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试当日，他早早起床了。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店可以当日取货。", "target_word": "当日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "当日：事情发生的那一天，当天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a68bebce-125a-410b-b066-2e5bc672fe83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91534, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当然", "is_correct": false, "explanation": "语法：“当然”是副词，不能作时间状语限定“活动”。"}, {"text": "当面", "is_correct": false, "explanation": "语义：“当面”指面对面，不能作时间状语限定“活动”。"}, {"text": "当日", "is_correct": true, "explanation": "当日：事情发生的那一天，当天，与“活动”的日子相符。"}, {"text": "当地", "is_correct": false, "explanation": "搭配：“当地”指地方，不能作时间状语限定“活动”。"}], "explanations": {"当然": "语法：“当然”是副词，不能作时间状语限定“活动”。", "当面": "语义：“当面”指面对面，不能作时间状语限定“活动”。", "当日": "当日：事情发生的那一天，当天，与“活动”的日子相符。", "当地": "搭配：“当地”指地方，不能作时间状语限定“活动”。"}, "sentence_index": 0, "correct_answer": "当日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个苹果很当日。", "explanation": "这里应该用〈新鲜〉。“当日”指某一天，不能用来形容苹果。"}, {"text": "我这周当日都很忙。", "explanation": "这里应该用〈每天〉。“当日”只指一天，不能用来概括一周。"}, {"text": "我花了两个当日才完成作业。", "explanation": "这里应该用〈两天〉。“当日”指某一天，本身不能计数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd360a919-9abe-40f8-8f86-b56d07902ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91534, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是日期，不能用来限定“会议”。"}, {"text": "教材", "is_correct": false, "explanation": "语义：“教材”指学习用的书籍，不能指会议的时间。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“会议”不能用“心情”来限定。"}, {"text": "当日", "is_correct": true, "explanation": "当日：指事情发生的那一天，与“会议”搭配，表示那天的会议。"}], "explanations": {"天气": "语义：“天气”不是日期，不能用来限定“会议”。", "教材": "语义：“教材”指学习用的书籍，不能指会议的时间。", "心情": "搭配：“会议”不能用“心情”来限定。", "当日": "当日：指事情发生的那一天，与“会议”搭配，表示那天的会议。"}, "sentence_index": 6, "correct_answer": "当日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我现在当日就出发。", "explanation": "这里应该删去〈当日〉。“现在”已经表示此刻，再加“当日”重复而且矛盾。"}, {"text": "这本书我当日看了三年。", "explanation": "这里应该删去〈当日〉。“当日”只指同一天，不能与“三年”这样的时段连用。"}, {"text": "我当日的脚很大，所以鞋子买小了。", "explanation": "这里应该删去〈当日〉。“当日”只能用来指与日期相关的事，不能修饰身体部位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd360a919-9abe-40f8-8f86-b56d07902ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91534, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "展览当日的，馆里挤满了人。", "corrected_sentence": "展览当日，馆里挤满了人。", "error_description": "错误：“当日”后面多加了“的”。正确：“当日”作时间状语，直接说“展览当日，……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd360a919-9abe-40f8-8f86-b56d07902ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91534, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他当日的就走了。", "corrected_sentence": "他当日就走了。", "error_description": "语法错误：“当日”作时间状语直接修饰动词，中间不能加“的”，应删去，写成“他当日就走了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd360a919-9abe-40f8-8f86-b56d07902ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
