INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91535, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生命带是有生命、能住下生物的一片地方。", "primary_collocate": null, "pronunciation": "shēng mìng dài", "ipa": "ʂɤŋ˥ miŋ˥˩ tai˥˩", "syllable_count": 3, "sentences": [{"text": "海边是一片美丽的生命带。", "target_word": "生命带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河两边是鱼和鸟的生命带。", "target_word": "生命带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林是动物最大的生命带。", "target_word": "生命带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山下有一片绿色的生命带。", "target_word": "生命带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里的小河变成了一条生命带。", "target_word": "生命带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片湖边的生命带里住着很多鸟。", "target_word": "生命带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要保护海边的生命带。", "target_word": "生命带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水多的地方有大片生命带。", "target_word": "生命带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了地图上的生命带。", "target_word": "生命带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那片树林是小动物的生命带。", "target_word": "生命带", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词；生物能够生活的一片地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90648837-04a1-444c-865a-4d09067f40f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91535, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生命带", "is_correct": true, "explanation": "正确：生命带指能住下生物的一片地方，“海边是一片美丽的生命带”说得通。"}, {"text": "办公室", "is_correct": false, "explanation": "搭配：“一片”用于连成一片的地方，不说“一片办公室”。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不是能住下生物的地方，句意不通。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是练习的任务，不是一片地方。"}], "explanations": {"生命带": "正确：生命带指能住下生物的一片地方，“海边是一片美丽的生命带”说得通。", "办公室": "搭配：“一片”用于连成一片的地方，不说“一片办公室”。", "时间": "语义：时间不是能住下生物的地方，句意不通。", "作业": "语义：作业是练习的任务，不是一片地方。"}, "sentence_index": 0, "correct_answer": "生命带"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只乌龟的生命带很长。", "explanation": "这里应该用〈寿命〉。生命带指能住下生物的一片地方，不是生存的时间；说生存的时间长要用〈寿命〉。"}, {"text": "他的生命带很幽默。", "explanation": "这里应该用〈性格〉。生命带指能住下生物的一片地方，不能用来形容人的幽默。"}, {"text": "这棵小树的生命带很强。", "explanation": "这里应该用〈生命力〉。生命带指地方，不能用“强”来形容；形容生物顽强的生存能力要用〈生命力〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91535, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生命带", "is_correct": true, "explanation": "正确：“保护海边的生命带”指保护这一片能住下生物的地方。"}, {"text": "方向", "is_correct": false, "explanation": "语义：方向不是地方，不能作为要保护的对象。"}, {"text": "字母", "is_correct": false, "explanation": "语义：字母是文字符号，与海边的地方无关。"}, {"text": "电话", "is_correct": false, "explanation": "搭配：“保护”与“电话”不搭配，一般不说保护电话。"}], "explanations": {"生命带": "正确：“保护海边的生命带”指保护这一片能住下生物的地方。", "方向": "语义：方向不是地方，不能作为要保护的对象。", "字母": "语义：字母是文字符号，与海边的地方无关。", "电话": "搭配：“保护”与“电话”不搭配，一般不说保护电话。"}, "sentence_index": 6, "correct_answer": "生命带"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小动物很喜欢吃生命带。", "explanation": "这里把“生命带”当成了食物，它指能住下生物的一片地方，不是能吃的东西。小动物吃的应是〈食物〉，不能说“吃生命带”。"}, {"text": "他把生命带挂在墙上。", "explanation": "生命带指一片地方，不能像地图、画那样挂在墙上；可以说“他把地图挂在墙上”。"}, {"text": "他是一片生命带。", "explanation": "生命带指能住下生物的一片地方，不指人；形容人充满活力应说“充满生命力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91535, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海边有一颗美丽的生命带。", "corrected_sentence": "海边有一片美丽的生命带。", "error_description": "错误：量词用错。生命带是一片地方，应用“片”；“颗”用于圆形的小东西，不用于地带。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91535, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要保护这本海边的生命带。", "corrected_sentence": "我们要保护这片海边的生命带。", "error_description": "错误：量词用错。生命带是一片地方，应用“片”；“本”用于书本，不能用来量地方。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
