INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91536, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指适宜生命存在的区域或带状范围，如天体周围的宜居带。", "primary_collocate": null, "pronunciation": "shēng mìng dài", "ipa": "ʂɤŋ˥ miŋ˥˩ tai˥˩", "syllable_count": 3, "sentences": [{"text": "地球在太阳的生命带里。", "target_word": "生命带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家在找别的星星的生命带。", "target_word": "生命带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这颗星星离太阳太近，不在生命带里。", "target_word": "生命带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火星在太阳系生命带的边上。", "target_word": "生命带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生命带里的星球可以有水。", "target_word": "生命带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离星星太近会太热，太远会太冷，所以生命带很窄。", "target_word": "生命带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们发现了一颗在生命带里的行星。", "target_word": "生命带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "恒星越大，生命带离它越远。", "target_word": "生命带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生命带内的温度正好适合生物。", "target_word": "生命带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位科学家一直在研究生命带。", "target_word": "生命带", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词；天体周围适宜生命存在的带状范围，即宜居带", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90648837-04a1-444c-865a-4d09067f40f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91536, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生命带", "is_correct": true, "explanation": "正确：“地球在太阳的生命带里”指地球处于太阳周围宜居的范围内。"}, {"text": "菜单", "is_correct": false, "explanation": "语义：菜单是列出菜品的纸，不能作为“在…里”的范围。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装东西的袋子，地球不能“在太阳的书包里”。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：工资不能用作“在…里”的处所，“在太阳的工资里”不搭配。"}], "explanations": {"生命带": "正确：“地球在太阳的生命带里”指地球处于太阳周围宜居的范围内。", "菜单": "语义：菜单是列出菜品的纸，不能作为“在…里”的范围。", "书包": "语义：书包是装东西的袋子，地球不能“在太阳的书包里”。", "工资": "搭配：工资不能用作“在…里”的处所，“在太阳的工资里”不搭配。"}, "sentence_index": 0, "correct_answer": "生命带"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "火星是太阳系的生命带。", "explanation": "这里应该用〈行星〉。生命带指宜居的一片范围，不是星球；火星是太阳系里的行星。"}, {"text": "这颗星球的生命带很便宜。", "explanation": "生命带指适宜生命存在的范围，不能用“便宜”来形容。形容星球适合生命存在应说〈宜居〉。"}, {"text": "这颗恒星的生命带已经活了几十亿年。", "explanation": "这里应该用〈年龄〉。生命带指适宜生命存在的范围，不能「活」了多久；说恒星存在了多久应用〈年龄〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91536, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生命带", "is_correct": true, "explanation": "正确：“在生命带里的行星”指位于宜居范围内的行星。"}, {"text": "分子", "is_correct": false, "explanation": "语义：分子是微观粒子，不是行星所在的范围。"}, {"text": "乐曲", "is_correct": false, "explanation": "语义：乐曲是音乐作品，行星不能在乐曲里。"}, {"text": "雨季", "is_correct": false, "explanation": "语义：雨季是一年中多雨的时间段，不是行星所在的空间范围，“在雨季里的行星”说不通。"}], "explanations": {"生命带": "正确：“在生命带里的行星”指位于宜居范围内的行星。", "分子": "语义：分子是微观粒子，不是行星所在的范围。", "乐曲": "语义：乐曲是音乐作品，行星不能在乐曲里。", "雨季": "语义：雨季是一年中多雨的时间段，不是行星所在的空间范围，“在雨季里的行星”说不通。"}, "sentence_index": 6, "correct_answer": "生命带"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "行星绕太阳运行的生命带很长。", "explanation": "这里应该用〈周期〉。生命带指宜居的范围，不表示时间；说运行所需的时间长要用〈周期〉。"}, {"text": "行星受到太阳的生命带。", "explanation": "这里应该用〈引力〉。“受到”的对象是力，生命带是范围，不能被“受到”。"}, {"text": "我们要用生命带测量这颗星球。", "explanation": "生命带指适宜生命存在的范围，不是测量工具，不能用来测量。测量星球应使用〈望远镜〉这类工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91536, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地球在太阳的一颗生命带里。", "corrected_sentence": "地球在太阳的一条生命带里。", "error_description": "错误：量词用错。生命带是带状范围，应用“条”；“颗”用于球状的小天体。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91536, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究人员在研究恒星周围的一颗生命带。", "corrected_sentence": "研究人员在研究恒星周围的一条生命带。", "error_description": "错误：量词用错。生命带是带状范围，应用“条”；“颗”用于球状的小天体，不能用来量生命带。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
