INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91539, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "戴在眼睛前面，让人看得清楚的东西。", "primary_collocate": null, "pronunciation": "yǎn jìng", "ipa": "jɛn˨˩ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我的眼镜放在桌子上。", "target_word": "眼镜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他戴着一副黑色的眼镜。", "target_word": "眼镜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看不清黑板，所以要戴眼镜。", "target_word": "眼镜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请帮我拿一下眼镜，好吗？", "target_word": "眼镜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她摘下眼镜，擦了擦眼睛。", "target_word": "眼镜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这副眼镜是我昨天买的。", "target_word": "眼镜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找不到眼镜了，你看见了吗？", "target_word": "眼镜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷戴上眼镜看报纸。", "target_word": "眼镜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的眼镜掉在地上了。", "target_word": "眼镜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有眼镜，我看不清手机上的字。", "target_word": "眼镜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一副眼镜", "label": "量词"}, {"form": "眼镜框", "label": "复合"}, {"form": "太阳眼镜", "label": "复合"}, {"form": "眼鏡", "label": "繁体"}], "register": "通用", "sense_fingerprint": "戴在脸上帮人看清东西的物品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6953d5e5-dcdc-42fa-bb07-a85678b32b99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91539, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眼镜", "is_correct": true, "explanation": "正确。眼镜是戴在眼前的物品，可以放在桌子上。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛是身体器官，不能放在桌子上。"}, {"text": "视力", "is_correct": false, "explanation": "语义：视力是抽象的能力，不是能放在桌子上的东西。"}, {"text": "长相", "is_correct": false, "explanation": "语义：长相指人的外貌，不是能放在桌子上的东西。"}], "explanations": {"眼镜": "正确。眼镜是戴在眼前的物品，可以放在桌子上。", "眼睛": "语义：眼睛是身体器官，不能放在桌子上。", "视力": "语义：视力是抽象的能力，不是能放在桌子上的东西。", "长相": "语义：长相指人的外貌，不是能放在桌子上的东西。"}, "sentence_index": 0, "correct_answer": "眼镜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上站在眼镜前整理头发。", "explanation": "这里应该用〈镜子〉。站在镜子前整理头发是照镜子，眼镜不是用来照的。"}, {"text": "学生用眼镜观察细菌。", "explanation": "这里应该用〈显微镜〉。观察细菌要用显微镜，眼镜不能代替它。"}, {"text": "这台相机的眼镜坏了，要送去修理。", "explanation": "这里应该用〈镜头〉。相机前端的镜头用于成像，不能说“眼镜”；“眼镜”指戴在眼前矫正视力的镜片及镜架。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91539, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眼镜", "is_correct": true, "explanation": "正确。“找不到眼镜”是合理的，“你看见了吗”也符合句意。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音是听的对象，看不见，所以不能用“你看见了吗”来问。"}, {"text": "双目", "is_correct": false, "explanation": "语域：“双目”是书面语，与口语句子“你看见了吗”不协调，句意也不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是靠嗅觉和味觉感知的，不能用“看见”来找。"}], "explanations": {"眼镜": "正确。“找不到眼镜”是合理的，“你看见了吗”也符合句意。", "声音": "语义：声音是听的对象，看不见，所以不能用“你看见了吗”来问。", "双目": "语域：“双目”是书面语，与口语句子“你看见了吗”不协调，句意也不通。", "味道": "语义：味道是靠嗅觉和味觉感知的，不能用“看见”来找。"}, "sentence_index": 6, "correct_answer": "眼镜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天买了一只眼镜。", "explanation": "这里应该用〈副〉。眼镜是成对使用的，量词用“副”，“只”用于单个的东西。"}, {"text": "我昨天买了一把眼镜。", "explanation": "这里应该用〈副〉。“把”用于有柄的东西，眼镜应说“一副”。"}, {"text": "我昨天买了一块眼镜。", "explanation": "这里应该用〈副〉。“块”用于块状的东西，眼镜应说“一副”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91539, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一只新眼镜。", "corrected_sentence": "我买了一副新眼镜。", "error_description": "错误：“一只眼镜”，正确：“一副眼镜”。眼镜是成对使用的，量词应为“副”，“只”用于单个的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91539, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爷爷戴下眼镜看报纸。", "corrected_sentence": "爷爷戴上眼镜看报纸。", "error_description": "错误：“戴下眼镜”。正确：“戴上眼镜”。把眼镜戴到脸上用“戴上”，“下”表示离开，摘眼镜才说“摘下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91540, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91540, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91540, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "戴在眼前用来矫正视力或保护眼睛的镜片及镜架。", "primary_collocate": null, "pronunciation": "yǎn jìng", "ipa": "jɛn˨˩ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "医生说我的眼睛不好，要配一副眼镜。", "target_word": "眼镜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他近视三百度，每天都戴眼镜。", "target_word": "眼镜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年纪大了，看书要戴眼镜。", "target_word": "眼镜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑自行车时戴眼镜可以挡风沙。", "target_word": "眼镜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这副眼镜的镜片能保护眼睛。", "target_word": "眼镜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的眼镜度数不对，看东西头疼。", "target_word": "眼镜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的视力下降了，需要配眼镜。", "target_word": "眼镜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他戴着眼镜，看远处的东西很清楚。", "target_word": "眼镜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做实验时，大家都要戴保护眼睛的眼镜。", "target_word": "眼镜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "视力矫正后，她不用再戴眼镜了。", "target_word": "眼镜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一副眼镜", "label": "量词"}, {"form": "眼镜框", "label": "复合"}, {"form": "近视眼镜", "label": "复合"}, {"form": "眼鏡", "label": "繁体"}], "register": "通用", "sense_fingerprint": "用来矫正视力或保护眼睛的镜片和镜架", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6953d5e5-dcdc-42fa-bb07-a85678b32b99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91540, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眼镜", "is_correct": true, "explanation": "正确。眼睛不好要配的是用来矫正视力的眼镜。"}, {"text": "助听器", "is_correct": false, "explanation": "语义：句子说的是眼睛不好，助听器是帮助听力的，与眼睛无关。"}, {"text": "手表", "is_correct": false, "explanation": "搭配：“配”通常用于眼镜、钥匙等，不说“配手表”。"}, {"text": "视力表", "is_correct": false, "explanation": "语义：视力表是检查视力的图表，不是可以配的物品。"}], "explanations": {"眼镜": "正确。眼睛不好要配的是用来矫正视力的眼镜。", "助听器": "语义：句子说的是眼睛不好，助听器是帮助听力的，与眼睛无关。", "手表": "搭配：“配”通常用于眼镜、钥匙等，不说“配手表”。", "视力表": "语义：视力表是检查视力的图表，不是可以配的物品。"}, "sentence_index": 0, "correct_answer": "眼镜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冬天出门一定要戴眼镜防寒。", "explanation": "这里应该用〈帽子〉。眼镜用来矫正视力或保护眼睛，不能用来防寒保暖。"}, {"text": "她每天早上站在眼镜前梳头。", "explanation": "这里应该用〈镜子〉。站在镜子前梳头是照镜子，眼镜不是用来照的。"}, {"text": "这台显微镜的眼镜脏了，要擦一擦。", "explanation": "这里应该用〈目镜〉。显微镜上靠近眼睛的部件叫目镜，“眼镜”指戴在眼前矫正视力或保护眼睛的镜架和镜片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91540, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眼镜", "is_correct": true, "explanation": "正确。孩子视力下降，需要配的是眼镜。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：孩子视力下降与钥匙无关，不该配钥匙。"}, {"text": "拐杖", "is_correct": false, "explanation": "语义：拐杖是帮助走路的，与孩子视力下降无关。"}, {"text": "耳镜", "is_correct": false, "explanation": "语义：耳镜是检查耳朵的器械，与视力下降无关。"}], "explanations": {"眼镜": "正确。孩子视力下降，需要配的是眼镜。", "钥匙": "语义：孩子视力下降与钥匙无关，不该配钥匙。", "拐杖": "语义：拐杖是帮助走路的，与孩子视力下降无关。", "耳镜": "语义：耳镜是检查耳朵的器械，与视力下降无关。"}, "sentence_index": 6, "correct_answer": "眼镜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我上周配了一只眼镜。", "explanation": "这里应该用〈副〉。眼镜是成对使用的，量词用“副”，“只”用于单个的东西。"}, {"text": "我上周配了一块眼镜。", "explanation": "这里应该用〈副〉。“块”用于块状的东西，眼镜应说“一副”。"}, {"text": "我上周配了一条眼镜。", "explanation": "这里应该用〈副〉。“条”用于细长的东西，眼镜应说“一副”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91540, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我奶奶配了一把新眼镜。", "corrected_sentence": "我奶奶配了一副新眼镜。", "error_description": "错误：“一把眼镜”，正确：“一副眼镜”。眼镜是成对使用的，量词应为“副”，“把”用于有柄的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91540, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他穿着眼镜看书。", "corrected_sentence": "他戴着眼镜看书。", "error_description": "错误：“穿着眼镜”。正确：“戴着眼镜”。眼镜要用动词“戴”，“穿”用于衣服、鞋子等。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e58b54b-5cb6-47d4-bdc7-082ebf7aa163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
