INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91541, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "男家是结婚时男方的家。", "primary_collocate": null, "pronunciation": "nán jiā", "ipa": "nan˧˥ tɕja˥", "syllable_count": 2, "sentences": [{"text": "新娘坐车去了男家。", "target_word": "男家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婚礼在男家的院子里办。", "target_word": "男家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结婚那天，客人都到男家吃饭。", "target_word": "男家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男家离女家不远，走路就到。", "target_word": "男家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男家的门口挂着红灯笼。", "target_word": "男家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新娘第一次来到男家，有点儿紧张。", "target_word": "男家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家把礼物送到了男家。", "target_word": "男家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男家的后院摆满了花。", "target_word": "男家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她明天要搬去男家住。", "target_word": "男家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婚车停在男家门前。", "target_word": "男家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词；结婚时男方的家，指住处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90648837-04a1-444c-865a-4d09067f40f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91541, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "男家", "is_correct": true, "explanation": "正确：“男家”是新娘要去的处所，可以作“去”的宾语。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是可以前往的地点。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“去了饭”不能这样说，“饭”不是处所，不能作目的地。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是人可以坐车前往的地方。"}], "explanations": {"男家": "正确：“男家”是新娘要去的处所，可以作“去”的宾语。", "手机": "语义：手机不是可以前往的地点。", "饭": "搭配：“去了饭”不能这样说，“饭”不是处所，不能作目的地。", "石头": "语义：石头不是人可以坐车前往的地方。"}, "sentence_index": 0, "correct_answer": "男家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只小猫是男家，那只是母的。", "explanation": "这里应该用〈公的〉。男家指结婚时男方的家，不表示动物的性别。"}, {"text": "这件男家衣服很好看。", "explanation": "这里应该用〈男式〉。男家是结婚时男方的家，不能用来说衣服的款式。"}, {"text": "我们班有十个男家。", "explanation": "这里应该用〈男生〉。男家指男方的家，不指男学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91541, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "男家", "is_correct": true, "explanation": "正确：“大家把礼物送到了”需要一个能收礼物的处所，“男家”符合。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能收礼物，也不是可以送达的地点。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是学科，不能作为收礼物的地方。"}, {"text": "昨天", "is_correct": false, "explanation": "搭配：“送到了”需要处所，“昨天”是时间词，不能作送达的地点。"}], "explanations": {"男家": "正确：“大家把礼物送到了”需要一个能收礼物的处所，“男家”符合。", "空气": "语义：空气不能收礼物，也不是可以送达的地点。", "数学": "语义：数学是学科，不能作为收礼物的地方。", "昨天": "搭配：“送到了”需要处所，“昨天”是时间词，不能作送达的地点。"}, "sentence_index": 6, "correct_answer": "男家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "婚礼那天，男家穿着红色的西装，笑得很开心。", "explanation": "这里应该用〈新郎〉。男家指房屋，不能指人；“穿着西装、笑得很开心”的应是新郎本人。"}, {"text": "新娘从男家出发，坐车去男家。", "explanation": "这里应该用〈女家〉。新娘出发的地方是娘家，“男家”与后面的“男家”指同一处，自相矛盾。"}, {"text": "她从小在男家长大，结婚后又搬回了娘家。", "explanation": "这里应该用〈老家〉。“男家”只指结婚时男方的家，不能指从小长大的家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91541, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "客人们坐车去了在男家。", "corrected_sentence": "客人们坐车去了男家。", "error_description": "错误：“去”后直接接处所“男家”，不能再加“在”。应为“去了男家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91541, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "男家们的门前停满了车。", "corrected_sentence": "男家的门前停满了车。", "error_description": "“男家”指房屋，是物，不能加“们”表示复数；应说“男家的门前”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
