INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91542, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "婚姻中男方的家庭。", "primary_collocate": null, "pronunciation": "nán jiā", "ipa": "nan˧˥ tɕja˥", "syllable_count": 2, "sentences": [{"text": "男家的亲戚都来参加婚礼了。", "target_word": "男家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女家和男家的人坐在一起吃饭。", "target_word": "男家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男家给女家送去了礼物。", "target_word": "男家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门亲事，男家很满意。", "target_word": "男家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男家的父母很喜欢新娘。", "target_word": "男家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家人见面时，男家先开了口。", "target_word": "男家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男家要出钱办婚礼。", "target_word": "男家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男家的人带着礼物去了女家。", "target_word": "男家", "complexity_tier": "T3", "furigana": "nán jiā de rén dài zhe lǐwù qù le nǚ jiā。", "sentence_source": "generated"}, {"text": "她嫁过去以后，和男家的人相处得很好。", "target_word": "男家", "complexity_tier": "T3", "furigana": "tā jià guo qù yǐhòu, hé nán jiā de rén xiāngchǔ de hěn hǎo。", "sentence_source": "generated"}, {"text": "男家和女家一起商量婚期。", "target_word": "男家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词；婚姻中男方的家庭、家人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90648837-04a1-444c-865a-4d09067f40f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91542, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "男家", "is_correct": true, "explanation": "正确：“男家”指男方家庭，与句中的“亲戚”“婚礼”相符。"}, {"text": "葬礼", "is_correct": false, "explanation": "语义：“葬礼”是丧事，与句中的“婚礼”矛盾。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是物品，没有亲戚。"}, {"text": "学校", "is_correct": false, "explanation": "搭配：“学校的亲戚”不能这样说，“学校”不能修饰“亲戚”。"}], "explanations": {"男家": "正确：“男家”指男方家庭，与句中的“亲戚”“婚礼”相符。", "葬礼": "语义：“葬礼”是丧事，与句中的“婚礼”矛盾。", "手机": "语义：手机是物品，没有亲戚。", "学校": "搭配：“学校的亲戚”不能这样说，“学校”不能修饰“亲戚”。"}, "sentence_index": 0, "correct_answer": "男家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新娘的父母是男家的人。", "explanation": "这里应该用〈女家〉。新娘的父母属于女方家庭，男家指男方的家庭。"}, {"text": "女儿出嫁那天，男家的妈妈哭着送她出门。", "explanation": "这里应该用〈女家〉。送女儿出嫁的是女方家庭，不是男家。"}, {"text": "婚礼前，男家把自己的女儿嫁了出去。", "explanation": "这里应该用〈女家〉。嫁女儿的是女方家庭，男家是娶媳妇的一方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91542, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "男家", "is_correct": true, "explanation": "正确：“男家”是一方家庭，能够出钱办婚礼。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“出钱”要求有钱的施事，“石头”无法出钱。"}, {"text": "树", "is_correct": false, "explanation": "语义：树没有钱，不能办婚礼。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能出钱办婚礼。"}], "explanations": {"男家": "正确：“男家”是一方家庭，能够出钱办婚礼。", "石头": "配价：“出钱”要求有钱的施事，“石头”无法出钱。", "树": "语义：树没有钱，不能办婚礼。", "桌子": "语义：桌子是家具，不能出钱办婚礼。"}, "sentence_index": 6, "correct_answer": "男家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新郎的爸妈带着礼物来到男家提亲。", "explanation": "这里应该用〈女家〉。提亲是男方去女方家，“来到男家提亲”自相矛盾：男家指男方家庭，不能作提亲的目的地。"}, {"text": "男家给男家送去了礼物。", "explanation": "这里应该用〈女家〉。送礼的一方不能和收礼的一方是同一家，“男家给男家”自相矛盾。"}, {"text": "两家成了男家。", "explanation": "这里应该用〈亲家〉。“男家”只指男方一家，“两家成了……”要用指互为姻亲的“亲家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91542, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "男家们的亲戚都来喝喜酒了。", "corrected_sentence": "男家的亲戚都来喝喜酒了。", "error_description": "“男家”指男方一个家庭，不能加“们”。应说“男家的亲戚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91542, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "男家们派人去女家送彩礼。", "corrected_sentence": "男家派人去女家送彩礼。", "error_description": "“男家”指男方一个家庭，不能加“们”。应说“男家派人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91543, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "热", "is_correct": true, "explanation": "正确：热与冷是反义词，指温度高。"}, {"text": "远", "is_correct": false, "explanation": "远指距离长，与冷的温度没有反义关系。"}, {"text": "厚", "is_correct": false, "explanation": "厚指厚度，与冷的温度没有反义关系。"}, {"text": "快", "is_correct": false, "explanation": "快指速度，与冷没有反义关系。"}], "correct_answer": "热", "explanations": {"热": "正确：热与冷是反义词，指温度高。", "远": "远指距离长，与冷的温度没有反义关系。", "厚": "厚指厚度，与冷的温度没有反义关系。", "快": "快指速度，与冷没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91543, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "热", "is_correct": true, "explanation": "正确：热与冷是反义词，指温度高。"}, {"text": "干", "is_correct": false, "explanation": "干指干燥，与冷没有反义关系。"}, {"text": "重", "is_correct": false, "explanation": "重指重量大，与冷的温度没有反义关系。"}, {"text": "慢", "is_correct": false, "explanation": "慢指速度低，与冷没有反义关系。"}], "correct_answer": "热", "explanations": {"热": "正确：热与冷是反义词，指温度高。", "干": "干指干燥，与冷没有反义关系。", "重": "重指重量大，与冷的温度没有反义关系。", "慢": "慢指速度低，与冷没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91543, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "冷是天气或东西让你觉得凉，想多穿衣服。", "primary_collocate": null, "pronunciation": "lěng", "ipa": "lɤŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "下雪了，外面冷得不想出门。", "target_word": "冷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没穿外套，冷得发抖。", "target_word": "冷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冷的时候，我喜欢喝热茶。", "target_word": "冷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间没有空调，冬天很冷。", "target_word": "冷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的秋天比去年冷。", "target_word": "冷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我怕冷，所以穿了三件衣服。", "target_word": "冷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天来了，早上很冷。", "target_word": "冷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件毛衣太薄了，穿上很冷。", "target_word": "冷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京的冬天冷，可是屋里很暖和。", "target_word": "冷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，天冷了，要戴帽子。", "target_word": "冷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "冷了", "label": "体标"}, {"form": "冷水", "label": "复合"}, {"form": "冷气", "label": "复合"}], "register": "通用", "sense_fingerprint": "天气或东西让人觉得凉，想多穿衣服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db945215-8bb7-469b-a806-7db5687ef759') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91543, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "冷", "is_correct": true, "explanation": "正确：冷（lěng）指天气或东西让人觉得凉。"}, {"text": "领", "is_correct": false, "explanation": "lǐng（第三声）与 lěng 韵母不同（-ing 与 -eng），意思是领子、领导。"}, {"text": "愣", "is_correct": false, "explanation": "lèng（第四声）与 lěng 声调不同，意思是发愣。"}, {"text": "朗", "is_correct": false, "explanation": "lǎng 与 lěng 韵母不同（-ang 与 -eng），意思是明朗。"}], "explanations": {"冷": "正确：冷（lěng）指天气或东西让人觉得凉。", "领": "lǐng（第三声）与 lěng 韵母不同（-ing 与 -eng），意思是领子、领导。", "愣": "lèng（第四声）与 lěng 声调不同，意思是发愣。", "朗": "lǎng 与 lěng 韵母不同（-ang 与 -eng），意思是明朗。"}, "sentence_index": null, "correct_answer": "冷"}, "level_3": {"options": [{"text": "冷", "is_correct": true, "explanation": "正确：下雪时天气冷，所以不想出门，符合语境。"}, {"text": "热", "is_correct": false, "explanation": "语义：下雪的语境中天气不会热，与语境矛盾。"}, {"text": "暖", "is_correct": false, "explanation": "语义：下雪的语境中不会说外面暖和。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“高”说高度，不用来形容外面的天气。"}], "explanations": {"冷": "正确：下雪时天气冷，所以不想出门，符合语境。", "热": "语义：下雪的语境中天气不会热，与语境矛盾。", "暖": "语义：下雪的语境中不会说外面暖和。", "高": "搭配：“高”说高度，不用来形容外面的天气。"}, "sentence_index": 0, "correct_answer": "冷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏夜的风很冷，吹在身上很舒服。", "explanation": "这里应该用〈凉〉。凉指微凉、让人舒服，冷指温度低、让人难受，与“舒服”矛盾。"}, {"text": "他的手被开水烫伤了，很冷。", "explanation": "这里应该用〈疼〉。烫伤后的感觉是疼，冷描述的是温度低，与烫伤的感受相反。"}, {"text": "这次比赛的规则很冷，大家都看不懂。", "explanation": "这里应该用〈复杂〉。形容规则繁杂要用复杂，冷指温度低，不能用来形容规则。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91543, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "冷", "is_correct": true, "explanation": "正确：冷（lěng）指天气或东西让人觉得凉。"}, {"text": "等", "is_correct": false, "explanation": "děng（第三声）与 lěng 只差声母 l/d，意思是等待。"}, {"text": "棱", "is_correct": false, "explanation": "léng（第二声）与 lěng 只差声调，意思是棱角。"}, {"text": "拢", "is_correct": false, "explanation": "lǒng（第三声）与 lěng 韵母不同（-ong 与 -eng），意思是聚拢。"}], "explanations": {"冷": "正确：冷（lěng）指天气或东西让人觉得凉。", "等": "děng（第三声）与 lěng 只差声母 l/d，意思是等待。", "棱": "léng（第二声）与 lěng 只差声调，意思是棱角。", "拢": "lǒng（第三声）与 lěng 韵母不同（-ong 与 -eng），意思是聚拢。"}, "sentence_index": null, "correct_answer": "冷"}, "level_3": {"options": [{"text": "冷", "is_correct": true, "explanation": "正确：冬天早上温度低，符合语境。"}, {"text": "短", "is_correct": false, "explanation": "搭配：“短”说长度，不用来形容早上。"}, {"text": "烫", "is_correct": false, "explanation": "语义：冬天的早上不会烫，与“冬天来了”的语境矛盾。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”说质地，不用来形容早上的气温。"}], "explanations": {"冷": "正确：冬天早上温度低，符合语境。", "短": "搭配：“短”说长度，不用来形容早上。", "烫": "语义：冬天的早上不会烫，与“冬天来了”的语境矛盾。", "硬": "搭配：“硬”说质地，不用来形容早上的气温。"}, "sentence_index": 6, "correct_answer": "冷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他面对困难很冷，没有慌张。", "explanation": "这里应该用〈冷静〉。形容人遇事镇定要用冷静，冷多指温度低或态度冷淡。"}, {"text": "他的字写得很冷，看不清楚。", "explanation": "这里应该用〈潦草〉。形容字迹随便要用潦草，冷指温度低，不能形容字迹。"}, {"text": "小宝宝发烧了，额头冷得厉害。", "explanation": "这里应该用〈烫〉。发烧时额头是发烫的，冷表示温度低，与发烧相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91543, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件外套太薄了，我冷的直发抖。", "corrected_sentence": "这件外套太薄了，我冷得直发抖。", "error_description": "错误：冷的；正确：冷得。形容词后面表示程度的补语要用“得”，不用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91543, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年的冬天跟去年冷。", "corrected_sentence": "今年的冬天比去年冷。", "error_description": "错误：跟去年冷；正确：比去年冷。比较句表示“比较”要用“比”，“跟”表示与…相同，要说“跟去年一样冷”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91545, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
