INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91546, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用刀、斧等猛力把物体断开。", "primary_collocate": null, "pronunciation": "kǎn", "ipa": "kʰan˨˩˦", "syllable_count": 1, "sentences": [{"text": "爷爷拿着斧子去山上砍树。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们砍了一天的柴。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树太粗，一把斧子砍不断。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民用斧头砍断了老树根。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天到了，爸爸去树林里砍柴。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用力砍，大树终于倒了。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没砍过树。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在路边砍着竹子。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要乱砍山上的树。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把门前的那棵老树砍了。", "target_word": "砍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "砍了", "label": "体标"}, {"form": "砍过", "label": "体标"}, {"form": "砍着", "label": "体标"}], "register": "中性", "sense_fingerprint": "用斧、刀猛力砍断树木、柴、竹子等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bca58ee-d389-40eb-ad5d-f4ddb4ef8f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91546, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "砍", "is_correct": true, "explanation": "正确。“砍”（kǎn）指用斧、刀猛力把物体断开。"}, {"text": "看", "is_correct": false, "explanation": "kàn（第四声）与 kǎn（第三声）声调不同，意思是看。"}, {"text": "赶", "is_correct": false, "explanation": "gǎn（第三声）与 kǎn 声母不同（g 与 k），意思是追赶。"}, {"text": "款", "is_correct": false, "explanation": "读音：“款”（kuǎn）与“砍”（kǎn）声调相同，只差介音 u，意思是款项，不是近义词。"}], "explanations": {"砍": "正确。“砍”（kǎn）指用斧、刀猛力把物体断开。", "看": "kàn（第四声）与 kǎn（第三声）声调不同，意思是看。", "赶": "gǎn（第三声）与 kǎn 声母不同（g 与 k），意思是追赶。", "款": "读音：“款”（kuǎn）与“砍”（kǎn）声调相同，只差介音 u，意思是款项，不是近义词。"}, "sentence_index": null, "correct_answer": "砍"}, "level_3": {"options": [{"text": "砍", "is_correct": true, "explanation": "正确。“砍”指用斧、刀猛力砍断树木，与“爷爷拿着斧子去山上……树”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物，不能说在山上吃树。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的宾语是歌曲，不能说唱树。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”是给人或动物吃东西，与拿斧子去山上的动作无关，句子不通。"}], "explanations": {"砍": "正确。“砍”指用斧、刀猛力砍断树木，与“爷爷拿着斧子去山上……树”相符。", "吃": "搭配：“吃”的宾语是食物，不能说在山上吃树。", "唱": "搭配：“唱”的宾语是歌曲，不能说唱树。", "喂": "语义：“喂”是给人或动物吃东西，与拿斧子去山上的动作无关，句子不通。"}, "sentence_index": 0, "correct_answer": "砍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她砍了一朵花。", "explanation": "这里应该用〈摘〉。摘花是用手采下，砍是用刀斧猛力切断，不能这样用。"}, {"text": "裁缝按尺寸砍了一块布做衣服。", "explanation": "这里应该用〈裁〉。按尺寸裁下布料做衣服要用裁，砍是用刀斧猛力断开硬物，不能这样用。"}, {"text": "工人砍了一个坑。", "explanation": "这里应该用〈挖〉。挖坑要靠挖掘，砍是切断，不能用来形成坑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91546, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "砍", "is_correct": true, "explanation": "正确。“砍”（kǎn）指用斧、刀猛力把物体断开。"}, {"text": "敢", "is_correct": false, "explanation": "gǎn（第三声）与 kǎn 声母不同（g 与 k），意思是敢。"}, {"text": "刊", "is_correct": false, "explanation": "kān（第一声）与 kǎn（第三声）声调不同，意思是刊登。"}, {"text": "看", "is_correct": false, "explanation": "kàn（第四声）与 kǎn（第三声）声调不同，意思是看。"}], "explanations": {"砍": "正确。“砍”（kǎn）指用斧、刀猛力把物体断开。", "敢": "gǎn（第三声）与 kǎn 声母不同（g 与 k），意思是敢。", "刊": "kān（第一声）与 kǎn（第三声）声调不同，意思是刊登。", "看": "kàn（第四声）与 kǎn（第三声）声调不同，意思是看。"}, "sentence_index": null, "correct_answer": "砍"}, "level_3": {"options": [{"text": "砍", "is_correct": true, "explanation": "正确。“砍”指用斧、刀断开树木，与“我从来没……过树”相符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的宾语是食物，不能说煮过树。"}, {"text": "织", "is_correct": false, "explanation": "搭配：“织”的宾语是布料或毛线，与“树”搭配不通。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”是用火加热食物，与砍树的行为毫无关系。"}], "explanations": {"砍": "正确。“砍”指用斧、刀断开树木，与“我从来没……过树”相符。", "煮": "搭配：“煮”的宾语是食物，不能说煮过树。", "织": "搭配：“织”的宾语是布料或毛线，与“树”搭配不通。", "烤": "语义：“烤”是用火加热食物，与砍树的行为毫无关系。"}, "sentence_index": 6, "correct_answer": "砍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用手砍了那棵老树。", "explanation": "这里不能用砍。砍必须借助刀斧等有刃工具，徒手不能砍；徒手可以掰断或折断细枝，但不能说“用手砍”。"}, {"text": "他不小心砍碎了碗。", "explanation": "这里应该用〈摔〉。碗是摔碎的，不是砍碎的；砍用于有刃工具猛力切断。"}, {"text": "妈妈砍掉了衣服的袖子。", "explanation": "这里应该用〈剪〉。裁剪衣服要用剪刀，砍是用刀斧猛力切断，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91546, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年砍了过三棵老树。", "corrected_sentence": "他去年砍过三棵老树。", "error_description": "体标错误：“过”表示经历，动词后用了“过”就不能再加“了”，“了”与“过”不能同时用在“砍”后。正确说法是“他去年砍过三棵老树”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91546, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用斧子把竹子砍了倒。", "corrected_sentence": "他用斧子把竹子砍倒了。", "error_description": "补语位置错误：结果补语“倒”必须紧跟动词，不能放在“了”之后。正确说法是“砍倒了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffc335a2-9eba-4e94-bf47-d3fa22753d6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
