INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91547, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "发光是自己放出亮亮的光。", "primary_collocate": null, "pronunciation": "fā guāng", "ipa": "fa˥ kuaŋ˥", "syllable_count": 2, "sentences": [{"text": "星星在夜里发光。", "target_word": "发光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盏小灯会发光。", "target_word": "发光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "萤火虫的尾巴会发光。", "target_word": "发光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳是自己发光的。", "target_word": "发光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机屏幕一直在发光。", "target_word": "发光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑暗中，他的眼睛好像在发光。", "target_word": "发光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，海边的小虫发光了。", "target_word": "发光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玩具一按就发光。", "target_word": "发光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮自己会发光吗？", "target_word": "发光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友的鞋会发光，很好玩。", "target_word": "发光", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "發光", "label": "繁体"}, {"form": "发着光", "label": "体标（着）"}, {"form": "发了光", "label": "体标（了）"}, {"form": "发过光", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "发光：自己放出亮亮的光，如星星、小灯、萤火虫", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90648837-04a1-444c-865a-4d09067f40f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91547, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "发光", "is_correct": true, "explanation": "正确：“发光”指自身放出光，与释义相符。"}, {"text": "花光", "is_correct": false, "explanation": "声母 h 与 f 不同（huā 与 fā），意思是“花光”（用完），与放光无关。"}, {"text": "风光", "is_correct": false, "explanation": "韵母 eng 与 a 不同（fēng 与 fā），意思是“风光”（景色），与放光无关。"}, {"text": "发慌", "is_correct": false, "explanation": "声母 h 与 g 不同（huāng 与 guāng），意思是“发慌”（心里着急或饿得难受）。"}, {"text": "发黄", "is_correct": false, "explanation": "声母 h 与 g 不同，声调也不同（huáng 第二声与 guāng 第一声），意思是“发黄”（变成黄色）。"}, {"text": "反光", "is_correct": false, "explanation": "韵母 an 与 a 不同，声调为第三声（fǎn 与 fā），意思是“反光”（反射光线）。"}], "explanations": {"发光": "正确：“发光”指自身放出光，与释义相符。", "花光": "声母 h 与 f 不同（huā 与 fā），意思是“花光”（用完），与放光无关。", "风光": "韵母 eng 与 a 不同（fēng 与 fā），意思是“风光”（景色），与放光无关。", "发慌": "声母 h 与 g 不同（huāng 与 guāng），意思是“发慌”（心里着急或饿得难受）。", "发黄": "声母 h 与 g 不同，声调也不同（huáng 第二声与 guāng 第一声），意思是“发黄”（变成黄色）。", "反光": "韵母 an 与 a 不同，声调为第三声（fǎn 与 fā），意思是“反光”（反射光线）。"}, "sentence_index": null, "correct_answer": "发光"}, "level_3": {"options": [{"text": "发光", "is_correct": true, "explanation": "正确：“发光”指自身放出光，与“星星在夜里”相符。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：星星不需要进食，“吃饭”与主语不符。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：“洗澡”通常用于人或动物，不能用来说星星。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：“发烧”指身体发热生病，星星没有身体，也不会生病。"}], "explanations": {"发光": "正确：“发光”指自身放出光，与“星星在夜里”相符。", "吃饭": "语义：星星不需要进食，“吃饭”与主语不符。", "洗澡": "搭配：“洗澡”通常用于人或动物，不能用来说星星。", "发烧": "语义：“发烧”指身体发热生病，星星没有身体，也不会生病。"}, "sentence_index": 0, "correct_answer": "发光"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冬天，暖气片一直发光，屋里很暖和。", "explanation": "这里应该用〈发热〉。暖气片放出的是热，不是光；“发光”指物体自身放出光线，应说“发热”。"}, {"text": "喇叭一按就发光，声音很大。", "explanation": "这里应该用〈发声〉。喇叭发出的是声音，不是光；“发光”指物体自身放出光线，应说“发声”。"}, {"text": "这朵花一开就发光，香味很浓。", "explanation": "这里应该用〈散发〉。花香是气味，不是光；“发光”指放出光线，应说“散发”香味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91547, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发光", "is_correct": true, "explanation": "正确：“发光”指自身放出光，与小虫的情况相符。"}, {"text": "开车", "is_correct": false, "explanation": "语义：小虫不会驾驶，“开车”与主语不符。"}, {"text": "签字", "is_correct": false, "explanation": "搭配：“签字”需要用手执笔，不能说小虫签字。"}, {"text": "画画", "is_correct": false, "explanation": "语义：小虫不会画画，“画画”与主语不符。"}], "explanations": {"发光": "正确：“发光”指自身放出光，与小虫的情况相符。", "开车": "语义：小虫不会驾驶，“开车”与主语不符。", "签字": "搭配：“签字”需要用手执笔，不能说小虫签字。", "画画": "语义：小虫不会画画，“画画”与主语不符。"}, "sentence_index": 6, "correct_answer": "发光"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块干冰放进水里，就一直发光。", "explanation": "这里应该用〈冒〉。干冰升华时冒出的是白烟，不是光；“发光”指放出光线，应说“冒”。"}, {"text": "面团放在暖和的地方，很快就发光。", "explanation": "这里应该用〈发酵〉。面团在温暖处发生的变化是发酵，不是发光；“发光”指放出光线。"}, {"text": "种子泡在水里一晚，就发光了。", "explanation": "这里应该用〈发芽〉。种子泡水后发生的变化是发芽，不是发光；“发光”指放出光线。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91547, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "萤火虫在草丛里发光着。", "corrected_sentence": "萤火虫在草丛里发着光。", "error_description": "“发光”是动宾式词语，体标“着”应放在“发”后，说“发着光”；“发光着”是错误的位置。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91547, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜里，灯笼很发光。", "corrected_sentence": "夜里，灯笼一直发光。", "error_description": "“很”不能修饰动词“发光”，表示持续应用“一直”，说“灯笼一直发光”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91550, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "购买", "is_correct": true, "explanation": "正确。“出售”是卖出，“购买”是买入，二者互为反义。"}, {"text": "保存", "is_correct": false, "explanation": "“保存”指留存，与“出售”没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "“修理”指修复损坏的东西，与“出售”没有反义关系。"}, {"text": "种植", "is_correct": false, "explanation": "“种植”指栽培作物，与“出售”没有反义关系。"}], "correct_answer": "购买", "explanations": {"购买": "正确。“出售”是卖出，“购买”是买入，二者互为反义。", "保存": "“保存”指留存，与“出售”没有反义关系。", "修理": "“修理”指修复损坏的东西，与“出售”没有反义关系。", "种植": "“种植”指栽培作物，与“出售”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91550, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "购买", "is_correct": true, "explanation": "正确。“出售”是卖出，“购买”是买入，二者互为反义。"}, {"text": "洗涤", "is_correct": false, "explanation": "“洗涤”指清洗，与“出售”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”指随意行走，与“出售”没有反义关系。"}, {"text": "测量", "is_correct": false, "explanation": "“测量”指量取尺寸，与“出售”没有反义关系。"}], "correct_answer": "购买", "explanations": {"购买": "正确。“出售”是卖出，“购买”是买入，二者互为反义。", "洗涤": "“洗涤”指清洗，与“出售”没有反义关系。", "散步": "“散步”指随意行走，与“出售”没有反义关系。", "测量": "“测量”指量取尺寸，与“出售”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91550, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "卖出（商品等）。", "primary_collocate": null, "pronunciation": "chū shòu", "ipa": "ʈʂʰu˥ ʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这家商店出售各种新鲜水果。", "target_word": "出售", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想出售自己的旧汽车。", "target_word": "出售", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书在网上出售，价格不贵。", "target_word": "出售", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店明天开始出售新手机。", "target_word": "出售", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些旧家具已经出售了。", "target_word": "出售", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "超市里出售的牛奶都很新鲜。", "target_word": "出售", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把自己的房子出售了。", "target_word": "出售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里不出售香烟，请去别的店买。", "target_word": "出售", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去年夏天，他出售过一批蔬菜。", "target_word": "出售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说这种茶叶只出售给老客人。", "target_word": "出售", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "出售了", "label": "完成体"}, {"form": "出售过", "label": "经历体"}], "register": "书面语", "sense_fingerprint": "把商品卖出去，多用于商店、网络等场合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78a3ef50-e145-4c82-a7e3-e5ad63c2ba2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91550, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "采摘", "is_correct": false, "explanation": "语义：采摘是从植株上摘下，商店不会采摘水果，与句意不符。"}, {"text": "出售", "is_correct": true, "explanation": "正确。商店把各种新鲜水果卖出去，与句意相符。"}, {"text": "品尝", "is_correct": false, "explanation": "语义：品尝是尝味道，与商店经营的语境不符。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的宾语须是地点或展览，不能接“新鲜水果”。"}], "explanations": {"采摘": "语义：采摘是从植株上摘下，商店不会采摘水果，与句意不符。", "出售": "正确。商店把各种新鲜水果卖出去，与句意相符。", "品尝": "语义：品尝是尝味道，与商店经营的语境不符。", "参观": "搭配：“参观”的宾语须是地点或展览，不能接“新鲜水果”。"}, "sentence_index": 0, "correct_answer": "出售"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "商店今天免费出售新手机。", "explanation": "这里应该用〈赠送〉。“出售”是卖出并收钱，与“免费”矛盾。"}, {"text": "这套房子出售给学生，每月要交一次房租。", "explanation": "这里应该用〈出租〉。“出售”是一次性卖断，与“每月交房租”矛盾。"}, {"text": "他弄坏了邻居的窗户，所以出售了损失。", "explanation": "这里应该用〈赔偿〉。“出售”的宾语是商品，损失不能出售，应说“赔偿了损失”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91550, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：房子不能吃，“吃了房子”句意不通。"}, {"text": "出售", "is_correct": true, "explanation": "正确。“出售”指把房子卖出去，与“把……了”的处置语境相符。"}, {"text": "读", "is_correct": false, "explanation": "语义：房子不能阅读，与句意不符。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”的对象一般是动物或婴儿，不能用于房子。"}], "explanations": {"吃": "语义：房子不能吃，“吃了房子”句意不通。", "出售": "正确。“出售”指把房子卖出去，与“把……了”的处置语境相符。", "读": "语义：房子不能阅读，与句意不符。", "喂": "搭配：“喂”的对象一般是动物或婴儿，不能用于房子。"}, "sentence_index": 6, "correct_answer": "出售"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他为了钱出售了朋友。", "explanation": "这里应该用〈出卖〉。“出售”用于商品，不用于人，背叛他人应说“出卖”。"}, {"text": "我把书出售给了同学，过几天就还。", "explanation": "这里应该用〈借〉。“出售”是卖断，不会归还，与“过几天就还”矛盾。"}, {"text": "学校每年出售一次运动会。", "explanation": "这里应该用〈举办〉。运动会是活动，不是商品，不能出售。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91550, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她去年出售着一批手工艺品。", "corrected_sentence": "她去年出售过一批手工艺品。", "error_description": "体标记错误。表示去年已经发生过的经历要用“过”，“着”表示持续状态，不能用于此句。应为“出售过一批”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91550, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这辆旧摩托出售了给同事。", "corrected_sentence": "他把这辆旧摩托出售给了同事。", "error_description": "“给”与“了”的位置错误。“给”应紧跟动词“出售”，“了”应放在“给”之后，应为“出售给了同事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
