INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91552, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "研究并制造出新的产品。", "primary_collocate": null, "pronunciation": "yán zhì", "ipa": "jɛn˧˥ ʈʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "这家工厂研制了一种新汽车。", "target_word": "研制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司准备研制新的电视。", "target_word": "研制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们研制的新产品卖得很好。", "target_word": "研制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家研制出了更安全的药。", "target_word": "研制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们厂去年研制成功一种新布。", "target_word": "研制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司专门研制手机。", "target_word": "研制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师研制出了便宜的电脑。", "target_word": "研制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们研制的机器人能打扫房间。", "target_word": "研制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司研制新产品需要很多钱。", "target_word": "研制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师研制了一种新玩具。", "target_word": "研制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "研制了", "label": "体标"}], "register": "书面语", "sense_fingerprint": "研究并制造出新的产品，多用于工厂、公司、专家的新产品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61745b1a-f27b-4aaf-b958-4b5b5e37ece2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91552, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "研制", "is_correct": true, "explanation": "研制：研究并制造出新产品，与“新汽车”搭配。"}, {"text": "骂", "is_correct": false, "explanation": "语义：“骂”指用言语责备，与制造新汽车无关。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，后面不能带“一种新汽车”作宾语。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指唱歌，不能用来指研制汽车。"}], "explanations": {"研制": "研制：研究并制造出新产品，与“新汽车”搭配。", "骂": "语义：“骂”指用言语责备，与制造新汽车无关。", "睡": "配价：“睡”是不及物动词，后面不能带“一种新汽车”作宾语。", "唱": "语义：“唱”指唱歌，不能用来指研制汽车。"}, "sentence_index": 0, "correct_answer": "研制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教授正在研制一个数学难题。", "explanation": "这里应该用〈研究〉。研制指研制新产品，数学难题要用研究。"}, {"text": "师傅研制了那台坏掉的冰箱。", "explanation": "这里应该用〈修理〉。研制指研制新产品，修好坏了的冰箱要用修理。"}, {"text": "这家工厂每天研制上千双鞋。", "explanation": "这里应该用〈生产〉。研制强调研发新产品，批量生产鞋要用生产。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '498de41c-d8ab-431f-8c2b-0a0dbd453e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
